# Límites y features por plan
# La IA va en TODOS los planes. Tenerla apagada en el de entrada significaba
# que quien probaba el producto veia justo la version que NO se diferencia de
# una hoja de calculo. Y ya no hay topes de flota: se cobra por furgoneta, asi
# que crecer no se castiga, se factura.
_LIM_OPERACION = {"max_vehicles": -1, "max_drivers": -1, "max_centers": 1,
                  "ai": True, "scorecard": False, "chat": True, "forensics": False,
                  "maintenance": True, "assignments": False, "export": False}
_LIM_COMPLETO = {"max_vehicles": -1, "max_drivers": -1, "max_centers": -1,
                 "ai": True, "scorecard": True, "chat": True, "forensics": True,
                 "maintenance": True, "assignments": True, "export": True}

PLAN_LIMITS = {
    "operacion":  _LIM_OPERACION,
    "completo":   _LIM_COMPLETO,
    "holding":    _LIM_COMPLETO,
    # Claves antiguas: las organizaciones existentes no se tocan.
    "basico":     _LIM_OPERACION,
    "pro":        _LIM_COMPLETO,
    "flota":      _LIM_COMPLETO,
    "enterprise": {"max_vehicles": -1,  "max_drivers": -1,  "max_centers": -1, "ai": True,  "scorecard": True,  "chat": True,  "forensics": True,  "maintenance": True,  "assignments": True,  "export": True},
    "owner":      {"max_vehicles": -1,  "max_drivers": -1,  "max_centers": -1, "ai": True,  "scorecard": True,  "chat": True,  "forensics": True,  "maintenance": True,  "assignments": True,  "export": True},
}
PLAN_DEFAULT = PLAN_LIMITS["pro"]  # trial sin plan elegido → acceso Pro para evaluación

_SIN_TOPE = 999


def _tope_centros(org: dict) -> int:
    """Cuantos centros puede tener una empresa: lo que diga su PLAN.

    El registro guardaba `max_centers: 1` a todo el mundo y «añadir centro» solo
    miraba ese numero, asi que una empresa del plan Completo —que se vende como
    «varios centros, sin limite»— no podia dar de alta su segunda nave. El tope
    guardado en la organizacion solo cuenta si es MAYOR (lo sube el
    super-admin a mano); nunca recorta lo que el plan da.
    """
    org = org or {}
    lim = PLAN_LIMITS.get((org.get("plan") or "").lower(), PLAN_DEFAULT).get("max_centers", 1)
    try:
        propio = int(org.get("max_centers") or 1)
    except (TypeError, ValueError):
        propio = 1
    return _SIN_TOPE if lim == -1 else max(int(lim), propio)


def _centros_de_texto(texto) -> list:
    """«OGA5, dga1 ; DGA2» -> ['OGA5', 'DGA1', 'DGA2'], sin repetir."""
    fuera = []
    for trozo in re.split(r"[,;/\n]+", str(texto or "")):
        c = re.sub(r"\s+", " ", trozo).strip().upper()
        if c and c not in fuera:
            fuera.append(c[:30])
    return fuera


def _slugify(s):
    s = (s or "").lower().strip()
    s = re.sub(r"[áàä]", "a", s); s = re.sub(r"[éèë]", "e", s)
    s = re.sub(r"[íìï]", "i", s); s = re.sub(r"[óòö]", "o", s)
    s = re.sub(r"[úùü]", "u", s); s = re.sub(r"ñ", "n", s)
    s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
    return s[:30]


