# =========================
# AUTH HELPERS
# =========================

_bearer = HTTPBearer(auto_error=False)


_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def hash_password(plain: str) -> str:
    return bcrypt.hashpw(plain.encode(), bcrypt.gensalt()).decode()


def verify_password(plain: str, hashed: str) -> bool:
    return bcrypt.checkpw(plain.encode(), hashed.encode())


def create_token(user_id: str, role: str, name: str,
                 org_id: Optional[str] = None, db_name: Optional[str] = None,
                 account_type: Optional[str] = None, centers: Optional[list] = None,
                 super_admin: bool = False, permissions: Optional[list] = None,
                 demo: bool = False, allowed_centers: Optional[list] = None,
                 suplantado: bool = False) -> str:
    # El conductor entra en su portal una vez cada muchos dias: pedir dias libres
    # o mirar sus turnos no es algo diario. Con las 72 h del panel, el token le
    # caducaba entre visita y visita y la pantalla le soltaba
    # "Token invalido: Signature has expired" en crudo, sin decirle que vuelva a
    # entrar. Le paso a Estela el 21-08-2026 al intentar pedir dias.
    #
    # Se le da un mes. El riesgo es bajo: un token de conductor solo alcanza a
    # SUS datos —sus turnos, sus peticiones, su furgoneta del dia—, nunca al
    # panel ni a los datos de nadie mas.
    horas = (24 * 30) if role == "driver" else JWT_EXPIRE_HOURS
    expires = datetime.now(timezone.utc) + timedelta(hours=horas)
    payload = {
        "sub": user_id,
        "role": role,
        "name": name,
        "exp": expires
    }
    if super_admin:
        payload["sa"] = True
    if demo:
        payload["demo"] = True  # solo lectura: get_current_user bloquea mutaciones
    if suplantado:
        # El super-admin mirando la cuenta de un cliente. Solo lo lee la
        # analitica, para no contar sus paseos por el panel como uso del cliente.
        payload["imp"] = True
    # Permisos por usuario (lista de módulos permitidos). None = sin restricción.
    if permissions is not None:
        payload["permissions"] = permissions
    if org_id:
        payload["org_id"] = org_id
    if db_name:
        payload["db_name"] = db_name
    if account_type:
        payload["account_type"] = account_type
    if centers:
        payload["centers"] = centers
    if allowed_centers:
        payload["allowed_centers"] = allowed_centers
    return jwt.encode(payload, SECRET_KEY, algorithm=JWT_ALGORITHM)


def decode_token(token: str) -> dict:
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[JWT_ALGORITHM])
    except JWTError as e:
        raise HTTPException(status_code=401, detail=f"Token inválido: {e}")


# Un JWT es válido hasta que caduca (72h) aunque el usuario haya sido borrado.
# Para que borrar/deshabilitar un admin surta efecto YA, se comprueba que siga
# existiendo en BD (con caché de 60s para no añadir una query a cada petición).
# user_id -> (expira_ts, existe, allowed_centers, permissions, admin_role)
# Los centros permitidos viajan aqui y no solo en el JWT: asi un token ya
# emitido queda restringido en cuanto se le asignan centros, sin esperar a
# que caduque ni obligar a volver a entrar.
#
# Los PERMISOS y el ROL viajan aqui por lo mismo, y se anadieron despues:
#   - Los permisos solo vivian en el JWT, asi que dar o quitar un modulo no
#     surtia efecto hasta 72 h despues o hasta que el usuario volvia a entrar.
#     Se guardaba, decia "OK", y el otro seguia viendo lo mismo.
#   - `admin_role` NO se metia nunca en el token (create_token no lo pone),
#     asi que `_is_center_manager()` lo leia del payload y salia siempre False.
#     Consecuencia: los gestores de centro recibian 403 al crear usuarios y al
#     tocar permisos, y ademas veian la plantilla ENTERA de la organizacion
#     porque el filtro por centros de `list_admins` tampoco llegaba a aplicarse.
# La BD manda sobre el token en las tres cosas.
_ADMIN_EXISTS_CACHE: dict = {}
_ADMIN_EXISTS_TTL = 60.0


async def _admin_cacheado(user_id: str):
    """(existe, allowed_centers, permissions, admin_role) con cache de 60 s.

    Una sola consulta: los cuatro datos salen del mismo documento.
    """
    now = time.time()
    hit = _ADMIN_EXISTS_CACHE.get(user_id)
    if hit and hit[0] > now:
        return hit[1], hit[2], hit[3], hit[4]
    doc = await global_db.admin_users.find_one(
        {"id": user_id}, {"_id": 0, "id": 1, "disabled": 1, "allowed_centers": 1,
                          "permissions": 1, "admin_role": 1})
    ok = bool(doc) and not doc.get("disabled")
    centros = (doc or {}).get("allowed_centers")
    # Ausente y None significan lo mismo aqui: sin restriccion. Es como estan
    # los usuarios antiguos y no se les puede cerrar el panel de golpe.
    permisos = (doc or {}).get("permissions")
    rol = (doc or {}).get("admin_role")
    if len(_ADMIN_EXISTS_CACHE) > 2000:
        _ADMIN_EXISTS_CACHE.clear()
    _ADMIN_EXISTS_CACHE[user_id] = (now + _ADMIN_EXISTS_TTL, ok, centros, permisos, rol)
    return ok, centros, permisos, rol


async def _admin_still_exists(user_id: str) -> bool:
    ok, _centros, _permisos, _rol = await _admin_cacheado(user_id)
    return ok


async def get_current_user(
    request: Request,
    credentials: Optional[HTTPAuthorizationCredentials] = Depends(_bearer),
) -> dict:
    if not credentials:
        raise HTTPException(status_code=401, detail="Se requiere autenticación")
    payload = decode_token(credentials.credentials)
    # Sesión revocada: el usuario ya no existe (o está deshabilitado) en BD.
    # Los tokens de demo y de mantenimiento no viven en admin_users.
    if (payload.get("role") == "admin" and not payload.get("demo")
            and payload.get("sub") != "maintenance-claude"):
        existe, centros_permitidos, permisos, rol_admin = await _admin_cacheado(payload.get("sub", ""))
        if not existe:
            raise HTTPException(status_code=401, detail="Sesión revocada: el usuario ya no existe")
        # La BD manda sobre el token: si le acaban de limitar los centros, se
        # aplica ya. Antes esto no llegaba nunca y la restricción no existía.
        payload["allowed_centers"] = centros_permitidos
        # Lo mismo con los permisos y el rol. Los permisos solo estaban en el
        # token: quitarle un módulo a alguien no hacía nada hasta que volvía a
        # entrar. Y `admin_role` no estaba ni en el token, así que el rol de
        # gestor de centro no existía para el servidor.
        payload["permissions"] = permisos
        payload["admin_role"] = rol_admin
    # Modo demo: cuenta de solo lectura para probar el producto sin registro.
    # Cualquier mutación se bloquea aquí, cubra el endpoint que cubra.
    if payload.get("demo") and request.method not in ("GET", "HEAD", "OPTIONS"):
        # Excepciones seguras en demo: el asistente IA (lectura vía POST) y los
        # datos de ejemplo de Cortex (TBADEMO*, aislados en la BD de la demo) —
        # así el visitante puede probar el tracker de paquetes de verdad.
        # El aparcamiento tambien se puede tocar en demo: BD aislada, y deja que
        # el visitante pruebe de verdad el plano (asignar, reportar, confirmar).
        _demo_ok = ("/assistant/ask", "/parking/assign", "/parking/report", "/parking/resolve")
        if not any(request.url.path.endswith(p) for p in _demo_ok):
            raise HTTPException(status_code=403, detail="Modo demo: solo lectura. Crea tu cuenta gratis para editar.")
    # AÍSLA: fija la BD de la organización del token para TODA esta petición.
    # Tokens antiguos sin db_name → BD por defecto (tu data) = sin cambios.
    set_current_org_db(payload.get("db_name"))
    # Un conductor que entro con una ficha de baja (el login elegia la que
    # fuera) sigue con ese token 30 dias: se le lleva a su ficha activa, en vez
    # de obligarle a salir y entrar sin que nadie sepa por que.
    if payload.get("role") == "driver" and payload.get("sub"):
        try:
            payload["sub"] = await _ficha_activa_de(payload["sub"])
        except Exception as e:                               # noqa: BLE001
            logger.warning(f"ficha activa de {payload.get('sub')}: {e}")
    return payload


def _a_numero(valor, defecto=0.0):
    """Un número a partir de lo que sea, sin lanzar. Para datos YA guardados:
    no se pueden re-validar, pero tampoco deben tumbar una pantalla."""
    if isinstance(valor, bool) or valor is None:
        return defecto
    if isinstance(valor, (int, float)):
        return float(valor)
    try:
        return float(str(valor).replace(",", ".").strip())
    except (TypeError, ValueError):
        return defecto


def _decimal(valor, campo, defecto=None, minimo=None, maximo=None):
    """Decimal validado que viene del cliente: 400 si no vale, nunca 500.

    Acepta la coma decimal española ("12,50"): escribirla es lo normal aquí y
    un 500 por eso sería de traca.
    """
    if valor is None or valor == "":
        if defecto is None:
            raise HTTPException(status_code=400, detail=f"Falta {campo}")
        return defecto
    if isinstance(valor, bool):
        raise HTTPException(status_code=400, detail=f"{campo} debe ser un número")
    try:
        n = float(str(valor).replace(",", ".").strip()) if not isinstance(valor, (int, float)) else float(valor)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail=f"{campo} debe ser un número")
    if n != n or n in (float("inf"), float("-inf")):      # NaN / infinito
        raise HTTPException(status_code=400, detail=f"{campo} debe ser un número")
    if minimo is not None and n < minimo:
        raise HTTPException(status_code=400, detail=f"{campo} no puede ser menor que {minimo}")
    if maximo is not None and n > maximo:
        raise HTTPException(status_code=400, detail=f"{campo} no puede ser mayor que {maximo}")
    return round(n, 2)


def _dict_cuerpo(valor) -> dict:
    """Un campo del cuerpo que se espera OBJETO, sin reventar.

    Hermano de `_texto_cuerpo` (gotcha 61) para la otra mitad del mismo fallo:
    `sub = data.get("subscription") or {}` es correcto mientras llegue un
    objeto, y en cuanto llega una lista o un booleano el `sub["endpoint"]` de
    la linea siguiente es un `TypeError` -> 500. Lo que no es un objeto da {},
    que hace que la validacion de despues conteste el 400 que tocaba.
    """
    return valor if isinstance(valor, dict) else {}


def _lista_cuerpo(valor, maximo: int = None) -> list:
    """Un campo del cuerpo que se espera LISTA, sin reventar.

    El tercer hermano de `_texto_cuerpo` y `_dict_cuerpo`, y el que mas veces
    faltaba: medido contra staging el 20-09-2026 mandando a cada mutacion SUS
    PROPIOS campos con el tipo cambiado, **31 endpoints devolvian «Error
    interno del servidor»**, y en la mayoria por lo mismo — `for x in
    _lista_cuerpo(data.get("y"))` con un booleano o un numero dentro, que no se puede
    recorrer.

    Es seguro por construccion, igual que `_texto_cuerpo` (gotcha 61): con una
    lista de verdad devuelve exactamente la misma lista, asi que reescribir los
    sitios de golpe no puede cambiar nada con datos buenos. Lo unico que cambia
    es lo que antes era una excepcion: un booleano, un numero o un objeto dan
    `[]`, y entonces la validacion de despues contesta su 400 con su mensaje en
    vez de un 500 sin ninguno — que ademas dispara la alerta de Telegram por un
    dato mal escrito.

    Una cadena tambien da `[]` A PROPOSITO: `for c in "abc"` recorre letras, y
    eso no es lo que queria nadie que mando ese campo.
    """
    if not isinstance(valor, list):
        return []
    return valor[:maximo] if maximo else valor


def _texto_cuerpo(valor, maximo: int = None) -> str:
    """Un campo de TEXTO que llega en el cuerpo de una peticion, sin reventar.

    Sustituye al `(data.get("x") or "").strip()` de siempre, que es correcto
    mientras lo que llegue sea texto y **un 500 en cuanto no lo es**: una lista,
    un objeto o un booleano no tienen `.strip()`. Medido contra staging mandando
    a cada endpoint SUS PROPIOS campos con el tipo cambiado: **43 de las 216
    mutaciones devolvian «Error interno del servidor»**, dos de ellas publicas
    (`/auth/lead` y `/auth/forgot-password`, o sea al alcance de cualquiera).
    Y un 500 no es solo un codigo feo: dispara la alerta de Telegram por un dato
    mal escrito, que es justo lo que `_entero` vino a evitar para los numeros.

    Se comporta EXACTAMENTE igual que lo que sustituye siempre que no reventara:
    lo falso (None, "", 0, listas y objetos vacios) da "", y el texto se recorta
    igual. Lo unico que cambia es lo que antes era una excepcion: un numero pasa
    a su texto —12345 es lo que quiso escribir quien lo mando— y una lista, un
    objeto o un booleano dan "", que hace que la validacion de despues conteste
    400 con su mensaje en vez de 500 sin ninguno.

    No se llama `_texto` ni `_cadena` a proposito —`_cadena` ya existe
    como variable local en el arranque—: en un fichero de 40.000 lineas un nombre
    generico puede estar pisando otro sin que Python diga nada (gotcha 24).
    """
    if not valor:
        return ""
    if isinstance(valor, bool) or not isinstance(valor, (str, int, float)):
        return ""
    s = str(valor).strip()
    return s[:maximo] if maximo else s


def _entero(valor, campo: str, defecto=None, minimo=None, maximo=None) -> int:
    """Convierte a entero o lanza 400 con un mensaje util.

    Antes se hacia int(data.get(...)) a pelo: un "abc" o un null reventaba con
    ValueError, el usuario veia "Error interno del servidor" y encima saltaba
    la alerta de Telegram por un simple dato mal escrito.
    """
    if valor is None or valor == "":
        if defecto is None:
            raise HTTPException(status_code=400, detail=f"Falta {campo}")
        return int(defecto)
    try:
        n = int(float(str(valor).replace(",", ".").strip()))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail=f"{campo} debe ser un numero")
    if minimo is not None and n < minimo:
        raise HTTPException(status_code=400, detail=f"{campo} no puede ser menor que {minimo}")
    if maximo is not None and n > maximo:
        raise HTTPException(status_code=400, detail=f"{campo} no puede ser mayor que {maximo}")
    return n


async def require_admin(user: dict = Depends(get_current_user)) -> dict:
    if user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Acceso restringido a administradores")
    return user


async def require_any_auth(user: dict = Depends(get_current_user)) -> dict:
    return user


async def require_owner(user: dict = Depends(get_current_user)) -> dict:
    """Cualquier cuenta dueño (tú y tus admins internos)."""
    if user.get("account_type") != "owner":
        raise HTTPException(status_code=403, detail="Acceso restringido")
    return user


async def require_superadmin(user: dict = Depends(get_current_user)) -> dict:
    """SOLO el super-admin (dani). Panel de control del negocio y facturación."""
    if not user.get("sa"):
        raise HTTPException(status_code=403, detail="Acceso solo para el super-admin")
    return user


