@api_router.get("/org/centros-geo")
async def org_centros_geo(_=Depends(require_admin)):
    """Donde esta cada centro: la mediana de sus talleres con posicion (tres o
    mas), y si no los hay, las coordenadas de referencia.

    Es para que Talleres arranque desde la nave en vez de pedir una direccion
    o el GPS del PC cada vez (02-09-2026): quien llama a un taller esta
    sentado en el centro, y el centro ya se sabe donde esta.
    """
    acc: dict = {}
    async for w in db.workshops.find(
            {"latitude": {"$type": "number"}, "longitude": {"$type": "number"}},
            {"_id": 0, "center": 1, "latitude": 1, "longitude": 1}):
        c = (w.get("center") or "").strip().upper()
        if c:
            acc.setdefault(c, []).append((float(w["latitude"]), float(w["longitude"])))
    out = {c: {"lat": _mediana([p[0] for p in ps]), "lng": _mediana([p[1] for p in ps]),
               "origen": "talleres"}
           for c, ps in acc.items() if len(ps) >= 3}
    # Las coordenadas de referencia salen de los talleres semilla, que son de
    # las naves de Dani. Sin filtrar, una empresa recien creada recibia OGA5,
    # DGA1 y DGA2 como si fueran suyas (medido el 16-09-2026).
    naves = set(await _centros_de_la_empresa())
    for c, (la, ln) in _centros_referencia().items():
        if c in naves:
            out.setdefault(c, {"lat": la, "lng": ln, "origen": "referencia"})
    return {"centros": {c: v for c, v in out.items() if not naves or c in naves}}


@api_router.post("/org/centers")
async def add_org_center(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Añade un centro a tu organización. Pasado el límite del plan → 402 (de pago)."""
    name = _texto_cuerpo(data.get("name")).upper()
    if not name:
        raise HTTPException(status_code=400, detail="Indica el nombre del centro")
    org = await get_org(user.get("org_id"))
    if not org:
        raise HTTPException(status_code=404, detail="Organización no encontrada")
    centers = org.get("centers") or []
    if name in centers:
        raise HTTPException(status_code=409, detail="Ese centro ya existe")
    if len(centers) >= _tope_centros(org):
        raise HTTPException(status_code=402,
                            detail="Has alcanzado el límite de centros de tu plan. Amplía tu suscripción para añadir más.")
    centers.append(name)
    await global_db.organizations.update_one(
        {"id": org["id"]}, {"$set": {"centers": centers}})
    return {"ok": True, "centers": centers}


@auth_router.post("/lead")
async def capture_lead(data: dict = Body(...), request: Request = None):
    """Captura interés (CRM) + guarda mensaje en Bandeja (append-only).
    - 'leads' es el CRM de interesados: 1 doc por email (upsert).
    - 'inbox_messages' es la bandeja real: 1 doc por envío (append).
    Así no se pierden mensajes si la misma persona escribe varias veces."""
    # Anti-spam: máx 5/min/IP y 30/día/IP.
    ip = _rl_key_ip(request) if request else "?"
    _rl_public_action(f"lead-ip-min:{ip}", max_count=5, window_s=60,
                      detail="Has enviado muchos mensajes en poco tiempo. Espera un minuto.")
    _rl_public_action(f"lead-ip-day:{ip}", max_count=30, window_s=86400,
                      detail="Has alcanzado el límite diario de envíos desde esta red.")
    email = _texto_cuerpo(data.get("email")).lower()
    if "@" not in email:
        raise HTTPException(status_code=400, detail="Pon un email válido")
    name = _texto_cuerpo(data.get("name"))
    company = _texto_cuerpo(data.get("company"))
    plan = _texto_cuerpo(data.get("plan"))  # también usado como "asunto + mensaje" desde el form
    now = datetime.now(timezone.utc).isoformat()
    # CRM: 1 lead por email (upsert).
    await global_db.leads.update_one(
        {"email": email},
        {"$set": {"email": email, "plan": plan, "name": name, "company": company, "updated_at": now},
         "$setOnInsert": {"created_at": now}},
        upsert=True)
    # Bandeja: append-only, no pierde mensajes.
    await global_db.inbox_messages.insert_one({
        "id": str(uuid.uuid4()), "email": email, "name": name, "company": company,
        "body": plan, "ip": ip, "ua": (request.headers.get("user-agent") if request else None),
        "created_at": now,
    })
    # AVISAR. Sin esto, el mensaje se guardaba y no se enteraba nadie, mientras
    # a quien escribe se le prometia respuesta en 24 h. Dos personas escribieron
    # el 15-08-2026 -los dos preguntando por un puesto de trabajo- y el aviso no
    # salio de la base de datos. Un buzon que nadie abre es peor que no tenerlo:
    # promete algo que no se cumple.
    try:
        lineas = [
            "Nuevo mensaje en flotadsp.com",
            f"De: {name or '(sin nombre)'} <{email}>",
            f"Empresa: {company or '-'}",
            "",
            (plan or "(sin mensaje)")[:600],
        ]
        await _telegram_aviso(chr(10).join(lineas))
    except Exception as e:
        # Que falle el aviso no puede tumbar la recogida del mensaje: lo
        # importante es no perderlo. Pero se deja en el log para poder verlo.
        logger.warning(f"aviso de lead no enviado: {type(e).__name__}: {e}")
    return {"ok": True, "mensaje": "¡Recibido! Te respondemos en menos de 24 horas hábiles."}


