# DRIVERS — solo admin
# =========================

@api_router.post("/drivers", response_model=Driver)
async def create_driver(data: DriverCreate, nueva: bool = False,
                        admin: dict = Depends(require_admin)):
    driver_data = data.model_dump()
    password = driver_data.pop("password", None)

    if isinstance(driver_data.get("name"), str):
        driver_data["name"] = re.sub(r"\s+", " ", driver_data["name"]).strip()
    # Mismo criterio que al editar: el movil personal se guarda ya montado, o no
    # se guarda. Vacio = sin movil personal, no una cadena vacia en la ficha.
    crudo = str(driver_data.get("movil_personal") or "").strip()
    if crudo:
        e164 = whatsapp.normaliza_telefono(crudo)
        if not e164:
            raise HTTPException(400, "Ese no parece un movil. Escribelo con 9 cifras "
                                     "(o con el prefijo del pais).")
        driver_data["movil_personal"] = "+" + e164
    else:
        driver_data["movil_personal"] = None
    driver = Driver(**driver_data)
    # UNA PERSONA, UNA FICHA ACTIVA. Esta ruta no comprobaba nada: dos altas
    # con el mismo correo, seguidas o a la vez, daban dos fichas, y el login
    # del portal cae en la que Mongo tenga primero (gotcha 15). Se compara sin
    # distinguir mayusculas y solo contra las activas: una persona que vuelve
    # tras una baja se da de alta otra vez con normalidad.
    email = (driver.email or "").strip()
    if email:
        otra = await db.drivers.find_one(
            {"email": {"$regex": "^%s$" % re.escape(email), "$options": "i"},
             "active": {"$ne": False}}, {"_id": 0, "id": 1, "name": 1})
        if otra:
            raise HTTPException(
                409, "Ya hay un conductor activo con el correo %s (%s). Edita esa "
                     "ficha o cambia el correo." % (email, otra.get("name") or otra.get("id")))
        # UNA PERSONA QUE VUELVE TRAS UNA BAJA RECUPERA SU FICHA. Crear otra
        # partia su historial en dos: el 09-09-2026 se dio de alta a David
        # Freire con ficha nueva mientras la suya —con su Transporter ID y
        # cuatro inspecciones— seguia de baja, y /drivers/duplicados lo marco.
        # No se decide por nadie: se para y se ofrece reactivar; quien sepa que
        # es otra persona con el mismo correo lo repite con `?nueva=true`.
        if not nueva:
            baja = await db.drivers.find_one(
                {"email": {"$regex": "^%s$" % re.escape(email), "$options": "i"},
                 "active": False, "status": {"$nin": ["deleted", "fusionada"]},
                 "merged_into": {"$exists": False}},
                {"_id": 0, "id": 1, "name": 1})
            if baja:
                raise HTTPException(409, {
                    "mensaje": "%s ya tiene una ficha dada de baja con este correo. "
                               "Reactivala para conservar su historial." % (baja.get("name") or email),
                    "reactivar_id": baja["id"], "nombre": baja.get("name") or "",
                })
    doc = serialize_doc(driver.model_dump())
    try:
        await db.drivers.insert_one(doc)
    except DuplicateKeyError:
        # Dos altas A LA VEZ: la comprobacion de arriba las deja pasar a las
        # dos y solo el indice `email_unico_activo` para a la segunda.
        raise HTTPException(409, "Ya hay un conductor activo con el correo %s." % email)

    if password and driver.email:
        await db.driver_accounts.insert_one({
            "id": str(uuid.uuid4()),
            "driver_id": driver.id,
            "email": driver.email,
            "hashed_password": hash_password(password),
            "active": True,
            "created_at": datetime.now(timezone.utc).isoformat()
        })
        logger.info(f"Conductor y cuenta creados: {driver.email}")

    return driver


_CENTRO_RE = re.compile(r"\b([A-Z]{2,4}\d{1,2})\b")


def _centro_norm(valor, conocidos=None) -> str:
    """Deja el centro en su codigo: 'AMZL OGA5 SANTIAGO XPT' -> 'OGA5'.

    El mismo centro esta guardado de siete formas en `vehicles`: 'OGA5' (76),
    'AMZL OGA5 SANTIAGO XPT' (37), 'oga5' (5), 'OGA5 ' (2)... El gotcha 6 lo
    documenta y por eso los filtros van por `$regex`, pero eso arregla la
    LECTURA, no el dato: cualquier recuento nuevo que agrupe por centro parte
    OGA5 en dos mitades sin avisar. Paso el 28-08-2026 contando la flota.

    NO ADIVINA. Solo reescribe cuando dentro del texto aparece EXACTAMENTE UN
    codigo que ya existe limpio en la base. Un centro nuevo que nadie haya
    escrito bien todavia se queda como esta, que es mejor que renombrarlo a algo
    que no es. Devuelve el original —solo recortado y en mayusculas— si no lo
    tiene claro.
    """
    t = str(valor or "").strip().upper()
    if not t:
        return ""
    if conocidos and t in conocidos:
        return t
    hallados = {c for c in _CENTRO_RE.findall(t) if not conocidos or c in conocidos}
    return hallados.pop() if len(hallados) == 1 else t


async def _centro_por_defecto() -> str:
    """El centro que se usa cuando no viene ninguno.

    Tres sitios lo tenian escrito como "OGA5" —importar cuadrante y las dos
    rutas del plan de reparto—, o sea el centro de la empresa principal. En
    cualquier otra, esos datos se guardaban en un centro que no existe en su
    flota y no volvian a aparecer en ninguna pantalla, sin ningun error.

    Se usa el PRIMERO de `organizations.centers`, que es el principal: el que
    la empresa escribio al darse de alta. Ordenar alfabeticamente parecia mas
    limpio y era peor — a la empresa principal le habria cambiado el centro por
    defecto de OGA5 a DGA1 en silencio, que es exactamente el tipo de cambio
    que nadie nota hasta que faltan datos en una pantalla.

    Si la organizacion no se encuentra, se cae a los centros que ya existen en
    los datos; y si tampoco hay, cadena vacia: mejor que decida quien llama,
    antes que inventarse el centro de otro.
    """
    try:
        org = await global_db.organizations.find_one(
            {"db_name": _current_db_name.get()}, {"_id": 0, "centers": 1})
        if not org and _current_db_name.get() == _DEFAULT_DB_NAME:
            # La organizacion principal no guarda `db_name`: se resuelve por
            # `account_type == "owner"` (ver `_tenant_db_name`).
            org = await global_db.organizations.find_one(
                {"account_type": "owner"}, {"_id": 0, "centers": 1})
        cs = [str(c).strip().upper() for c in ((org or {}).get("centers") or []) if str(c).strip()]
        if cs:
            return cs[0]
        conocidos = sorted(c for c in await _centros_conocidos() if c)
        return conocidos[0] if conocidos else ""
    except Exception:
        return ""


async def _centros_conocidos() -> set:
    """Los codigos de centro que ya existen escritos limpios.

    Se sacan de `drivers`, que es la coleccion que los tiene bien (medido: 4
    formas y todas limpias), y no de `vehicles`, que es justo la sucia. Sin esta
    lista, `_centro_norm` no puede distinguir un codigo de verdad de tres letras
    y un numero que aparezcan por casualidad en un texto libre.
    """
    fuera = set()
    for col in ("drivers", "workshops"):
        for v in await db[col].distinct("center"):
            t = str(v or "").strip().upper()
            if t and _CENTRO_RE.fullmatch(t):
                fuera.add(t)
    return fuera


@api_router.get("/drivers/duplicados")
async def drivers_duplicados(_=Depends(require_admin)):
    """La misma persona dada de alta dos veces, emparejada por CORREO.

    Por correo y nunca por nombre: dos tocayos distintos acabarian fusionados y
    uno auditando la furgoneta del otro. El correo lo pone la empresa y es unico
    por persona (gotcha 15).

    Esto ya costo un dia de operacion. El 19-08-2026 hubo cinco conductores en
    ruta viendo "no tienes furgoneta asignada": el cuadrante apuntaba a una
    ficha y el login del portal resuelve por correo con `find_one`, que devuelve
    la que Mongo tenga primero — normalmente la otra. Medido el 28-08-2026
    seguian 13 correos con dos fichas, 14 fichas de mas.

    De cada ficha se cuenta lo que cuelga de ella para poder decidir cual se
    queda: la que tiene el historial, no la que se creo antes.

    OJO AL ORDEN: declarado ANTES de /drivers/{driver_id}/... o 'duplicados'
    entraria como si fuera un id.
    """
    porcorreo: dict = {}
    async for d in db.drivers.find({}, {"_id": 0}):
        e = (d.get("email") or "").strip().lower()
        if not e or d.get("merged_into"):
            continue
        porcorreo.setdefault(e, []).append(d)
    grupos = {e: v for e, v in porcorreo.items() if len(v) > 1}
    if not grupos:
        return {"grupos": [], "total": 0, "fichas_de_mas": 0}

    ids = [d["id"] for v in grupos.values() for d in v if d.get("id")]
    async def _cuenta(col, campo):
        out: dict = {}
        async for r in db[col].aggregate([
            {"$match": {campo: {"$in": ids}}},
            {"$group": {"_id": "$" + campo, "n": {"$sum": 1}}},
        ]):
            out[r["_id"]] = r["n"]
        return out
    insp = await _cuenta("inspections", "driver_id")
    turnos = await _cuenta("shifts", "driver_id")
    pets = await _cuenta("shift_requests", "driver_id")
    asig: dict = {}
    async for a_doc in db.daily_assignments.find({}, {"_id": 0, "slots": 1}):
        for sl in (a_doc.get("slots") or []):
            if sl.get("driver_id") in ids:
                asig[sl["driver_id"]] = asig.get(sl["driver_id"], 0) + 1

    fuera = []
    for e, fichas in sorted(grupos.items()):
        filas = []
        for d in fichas:
            i = d["id"]
            filas.append({
                "id": i, "nombre": d.get("name"), "center": d.get("center"),
                "creada": str(d.get("created_at") or "")[:10],
                "telefono": d.get("phone") or d.get("telefono"),
                "inspecciones": insp.get(i, 0), "turnos": turnos.get(i, 0),
                "peticiones": pets.get(i, 0), "asignaciones": asig.get(i, 0),
            })
            filas[-1]["total"] = sum(filas[-1][k] for k in
                                     ("inspecciones", "turnos", "peticiones", "asignaciones"))
        # La que mas historial tiene primero: es la que conviene conservar.
        filas.sort(key=lambda x: -x["total"])
        fuera.append({"email": e, "fichas": filas, "sugerida": filas[0]["id"]})
    return {"grupos": fuera, "total": len(fuera),
            "fichas_de_mas": sum(len(g["fichas"]) - 1 for g in fuera)}


# ── IMPORTAR CONDUCTORES DE GOLPE ───────────────────────────────────────────
# Una empresa que empieza tiene la plantilla en un Excel, y darla de alta a mano
# —cincuenta fichas, una a una— es el motivo por el que la mayoría de las
# aplicaciones de flota se abandonan la primera semana.
#
# Dos decisiones que hacen que esto funcione de verdad:
#
#   1. NO SE PIDE UNA PLANTILLA. Se lee el Excel que ya tienen, con las columnas
#      que ya usan. Pedir un formato concreto es trasladarles el trabajo:
#      reconocer «Nombre», «NOMBRE Y APELLIDOS» o «Driver name» lo hacemos aquí
#      una vez, y ellos no hacen nada.
#   2. SE ENSEÑA ANTES DE GUARDAR. Primero se dice qué se ha entendido, cuántos
#      se darían de alta y qué filas se van a saltar y por qué. Importar a ciegas
#      y descubrir que han entrado 50 fichas mal es peor que no importar.
#
# El teléfono y el correo se normalizan al entrar, porque el gotcha 15 nació
# justo de aquí: nombres con espacios de más y correos en mayúsculas crearon
# 17 personas duplicadas y cinco conductores acabaron viendo la furgoneta de
# otro.

# Cómo se llama cada cosa en los Excel que se ven de verdad. El orden importa:
# gana la primera que case.
_IMP_COLS = {
    "name": ("nombre y apellidos", "nombre completo", "nombre", "conductor",
             "driver name", "empleado", "trabajador", "apellidos y nombre"),
    "dni": ("dni", "nif", "documento", "dni/nie", "nie", "id documento"),
    "phone": ("telefono", "teléfono", "movil", "móvil", "tlf", "phone", "contacto"),
    "email": ("email", "correo", "correo electronico", "correo electrónico",
              "e-mail", "mail"),
    "driver_id": ("driver id", "id conductor", "id empleado", "nº empleado",
                  "n empleado", "numero empleado", "número empleado",
                  "codigo empleado", "código empleado"),
    "center": ("centro", "estacion", "estación", "nave", "station", "site"),
    "license_number": ("carnet", "licencia", "permiso", "license"),
    "contrato": ("contrato", "tipo contrato", "empresa/ett", "modalidad"),
}


def _imp_norm(s) -> str:
    """Texto de cabecera comparable: sin tildes, sin dobles espacios, en bajas."""
    t = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
    return re.sub(r"\s+", " ", t).strip().lower()


def _imp_mapea(cabecera: list) -> dict:
    """{indice de columna: campo}. Solo la PRIMERA columna que case cada campo.

    Sin ese «solo la primera», un Excel con «Teléfono» y «Teléfono 2» mapearía
    las dos al mismo campo y la segunda pisaría a la primera.
    """
    mapa, usados = {}, set()
    limpio = [_imp_norm(c) for c in cabecera]
    for campo, nombres in _IMP_COLS.items():
        for n in nombres:
            for i, c in enumerate(limpio):
                if i in mapa or campo in usados:
                    continue
                if c == n or (len(n) > 4 and n in c):
                    mapa[i] = campo
                    usados.add(campo)
                    break
            if campo in usados:
                break
    return mapa


def _imp_cabecera(filas: list) -> int:
    """En qué fila está la cabecera.

    No siempre es la primera: los Excel de gestoría traen el logo, el mes y un
    par de filas vacías antes. Se busca la que más columnas reconocidas tenga.
    """
    mejor, mejor_n = 0, 0
    for i, f in enumerate(filas[:15]):
        n = len(_imp_mapea(f))
        if n > mejor_n:
            mejor, mejor_n = i, n
    return mejor if mejor_n >= 1 else 0


_IMP_RESUMEN = ("total", "totales", "suma", "subtotal", "recuento", "n conductores",
                "num conductores", "plantilla", "resumen")


def _imp_es_resumen(nombre: str) -> bool:
    """Si esa «persona» es en realidad la fila de totales del final.

    Se compara contra el nombre ENTERO o su primera palabra, no por «contiene»:
    hay apellidos que empiezan por Suma y no queremos tirar a nadie de verdad.
    """
    t = _imp_norm(nombre)
    if t in _IMP_RESUMEN:
        return True
    # «TOTAL: 47», «TOTAL 47», «Total conductores»
    primera = t.split(":")[0].split()[0] if t.split() else ""
    return primera in _IMP_RESUMEN and len(t.split()) <= 3


def _imp_lee(filas: list) -> dict:
    """Convierte las filas del Excel en fichas, diciendo qué se salta y por qué."""
    if not filas:
        return {"cabecera": [], "mapa": {}, "personas": [], "saltadas": []}
    ic = _imp_cabecera(filas)
    mapa = _imp_mapea(filas[ic])
    personas, saltadas, vistos = [], [], set()

    for n, fila in enumerate(filas[ic + 1:], start=ic + 2):
        d = {}
        for i, campo in mapa.items():
            if i < len(fila):
                d[campo] = str(fila[i] or "").strip()
        nombre = re.sub(r"\s+", " ", (d.get("name") or "")).strip()
        if not nombre:
            # Una fila sin nombre no es un error: son los totales y las filas en
            # blanco del final. Se cuentan aparte para no asustar con «40 filas
            # con problemas» cuando son cuarenta líneas vacías.
            if any(v for v in d.values()):
                saltadas.append({"fila": n, "motivo": "no tiene nombre"})
            continue
        if len(nombre) < 3:
            saltadas.append({"fila": n, "motivo": "el nombre es demasiado corto: %r" % nombre})
            continue
        # Las filas de resumen del final. Casi todos los Excel de plantilla
        # llevan una, y sin esto se daba de alta un conductor llamado
        # «TOTAL: 47» — basura que luego sale en el cuadrante y en las listas.
        if _imp_es_resumen(nombre):
            saltadas.append({"fila": n, "motivo": "parece una fila de totales: %r" % nombre})
            continue

        correo = (d.get("email") or "").strip().lower()
        if correo and not _EMAIL_RE.match(correo):
            correo = ""
        clave = correo or _imp_norm(nombre)
        if clave in vistos:
            saltadas.append({"fila": n, "motivo": "repetido en el propio fichero: %s" % nombre})
            continue
        vistos.add(clave)

        personas.append({
            "name": nombre.upper(),          # como el resto de la base
            "dni": (d.get("dni") or "").strip().upper() or None,
            "phone": whatsapp.normaliza_telefono(d.get("phone")) or None,
            "email": correo or None,
            "driver_id": (d.get("driver_id") or "").strip() or None,
            "center": (d.get("center") or "").strip() or None,
            "centro_texto": (d.get("center") or "").strip(),
            "license_number": (d.get("license_number") or "").strip() or None,
            "fila": n,
        })
    return {"cabecera": [str(c) for c in filas[ic]], "fila_cabecera": ic + 1,
            "mapa": {str(k): v for k, v in mapa.items()},
            "personas": personas, "saltadas": saltadas}


@api_router.post("/drivers/importar/previsualizar")
async def drivers_importar_prev(file: UploadFile = File(...), center: str = Form(""),
                                _=Depends(require_admin)):
    """Qué se importaría, SIN guardar nada."""
    contenido = await file.read()
    try:
        filas = _read_table_any(contenido, file.filename or "")
    except Exception as e:                                       # noqa: BLE001
        raise HTTPException(400, "No se pudo leer el fichero: %s" % str(e)[:120])
    r = _imp_lee(filas)
    if not r["personas"]:
        raise HTTPException(
            400, "No se ha encontrado ninguna persona. Hace falta una columna con "
                 "el nombre — puede llamarse «Nombre», «Conductor», «Nombre y "
                 "apellidos» o «Driver name».")

    # Quién ya está. Por correo, nunca por nombre: dos tocayos son dos personas
    # (gotcha 15), y fusionarlos haría que uno viera la furgoneta del otro.
    correos = [p["email"] for p in r["personas"] if p["email"]]
    ya = {}
    async for d in db.drivers.find({"email": {"$in": correos}},
                                   {"_id": 0, "email": 1, "name": 1}):
        ya[str(d.get("email") or "").lower()] = d.get("name")
    nombres_bd = {_imp_norm(d["name"]) async for d in db.drivers.find(
        {}, {"_id": 0, "name": 1}) if d.get("name")}

    nuevos = repetidos = 0
    for p in r["personas"]:
        p["ya_existe"] = bool(p["email"] and p["email"] in ya) or \
            (not p["email"] and _imp_norm(p["name"]) in nombres_bd)
        if p["ya_existe"]:
            repetidos += 1
        else:
            nuevos += 1
    conocidos = set(c.upper() for c in (await _centros_de_la_empresa()) if c)
    # Un fichero de varias naves: se reparte por centro para que se elija cual
    # entra. Es la misma pieza que usan las furgonetas.
    centros = _grupos_por_centro(
        [{"centro_texto": p["centro_texto"], "nueva": not p["ya_existe"], "ejemplo": p["name"]}
         for p in r["personas"]], conocidos)

    return {
        "columnas_reconocidas": r["mapa"],
        "cabecera": r["cabecera"], "fila_cabecera": r["fila_cabecera"],
        "total_leidas": len(r["personas"]),
        "nuevas": nuevos, "ya_estaban": repetidos,
        "saltadas": r["saltadas"][:40], "n_saltadas": len(r["saltadas"]),
        # Las primeras, para que se vea que se ha entendido bien antes de tocar
        # nada. Es la diferencia entre importar y importar a ciegas.
        "muestra": r["personas"][:12],
        "centro_por_defecto": center,
        "sin_correo": sum(1 for p in r["personas"] if not p["email"]),
        "centros": centros,
        "centros_empresa": sorted(conocidos),
    }


@api_router.post("/drivers/importar")
async def drivers_importar(file: UploadFile = File(...), center: str = Form(""),
                           centros: Optional[str] = Form(None),
                           mapa: Optional[str] = Form(None),
                           user: dict = Depends(require_admin)):
    """Da de alta lo que no esté ya. Nunca pisa una ficha existente."""
    contenido = await file.read()
    try:
        filas = _read_table_any(contenido, file.filename or "")
    except Exception as e:                                       # noqa: BLE001
        raise HTTPException(400, "No se pudo leer el fichero: %s" % str(e)[:120])
    r = _imp_lee(filas)
    if not r["personas"]:
        raise HTTPException(400, "No se ha encontrado ninguna persona en el fichero.")

    correos = [p["email"] for p in r["personas"] if p["email"]]
    ya = set()
    async for d in db.drivers.find({"email": {"$in": correos}}, {"_id": 0, "email": 1}):
        ya.add(str(d.get("email") or "").lower())
    nombres_bd = {_imp_norm(d["name"]) async for d in db.drivers.find(
        {}, {"_id": 0, "name": 1}) if d.get("name")}

    ahora = datetime.now(timezone.utc).isoformat()
    quien = user.get("name") or user.get("username") or "importación"
    # El centro de la empresa, si solo tiene uno. Se saca de la organizacion y
    # no de los conductores que ya haya: en una empresa nueva no hay ninguno.
    unico_centro = ""
    try:
        org = await get_org(user.get("org_id"))
        # OJO con el nombre: `centros` es el campo del formulario (lo que se
        # eligio en la vista previa). Esta lista se llamaba igual y lo PISABA,
        # asi que importar conductores daba 400 siempre (17-09-2026).
        naves_org = [c for c in ((org or {}).get("centers") or []) if c]
        if len(naves_org) == 1:
            unico_centro = naves_org[0]
    except Exception:                                            # noqa: BLE001
        pass
    conocidos = set(c.upper() for c in (await _centros_de_la_empresa()) if c)
    elegidos, destino = _eleccion_centros(centros, mapa, conocidos)
    nuevos, saltados, fuera_seleccion = [], [], 0
    for p in r["personas"]:
        clave = p.pop("centro_texto", "").upper()
        if elegidos is not None and clave not in elegidos:
            fuera_seleccion += 1
            continue
        # El centro, como CODIGO: el que se eligio para ese grupo, o el que se
        # lee en el texto. Antes se guardaba «AMZL OGA5 SANTIAGO XPT» tal cual
        # y esa persona no salia en las listas filtradas por OGA5 (gotcha 6).
        codigo = destino.get(clave) or _veh_centro_de(clave, conocidos)
        if codigo:
            p["center"] = codigo
        existe = (p["email"] and p["email"] in ya) or \
            (not p["email"] and _imp_norm(p["name"]) in nombres_bd)
        if existe:
            # NO se actualiza la ficha que ya está. Importar es dar de alta lo
            # que falta; pisar datos buenos con los de un Excel viejo es la
            # forma más rápida de que se deje de confiar en la aplicación.
            saltados.append({"nombre": p["name"], "motivo": "ya estaba dado de alta"})
            continue
        d = {k: v for k, v in p.items() if k != "fila" and v is not None}
        d.update({"id": str(uuid.uuid4()), "active": True,
                  "created_at": ahora, "updated_at": ahora,
                  "importado_por": quien, "importado_en": ahora})
        if not d.get("center"):
            # El centro que venga del formulario; y si no hay ninguno, el unico
            # de la empresa. Casi todos los DSP empiezan con una sola nave, y
            # sin centro los conductores NO SALEN en ninguna lista filtrada:
            # importas cincuenta y parece que no ha funcionado nada.
            d["center"] = (center if center and center not in ("Todos", "todos")
                           else (unico_centro or None))
        nuevos.append(d)
        if p["email"]:
            ya.add(p["email"])
        else:
            nombres_bd.add(_imp_norm(p["name"]))

    metidos = len(nuevos)
    if nuevos:
        try:
            await db.drivers.insert_many(nuevos, ordered=False)
        except BulkWriteError as e:
            # Dos importaciones a la vez del mismo fichero: los correos que ya
            # entraron por la otra los para el indice `email_unico_activo`, el
            # resto entra igual (`ordered=False`). Se cuenta lo que entro.
            metidos = int((e.details or {}).get("nInserted") or 0)
            saltados = saltados + [None] * (len(nuevos) - metidos)
    logger.info("Conductores importados: %d nuevos, %d ya estaban", metidos, len(saltados))
    return {"importados": metidos, "ya_estaban": len(saltados),
            "no_leidas": len(r["saltadas"]), "fuera_seleccion": fuera_seleccion,
            "nombres": [d["name"] for d in nuevos][:50]}


# DONDE SE APUNTA A UN CONDUCTOR. Una sola lista, porque el fallo de fusionar
# no es fusionar mal: es OLVIDARSE de un sitio, y eso deja el historial de una
# persona partido en dos sin que nada falle. Sacada de la base de produccion
# barriendo TODAS las colecciones en busca de campos con forma de uuid de ficha
# —no de memoria—, el 08-09-2026. Las dos ultimas no estaban y por eso 41
# apuntes de kilometros y 14 inspecciones seguian colgando de fichas ya
# absorbidas.
_DONDE_EL_CONDUCTOR = (
    ("inspections", "driver_id"),
    ("shifts", "driver_id"),
    ("shift_requests", "driver_id"),
    ("incidents", "driver_id"),
    ("tienda_pedidos", "driver_id"),
    ("parking_assignments", "driver_id"),
    ("candidatos", "driver_id"),
    ("driver_accounts", "driver_id"),
)


async def _repuntar_conductor(absorber: list, conservar: str, nombre: str) -> dict:
    """Manda a `conservar` todo lo que apuntaba a las fichas absorbidas."""
    movidos = {}
    for col, campo in _DONDE_EL_CONDUCTOR:
        r = await db[col].update_many({campo: {"$in": absorber}},
                                      {"$set": {campo: conservar}})
        if r.modified_count:
            movidos["%s.%s" % (col, campo)] = r.modified_count
    # Los dos que viven dentro de un array necesitan `array_filters`.
    r = await db.daily_assignments.update_many(
        {"slots.driver_id": {"$in": absorber}},
        {"$set": {"slots.$[s].driver_id": conservar, "slots.$[s].driver_name": nombre}},
        array_filters=[{"s.driver_id": {"$in": absorber}}])
    if r.modified_count:
        movidos["daily_assignments.slots"] = r.modified_count
    # Los kilometros: aqui estaba el agujero mas gordo —41 apuntes— y no se veia
    # porque un historial de km no lo echa en falta nadie hasta que hay que
    # mirar quien puso ese numero.
    r = await db.vehicles.update_many(
        {"mileage_history.driver_id": {"$in": absorber}},
        {"$set": {"mileage_history.$[m].driver_id": conservar}},
        array_filters=[{"m.driver_id": {"$in": absorber}}])
    if r.modified_count:
        movidos["vehicles.mileage_history"] = r.modified_count
    return movidos


@api_router.post("/drivers/fusiones/repasar")
async def drivers_fusiones_repasar(_=Depends(require_admin)):
    """Repunta lo que siga colgando de una ficha ya absorbida.

    Hace falta aunque fusionar este bien: una inspeccion creada DESPUES de la
    fusion —alguien que entro con la ficha vieja antes de que se le cerrara—
    vuelve a quedarse huerfana, y ademas los dos sitios que faltaban llevan
    meses sin repuntarse. Es idempotente: si no hay nada que mover, no mueve.
    """
    absorbidas = await db.drivers.find(
        {"merged_into": {"$exists": True}},
        {"_id": 0, "id": 1, "merged_into": 1}).to_list(500)
    porDestino: dict = {}
    for f in absorbidas:
        porDestino.setdefault(f["merged_into"], []).append(f["id"])
    total: dict = {}
    for destino, ids in porDestino.items():
        buena = await db.drivers.find_one({"id": destino}, {"_id": 0, "name": 1})
        if not buena:
            continue          # la superviviente ya no esta: no se inventa un destino
        for k, v in (await _repuntar_conductor(ids, destino, buena.get("name") or "")).items():
            total[k] = total.get(k, 0) + v
    return {"ok": True, "fusiones": len(porDestino), "movidos": total}


@api_router.post("/drivers/fusionar")
async def drivers_fusionar(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Une dos fichas de la misma persona en una.

    NO BORRA NADA. La ficha absorbida se marca `merged_into` y se desactiva,
    asi que si el emparejamiento estuviera mal se puede deshacer mirando el
    campo. Borrarla dejaria huerfano cualquier documento que se nos hubiera
    escapado, y eso no se ve hasta que alguien lo echa en falta.

    Se repuntan los CUATRO sitios que apuntan a un conductor, contados sobre la
    base de produccion: inspections, shifts, shift_requests y los slots de
    daily_assignments. Se comprueban en un test, no de memoria.
    """
    conservar = str(data.get("conservar") or "").strip()
    absorber = [str(x).strip() for x in _lista_cuerpo(data.get("absorber")) if str(x).strip()]
    if not conservar or not absorber:
        raise HTTPException(400, "Hace falta cual se conserva y cual se absorbe")
    if conservar in absorber:
        raise HTTPException(400, "Una ficha no se puede absorber a si misma")

    buena = await db.drivers.find_one({"id": conservar}, {"_id": 0})
    if not buena:
        raise HTTPException(404, "La ficha que se conserva no existe")
    otras = await db.drivers.find({"id": {"$in": absorber}}, {"_id": 0}).to_list(20)
    if len(otras) != len(absorber):
        raise HTTPException(404, "Alguna de las fichas a absorber no existe")
    # Mismo correo o no se toca: es la unica prueba de que son la misma persona.
    correo = (buena.get("email") or "").strip().lower()
    for o in otras:
        if (o.get("email") or "").strip().lower() != correo or not correo:
            raise HTTPException(400,
                                "Solo se fusionan fichas con el MISMO correo. "
                                "Por nombre no: dos tocayos acabarian mezclados.")

    movidos = await _repuntar_conductor(absorber, conservar, buena.get("name") or "")

    # Lo que le falte a la buena se lo queda de las otras: telefono, foto,
    # DNI... Nunca al reves — la buena manda.
    def _vacio(v):
        return v is None or (isinstance(v, str) and not v.strip())

    relleno = {}
    for campo in ("phone", "telefono", "photo_url", "dni", "center", "driver_id"):
        if not _vacio(buena.get(campo)):
            continue                      # la buena ya lo tiene: manda ella
        for o in otras:
            v = o.get(campo)
            if isinstance(v, str) and v.strip():
                relleno[campo] = v.strip()
                break
    ahora = datetime.now(timezone.utc).isoformat()
    if relleno:
        await db.drivers.update_one({"id": conservar}, {"$set": relleno})
    await db.drivers.update_many({"id": {"$in": absorber}}, {"$set": {
        "merged_into": conservar, "active": False, "status": "fusionada",
        "merged_at": ahora, "merged_by": user.get("name") or "oficina"}})
    logger.info("Fichas fusionadas en %s: %s (movidos %s)", conservar, absorber, movidos)
    return {"ok": True, "conservada": conservar, "absorbidas": absorber,
            "movidos": movidos, "rellenado": relleno}


@api_router.get("/drivers", response_model=List[Driver])
async def get_drivers(center: Optional[str] = None, user: dict = Depends(require_admin)):
    query = {"active": {"$ne": False}}
    query.update(_filtro_centro(user, center))
    drivers = await db.drivers.find(query, {"_id": 0}).to_list(1000)
    return drivers


@api_router.patch("/drivers/{driver_id}")
async def update_driver(driver_id: str, data: dict, _=Depends(require_admin)):
    _DRIVER_ALLOWED = {
        "name","email","phone","center","notes","photo_url","active","dni",
        "license_number","license_expiry","address","emergency_contact",
        "contract_type","hire_date","tags","score_override",
        # Campos del formulario del panel (antes se filtraban y el guardado
        # fallaba en silencio): contrato/nivel/zona + ficha extendida.
        "contrato","nivel","zona","driver_id","alojamiento","notas","login",
        # Poder apagar el WhatsApp de UNA persona sin apagarlo para todos.
        # Sin esto en la whitelist, el campo se descartaria en silencio al
        # guardar y la casilla del panel no haria nada (gotcha 1).
        "whatsapp_opt_in",
        # Ver `Driver.movil_personal`. Sin esto aqui se descartaria en silencio
        # al guardar y la casilla del panel no haria nada (gotcha 1).
        "movil_personal",
    }
    data = {k: v for k, v in data.items() if k in _DRIVER_ALLOWED}
    # El nombre sin espacios de mas: 18 fichas activas los tenian (« Karim…») y
    # salian las primeras de la lista, y dos iguales con un espacio de diferencia
    # son la misma persona (gotcha 15).
    if isinstance(data.get("name"), str):
        data["name"] = re.sub(r"\s+", " ", data["name"]).strip()

    quitar = {}

    # Quien puso el telefono: la oficina, el propio conductor desde su portal o
    # la candidatura de empleo. Sirve para saber de quien fiarse si no coinciden.
    if "phone" in data and str(data.get("phone") or "").strip():
        data["telefono_por"] = "oficina"

    # EL MOVIL PERSONAL SE GUARDA YA MONTADO (+34...). Un numero mal escrito no
    # da error al enviar: Meta contesta 200 y el mensaje no llega a nadie. Se
    # rechaza aqui, donde la oficina lo esta escribiendo y lo puede corregir, y
    # no el dia que sale un aviso.
    if "movil_personal" in data:
        crudo = str(data.get("movil_personal") or "").strip()
        if not crudo:
            data.pop("movil_personal")
            quitar["movil_personal"] = ""
        else:
            e164 = whatsapp.normaliza_telefono(crudo)
            if not e164:
                raise HTTPException(400, "Ese no parece un movil. Escribelo con 9 cifras "
                                         "(o con el prefijo del pais).")
            data["movil_personal"] = "+" + e164

    cambio = {}
    if data:
        cambio["$set"] = data
    if quitar:
        cambio["$unset"] = quitar
    if not cambio:
        return {"success": True, "sin_cambios": True}
    try:
        result = await db.drivers.update_one({"id": driver_id}, cambio)
    except DuplicateKeyError:
        raise HTTPException(409, "Ese correo ya lo tiene otro conductor activo.")
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Conductor no encontrado")
    return {"success": True}


# =========================
# DRIVER — su propio perfil
# =========================

@api_router.get("/me/driver")
async def get_my_driver_profile(user: dict = Depends(require_any_auth)):
    if user["role"] == "admin":
        raise HTTPException(status_code=400, detail="Usa /api/auth/me para admins")
    driver = await db.drivers.find_one({"id": user["sub"]}, {"_id": 0})
    if not driver:
        raise HTTPException(status_code=404, detail="Perfil no encontrado")
    return driver


@api_router.get("/me/vehicle")
async def get_my_current_vehicle(user: dict = Depends(require_any_auth)):
    vehicle = await db.vehicles.find_one(
        {"current_driver_id": user["sub"]}, {"_id": 0}
    )
    if not vehicle:
        raise HTTPException(status_code=404, detail="No tienes ningún vehículo asignado")
    return vehicle


# =========================
# INSPECTIONS — upload
# =========================

@api_router.post("/inspections/upload")
async def upload_inspection_photos(
    vehicle_id: str = Form(...),
    driver_id: Optional[str] = Form(None),
    notes: str = Form(""),
    files: List[UploadFile] = File(...),
    user: dict = Depends(require_any_auth)
):
    notes = (notes or "")[:2000]
    if not files:
        raise HTTPException(status_code=400, detail="Se requiere al menos una imagen.")
    if len(files) > 20:
        raise HTTPException(status_code=400, detail="Máximo 20 imágenes por inspección.")

    # Anti-duplicados: una inspección por vehículo+conductor al día (evita doble
    # tap con mala cobertura, análisis duplicados y Telegram repetido).
    # Los admins pueden repetir (peritajes manuales desde el panel).
    if user.get("role") == "driver":
        today = _dia_negocio()
        dup = await db.inspections.find_one({
            "deleted": {"$ne": True}, "vehicle_id": vehicle_id,
            "driver_id": driver_id or user.get("sub"),
            "created_at": {"$regex": f"^{today}"}
        }, {"_id": 0, "id": 1})
        if dup:
            raise HTTPException(
                status_code=409,
                detail="Ya enviaste la inspección de esta furgoneta hoy. Si necesitas repetirla, avisa a tu coordinador."
            )

    # ── ¿Puede este conductor inspeccionar ESTA furgoneta? ───────────────────
    # Mandaba el centro del conductor contra el de la furgoneta, y punto. Pero
    # los conductores se prestan entre naves: uno de DGA2 trabajando hoy en
    # OGA5 hacía las cinco fotos, el cuentakilómetros y el checklist entero, y
    # al darle a enviar se comía un "solo puedes subir inspecciones de
    # vehículos de tu centro". Todo el trabajo a la basura por una regla que no
    # miraba lo único que importa.
    #
    # Lo que manda es la ASIGNACIÓN: si alguien de la oficina le ha puesto esa
    # furgoneta hoy, es la suya, venga del centro que venga. El centro sólo
    # decide cuando no consta ninguna asignación, y ahí sí protege de que
    # alguien inspeccione una furgoneta de otra nave por error.
    if user["role"] == "driver":
        driver_id = user["sub"]
        vehicle_doc = await db.vehicles.find_one(
            {"id": vehicle_id, "status": {"$ne": "deleted"}}, {"_id": 0, "center": 1, "current_driver_id": 1})
        if not vehicle_doc:
            raise HTTPException(status_code=404, detail="Vehículo no encontrado")

        _yo = await db.drivers.find_one({"id": driver_id}, {"_id": 0, "id": 1, "center": 1, "email": 1})
        mis_ids, _ = await _fichas_misma_persona(_yo or {"id": driver_id})
        asignada_hoy = await db.daily_assignments.find_one(
            {"date": _dia_negocio(),
             "slots": {"$elemMatch": {"driver_id": {"$in": list(mis_ids)}, "vehicle_id": vehicle_id}}},
            {"_id": 0, "center": 1})
        asignada_fija = vehicle_doc.get("current_driver_id") in mis_ids

        if not (asignada_hoy or asignada_fija):
            driver_doc = await db.drivers.find_one({"id": driver_id}, {"_id": 0, "center": 1})
            driver_center = (driver_doc.get("center") or "")[:4] if driver_doc else ""
            vehicle_center = (vehicle_doc.get("center") or "")[:4]
            # El centro del conductor es corto ("OGA5") y el de la furgoneta
            # puede ser largo ("AMZL OGA5 SANTIAGO XPT"): basta con que uno
            # contenga al otro (gotcha 6: el centro está sucio en la BD).
            if driver_center and vehicle_center:
                dc = driver_center.upper()
                vc = (vehicle_doc.get("center") or "").upper()
                if dc not in vc and vc[:4] not in dc:
                    raise HTTPException(
                        status_code=403,
                        detail=("Esta furgoneta es de otro centro y hoy no te la han asignado. "
                                "Si estás cubriendo en otra nave, pide que te la asignen en el "
                                "cuadrante de hoy y vuelve a enviarla."),
                    )

    try:
        photo_urls = []
        photos_base64 = []
        photo_roles = []  # angle | odometer | checklist — por nombre de archivo del portal
        photo_vistas = []  # frontal | trasera | lateral_izq | lateral_der | odometro | checklist:x

        vacias = 0
        for file in files:
            content = await file.read()
            if not content:
                vacias += 1
                logger.warning(f"Fichero vacío recibido: {file.filename} — ignorado")
                continue
            validate_image_content(content)
            photo_url, processed_bytes = await process_and_save_image(content, vehicle_id)
            photo_urls.append(photo_url)
            photos_base64.append(base64.b64encode(processed_bytes).decode("utf-8"))
            _fn = (file.filename or "").lower()
            photo_roles.append(
                "odometer" if _fn.startswith("odometro")
                else "fuel" if _fn.startswith("combustible")
                else "checklist" if _fn.startswith("checklist")
                else "angle")
            photo_vistas.append(_vista_de_fichero(_fn))

        if not photo_urls:
            # QUE PASO DE VERDAD, que no es lo que decia antes. Si se llega aqui
            # con ficheros vacios, las fotos NO estaban mal: se cortó la subida
            # a medias, que en una furgoneta con mala cobertura es lo normal.
            # Medido el 20-09-2026 en `audit_requests`: tres subidas acabaron en
            # este 400 **despues de 58, 75 y 97 segundos**, o sea con el
            # conductor esperando minuto y medio en la calle para leer que sus
            # fotos «no son validas». Las que de verdad estan mal ya salen antes
            # con su propio mensaje (413 pesa demasiado, 415 no es JPEG o PNG,
            # 422 demasiado pequena), asi que aqui solo caben las vacias.
            logger.warning("Subida de inspeccion sin ninguna foto entera: %d de %d "
                           "llegaron vacias (vehiculo %s)", vacias, len(files), vehicle_id)
            raise HTTPException(
                status_code=400,
                detail=("No llegó ninguna foto entera — casi siempre es la cobertura, "
                        "no las fotos. No se ha guardado nada: vuelve a enviarlas desde "
                        "un sitio con señal y, si puedes, de una en una."))

        # El análisis de daños SOLO mira la carrocería: las fotos del cuentakm y
        # del checklist confundían a la IA (daños fantasma en salpicaderos) y
        # gastaban tokens. Se guardan igual, pero no entran al análisis.
        analysis_photo_idx = [i for i, r in enumerate(photo_roles) if r == "angle"]
        if not analysis_photo_idx:  # nombres inesperados → comportamiento clásico
            analysis_photo_idx = list(range(len(photo_urls)))
        analysis_b64 = [photos_base64[i] for i in analysis_photo_idx]
        # índice en el análisis (1-based) → índice real en photos (1-based)
        analysis_idx_map = {k + 1: analysis_photo_idx[k] + 1 for k in range(len(analysis_photo_idx))}

        logger.info(f"Guardadas {len(photo_urls)} fotos — vehículo {vehicle_id}")

        # Si el nombre de algun fichero no trae la vista, se reconstruye por el
        # orden (mismo criterio que para las inspecciones antiguas).
        if any(v is None for v in photo_vistas):
            photo_vistas = _vistas_inspeccion({"photos": photo_urls, "photo_roles": photo_roles})
        # Referencia de cada foto: la ultima de SU misma vista de esta furgoneta.
        ref_photo_urls = await _referencias_por_vista(vehicle_id, photo_vistas)
        ref_bytes_list, ref_labels = await _referencias_para_ia(
            ref_photo_urls, photo_vistas, analysis_photo_idx)
        cur_labels = [_VISTA_NOMBRE.get(photo_vistas[i], "") for i in analysis_photo_idx]
        if ref_bytes_list:
            logger.info(f"Referencia cargada: {len(ref_bytes_list)} imágenes ({', '.join(ref_labels)})")

        # Guardar inspección PRIMERO (sin esperar a Gemini) para responder rápido al conductor
        inspection = Inspection(
            vehicle_id=vehicle_id,
            driver_id=driver_id,
            photos=photo_urls,
            reference_photos=ref_photo_urls if any(ref_photo_urls) else [],
            analysis=None,
            analysis_status="pending",
            analysis_error=None,
            notes=notes,
            analyzed_at=None
        )
        doc = serialize_doc(inspection.model_dump())
        doc["photo_roles"] = photo_roles  # para reanálisis: qué fotos son carrocería
        doc["photo_vistas"] = photo_vistas
        await db.inspections.insert_one(doc)

        # Actualizar automáticamente el kilometraje de la furgoneta con el que la
        # IA leyó del cuentakilómetros en la inspección (el portal del conductor
        # lo manda en notes como odometer_km). Así el km real se refleja al
        # instante en el panel web y en la app, sin ningún paso manual.
        try:
            odo_km = None
            try:
                _n = json.loads(notes) if notes else None
                if isinstance(_n, dict):
                    odo_km = _n.get("odometer_km")
            except Exception:
                odo_km = None
            if isinstance(odo_km, str) and odo_km.strip().isdigit():
                odo_km = int(odo_km.strip())
            if isinstance(odo_km, (int, float)) and odo_km > 0:
                # Antes de registrar: ¿son los mismos km que otro dia?
                _vh = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "mileage_history": 1})
                _dia_rep = _km_repetido((_vh or {}).get("mileage_history"), odo_km, _dia_negocio())
                if _dia_rep:
                    await db.inspections.update_one(
                        {"id": doc.get("id")},
                        {"$set": {"km_repetido": {"km": int(odo_km), "fecha_anterior": _dia_rep}}})
                _origen = "inspeccion_manual" if (isinstance(_n, dict) and _n.get("odometer_manual")) else "inspeccion_foto"
                _aplicado, _motivo, _inf = await _odo_registrar(
                    vehicle_id, int(odo_km), _origen,
                    {"inspection_id": doc.get("id"), "driver_id": driver_id})
                if not _aplicado:
                    # No se escribe, pero queda constancia en la inspeccion para
                    # que el jefe de flota lo vea y lo corrija a mano.
                    await db.inspections.update_one(
                        {"id": doc.get("id")},
                        {"$set": {"odometer_rejected": {"km": int(odo_km),
                                                        "reason": _motivo}}})
        except Exception as _km_e:
            logger.warning(f"Auto-km inspección: {_km_e}")

        # Deposito: el nivel que marca el conductor, con su foto. Un portal
        # abierto desde antes no lo manda: entonces no se registra nada (no es
        # un error, gotcha 76).
        try:
            _nn = json.loads(notes) if notes else None
            _pct = _combustible_nivel(_nn.get("combustible_pct")) if isinstance(_nn, dict) else None
            if _pct is not None:
                _foto_dep = next((u for u, vv in zip(photo_urls, photo_vistas) if vv == "combustible"), "")
                await _combustible_registrar(vehicle_id, doc.get("id"), driver_id, _pct, _foto_dep)
        except Exception as _dep_e:
            logger.warning(f"Depósito inspección: {_dep_e}")

        # Llamar a Gemini en background SOLO si el plan lo permite
        org = await get_org(user.get("org_id"))
        plan_ai = _org_billing(org)["limits"].get("ai", False)

        async def _analyze_and_update():
            try:
                # ── CV PRIMERO: el detector propio ve las fotos antes que Gemini.
                # Sus detecciones (con pieza por geometría) guían el prompt y
                # después corrigen las cajas (snap) sin llamar al servicio 2 veces.
                cv_dets_full = {}  # índice real en photos (1-based) → detecciones
                cv_text = ""
                if AI_SERVICE_URL:
                    try:
                        _cv_lines = []
                        for _k, _full_i in enumerate(analysis_photo_idx, start=1):
                            dets = await _call_ai_service_detect(
                                inspection.id, _full_i, base64.b64decode(photos_base64[_full_i]))
                            if dets:
                                cv_dets_full[_full_i + 1] = dets
                                for det in dets:
                                    _pnl = f" en {det.panel}" if getattr(det, "panel", None) else ""
                                    _cv_lines.append(
                                        f"Foto {_k}: {det.label}{_pnl} (confianza {det.confidence:.2f})")
                        if _cv_lines:
                            cv_text = (
                                "\n=== DETECCIONES DEL DETECTOR CV PROPIO (geometría verificada) ===\n"
                                + "\n".join(_cv_lines) +
                                "\nEstas detecciones vienen de un modelo entrenado con miles de daños "
                                "reales de carrocería; la pieza está determinada por intersección "
                                "geométrica, no por estimación. Úsalas como BASE del análisis: "
                                "confirma y describe con precisión cada una que veas en la foto. "
                                "NO reportes daños adicionales salvo evidencia clara e inequívoca; "
                                "si no ves alguna de estas detecciones, inclúyela con confidence < 0.5."
                            )
                    except Exception as _cve:
                        logger.warning(f"CV pre-análisis: {_cve}")

                analysis, analysis_status, analysis_error = await asyncio.wait_for(
                    analyze_images_with_gemini(analysis_b64, ref_bytes_list if ref_bytes_list else None, db=db,
                                               reference_labels=ref_labels or None,
                                               current_labels=cur_labels,
                                               cv_detections_text=cv_text),
                    timeout=120.0
                )
                # Los photo_index de Gemini son relativos a las fotos analizadas
                # (solo carrocería); remapear al índice real dentro de photos.
                if analysis:
                    _remap_photo_indexes(analysis, analysis_idx_map)
                # Filtro determinista: un panel ya dañado antes NO es "nuevo" otra vez
                if analysis and analysis_status == "ok" and getattr(analysis, "new_damages", None):
                    try:
                        known = await _known_damaged_panels(
                            vehicle_id, before_iso=doc.get("created_at"), exclude_id=inspection.id)
                        if known:
                            kept = [nd for nd in analysis.new_damages
                                    if _canon_panel(getattr(nd, "part", None) or getattr(nd, "zone", None)) not in known]
                            if len(kept) != len(analysis.new_damages):
                                analysis.new_damages = kept
                                analysis.new_damages_count = len(kept)
                    except Exception as _fe:
                        logger.warning(f"Filtro panel-historial: {_fe}")
                # Coste tipo taller (por panel) como total de la inspección
                if analysis and analysis_status == "ok":
                    try:
                        dmg_dicts = [d.model_dump() if hasattr(d, "model_dump") else d
                                     for d in (analysis.damages or [])]
                        analysis.total_estimated_cost = float(_vehicle_panel_cost(dmg_dicts)[0])
                    except Exception as _ce:
                        logger.warning(f"Coste por panel: {_ce}")
                # Snap de cajas al detector CV: el LLM decide el QUÉ, YOLO el DÓNDE
                # (reutiliza las detecciones ya pedidas antes del análisis)
                if cv_dets_full and analysis and analysis_status == "ok" and (analysis.damages or analysis.new_damages):
                    try:
                        _s1 = _snap_damage_boxes_to_yolo(analysis.damages or [], cv_dets_full)
                        _s2 = _snap_damage_boxes_to_yolo(analysis.new_damages or [], cv_dets_full)
                        if _s1 or _s2:
                            logger.info(f"Snap YOLO: {_s1}+{_s2} cajas corregidas insp={inspection.id[:8]}")
                    except Exception as _se:
                        logger.warning(f"Snap YOLO: {_se}")
                await db.inspections.update_one(
                    {"id": inspection.id},
                    {"$set": {"analysis": serialize_doc(analysis.model_dump()) if analysis else None,
                              "analysis_status": analysis_status,
                              "analysis_error": analysis_error,
                              "analyzed_at": datetime.now(timezone.utc)}}
                )
                # ─ Generar fotos anotadas profesionalmente ─
                if analysis and analysis_status == "ok" and analysis.damages:
                    try:
                        ann_urls = await generate_annotated_photos(
                            inspection.id, photo_urls, analysis.damages,
                            photos_bytes=photos_base64 and
                            [base64.b64decode(b) for b in photos_base64]
                        )
                        if any(u for u in ann_urls):
                            await db.inspections.update_one(
                                {"id": inspection.id},
                                {"$set": {"annotated_photos": ann_urls}}
                            )
                    except Exception as _ae:
                        logger.warning(f"Error generando anotaciones: {_ae}")
                # Notificar por Telegram si hay daños graves o críticos
                if analysis and analysis_status == "ok":
                    sev = (analysis.severity or "").lower()
                    if sev in ("grave", "critico"):
                        # Obtener matrícula y centro del vehículo
                        veh_doc = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "license_plate": 1, "center": 1})
                        plate = veh_doc.get("license_plate", vehicle_id) if veh_doc else vehicle_id
                        veh_center = veh_doc.get("center", "") if veh_doc else ""
                        # Obtener nombre y centro del conductor
                        drv_name = "Desconocido"
                        drv_center = ""
                        if driver_id:
                            drv_doc = await db.drivers.find_one({"id": driver_id}, {"_id": 0, "name": 1, "center": 1})
                            if drv_doc:
                                drv_name = drv_doc.get("name", "Desconocido")
                                drv_center = drv_doc.get("center", "")
                        center = drv_center or veh_center or ""
                        try:
                            await send_telegram_damage_alert(
                                plate=plate,
                                driver_name=drv_name,
                                analysis=analysis,
                                photo_urls=photo_urls,
                                inspection_id=inspection.id,
                                center=center
                            )
                        except Exception as _te:
                            logger.warning(f"Telegram alert falló (no crítico): {_te}")
            except Exception as _e:
                logger.error(f"Análisis Gemini background falló: {_e}")
                await db.inspections.update_one(
                    {"id": inspection.id},
                    {"$set": {"analysis_status": "error", "analysis_error": str(_e)}}
                )
        if plan_ai:
            asyncio.create_task(_analyze_and_update())
        else:
            await db.inspections.update_one(
                {"id": inspection.id},
                {"$set": {"analysis_status": "plan_disabled", "analysis_error": "IA no incluida en tu plan"}}
            )

        # Lanzar detección YOLO en background (no bloquea la respuesta al usuario)
        asyncio.create_task(_run_yolo_for_inspection(inspection.id, photo_urls))
        # Lanzar fraud check en background (depende de analysis.plate_text, así que esperamos un poco).
        async def _delayed_fraud():
            await asyncio.sleep(45)  # da tiempo al análisis Gemini para escribir plate_text
            try: await _calculate_fraud_score(inspection.id)
            except Exception as e: logger.warning(f"fraud check bg failed: {e}")
        asyncio.create_task(_delayed_fraud())

        # Respuesta inmediata — análisis Gemini se completa en background
        return {
            "success": True,
            "inspection_id": inspection.id,
            "analysis": None,
            "analysis_status": "pending",
            "analysis_error": None,
            "photos": photo_urls,
            "message": "Inspección enviada correctamente. Las fotos se han guardado."
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error upload inspección: {type(e).__name__}: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e))


# Sin response_model a proposito. FastAPI revalidaba con Pydantic las 100
# inspecciones enteras —cada una con su analisis anidado, sus danos y sus
# cajas— antes de mandarlas, y ese paso solo se comia mas de los 30 segundos
# que espera el navegador. Los documentos ya salen limpios de Mongo.
@api_router.get("/inspections")
async def get_inspections(
    vehicle_id: Optional[str] = None,
    center: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    limit: int = 100,
    skip: int = 0,
    campos: Optional[str] = None,
    user: dict = Depends(require_admin),
):
    query = {"deleted": {"$ne": True}}
    permitido = await _filtro_por_vehiculos(user, center)
    if vehicle_id:
        # Pedir por vehiculo no puede ser la puerta de atras a otro centro.
        if permitido and vehicle_id not in permitido["vehicle_id"]["$in"]:
            raise HTTPException(403, "No tienes acceso a ese vehículo")
        query["vehicle_id"] = vehicle_id
    else:
        query.update(permitido)
    if date_from:
        query.setdefault("created_at", {})["$gte"] = date_from
    if date_to:
        query.setdefault("created_at", {})["$lte"] = date_to + "T23:59:59"
    limit = max(1, min(limit, 500))
    skip = max(0, skip)
    # `campos=lista`: lo justo para pintar la tarjeta (primera foto, severidad y
    # contadores; IA Peritaje mira además `annotated_photos`). El detalle se
    # pide aparte con GET /inspections/{id}; así el
    # listado de 200 baja de ~730 KB a una fracción.
    proj = {"_id": 0}
    if campos == "lista":
        proj = {
            "_id": 0,
            "analysis.damages": 0, "analysis.new_damages": 0, "analysis.existing_damages": 0,
            "analysis.executive_summary": 0, "analysis.zonas_no_evaluables": 0,
            "reference_photos": 0, "notes": 0, "photo_roles": 0,
            "photos": {"$slice": 1},
        }
    inspections = await db.inspections.find(query, proj).sort("created_at", -1).skip(skip).to_list(limit)
    return inspections


@api_router.get("/inspections/cobertura")
async def inspecciones_cobertura(center: Optional[str] = None,
                                 user: dict = Depends(require_admin)):
    """QUE FURGONETAS NO SE HAN MIRADO. Al reves que la pantalla de siempre.

    La lista de inspecciones ensena lo que SI se hizo, y por eso una furgoneta
    que lleva un mes sin que nadie la abra no aparece en ninguna parte: no hay
    fila que ensenar. Medido el 28-08-2026 sobre 113 activas: 58 miradas hoy o
    ayer, 20 entre 2 y 7 dias, 13 entre 8 y 30, 2 por encima de 30 y **20 sin
    una sola inspeccion en toda su vida**. Treinta y cinco furgonetas fuera de
    control y ni un sitio donde se vieran.

    Las que estan en taller se cuentan aparte y no se reclaman: nadie puede
    inspeccionar una furgoneta que no esta.

    OJO AL ORDEN: va declarado ANTES que /inspections/{inspection_id}. Puesto
    despues, la palabra 'cobertura' entraria como si fuera un id.
    """
    q = {"status": {"$nin": ["deleted", "baja"]}}
    if center and center not in ("Todos", "todos"):
        q["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}
    vehiculos = await db.vehicles.find(
        q, {"_id": 0, "id": 1, "license_plate": 1, "center": 1, "status": 1}).to_list(500)
    if not vehiculos:
        return {"furgonetas": [], "total": 0, "resumen": {}}

    ids = [v["id"] for v in vehiculos if v.get("id")]
    ultima: dict = {}
    async for r in db.inspections.aggregate([
        {"$match": {"deleted": {"$ne": True}, "vehicle_id": {"$in": ids}}},
        {"$group": {"_id": "$vehicle_id", "ult": {"$max": "$created_at"},
                    "n": {"$sum": 1}}},
    ]):
        ultima[r["_id"]] = (str(r.get("ult") or "")[:10], r.get("n") or 0)

    hoy = datetime.now(timezone.utc).date()
    resumen = {"hoy": 0, "ayer": 0, "2_7": 0, "8_30": 0, "mas_30": 0,
               "nunca": 0, "en_taller": 0}
    filas = []
    for v in vehiculos:
        f, n = ultima.get(v.get("id"), (None, 0))
        dias = None
        if f:
            try:
                dias = (hoy - datetime.strptime(f, "%Y-%m-%d").date()).days
            except ValueError:
                dias = None
        if (v.get("status") or "") == "taller":
            resumen["en_taller"] += 1
            cajon = "en_taller"
        elif dias is None:
            resumen["nunca"] += 1
            cajon = "nunca"
        elif dias <= 0:
            resumen["hoy"] += 1
            cajon = "hoy"
        elif dias == 1:
            resumen["ayer"] += 1
            cajon = "ayer"
        elif dias <= 7:
            resumen["2_7"] += 1
            cajon = "2_7"
        elif dias <= 30:
            resumen["8_30"] += 1
            cajon = "8_30"
        else:
            resumen["mas_30"] += 1
            cajon = "mas_30"
        filas.append({"vehicle_id": v.get("id"), "matricula": v.get("license_plate") or "?",
                      "center": (v.get("center") or "").strip(), "estado": v.get("status"),
                      "ultima": f, "dias": dias, "inspecciones": n, "cajon": cajon})

    # Lo mas abandonado arriba. Las que no se han mirado NUNCA van las primeras
    # de todo: son las unicas de las que no se sabe absolutamente nada.
    _peso = {"nunca": 0, "mas_30": 1, "8_30": 2, "2_7": 3, "ayer": 4, "hoy": 5,
             "en_taller": 6}
    filas.sort(key=lambda x: (_peso.get(x["cajon"], 9), -(x["dias"] or 9999)))
    return {
        "furgonetas": filas,
        "total": len(filas),
        "resumen": resumen,
        # Las que hay que reclamar hoy: ni miradas hoy, ni en taller.
        "sin_mirar_hoy": sum(1 for x in filas if x["cajon"] not in ("hoy", "en_taller")),
        "descuidadas": sum(1 for x in filas if x["cajon"] in ("nunca", "mas_30", "8_30")),
    }


@api_router.get("/inspections/vehicle/{vehicle_id}")
async def get_vehicle_inspections(vehicle_id: str, user: dict = Depends(require_any_auth)):
    if user["role"] == "driver":
        assigned = await db.vehicles.find_one({"id": vehicle_id, "current_driver_id": user["sub"]})
        if not assigned:
            raise HTTPException(status_code=403, detail="Acceso denegado")

    inspections = await db.inspections.find(
        {"deleted": {"$ne": True}, "vehicle_id": vehicle_id}, {"_id": 0}
    ).sort("created_at", -1).to_list(50)

    # Enrich with driver name
    driver_ids = list({i["driver_id"] for i in inspections if i.get("driver_id")})
    if driver_ids:
        drivers = await db.drivers.find({"id": {"$in": driver_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(200)
        name_map = {d["id"]: d["name"] for d in drivers}
        for insp in inspections:
            if insp.get("driver_id"):
                insp["driver_name"] = name_map.get(insp["driver_id"], "")

    return inspections


@api_router.post("/vehicles/{vehicle_id}/ledger/repair")
async def vehicle_ledger_repair(vehicle_id: str, body: dict = Body(default={}), user: dict = Depends(require_admin)):
    """Marca daños del registro como reparados.
    body: {"panel": "puerta"} para un panel, o {"all": true, "note": "chapa completa"}
    para el vehículo entero (salió del taller como nuevo). Un golpe futuro en esos
    paneles vuelve a contar como daño NUEVO (lo justo para scoring y €)."""
    now_iso = datetime.now(timezone.utc).isoformat()
    q = {"vehicle_id": vehicle_id, "status": "open"}
    if body.get("all"):
        pass
    elif body.get("panel"):
        p = _canon_panel(str(body["panel"]))
        if not p:
            raise HTTPException(400, "Panel no reconocido")
        q["panel"] = p
    else:
        raise HTTPException(400, "Indica 'panel' o 'all': true")
    res = await db.vehicle_damage_ledger.update_many(q, {"$set": {
        "status": "repaired", "repaired_at": now_iso,
        "repaired_note": str(body.get("note") or "")[:200],
        "repaired_by": user.get("name") or "",
    }})
    if body.get("all"):
        # Marca de "salió de chapa": la IA sabrá que los daños de fotos de
        # referencia anteriores a esta fecha YA NO EXISTEN.
        await db.vehicles.update_one({"id": vehicle_id}, {"$set": {"body_repaired_at": now_iso}})
    return {"ok": True, "repaired": res.modified_count}


# ─── LO QUE LA IA SABE DE SI MISMA ───────────────────────────────────────────
# Por debajo de este porcentaje de aciertos, un daño leve o moderado en esa
# pieza no se afirma: se manda a revisar. 35 % sale de la medicion — separa
# limpiamente el grupo de piezas siempre-rozadas (paragolpes, pasos de rueda,
# umbrales: 10-33 %) del resto (39-53 %).
_IA_FIAB_UMBRAL = float(os.environ.get("IA_FIABILIDAD_MIN") or 35.0)
# Con menos casos no hay estadistica, hay ruido: la pieza pasa sin filtro.
_IA_FIAB_MIN_CASOS = int(os.environ.get("IA_FIABILIDAD_CASOS") or 10)
_IA_FIAB_CACHE: dict = {}


def _canon_pieza_fiab(s: str) -> str:
    """La misma forma con la que se agrupa en el autoexamen: minusculas y sin
    espacios de sobra. Si las dos no coinciden, la tabla no encuentra nada y
    el filtro no hace nada — en silencio, que es lo peor."""
    return " ".join((s or "").strip().lower().split())


async def _ia_fiabilidad_piezas() -> dict:
    """Por pieza: cuantas veces el daño que la IA reporto EXISTIA de verdad.

    Sale de los veredictos humanos de la revision expres. Un `corrected`
    cuenta como que SI existia —el daño estaba, lo que fallo fue el
    recuadro—, que es justo lo que la metrica vieja se comia.

    Se recalcula cada media hora, asi que cada boton que alguien pulsa mueve
    la tabla sola. No hay nada que reentrenar ni que mantener a mano.

    LA CACHE VA POR BASE DE DATOS (gotcha: multiempresa). Una tabla global
    mezclaria la experiencia de dos clientes y le aplicaria a uno el sesgo
    del otro.
    """
    clave = _current_db_name.get()
    ent = _IA_FIAB_CACHE.get(clave)
    ahora = time.time()
    if ent and ahora - ent["en"] < 1800:
        return ent["datos"]

    datos: dict = {}
    try:
        cur = db.ai_feedback.aggregate([
            {"$group": {"_id": {"p": {"$toLower": {"$trim": {"input": {"$ifNull": ["$damage.part", ""]}}}},
                                "v": "$verdict"},
                        "n": {"$sum": 1}}}])
        crudo: dict = {}
        async for g in cur:
            p = (g["_id"].get("p") or "").strip()
            if not p:
                continue
            crudo.setdefault(p, {})[g["_id"].get("v")] = g["n"]
        for p, v in crudo.items():
            rep = v.get("correct", 0) + v.get("wrong", 0) + v.get("corrected", 0)
            if rep < _IA_FIAB_MIN_CASOS:
                continue
            existe = v.get("correct", 0) + v.get("corrected", 0)
            datos[p] = {"existe": 100.0 * existe / rep, "n": rep}
    except Exception as e:
        # Que falle esto no puede dejar de analizar fotos: sin tabla, no filtra.
        logger.warning(f"fiabilidad por pieza: {type(e).__name__}: {str(e)[:120]}")
        return {}

    _IA_FIAB_CACHE[clave] = {"en": ahora, "datos": datos}
    return datos


@api_router.get("/ai/fiabilidad")
async def ia_fiabilidad(_=Depends(require_admin)):
    """Lo que la IA ha aprendido sobre si misma, para poder mirarlo.

    Existe para que el filtro no sea una caja negra: si se calla en una
    pieza, tiene que poder enseñarse por que y con cuantos casos.
    """
    d = await _ia_fiabilidad_piezas()
    filas = sorted(({"pieza": p, "existe": round(v["existe"], 1), "casos": v["n"],
                     "se_calla": v["existe"] < _IA_FIAB_UMBRAL}
                    for p, v in d.items()), key=lambda x: x["existe"])
    return {"umbral": _IA_FIAB_UMBRAL, "min_casos": _IA_FIAB_MIN_CASOS,
            "piezas": filas,
            "se_calla_en": sum(1 for f in filas if f["se_calla"]),
            "de": len(filas)}


@api_router.get("/vehicles/{vehicle_id}/damage-ledger")
async def get_vehicle_damage_ledger(vehicle_id: str, _admin: dict = Depends(require_admin)):
    """Ledger de daños del vehículo (gemelo digital 3D): daños abiertos
    (con backfill perezoso si aún no existe) + historial de reparados."""
    open_entries = await _get_vehicle_ledger(vehicle_id)
