@app.on_event("startup")
async def start_analysis_recovery():
    """Auto-recuperación de análisis perdidos: si el servidor se reinicia a mitad
    de un análisis (queda 'pending' colgado) o Gemini falló, se reintenta solo.
    Máximo 3 reintentos automáticos por inspección, 5 por ciclo, cada 10 min."""
    # Al arrancar, dar OTRA ronda de reintentos a las fallidas recientes: si el
    # reinicio viene de arreglar la config de Gemini (billing/clave caída), las
    # que agotaron sus 3 intentos contra un Gemini roto deben curarse solas.
    # Todo dentro del try: el arranque nunca puede caerse por esto.
    try:
        # Primero recuperar el veto: sin esto, cada despliegue olvidaba que el
        # cupo estaba agotado y reencolaba trabajo para quemarlo de nuevo.
        await _cargar_veto_gemini()
        _cadena = ["gemini-2.5-flash", "gemini-flash-latest",
                   "gemini-flash-lite-latest", "gemini-2.5-flash-lite"]
        if all(_is_daily_exhausted(m) for m in _cadena):
            logger.info("Arranque: cupo diario de Gemini agotado, no se reencolan reintentos")
        else:
            _reset = await db.inspections.update_many(
                {"analysis_status": {"$in": ["error", "gemini_failed", "gemini_timeout"]},
                 "deleted": {"$ne": True}, "auto_retries": {"$gte": 3},
                 "created_at": {"$gt": (datetime.now(timezone.utc) - timedelta(days=14)).isoformat()}},
                {"$set": {"auto_retries": 0}},
            )
            if _reset.modified_count:
                logger.info(f"Auto-recuperación: {_reset.modified_count} inspecciones fallidas reencoladas tras reinicio")
    except Exception as _rr:
        logger.warning(f"Reset de reintentos al arrancar: {_rr}")

    async def _recovery_loop():
        await asyncio.sleep(60)  # dejar arrancar el servidor con calma
        _chain = ["gemini-2.5-flash", "gemini-flash-latest",
                  "gemini-flash-lite-latest", "gemini-2.5-flash-lite"]
        while True:
            try:
                # Toda la cadena con el día agotado (free tier): reintentar solo
                # quemaría los auto_retries de cada inspección contra un muro.
                if all(_is_daily_exhausted(m) for m in _chain):
                    logger.info("Auto-recuperación en pausa: cuota diaria de Gemini agotada en toda la cadena")
                    await asyncio.sleep(1800)
                    continue
                now = datetime.now(timezone.utc)
                cutoff_stuck = (now - timedelta(minutes=15)).isoformat()
                # 14 días: una caída larga (p. ej. créditos de Gemini agotados
                # durante días) no debe dejar inspecciones huérfanas sin análisis.
                cutoff_recent = (now - timedelta(days=14)).isoformat()
                # La reconstrucción de flota (rebuild_pass) NO se procesa aquí:
                # con cuota gratuita (20/día) agotaría el cupo y dejaría sin IA a
                # las operaciones diarias (plantillas, inspecciones reales). Se
                # procesa aparte, con presupuesto propio y a ritmo lento.
                stuck = await db.inspections.find({
                    "$and": [
                        {"$or": [
                            {"analysis_status": "pending", "created_at": {"$lt": cutoff_stuck}},
                            {"analysis_status": {"$in": ["error", "gemini_failed", "gemini_timeout"]},
                             "created_at": {"$gt": cutoff_recent}},
                        ]},
                        {"rebuild_pass": {"$exists": False}},
                        {"auto_retries": {"$not": {"$gte": 3}}},
                        {"photos": {"$exists": True, "$ne": []}},
                        {"deleted": {"$ne": True}},
                    ]
                }, {"_id": 0, "id": 1, "analysis_status": 1}).sort("created_at", -1).to_list(5)

                # Reconstrucción de flota: MÁXIMO 3 furgonetas por ciclo (~10 min)
                # y solo si el modelo base tiene cuota. Así no ahoga las operaciones.
                if not _is_daily_exhausted("gemini-2.5-flash"):
                    rebuild_stuck = await db.inspections.find({
                        "rebuild_pass": {"$exists": True}, "inventory_done": {"$ne": True},
                        "analysis_status": "pending", "auto_retries": {"$not": {"$gte": 3}},
                        "photos": {"$exists": True, "$ne": []}, "deleted": {"$ne": True},
                    }, {"_id": 0, "id": 1, "analysis_status": 1}).sort("created_at", -1).to_list(2)
                    stuck = stuck + rebuild_stuck

                for insp in stuck:
                    iid = insp["id"]
                    await db.inspections.update_one({"id": iid}, {"$inc": {"auto_retries": 1}})
                    logger.info(f"Auto-recuperación: reintentando análisis de {iid} (estaba {insp.get('analysis_status')})")
                    try:
                        await reanalyze_inspection(iid, None)
                    except Exception as _re:
                        logger.warning(f"Auto-recuperación {iid} falló: {_re}")
                    await asyncio.sleep(10)  # no saturar Gemini
            except Exception as e:
                logger.error(f"Recovery loop error: {e}")
            await asyncio.sleep(600)
    asyncio.create_task(_recovery_loop())


@api_router.get("/inspections/{inspection_id}/debug-segment")
async def debug_segment(inspection_id: str, photo_index: int = 0, damage_index: int = 0,
                        _=Depends(require_admin)):
    """Devuelve imagen compuesta con las 6 fases del pipeline de segmentación OpenCV.
    photo_index: 0-based. damage_index: índice del daño en analysis.damages."""
    from fastapi.responses import Response as _FR
    insp = await db.inspections.find_one({"id": inspection_id}, {"_id": 0})
    if not insp:
        raise HTTPException(status_code=404, detail="Inspección no encontrada")
    photos = insp.get("photos") or []
    if photo_index >= len(photos):
        raise HTTPException(status_code=400, detail="photo_index fuera de rango")

    analysis = insp.get("analysis") or {}
    damages = analysis.get("damages") or analysis.get("new_damages") or []
    if damage_index >= len(damages):
        raise HTTPException(status_code=400, detail="damage_index fuera de rango")

    dmg = damages[damage_index]
    box_2d = dmg.get("box_2d")
    if not box_2d or len(box_2d) != 4 or not any(v > 0 for v in box_2d):
        raise HTTPException(status_code=400, detail="Daño sin box_2d válido")

    img_bytes = await _fetch_photo_bytes(photos[photo_index])
    if not img_bytes:
        raise HTTPException(status_code=400, detail="No se pudo cargar la foto")

    loop = asyncio.get_running_loop()
    poly, debug_imgs = await loop.run_in_executor(
        _executor, lambda: _segment_damage_opencv(img_bytes, box_2d, debug=True)
    )

    if not debug_imgs:
        raise HTTPException(status_code=422, detail="La segmentación no produjo resultado")

    # Construir imagen compuesta: original | edges | shadows | reflection | candidate | mask
    import cv2 as _cv2
    import numpy as _np
    from PIL import Image as _PILImg
    import io as _io

    labels = ['original', 'bordes', 'sombras', 'reflexión', 'candidato', 'máscara']
    frames_raw = [
        debug_imgs['crop'],
        debug_imgs['edges'],
        debug_imgs['shadows'],
        debug_imgs['reflection'],
        debug_imgs['candidate'],
        debug_imgs['mask'],
    ]

    # Convertir todos a uint8 BGR para cv2 (float32 → normalizar, grises → BGR)
    frames = []
    for f in frames_raw:
        if f.dtype != _np.uint8:
            f = _cv2.normalize(f, None, 0, 255, _cv2.NORM_MINMAX).astype(_np.uint8)
        if len(f.shape) == 2:
            frames.append(_cv2.cvtColor(f, _cv2.COLOR_GRAY2BGR))
        else:
            frames.append(f)

    # Redimensionar todos al mismo alto
    H_target = 300
    resized = []
    for f in frames:
        h, w = f.shape[:2]
        new_w = int(w * H_target / h)
        resized.append(_cv2.resize(f, (new_w, H_target)))

    # Añadir etiqueta encima de cada frame
    labeled = []
    for i, (f, lbl) in enumerate(zip(resized, labels)):
        bar = _np.zeros((28, f.shape[1], 3), dtype=_np.uint8)
        _cv2.putText(bar, lbl, (4, 20), _cv2.FONT_HERSHEY_SIMPLEX, 0.55, (255, 255, 255), 1)
        labeled.append(_np.vstack([bar, f]))

    composite = _np.hstack(labeled)

    # Si hay polígono, dibujarlo sobre el crop en la primera columna (frame original)
    if poly and len(poly) >= 4:
        orig_with_poly = labeled[0].copy()
        pts_px = _np.array([
            [int(pt[1] / 1000 * resized[0].shape[1]),
             int(pt[0] / 1000 * resized[0].shape[0]) + 28]
            for pt in poly
        ], dtype=_np.int32)
        _cv2.polylines(orig_with_poly, [pts_px], True, (0, 80, 255), 2)
        composite[:, :labeled[0].shape[1]] = orig_with_poly

    # Codificar como JPEG
    ok, buf = _cv2.imencode('.jpg', composite, [_cv2.IMWRITE_JPEG_QUALITY, 88])
    if not ok:
        raise HTTPException(status_code=500, detail="Error codificando imagen")

    return _FR(content=buf.tobytes(), media_type="image/jpeg",
               headers={"Content-Disposition": f'inline; filename="debug_{inspection_id[:8]}_p{photo_index}_d{damage_index}.jpg"'})


@api_router.post("/inspections/{inspection_id}/reanalyze")
async def reanalyze_inspection(inspection_id: str, silent: bool = False, _=Depends(require_admin)):
    """Relanza el análisis IA de una inspección usando las fotos ya guardadas.
    silent=true suprime la notificación de Telegram (útil para pruebas)."""
    insp = await db.inspections.find_one({"id": inspection_id}, {"_id": 0})
    if not insp:
        raise HTTPException(status_code=404, detail="Inspección no encontrada")

    photo_urls = insp.get("photos") or []
    if not photo_urls:
        raise HTTPException(status_code=400, detail="La inspección no tiene fotos guardadas")

    # Descargar las fotos desde R2/disco
    photo_bytes = await load_reference_images(photo_urls)
    if not photo_bytes:
        raise HTTPException(status_code=502, detail="No se pudieron descargar las fotos guardadas")

    photos_base64 = [base64.b64encode(b).decode("utf-8") for b in photo_bytes]

    # Solo carrocería al análisis (photo_roles existe desde 2026-07; en
    # inspecciones antiguas sin roles se analizan todas, como siempre).
    _roles = insp.get("photo_roles") or []
    if len(_roles) == len(photos_base64):
        _aidx = [i for i, r in enumerate(_roles) if r == "angle"] or list(range(len(photos_base64)))
    else:
        _aidx = list(range(len(photos_base64)))
    analysis_b64 = [photos_base64[i] for i in _aidx]
    _idx_map = {k + 1: _aidx[k] + 1 for k in range(len(_aidx))}

    # MODO INVENTARIO (reconstrucción de flota): ignora las fotos de referencia
    # para hacer un censo COMPLETO de todos los daños actuales del vehículo, en
    # vez de comparar con el "antes" y decir "ya estaban". Se usa una sola vez
    # por furgoneta (inventory_done) y a partir de ahí vuelve el modo normal.
    inv_mode = bool(insp.get("rebuild_pass")) and not insp.get("inventory_done")

    # Fotos de referencia (estado anterior) si las había — salvo en inventario
    _vistas = _vistas_inspeccion({**insp, "photos": insp.get("photos") or []})
    ref_urls, ref_labels = [], []
    ref_bytes_list = None
    if not inv_mode:
        # Siempre recalculadas: las guardadas antes del 17-09-2026 eran las dos
        # primeras fotos de la inspeccion anterior, sin mirar la vista.
        ref_urls = await _referencias_por_vista(insp.get("vehicle_id"), _vistas,
                                                antes_de=insp.get("created_at"), excluir_id=inspection_id)
        ref_bytes_list, ref_labels = await _referencias_para_ia(ref_urls, _vistas, _aidx)
        await db.inspections.update_one(
            {"id": inspection_id},
            {"$set": {"reference_photos": ref_urls if any(ref_urls) else [], "photo_vistas": _vistas}})
    _cur_labels = [_VISTA_NOMBRE.get(_vistas[i], "") if i < len(_vistas) else "" for i in _aidx]

    # Marcar como pendiente mientras se reanaliza
    await db.inspections.update_one(
        {"id": inspection_id},
        {"$set": {"analysis_status": "pending", "analysis_error": None}}
    )

    # CV primero (igual que en la subida): guía el prompt y luego el snap
    cv_dets_full = {}
    cv_text = ""
    if AI_SERVICE_URL:
        try:
            _cv_lines = []
            for _k, _full_i in enumerate(_aidx, start=1):
                if _full_i < len(photo_bytes):
                    dets = await _call_ai_service_detect(inspection_id, _full_i, photo_bytes[_full_i])
                    if dets:
                        cv_dets_full[_full_i + 1] = dets
                        for det in dets:
                            _pnl = f" en {det.panel}" if getattr(det, "panel", None) else ""
                            _cv_lines.append(f"Foto {_k}: {det.label}{_pnl} (confianza {det.confidence:.2f})")
            if _cv_lines:
                cv_text = (
                    "\n=== DETECCIONES DEL DETECTOR CV PROPIO (geometría verificada) ===\n"
                    + "\n".join(_cv_lines) +
                    "\nEstas detecciones vienen de un modelo entrenado con miles de daños "
                    "reales de carrocería; la pieza está determinada por intersección "
                    "geométrica, no por estimación. Úsalas como BASE del análisis: "
                    "confirma y describe con precisión cada una que veas en la foto. "
                    "NO reportes daños adicionales salvo evidencia clara e inequívoca; "
                    "si no ves alguna de estas detecciones, inclúyela con confidence < 0.5."
                )
        except Exception as _cve:
            logger.warning(f"CV pre-reanálisis: {_cve}")

    _known_txt = await _known_damages_prompt(insp.get("vehicle_id"), exclude_inspection_id=inspection_id)
    analysis, analysis_status, analysis_error = await analyze_images_with_gemini(
        analysis_b64, ref_bytes_list if ref_bytes_list else None, db=db,
        known_damages_text=_known_txt,
        cv_detections_text=cv_text,
        reference_labels=ref_labels or None,
        current_labels=_cur_labels,
    )
    if analysis:
        _remap_photo_indexes(analysis, _idx_map)
    # En inventario, TODOS los daños vistos pasan a "pendientes de validar"
    # (new_damages), para que el humano confirme el estado base de la furgoneta.
    if inv_mode and analysis_status == "ok" and analysis and getattr(analysis, "damages", None):
        analysis.new_damages = list(analysis.damages)
    if analysis_status == "ok" and analysis:
        await _apply_vehicle_memory(insp.get("vehicle_id"), analysis, inspection_id=inspection_id)
        # Y la IA decide en el acto lo que pueda decidir de ESTA inspeccion,
        # sin esperar al bucle: la cola solo enseña dudas.
        try:
            await autorrevisar_inspecciones(limite=1, ids=[inspection_id])
        except Exception as _ar:                                 # noqa: BLE001
            logger.warning("autorrevision tras analisis %s: %s", inspection_id, _ar)
        if inv_mode:
            await db.inspections.update_one({"id": inspection_id}, {"$set": {"inventory_done": True}})

    # Snap de cajas al detector CV (reutiliza las detecciones ya pedidas)
    if cv_dets_full and analysis and analysis_status == "ok" and (analysis.damages or analysis.new_damages):
        try:
            _s1 = _snap_damage_boxes_to_yolo(analysis.damages or [], cv_dets_full)
            _s2 = _snap_damage_boxes_to_yolo(analysis.new_damages or [], cv_dets_full)
            if _s1 or _s2:
                logger.info(f"Snap YOLO (reanálisis): {_s1}+{_s2} cajas corregidas insp={inspection_id[:8]}")
        except Exception as _se:
            logger.warning(f"Snap YOLO reanálisis: {_se}")

    await db.inspections.update_one(
        {"id": inspection_id},
        {"$set": {"analysis": serialize_doc(analysis.model_dump()) if analysis else None,
                  "analysis_status": analysis_status,
                  "analysis_error": analysis_error,
                  "analyzed_at": datetime.now(timezone.utc).isoformat()}}
    )

    # ─ Regenerar fotos anotadas ─
    if analysis and analysis_status == "ok" and analysis.damages:
        try:
            ann_urls = await generate_annotated_photos(
                inspection_id, photo_urls, analysis.damages
            )
            if any(u for u in ann_urls):
                await db.inspections.update_one(
                    {"id": inspection_id},
                    {"$set": {"annotated_photos": ann_urls}}
                )
        except Exception as _ae:
            logger.warning(f"Error generando anotaciones en reanálisis: {_ae}")

    # Telegram si el reanálisis revela daños graves/críticos (omitir si silent=True)
    if not silent and analysis and analysis_status == "ok":
        sev = (analysis.severity or "").lower()
        if sev in ("grave", "critico"):
            try:
                vehicle_id = insp.get("vehicle_id", "")
                driver_id = insp.get("driver_id", "")
                veh_doc = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "license_plate": 1, "center": 1})
                plate = veh_doc.get("license_plate", vehicle_id) if veh_doc else vehicle_id
                drv_doc = await db.drivers.find_one({"id": driver_id}, {"_id": 0, "name": 1, "center": 1}) if driver_id else None
                drv_name = drv_doc.get("name", "Desconocido") if drv_doc else "Desconocido"
                center = (drv_doc.get("center", "") if drv_doc else "") or (veh_doc.get("center", "") if veh_doc else "")
                await send_telegram_damage_alert(
                    plate=plate, driver_name=drv_name, analysis=analysis,
                    photo_urls=photo_urls, inspection_id=inspection_id, center=center
                )
            except Exception as _te:
                logger.warning(f"Telegram tras reanálisis falló (no crítico): {_te}")

    logger.info(f"Reanálisis {inspection_id}: status={analysis_status}, severity={analysis.severity if analysis else 'n/a'}")
    return {
        "success": analysis_status == "ok",
        "analysis_status": analysis_status,
        "analysis_error": analysis_error,
        "analysis": serialize_doc(analysis.model_dump()) if analysis else None,
    }


# =========================
# PERITAJE TÉCNICO FIRMADO (S1) — cadena de custodia con hash encadenado
# =========================
# Cada firma calcula content_hash = SHA-256(prev_hash + payload canónico de la inspección).
# El prev_hash es el hash de la firma INMEDIATAMENTE anterior de la MISMA organización.
# Si alguien manipula o elimina una firma intermedia, la cadena se rompe (detectable).
# NOTA LEGAL: es evidencia técnica con cadena de custodia, NO firma electrónica avanzada eIDAS.

_GENESIS_HASH = "0" * 64


def _canonical_inspection_payload(insp: dict, prev_hash: str) -> str:
    """Serialización determinista de la inspección para hashear.
    NO usamos json.dumps con sort_keys directamente porque queremos un subconjunto fijo
    para que cambios futuros en otros campos no rompan la cadena."""
    payload = {
        "prev_hash": prev_hash,
        "inspection_id": insp.get("id"),
        "vehicle_id": insp.get("vehicle_id"),
        "driver_id": insp.get("driver_id"),
        "created_at": insp.get("created_at"),
        "photos": list(insp.get("photos") or []),  # URLs en R2; URL inmutable = foto inmutable
        "plate_text": (insp.get("plate_text") or ""),
        "analysis_summary": {
            "severity": (insp.get("analysis") or {}).get("severity"),
            "total_damages_count": (insp.get("analysis") or {}).get("total_damages_count"),
            "executive_summary": (insp.get("analysis") or {}).get("executive_summary"),
        },
    }
    return json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str)


async def _last_signature_hash() -> str:
    """Último hash de la cadena (esta org). _GENESIS_HASH si la cadena está vacía."""
    last = await db.forensic_signatures.find_one({}, sort=[("signed_at", -1)])
    return (last or {}).get("content_hash", _GENESIS_HASH)


class SignInspectionRequest(BaseModel):
    signature_text: str   # declaración aceptada por el firmante (texto libre, queda inmortalizada)


@api_router.post("/inspections/{inspection_id}/sign")
async def sign_inspection(inspection_id: str, data: SignInspectionRequest, request: Request,
                          user: dict = Depends(require_any_auth)):
    """Firma una inspección con cadena de custodia hash. Idempotente: 409 si ya firmada.
    Auth: el conductor asignado al vehículo de esa inspección, o cualquier admin de la org."""
    await _require_plan_feature(user, "forensics")
    # Rate-limit: 3 firmas/min por usuario (anti-rebote).
    _rl_public_action(f"sign:{user.get('sub')}", max_count=3, window_s=60,
                      detail="Demasiadas firmas seguidas. Espera un minuto.")

    insp = await db.inspections.find_one({"id": inspection_id, "deleted": {"$ne": True}}, {"_id": 0})
    if not insp:
        raise HTTPException(status_code=404, detail="Inspección no encontrada")
    if insp.get("forensic_signed"):
        raise HTTPException(status_code=409,
                            detail="Esta inspección ya está firmada (cadena de custodia cerrada)")

    # Autorización: admin puede firmar cualquiera. Conductor solo la suya.
    if user.get("role") == "driver":
        if insp.get("driver_id") and insp["driver_id"] != user.get("sub"):
            # Si la inspección no tiene driver_id, comprobamos por current_driver del vehículo.
            v = await db.vehicles.find_one({"id": insp.get("vehicle_id")}, {"_id": 0, "current_driver_id": 1})
            if not v or v.get("current_driver_id") != user.get("sub"):
                raise HTTPException(status_code=403, detail="No puedes firmar inspecciones de otro conductor")

    # Calcular hashes con reintento simple ante race condition de prev_hash.
    import hashlib as _hl
    now = datetime.now(timezone.utc).isoformat()
    sig_doc = None
    for attempt in range(3):
        prev_hash = await _last_signature_hash()
        payload = _canonical_inspection_payload(insp, prev_hash)
        content_hash = _hl.sha256(payload.encode("utf-8")).hexdigest()
        try:
            sig_doc = {
                "id": str(uuid.uuid4()),
                "inspection_id": inspection_id,
                "revision": 1,
                "prev_hash": prev_hash,
                "content_hash": content_hash,
                "payload_canonical": payload,           # útil para reverificar sin recalcular
                "signed_by_user_id": user.get("sub"),
                "signed_by_user_role": user.get("role"),
                "signed_by_name": user.get("name", ""),
                "signed_at": now,
                "client_ip": _rl_key_ip(request),
                "user_agent": (request.headers.get("user-agent") or "")[:300],
                "signature_text": (data.signature_text or "").strip()[:1000],
            }
            await db.forensic_signatures.insert_one(sig_doc)
            break
        except DuplicateKeyError:
            # Otra firma se coló en el medio: recalcula y reintenta.
            if attempt == 2:
                raise HTTPException(status_code=503, detail="Conflicto al firmar. Reintenta.")
            await asyncio.sleep(0.05)

    # Marca la inspección como firmada (no rompemos compatibilidad: campos nuevos opcionales).
    await db.inspections.update_one(
        {"id": inspection_id},
        {"$set": {"forensic_signed": True, "forensic_hash": sig_doc["content_hash"],
                  "forensic_signed_at": now, "forensic_signed_by": sig_doc["signed_by_name"]}}
    )
    # Índice global hash → tenant (para que /verify/{hash} público pueda localizar la firma sin auth).
    # Aditivo: si falla (DuplicateKey, race), no rompe la firma local.
    try:
        await global_db.forensic_index.insert_one({
            "content_hash": sig_doc["content_hash"],
            "org_id": user.get("org_id"),
            "db_name": _tenant_db_name(await get_org(user.get("org_id"))),
            "inspection_id": inspection_id,
            "signed_at": now,
        })
    except DuplicateKeyError:
        logger.warning(f"forensic_index duplicado para hash={sig_doc['content_hash'][:12]}")
    logger.info(f"Inspección {inspection_id} firmada por {user.get('name')} hash={sig_doc['content_hash'][:12]}…")
    return {
        "ok": True,
        "hash": sig_doc["content_hash"],
        "prev_hash": sig_doc["prev_hash"],
        "signed_at": now,
        "signed_by_name": sig_doc["signed_by_name"],
    }


@api_router.get("/inspections/{inspection_id}/forensic")
async def get_forensic_status(inspection_id: str, _=Depends(require_any_auth)):
    """Estado de firma de una inspección. Sin secretos: NO devuelve payload completo."""
    # FIX (bug S1.A): incluir 'id' en projection para que find_one no devuelva {} en docs
    # sin campos forensic_*. Sin esto, /forensic devolvía 404 para inspecciones no firmadas.
    insp = await db.inspections.find_one(
        {"id": inspection_id}, {"_id": 0, "id": 1, "forensic_signed": 1, "forensic_hash": 1,
                                "forensic_signed_at": 1, "forensic_signed_by": 1}
    )
    if not insp:
        raise HTTPException(status_code=404, detail="Inspección no encontrada")
    if not insp.get("forensic_signed"):
        return {"signed": False}
    sig = await db.forensic_signatures.find_one(
        {"inspection_id": inspection_id}, {"_id": 0, "prev_hash": 1, "content_hash": 1,
                                            "signed_at": 1, "signed_by_name": 1, "signature_text": 1,
                                            "revision": 1}
    )
    return {
        "signed": True,
        "hash": insp.get("forensic_hash"),
        "prev_hash": (sig or {}).get("prev_hash"),
        "signed_at": insp.get("forensic_signed_at"),
        "signed_by_name": insp.get("forensic_signed_by"),
        "signature_text": (sig or {}).get("signature_text"),
        "revision": (sig or {}).get("revision", 1),
    }


# --- Generación del PDF forense (reportlab + qrcode) ---

_PORTAL_BASE_FRONT = os.environ.get("PUBLIC_BASE_URL_FRONT", "https://flotadsp.com").rstrip("/")


def _mask_plate(plate: str) -> str:
    """Oculta parcialmente una matrícula para mostrarla en el verificador público.
    1234ABC -> 1234A** ; corto -> tal cual."""
    if not plate:
        return "—"
    p = re.sub(r"\s+", "", plate.strip().upper())
    if len(p) < 5:
        return p
    keep = max(4, len(p) - 2)
    return p[:keep] + "*" * (len(p) - keep)


async def _fetch_photo_bytes(url: str, timeout: int = 8):
    """Descarga una foto de R2/CDN. None si falla. Usado solo para embedirla en PDF."""
    if not url:
        return None
    try:
        async with _aiohttp.ClientSession() as s:
            async with s.get(url, timeout=_aiohttp.ClientTimeout(total=timeout)) as r:
                if r.status == 200:
                    return await r.read()
    except Exception as e:
        logger.warning(f"forensic PDF: foto inaccesible {url}: {e}")
    return None


# Umbral de confianza mínimo para DIBUJAR caja en el PDF (compromiso de veracidad).
# Daños bajo el umbral aparecen listados como "sugeridos" pero NO se marcan visualmente.
_FORENSIC_CONFIDENCE_MIN = 0.5
# Mínimo área de caja (en % del área de la imagen) para considerarla un daño real.
_FORENSIC_MIN_BOX_AREA_PCT = 0.5  # 0.5% mínimo

_SEVERITY_COLORS = {
    "leve":     (250, 204, 21),   # amarillo
    "moderado": (251, 146, 60),   # naranja
    "grave":    (239, 68, 68),    # rojo
    "critico":  (220, 38, 38),    # rojo intenso
    "sin_danos": (34, 197, 94),   # verde (no se dibuja normalmente)
}


def _is_box_valid(box_2d) -> bool:
    """Valida que box_2d sea una caja real (no placeholder, dentro de rango, con área mínima)."""
    if not isinstance(box_2d, (list, tuple)) or len(box_2d) != 4:
        return False
    try:
        y1, x1, y2, x2 = [float(v) for v in box_2d]
    except Exception:
        return False
    if y1 + x1 + y2 + x2 == 0:                # placeholder [0,0,0,0]
        return False
    if not (0 <= y1 < y2 <= 1000 and 0 <= x1 < x2 <= 1000):
        return False
    area_pct = ((y2 - y1) * (x2 - x1)) / 10000.0  # 1000*1000/10000 = 100%
    if area_pct < _FORENSIC_MIN_BOX_AREA_PCT:
        return False
    return True


def _annotate_photo_with_damages(photo_bytes: bytes, damages_for_photo: list) -> bytes:
    """Dibuja cajas sobre los daños VERÍDICOS de una foto.
    Solo dibuja: confidence ≥ 0.5, box_2d válido, severity ≠ sin_danos.
    Si la imagen falla → devuelve los bytes originales (fallback seguro)."""
    if not photo_bytes:
        return photo_bytes
    try:
        from PIL import Image as PILImage, ImageDraw, ImageFont
        import io as _io
        img = PILImage.open(_io.BytesIO(photo_bytes))
        if img.mode != "RGB":
            img = img.convert("RGB")
        W, H = img.size
        draw = ImageDraw.Draw(img)
        # Grosor proporcional a la imagen (mínimo 3 px).
        thick = max(3, int(min(W, H) * 0.006))
        try:
            font = ImageFont.truetype("DejaVuSans-Bold.ttf", max(14, int(min(W, H) * 0.022)))
        except Exception:
            font = ImageFont.load_default()

        drawn = 0
        for d in (damages_for_photo or []):
            if (d.get("severity") in (None, "sin_danos", "sin_analisis")):
                continue
            if float(d.get("confidence", 0)) < _FORENSIC_CONFIDENCE_MIN:
                continue
            box = d.get("box_2d")
            if not _is_box_valid(box):
                continue
            y1, x1, y2, x2 = box
            # Mapear 0-1000 a píxeles.
            left, top = int(x1 / 1000.0 * W), int(y1 / 1000.0 * H)
            right, bottom = int(x2 / 1000.0 * W), int(y2 / 1000.0 * H)
            color = _SEVERITY_COLORS.get(d.get("severity"), (239, 68, 68))
            verified = bool(d.get("_verified"))
            if verified:
                # Sólido + grueso → daño cross-validado con YOLO/SAM.
                draw.rectangle([left, top, right, bottom], outline=color, width=thick)
            else:
                # Discontinuo → solo Gemini (caja aproximada, sin confirmación geométrica).
                seg = max(8, thick * 3)
                for sx in range(left, right, seg * 2):
                    draw.line([(sx, top), (min(sx + seg, right), top)], fill=color, width=thick)
                    draw.line([(sx, bottom), (min(sx + seg, right), bottom)], fill=color, width=thick)
                for sy in range(top, bottom, seg * 2):
                    draw.line([(left, sy), (left, min(sy + seg, bottom))], fill=color, width=thick)
                    draw.line([(right, sy), (right, min(sy + seg, bottom))], fill=color, width=thick)
            # Etiqueta arriba del rectángulo: parte + confidence (+ ~ si no verificada)
            tag = "" if verified else "~"
            label = f"{tag}{(d.get('part') or 'daño')[:22]}  {int(float(d.get('confidence', 0)) * 100)}%"
            try:
                tb = draw.textbbox((0, 0), label, font=font)
                tw, th = tb[2] - tb[0], tb[3] - tb[1]
            except Exception:
                tw, th = (len(label) * 8, 14)
            ly = max(0, top - th - 6)
            draw.rectangle([left, ly, left + tw + 8, ly + th + 4], fill=color)
            draw.text((left + 4, ly), label, fill=(0, 0, 0), font=font)
            drawn += 1

        buf = _io.BytesIO()
        # JPEG para no inflar PDF; calidad alta para mantener detalle del daño.
        img.save(buf, format="JPEG", quality=85, optimize=True)
        return buf.getvalue()
    except Exception as e:
        logger.warning(f"forensic PDF: anotación de foto falló: {e}")
        return photo_bytes


def _filter_damages_for_peritaje(damages: list):
    """Devuelve (incluidos, sugeridos): incluidos pasan los filtros estrictos."""
    incluidos, sugeridos = [], []
    for d in (damages or []):
        sev = d.get("severity")
        if sev in (None, "sin_danos", "sin_analisis"):
            continue
        conf = float(d.get("confidence", 0))
        if conf >= _FORENSIC_CONFIDENCE_MIN and _is_box_valid(d.get("box_2d")):
            incluidos.append(d)
        else:
            sugeridos.append(d)
    return incluidos, sugeridos


# --- ENSEMBLE GEMINI + YOLO+SAM (precisión geométrica del bounding box) ---

def _bbox_iou(a, b) -> float:
    """IoU entre 2 cajas [y1,x1,y2,x2] (cualquier escala). 0 si no se solapan."""
    try:
        ay1, ax1, ay2, ax2 = float(a[0]), float(a[1]), float(a[2]), float(a[3])
        by1, bx1, by2, bx2 = float(b[0]), float(b[1]), float(b[2]), float(b[3])
    except Exception:
        return 0.0
    iy1, ix1 = max(ay1, by1), max(ax1, bx1)
    iy2, ix2 = min(ay2, by2), min(ax2, bx2)
    iw, ih = max(0.0, ix2 - ix1), max(0.0, iy2 - iy1)
    inter = iw * ih
    if inter <= 0:
        return 0.0
    area_a = max(0.0, ay2 - ay1) * max(0.0, ax2 - ax1)
    area_b = max(0.0, by2 - by1) * max(0.0, bx2 - bx1)
    union = area_a + area_b - inter
    return inter / union if union > 0 else 0.0


def _nms_damages(damages: list, iou_thresh: float = 0.7) -> list:
    """Non-Max Suppression: si 2 daños solapan IoU>thresh, queda el de mayor confidence."""
    if not damages:
        return []
    sorted_d = sorted(damages, key=lambda d: float(d.get("confidence", 0)), reverse=True)
    keep, suppressed = [], set()
    for i, d in enumerate(sorted_d):
        if i in suppressed:
            continue
        keep.append(d)
        for j in range(i + 1, len(sorted_d)):
            if j in suppressed:
                continue
            if _bbox_iou(d.get("box_2d") or [0, 0, 0, 0],
                        sorted_d[j].get("box_2d") or [0, 0, 0, 0]) > iou_thresh:
                suppressed.add(j)
    return keep


async def _refine_damage_boxes_with_yolo_sam(inspection_id: str, photo_index_0based: int,
                                              gemini_damages_for_photo: list) -> list:
    """Cruza cajas Gemini con detecciones YOLO+SAM ya almacenadas en inspection_ai_results.
    Cuando hay coincidencia (IoU≥0.3) → caja YOLO/SAM (geométricamente precisa)
                                       + label semántica Gemini (qué es el daño).
    Sin coincidencia → mantiene Gemini SOLO si confidence ≥ 0.7 (compromiso de veracidad).
    Sin detecciones YOLO disponibles → degrada elegantemente a Gemini sin cambios."""
    ai_doc = await db.inspection_ai_results.find_one(
        {"inspection_id": inspection_id, "photo_index": photo_index_0based}, {"_id": 0}
    )
    yolo_dets = (ai_doc or {}).get("detections") or []
    # Filtra detecciones YOLO/SAM con cajas válidas y confianza decente.
    yolo_dets = [y for y in yolo_dets
                 if y.get("box_2d") and _is_box_valid(y["box_2d"])
                 and float(y.get("confidence", 0)) >= 0.35]

    # Filtro geométrico estricto: cajas > 15% del área = "toda la pieza" → no es daño puntual.
    # Aplicable a Gemini y a YOLO. Un daño real raramente supera el 15% de la foto.
    MAX_AREA_PCT = 15.0
    refined = []
    for g in gemini_damages_for_photo:
        g_box = g.get("box_2d")
        if not _is_box_valid(g_box):
            continue
        y1, x1, y2, x2 = g_box
        g_area = ((y2 - y1) * (x2 - x1)) / 10000.0
        if g_area > MAX_AREA_PCT:
            continue  # Gemini marcó la pieza entera, no el daño.
        # Cross-validation con YOLO/SAM.
        best_iou, best_y = 0.0, None
        for y in yolo_dets:
            iou = _bbox_iou(g_box, y["box_2d"])
            if iou > best_iou:
                best_iou, best_y = iou, y
        if best_iou >= 0.3 and best_y is not None:
            yy1, yx1, yy2, yx2 = best_y["box_2d"]
            y_area = ((yy2 - yy1) * (yx2 - yx1)) / 10000.0
            if y_area <= MAX_AREA_PCT:
                # Cross-validado: caja YOLO precisa + label Gemini. Borde SÓLIDO.
                refined.append({**g, "box_2d": list(best_y["box_2d"]),
                                "_box_source": "yolo+sam", "_iou": round(best_iou, 2),
                                "_verified": True})
                continue
        # Gemini sin confirmación pero con caja pequeña razonable. Borde DISCONTINUO.
        refined.append({**g, "_box_source": "gemini_only", "_verified": False})
    return _nms_damages(refined, iou_thresh=0.7)


def _generate_qr_png(data: str) -> bytes:
    """QR como PNG bytes (para embed en PDF). Importado lazy."""
    import qrcode as _qr
    import io as _io
    q = _qr.QRCode(border=2, box_size=4)
    q.add_data(data)
    q.make(fit=True)
    img = q.make_image()
    buf = _io.BytesIO()
    img.save(buf, format="PNG")
    return buf.getvalue()


def _legend_pill(color_hex, label):
    """Genera una mini-tabla 'cuadrito de color + label' para la leyenda."""
    from reportlab.platypus import Table, TableStyle, Paragraph
    from reportlab.lib import colors as _c
    from reportlab.lib.styles import getSampleStyleSheet
    st = getSampleStyleSheet()
    return Table([["", Paragraph(label, st["BodyText"])]],
                 colWidths=[4*1.5, None],
                 style=TableStyle([
                     ("BACKGROUND", (0, 0), (0, 0), color_hex),
                     ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                     ("LEFTPADDING", (0, 0), (-1, -1), 2),
                 ]))


def _build_forensic_pdf(insp: dict, sig: dict, vehicle: dict, driver_name: str,
                        photo_bytes_list: list, verify_url: str,
                        damages_incluidos: list = None, damages_sugeridos: list = None) -> bytes:
    """Construye el PDF de peritaje técnico. Síncrono, llamado vía run_in_executor.
    photo_bytes_list contiene fotos YA anotadas con cajas (donde aplique)."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Image, Table,
                                    TableStyle, PageBreak)
    from reportlab.lib.enums import TA_LEFT
    import io as _io

    damages_incluidos = damages_incluidos or []
    damages_sugeridos = damages_sugeridos or []

    buf = _io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, rightMargin=15*mm, leftMargin=15*mm,
                            topMargin=15*mm, bottomMargin=15*mm,
                            title=f"Peritaje técnico {insp.get('id','')[:8]}",
                            author="FlotaDSP")
    styles = getSampleStyleSheet()
    h1 = ParagraphStyle("H1", parent=styles["Heading1"], fontSize=18, textColor=colors.HexColor("#0b1220"))
    h2 = ParagraphStyle("H2", parent=styles["Heading2"], fontSize=12, textColor=colors.HexColor("#0ea5e9"),
                        spaceBefore=8, spaceAfter=4)
    body = ParagraphStyle("body", parent=styles["BodyText"], fontSize=9.5, leading=13, alignment=TA_LEFT)
    small = ParagraphStyle("small", parent=styles["BodyText"], fontSize=8, textColor=colors.HexColor("#6b7280"))
    mono = ParagraphStyle("mono", parent=styles["BodyText"], fontSize=8.5, fontName="Courier",
                          textColor=colors.HexColor("#0b1220"))

    story = []

    # Cabecera
    story.append(Paragraph("Peritaje técnico de inspección", h1))
    story.append(Paragraph("Cadena de custodia con hash inmutable · FlotaDSP", small))
    story.append(Spacer(1, 5*mm))

    # Bloque datos
    analysis = (insp.get("analysis") or {})
    rows = [
        ["Matrícula", vehicle.get("license_plate", "—"), "Centro", vehicle.get("center", "—")],
        ["Marca/Modelo", f"{vehicle.get('brand','—')} {vehicle.get('model','')}".strip(), "VIN", vehicle.get("vin", "—")],
        ["Conductor", driver_name or "—", "Inspección ID", (insp.get("id","")[:8] + "…")],
        ["Fecha inspección", (insp.get("created_at") or "")[:19].replace("T", " "), "Severidad", str(analysis.get("severity", "—"))],
        ["Daños incluidos", str(len(damages_incluidos)), "Coste estimado", f"{analysis.get('total_estimated_cost', 0)} €"],
    ]
    t = Table(rows, colWidths=[28*mm, 60*mm, 28*mm, 64*mm])
    t.setStyle(TableStyle([
        ("FONTSIZE", (0, 0), (-1, -1), 9),
        ("TEXTCOLOR", (0, 0), (0, -1), colors.HexColor("#6b7280")),
        ("TEXTCOLOR", (2, 0), (2, -1), colors.HexColor("#6b7280")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LINEBELOW", (0, 0), (-1, -1), 0.4, colors.HexColor("#e5e7eb")),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
    ]))
    story.append(t)
    story.append(Spacer(1, 5*mm))

    # Leyenda de colores
    if damages_incluidos:
        legend_data = [[
            "Leyenda:",
            _legend_pill(colors.HexColor("#facc15"), "Leve"),
            _legend_pill(colors.HexColor("#fb923c"), "Moderado"),
            _legend_pill(colors.HexColor("#ef4444"), "Grave"),
            _legend_pill(colors.HexColor("#dc2626"), "Crítico"),
        ]]
        leg = Table(legend_data, colWidths=[18*mm, 30*mm, 35*mm, 30*mm, 30*mm])
        leg.setStyle(TableStyle([
            ("FONTSIZE", (0, 0), (-1, -1), 8.5),
            ("TEXTCOLOR", (0, 0), (0, 0), colors.HexColor("#6b7280")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
        ]))
        story.append(leg)
        story.append(Spacer(1, 3*mm))

    # Resumen ejecutivo si hay
    if analysis.get("executive_summary"):
        story.append(Paragraph("Resumen del peritaje IA", h2))
        story.append(Paragraph((analysis.get("executive_summary") or "")[:1500], body))

    # Fotos con cajas
    photos_valid = [b for b in photo_bytes_list if b]
    if photos_valid:
        story.append(Paragraph("Evidencia fotográfica con daños marcados", h2))
        msg = (f"{len(photos_valid)} fotos analizadas. "
               f"<b>Borde sólido</b> = daño confirmado por dos modelos (Gemini+YOLO/SAM). "
               f"<b>Borde discontinuo</b> = detectado por Gemini sin confirmación geométrica (caja aproximada, marcado con ~). "
               f"El hash de cada imagen está sellado en la cadena de custodia.")
        story.append(Paragraph(msg, small))
        story.append(Spacer(1, 3*mm))
        thumbs = []
        for b in photos_valid:
            try:
                img = Image(_io.BytesIO(b), width=85*mm, height=64*mm, kind="proportional")
                thumbs.append(img)
            except Exception as e:
                logger.warning(f"forensic PDF: foto inválida: {e}")
        # Tabla 2 columnas
        if thumbs:
            grid = []
            for i in range(0, len(thumbs), 2):
                row = [thumbs[i], thumbs[i+1] if i + 1 < len(thumbs) else ""]
                grid.append(row)
            tg = Table(grid, colWidths=[90*mm, 90*mm])
            tg.setStyle(TableStyle([
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING", (0, 0), (-1, -1), 2),
                ("RIGHTPADDING", (0, 0), (-1, -1), 2),
                ("TOPPADDING", (0, 0), (-1, -1), 2),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ]))
            story.append(tg)

    # Tabla de daños incluidos en el peritaje
    if damages_incluidos:
        story.append(Spacer(1, 4*mm))
        story.append(Paragraph(f"Daños incluidos en el peritaje ({len(damages_incluidos)})", h2))
        story.append(Paragraph("Cada daño cumple los criterios de veracidad: confianza ≥ 50%, caja delimitada, severidad clasificada.", small))
        story.append(Spacer(1, 2*mm))
        tdata = [["Pieza", "Severidad", "Confianza", "Foto", "Coste est."]]
        for d in damages_incluidos[:30]:
            tdata.append([
                (d.get("part") or "—")[:38],
                (d.get("severity") or "—"),
                f"{int(float(d.get('confidence', 0)) * 100)}%",
                str(d.get("photo_index") or "—"),
                f"{d.get('estimated_cost', 0)} €",
            ])
        tdmg = Table(tdata, colWidths=[68*mm, 24*mm, 22*mm, 14*mm, 22*mm])
        tdmg.setStyle(TableStyle([
            ("FONTSIZE", (0, 0), (-1, -1), 8.5),
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#f3f4f6")),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#0b1220")),
            ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
            ("LINEBELOW", (0, 0), (-1, -1), 0.3, colors.HexColor("#e5e7eb")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("LEFTPADDING", (0, 0), (-1, -1), 4),
            ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ]))
        story.append(tdmg)

    # Daños sugeridos (NO incluidos por baja confianza)
    if damages_sugeridos:
        story.append(Spacer(1, 4*mm))
        story.append(Paragraph(f"Sugerencias no incluidas ({len(damages_sugeridos)})", h2))
        story.append(Paragraph("La IA detectó estos posibles daños pero NO cumplen el umbral de veracidad para formar parte del peritaje. Revisión humana recomendada.", small))
        story.append(Spacer(1, 2*mm))
        tdata2 = [["Pieza", "Severidad", "Confianza", "Motivo de exclusión"]]
        for d in damages_sugeridos[:20]:
            conf = float(d.get("confidence", 0))
            box_ok = _is_box_valid(d.get("box_2d"))
            motivo = []
            if d.get("_motivo"): motivo.append(d["_motivo"])
            if conf < _FORENSIC_CONFIDENCE_MIN: motivo.append(f"confianza {int(conf*100)}%<50%")
            if not box_ok: motivo.append("caja inválida")
            tdata2.append([
                (d.get("part") or "—")[:38],
                (d.get("severity") or "—"),
                f"{int(conf * 100)}%",
                ", ".join(motivo) or "—",
            ])
        tsug = Table(tdata2, colWidths=[60*mm, 24*mm, 22*mm, 64*mm])
        tsug.setStyle(TableStyle([
            ("FONTSIZE", (0, 0), (-1, -1), 8),
            ("TEXTCOLOR", (0, 0), (-1, -1), colors.HexColor("#6b7280")),
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#fef3c7")),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#854d0e")),
            ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
            ("LINEBELOW", (0, 0), (-1, -1), 0.3, colors.HexColor("#fde68a")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ]))
        story.append(tsug)

    # Sección de firma + cadena
    story.append(PageBreak())
    story.append(Paragraph("Firma electrónica y cadena de custodia", h2))
    sig_rows = [
        ["Firmado por", sig.get("signed_by_name", "—")],
        ["Fecha de firma", (sig.get("signed_at") or "")[:19].replace("T", " ")],
        ["IP del firmante", sig.get("client_ip", "—")],
        ["Hash de esta inspección", Paragraph(sig.get("content_hash", "—"), mono)],
        ["Hash anterior en la cadena", Paragraph(sig.get("prev_hash", "—"), mono)],
        ["Revisión", str(sig.get("revision", 1))],
    ]
    st = Table(sig_rows, colWidths=[55*mm, 119*mm])
    st.setStyle(TableStyle([
        ("FONTSIZE", (0, 0), (-1, -1), 9),
        ("TEXTCOLOR", (0, 0), (0, -1), colors.HexColor("#6b7280")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LINEBELOW", (0, 0), (-1, -1), 0.4, colors.HexColor("#e5e7eb")),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
    ]))
    story.append(st)
    story.append(Spacer(1, 4*mm))

    # Declaración firmada
    if sig.get("signature_text"):
        story.append(Paragraph("Declaración aceptada por el firmante", h2))
        story.append(Paragraph(f"«{sig.get('signature_text','')}»", body))
    story.append(Spacer(1, 6*mm))

    # QR al verificador
    try:
        qr_png = _generate_qr_png(verify_url)
        qr_img = Image(_io.BytesIO(qr_png), width=32*mm, height=32*mm)
        qr_tbl = Table([[qr_img,
                         Paragraph(f"<b>Verifica este peritaje</b><br/>{verify_url}<br/><br/>"
                                   f"Escanea el QR o introduce el hash en el verificador público.", body)]],
                       colWidths=[36*mm, 138*mm])
        qr_tbl.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "MIDDLE")]))
        story.append(qr_tbl)
    except Exception as e:
        logger.warning(f"forensic PDF: QR falló: {e}")

    # Disclaimer legal honesto
    story.append(Spacer(1, 8*mm))
    story.append(Paragraph(
        "<b>Aviso:</b> este documento es evidencia técnica con cadena de custodia hash, NO una firma "
        "electrónica avanzada conforme al reglamento eIDAS. FlotaDSP no presta servicios de asesoría "
        "jurídica. La validez probatoria del documento dependerá de la valoración que haga el "
        "destinatario o, en su caso, la autoridad competente.", small))

    doc.build(story)
    return buf.getvalue()


def _build_damage_report_pdf(insp: dict, vehicle: dict, driver_name: str,
                             dmg: dict, annotated_photo: Optional[bytes]) -> bytes:
    """Parte de daño individual (1-2 páginas): foto anotada + datos clave + hash.
    Pensado para enviarse tal cual al renting o al seguro."""
    import io as _io
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Image as RLImage,
                                    Table, TableStyle)

    buf = _io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, topMargin=16 * mm, bottomMargin=14 * mm,
                            leftMargin=16 * mm, rightMargin=16 * mm,
                            title="Parte de daño — FlotaDSP")
    ss = getSampleStyleSheet()
    h1 = ParagraphStyle("h1", parent=ss["Title"], fontSize=17, spaceAfter=2)
    small = ParagraphStyle("small", parent=ss["Normal"], fontSize=8.5, textColor=colors.grey)
    body = ParagraphStyle("body", parent=ss["Normal"], fontSize=10.5, leading=15)

    sev = (dmg.get("severity") or "").capitalize()
    fecha = (insp.get("created_at") or "")[:16].replace("T", " ")
    story = [
        Paragraph("PARTE DE DAÑO DE VEHÍCULO", h1),
        Paragraph("Documento generado por FlotaDSP — registro fotográfico con sello temporal", small),
        Spacer(1, 6 * mm),
    ]

    rows = [
        ["Matrícula", vehicle.get("license_plate") or "—",
         "Marca / Modelo", f"{vehicle.get('brand') or ''} {vehicle.get('model') or ''}".strip() or "—"],
        ["Fecha de detección", fecha or "—", "Conductor asignado", driver_name or "—"],
        ["Pieza afectada", dmg.get("part") or "—", "Severidad", sev or "—"],
        ["Coste estimado reparación", f"{float(dmg.get('estimated_cost') or 0):,.0f} €".replace(",", "."),
         "Centro", vehicle.get("center") or "—"],
    ]
    t = Table(rows, colWidths=[38 * mm, 52 * mm, 42 * mm, 46 * mm])
    t.setStyle(TableStyle([
        ("FONTSIZE", (0, 0), (-1, -1), 9),
        ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"),
        ("FONTNAME", (2, 0), (2, -1), "Helvetica-Bold"),
        ("TEXTCOLOR", (0, 0), (0, -1), colors.HexColor("#555555")),
        ("TEXTCOLOR", (2, 0), (2, -1), colors.HexColor("#555555")),
        ("LINEBELOW", (0, 0), (-1, -2), 0.4, colors.HexColor("#dddddd")),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
    ]))
    story.append(t)
    story.append(Spacer(1, 5 * mm))

    if dmg.get("description"):
        story.append(Paragraph(f"<b>Descripción técnica:</b> {dmg['description'][:600]}", body))
        story.append(Spacer(1, 4 * mm))

    if annotated_photo:
        try:
            from PIL import Image as PILImage
            pil = PILImage.open(_io.BytesIO(annotated_photo))
            iw, ih = pil.size
            max_w = 178 * mm
            max_h = 150 * mm
            ratio = min(max_w / iw, max_h / ih)
            story.append(RLImage(_io.BytesIO(annotated_photo), width=iw * ratio, height=ih * ratio))
            story.append(Spacer(1, 2 * mm))
            story.append(Paragraph("Fotografía original de la inspección con el daño señalizado automáticamente.", small))
        except Exception as _ie:
            logger.warning(f"parte PDF: imagen no embebible: {_ie}")

    story.append(Spacer(1, 6 * mm))
    fh = insp.get("forensic_hash") or ""
    integrity = (f"Integridad: las fotos originales están selladas con hash SHA-256 ({fh[:24]}…) "
                 f"en el momento de la subida." if fh else
                 "Las fotos originales se conservan sin alteración en el sistema.")
    story.append(Paragraph(
        f"{integrity} Inspección {insp.get('id', '')} · Generado el "
        f"{datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC')} · flotadsp.com", small))

    doc.build(story)
    return buf.getvalue()


@api_router.get("/inspections/{inspection_id}/damage-report")
async def damage_report_pdf(inspection_id: str, damage_index: int, scope: str = "new",
                            _=Depends(require_admin)):
    """PARTE DE DAÑO EN UN CLIC: PDF de un daño concreto (foto anotada + datos +
    coste + sello), listo para enviar al renting o al seguro."""
    insp = await db.inspections.find_one({"id": inspection_id}, {"_id": 0})
    if not insp:
        raise HTTPException(status_code=404, detail="Inspección no encontrada")
    analysis = insp.get("analysis") or {}
    pool = analysis.get("new_damages" if scope == "new" else "damages") or []
    if not (0 <= damage_index < len(pool)):
        raise HTTPException(status_code=404, detail="Daño no encontrado")
    dmg = pool[damage_index] if isinstance(pool[damage_index], dict) else {}

    vehicle = await db.vehicles.find_one({"id": insp.get("vehicle_id")}, {"_id": 0}) or {}
    driver_name = ""
    if insp.get("driver_id"):
        drv = await db.drivers.find_one({"id": insp["driver_id"]}, {"_id": 0, "name": 1})
        driver_name = (drv or {}).get("name", "")

    # Foto donde está el daño, anotada con su caja
    photos = insp.get("photos") or []
    pi = dmg.get("photo_index")
    photo_url = photos[pi - 1] if (isinstance(pi, int) and 1 <= pi <= len(photos)) else (photos[0] if photos else None)
    annotated = None
    if photo_url:
        raw = await _fetch_photo_bytes(photo_url, timeout=10)
        if raw:
            annotated = _annotate_photo_with_damages(raw, [dmg])

    loop = asyncio.get_running_loop()
    pdf_bytes = await loop.run_in_executor(
        None, _build_damage_report_pdf, insp, vehicle, driver_name, dmg, annotated)

    from fastapi.responses import Response as _Resp
    plate = (vehicle.get("license_plate") or "vehiculo").replace(" ", "")
    return _Resp(
        content=pdf_bytes, media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="parte-dano-{plate}-{inspection_id[:8]}.pdf"'},
    )


@api_router.get("/inspections/{inspection_id}/forensic-pdf")
async def forensic_pdf(inspection_id: str, _=Depends(require_admin)):
    """Genera y devuelve el PDF de peritaje técnico de una inspección firmada."""
    insp = await db.inspections.find_one({"id": inspection_id, "deleted": {"$ne": True}}, {"_id": 0})
    if not insp:
        raise HTTPException(status_code=404, detail="Inspección no encontrada")
    if not insp.get("forensic_signed"):
        raise HTTPException(status_code=409, detail="Esta inspección aún no está firmada. Fírmala antes de generar el peritaje.")
    sig = await db.forensic_signatures.find_one({"inspection_id": inspection_id}, {"_id": 0})
    if not sig:
        raise HTTPException(status_code=500, detail="Firma marcada pero no encontrada (estado inconsistente).")
    vehicle = await db.vehicles.find_one({"id": insp.get("vehicle_id")}, {"_id": 0}) or {}
    driver_name = "—"
    did = insp.get("driver_id") or vehicle.get("current_driver_id")
    if did:
        d = await db.drivers.find_one({"id": did}, {"_id": 0, "name": 1})
        if d:
            driver_name = d.get("name", "—")
    photos = (insp.get("photos") or [])[:6]
    raw_bytes_list = await asyncio.gather(*[_fetch_photo_bytes(u) for u in photos]) if photos else []

    # Filtrar daños incluidos vs sugeridos (umbral de veracidad inicial sobre Gemini).
    all_damages = ((insp.get("analysis") or {}).get("damages") or []) + \
                  ((insp.get("analysis") or {}).get("new_damages") or [])
    # Dedupe por (part, photo_index, hash de box) para no duplicar entre damages y new_damages.
    seen, dedup = set(), []
    for d in all_damages:
        k = (d.get("part"), d.get("photo_index"), tuple(d.get("box_2d") or []))
        if k in seen: continue
        seen.add(k); dedup.append(d)
    gemini_incluidos, damages_sugeridos = _filter_damages_for_peritaje(dedup)

    # ENSEMBLE STRICT: cruzar Gemini con YOLO+SAM por foto. Solo dibujamos cajas confirmadas.
    refined_per_photo = []
    incluidos_keys = set()
    for i in range(len(raw_bytes_list)):
        gem_for_photo = [d for d in gemini_incluidos if (d.get("photo_index") or 1) == (i + 1)]
        rfn = await _refine_damage_boxes_with_yolo_sam(inspection_id, i, gem_for_photo)
        refined_per_photo.append(rfn)
        for d in rfn:
            incluidos_keys.add((d.get("part"), d.get("photo_index")))
    damages_incluidos = [d for sub in refined_per_photo for d in sub]
    # Los Gemini que NO pasaron el filtro estricto pasan a "sugeridos" (transparencia total).
    for g in gemini_incluidos:
        if (g.get("part"), g.get("photo_index")) not in incluidos_keys:
            damages_sugeridos.append({**g, "_motivo": "no confirmado por YOLO/SAM"})

    # Anotar cada foto con sus daños refinados.
    annotated_bytes_list = []
    for i, raw in enumerate(raw_bytes_list):
        if not raw:
            annotated_bytes_list.append(None)
            continue
        annotated_bytes_list.append(_annotate_photo_with_damages(raw, refined_per_photo[i]))

    verify_url = f"{_PORTAL_BASE_FRONT}/verify/{sig['content_hash']}"
    # Generación PDF en hilo (reportlab es síncrono y CPU-bound).
    loop = asyncio.get_event_loop()
    pdf_bytes = await loop.run_in_executor(
        None, _build_forensic_pdf, insp, sig, vehicle, driver_name, annotated_bytes_list, verify_url,
        damages_incluidos, damages_sugeridos
    )
    fn_plate = re.sub(r"[^A-Za-z0-9]", "", (vehicle.get("license_plate") or "INSP"))
    fn_date = (sig.get("signed_at") or "")[:10]
    filename = f"peritaje-{fn_plate}-{fn_date}.pdf"
    from starlette.responses import Response
    return Response(
        content=pdf_bytes, media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@api_router.get("/verify/{content_hash}")
async def verify_hash_public(content_hash: str, request: Request):
    """Verificador PÚBLICO (sin auth) de un hash de peritaje.
    Devuelve solo info mínima no sensible. Rate-limited para evitar scraping enumerativo."""
    ip = _rl_key_ip(request)
    _rl_public_action(f"verify-ip-min:{ip}", max_count=20, window_s=60,
                      detail="Demasiadas verificaciones. Espera un minuto.")
    _rl_public_action(f"verify-ip-hour:{ip}", max_count=200, window_s=3600,
                      detail="Demasiadas verificaciones esta hora.")
    h = (content_hash or "").strip().lower()
    if len(h) != 64 or not re.match(r"^[0-9a-f]+$", h):
        raise HTTPException(status_code=400, detail="Hash inválido (debe ser SHA-256 hex de 64 caracteres).")

    # Localiza el tenant donde vive este hash (índice global creado al firmar).
    idx = await global_db.forensic_index.find_one({"content_hash": h}, {"_id": 0})
    if not idx:
        return {"valid": False, "error": "Hash no encontrado. Puede que no exista o que se firmara antes de junio 2026."}

    # Carga el cliente de Mongo del tenant correcto.
    tenant_db = client[idx["db_name"]]
    sig = await tenant_db.forensic_signatures.find_one({"content_hash": h}, {"_id": 0})
    if not sig:
        return {"valid": False, "error": "Inconsistencia interna. Contacta con soporte."}
    insp = await tenant_db.inspections.find_one({"id": sig.get("inspection_id")},
                                                 {"_id": 0, "vehicle_id": 1, "created_at": 1, "id": 1}) or {}
    vehicle = await tenant_db.vehicles.find_one({"id": insp.get("vehicle_id")},
                                                 {"_id": 0, "license_plate": 1}) or {}
    next_sig = await tenant_db.forensic_signatures.find_one(
        {"signed_at": {"$gt": sig.get("signed_at", "")}}, {"_id": 0, "content_hash": 1}
    )

    return {
        "valid": True,
        "hash": h,
        "prev_hash": sig.get("prev_hash"),
        "signed_at": sig.get("signed_at"),
        "signed_by_name": sig.get("signed_by_name", ""),
        "inspection_date": insp.get("created_at"),
        "vehicle_plate_masked": _mask_plate(vehicle.get("license_plate", "")),
        "has_next_in_chain": bool(next_sig),
        "disclaimer": "Evidencia técnica con cadena de custodia hash. No constituye firma electrónica avanzada eIDAS.",
    }


# =========================
# CHECKLIST OPERATIVO POR CENTRO/TURNO (dispatcher)
# =========================
# 1 doc por (center, date, shift) en db.daily_checklists. Items con done/done_by/done_at.
# Permisos: el admin ve solo los centros de su allowed_centers (o todos si no esta seteado).

_DEFAULT_CHECKLIST_ITEMS_MANANA = [
    "Confirmar asignaciones conductor-vehículo",
    "Revisar vehículos con daños o avisos abiertos",
    "Briefing de mañana completado",
    "Verificar combustible de la flota",
    "Comprobar la documentación de los vehículos que salen",
]

_DEFAULT_CHECKLIST_ITEMS_TARDE = [
    "Recepción de vehículos del turno de mañana",
    "Revisión de incidencias del día",
    "Confirmar asignaciones conductor-vehículo (tarde)",
    "Briefing de tarde completado",
    "Cierre y documentación de turno",
]

def _default_items_for_shift(shift: str) -> list:
    src = _DEFAULT_CHECKLIST_ITEMS_TARDE if shift == "tarde" else _DEFAULT_CHECKLIST_ITEMS_MANANA
    return [{"id": str(uuid.uuid4()), "text": t, "done": False, "done_by": None, "done_at": None} for t in src]


async def _template_items_for(center: str, shift: str) -> list:
    """Items iniciales del día para UN centro: su plantilla propia si la tiene,
    y si no, la genérica. Así cada centro tiene sus tareas recurrentes SUYAS
    (antes todos los centros clonaban la misma lista fija cada día)."""
    tpl = await db.checklist_templates.find_one(
        {"center": center, "shift": shift}, {"_id": 0, "texts": 1})
    texts = (tpl or {}).get("texts")
    if not texts:
        # Las de fábrica nacen fijas: si no, el primer día que alguien edite la
        # lista se borrarían todas de la plantilla sin haberlo pedido.
        return [{**i, "fija": True} for i in _default_items_for_shift(shift)]
    return [{"id": str(uuid.uuid4()), "text": t, "done": False, "done_by": None,
             "done_at": None, "fija": True}
            for t in texts if (t or "").strip()]


@api_router.post("/checklist/template")
async def save_checklist_template(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Marca TODAS las tareas de hoy como fijas, de una vez.

    Es el atajo para cuando la lista entera es recurrente: con nueve tareas,
    poner nueve chinchetas a mano cansa. La chincheta por tarea sigue siendo lo
    que manda — esto solo las pone todas.
    """
    center = _texto_cuerpo(data.get("center"), 30)
    shift = data.get("shift")
    date = _texto_cuerpo(data.get("date"), 10) or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    if not center or shift not in ("manana", "tarde"):
        raise HTTPException(400, "Faltan center/shift válidos")
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a este centro")
    texts = [(it.get("text") or "").strip()[:300] if isinstance(it, dict) else str(it).strip()[:300]
             for it in _lista_cuerpo(data.get("items"))]
    texts = [t for t in texts if t][:50]
    now = datetime.now(timezone.utc).isoformat()
    await db.checklist_templates.update_one(
        {"center": center, "shift": shift},
        {"$set": {"center": center, "shift": shift, "texts": texts,
                  "updated_by": user.get("name"), "updated_at": now}},
        upsert=True,
    )
    # Y en la lista de hoy, para que la chincheta se vea al momento: si no, la
    # pantalla diría "solo hoy" de tareas que acaban de quedar fijas.
    await db.daily_checklists.update_many(
        {"center": center, "date": date, "shift": shift},
        {"$set": {"items.$[].fija": True, "updated_at": now}},
    )
    return {"ok": True, "count": len(texts)}


def _user_can_see_center(user: dict, center: str) -> bool:
    """True si el usuario admin puede ver ese centro. Super-admin/owner ve todos."""
    if user.get("sa") or user.get("account_type") == "owner":
        return True
    ac = user.get("allowed_centers")
    if not ac:
        return True   # sin restricción: ve todos los de la org
    # Los centros en BD vienen sucios ('AMZL OGA5 SANTIAGO XPT'), así que se
    # compara por código contenido, no por igualdad exacta.
    c = (center or "").upper()
    return any(p.upper() in c or c in p.upper() for p in ac if p)


async def _filtro_por_vehiculos(user: dict, center: Optional[str] = None) -> dict:
    """Igual que _filtro_centro pero para colecciones SIN campo 'center'.

    inspections, incidents y alerts no guardan el centro (0 de 2.380 documentos
    en producción) pero todas llevan vehicle_id, así que se acota por las
    furgonetas de esos centros. Esto arregla de paso el filtro por centro de
    inspecciones, que consultaba un campo inexistente y devolvía siempre vacío
    (lo usa Asignación diaria).

    Devuelve {} si no hay nada que acotar.
    """
    sub = _filtro_centro(user, center)          # valida permisos y devuelve el regex
    if not sub:
        return {}
    ids = await db.vehicles.distinct("id", sub)
    return {"vehicle_id": {"$in": ids}}


def _filtro_centro(user: dict, center: Optional[str] = None) -> dict:
    """Trozo de query con los centros que este usuario PUEDE ver.

    Sin esto, un dispatcher limitado a OGA5 pedía ?center=DGA1 (o ninguno) y
    veía los demás centros: allowed_centers estaba definido pero no llegaba a
    filtrar ninguna consulta de datos.
    """
    permitidos = [p for p in (user.get("allowed_centers") or []) if p] \
        if not (user.get("sa") or user.get("account_type") == "owner") else []

    if center and center != "Todos":
        if not re.match(r'^[A-Za-z0-9_\- ]{1,30}$', center):
            raise HTTPException(400, "Código de centro inválido")
        if not _user_can_see_center(user, center):
            raise HTTPException(403, "No tienes acceso a ese centro")
        return {"center": {"$regex": re.escape(center.strip()), "$options": "i"}}

    if permitidos:
        return {"center": {"$regex": "|".join(re.escape(p) for p in permitidos),
                           "$options": "i"}}
    return {}


@api_router.get("/checklist")
async def get_checklist(center: str, date: Optional[str] = None,
                        user: dict = Depends(require_admin)):
    """Devuelve los 2 turnos (mañana, tarde) de un centro y día. Crea con defaults si no existe."""
    if not center:
        raise HTTPException(400, "Centro requerido")
    if center.strip().lower() in ("todos", "all"):
        # La lista es POR CENTRO y se crea sola la primera vez que se pide:
        # con «Todos» se creaba un turno fantasma para un centro que no
        # existe, que nadie ve desde su centro (medido el 02-09-2026).
        raise HTTPException(400, "Elige un centro: la lista de tareas es por centro")
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a este centro")
    date = date or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    docs = await db.daily_checklists.find({"center": center, "date": date}, {"_id": 0}).to_list(2)
    by_shift = {d["shift"]: d for d in docs}
    result = {}
    now = datetime.now(timezone.utc).isoformat()
    for shift in ("manana", "tarde"):
        if shift in by_shift:
            result[shift] = by_shift[shift]
            continue
        # No existe: crear y PERSISTIR con la plantilla DEL CENTRO (IDs estables).
        new_doc = {
            "id": str(uuid.uuid4()), "center": center, "date": date, "shift": shift,
            "items": await _template_items_for(center, shift),
            "created_at": now, "updated_at": now,
        }
        try:
            # dict(...) NO sobra: insert_one MUTA el dict que le pasas y le mete
            # `_id` con un ObjectId. Como este mismo `new_doc` es lo que se
            # devuelve, sin la copia FastAPI no sabe serializarlo y responde 500.
            # Solo reventaba la peticion que CREA —las siguientes leen el
            # documento con proyeccion `{"_id": 0}`—, o sea el PRIMERO que abria
            # el checklist cada dia, en todos los centros. Al recargar funciona,
            # asi que nadie lo reportaba nunca.
            await db.daily_checklists.insert_one(dict(new_doc))
        except DuplicateKeyError:
            # Race: alguien lo creó entre el find y el insert. Recargamos.
            existing = await db.daily_checklists.find_one(
                {"center": center, "date": date, "shift": shift}, {"_id": 0})
            if existing:
                result[shift] = existing
                continue
        result[shift] = new_doc
    return result


@api_router.put("/checklist")
async def upsert_checklist(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Crea/actualiza la lista de items de un (center,date,shift). El cliente envía items completos."""
    center = _texto_cuerpo(data.get("center"), 30)
    date = _texto_cuerpo(data.get("date"), 10) or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    shift = data.get("shift")
    if not center or shift not in ("manana", "tarde"):
        raise HTTPException(400, "Faltan center/shift válidos")
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a este centro")
    raw_items = _lista_cuerpo(data.get("items"))
    items = []
    for it in raw_items:
        if not isinstance(it, dict):
            continue
        text = (it.get("text") or "").strip()
        if not text:
            continue
        items.append({
            "id": it.get("id") or str(uuid.uuid4()),
            "text": text[:300],
            "done": bool(it.get("done")),
            "done_by": it.get("done_by"),
            "done_at": it.get("done_at"),
            # Fija = sale todos los días. Sin marcar = solo hoy.
            "fija": bool(it.get("fija")),
        })
    # Detectar tareas NUEVAS (para avisar por push a los del centro)
    _prev = await db.daily_checklists.find_one(
        {"center": center, "date": date, "shift": shift}, {"_id": 0, "items.id": 1})
    _prev_ids = {i.get("id") for i in (_prev or {}).get("items", [])}
    _new_items = [i for i in items if i["id"] not in _prev_ids] if _prev else []

    now = datetime.now(timezone.utc).isoformat()
    await db.daily_checklists.update_one(
        {"center": center, "date": date, "shift": shift},
        {"$set": {"items": items, "updated_at": now, "updated_by": user.get("name")},
         "$setOnInsert": {"id": str(uuid.uuid4()), "center": center, "date": date, "shift": shift,
                          "created_at": now}},
        upsert=True,
    )
    # ── La plantilla del centro SON las tareas marcadas como fijas ───────────
    # Antes había que acordarse de pulsar un botón aparte ("guardar como
    # plantilla") que además reemplazaba la lista entera: o todas recurrentes o
    # ninguna. Ahora cada tarea lleva su chincheta y la plantilla sale de ahí,
    # así que "para siempre" y "solo hoy" se deciden al escribirla, que es
    # cuando se sabe.
    fijas = [i["text"] for i in items if i.get("fija")][:50]
    await db.checklist_templates.update_one(
        {"center": center, "shift": shift},
        {"$set": {"center": center, "shift": shift, "texts": fijas,
                  "updated_by": user.get("name"),
                  "updated_at": now}},
        upsert=True,
    )

    # Push a los coordinadores del centro por cada tarea nueva (máx 3 avisos)
    for _ni in _new_items[:3]:
        await push_center_event(
            center, f"📝 Nueva tarea · {center}", _ni.get("text", ""),
            url="/panel/checklist-operativo", exclude_id=user.get("sub"))
    return {"ok": True, "count": len(items), "new_items": len(_new_items),
            "fijas": len(fijas)}


@api_router.delete("/chat/{center}/{message_id}")
async def chat_delete_message(center: str, message_id: str, user: dict = Depends(require_admin)):
    """Borra un mensaje del chat del centro. El autor puede borrar los suyos;
    el super-admin/owner puede borrar cualquiera."""
    if not await _chat_room_can_access(user, center):
        raise HTTPException(403, "No tienes acceso a este chat")
    msg = await db.chat_messages.find_one({"id": message_id, "center": center}, {"_id": 0})
    if not msg:
        raise HTTPException(404, "Mensaje no encontrado")
    is_owner_like = user.get("sa") or user.get("account_type") == "owner"
    if msg.get("author_id") != user.get("sub") and not is_owner_like:
        raise HTTPException(403, "Solo puedes borrar tus propios mensajes")
    await db.chat_messages.delete_one({"id": message_id, "center": center})
    return {"ok": True}


@api_router.post("/checklist/toggle")
async def toggle_checklist_item(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Marca/desmarca un item concreto. Más rápido que reenviar la lista entera."""
    center = _texto_cuerpo(data.get("center"), 30)
    date = _texto_cuerpo(data.get("date"), 10) or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    shift = data.get("shift")
    item_id = data.get("item_id")
    done = bool(data.get("done"))
    if not center or shift not in ("manana", "tarde") or not item_id:
        raise HTTPException(400, "Faltan center/shift/item_id")
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a este centro")
    now = datetime.now(timezone.utc).isoformat()
    # 1) Asegurar que el doc existe (con defaults si no).
    doc = await db.daily_checklists.find_one({"center": center, "date": date, "shift": shift}, {"_id": 0})
    if not doc:
        doc = {
            "id": str(uuid.uuid4()), "center": center, "date": date, "shift": shift,
            "items": _default_items_for_shift(shift),
            "created_at": now, "updated_at": now,
        }
        await db.daily_checklists.insert_one(doc)
    # 2) Toggle item por id.
    items = doc.get("items", [])
    found = False
    for it in items:
        if it.get("id") == item_id:
            it["done"] = done
            it["done_by"] = user.get("name") if done else None
            it["done_at"] = now if done else None
            found = True
            break
    if not found:
        raise HTTPException(404, "Item no encontrado")
    await db.daily_checklists.update_one(
        {"center": center, "date": date, "shift": shift},
        {"$set": {"items": items, "updated_at": now}}
    )

    # ── Avisar a los coordinadores del centro ────────────────────────────────
    # La queja de fondo no era que no se apuntara quién y cuándo (eso ya se
    # guardaba y se veía), sino tener que ENTRAR a mirarlo. Quien lleva el
    # centro se entera en el momento, sin abrir nada.
    #
    # Sólo al marcar: destildar suele ser corregir un toque mal dado, y avisar
    # de eso convertiría el aviso en ruido, que es como se acaban silenciando.
    if done:
        hechas = sum(1 for x in items if x.get("done"))
        texto = next((x.get("text") for x in items if x.get("id") == item_id), "")
        await push_center_event(
            center,
            f"{center} · {'mañana' if shift == 'manana' else 'tarde'} · {hechas}/{len(items)}",
            f"{user.get('name') or 'Alguien'} ✓ {texto}",
            "/panel/checklist-operativo",
            exclude_id=user.get("sub"),          # a quien la marca no se le avisa
        )
    return {"ok": True}


async def _resumen_turno(center: str, date: str, shift: str) -> Optional[dict]:
    """Cómo ha quedado el checklist de un turno. None si ese turno no existe.

    Devolver None cuando no hay checklist es deliberado: un centro que ese día
    no abrió turno no debe generar un "0 de 0 hechas" que parece un problema.
    """
    doc = await db.daily_checklists.find_one(
        {"center": center, "date": date, "shift": shift}, {"_id": 0})
    items = (doc or {}).get("items") or []
    if not items:
        return None
    hechas = [i for i in items if i.get("done")]
    faltan = [i for i in items if not i.get("done")]
    return {
        "center": center, "date": date, "shift": shift,
        "total": len(items), "hechas": len(hechas),
        "faltan": [i.get("text") or "—" for i in faltan],
        "quien": sorted({i.get("done_by") for i in hechas if i.get("done_by")}),
        "ultima": max((i.get("done_at") or "" for i in hechas), default=""),
    }


async def enviar_resumen_turno(shift: str, date: Optional[str] = None) -> list:
    """Manda el cierre de turno de cada centro: qué se hizo y qué quedó colgado.

    Es la otra mitad de los avisos al marcar. Ver los ticks según caen dice si
    la cosa avanza; esto dice cómo acabó, que es lo que hace falta para tirar
    de alguien al día siguiente sin ir de memoria.

    Va por push a los coordinadores del centro (gratis, inmediato) y por
    Telegram al grupo. El aviso por WhatsApp usará este mismo texto: lo que
    falta ahí no es el mensaje, son las credenciales de la API de Meta.
    """
    date = date or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    centros = await db.daily_checklists.distinct("center", {"date": date, "shift": shift})
    turno = "mañana" if shift == "manana" else "tarde"
    enviados = []

    for center in sorted(c for c in centros if c):
        r = await _resumen_turno(center, date, shift)
        if not r:
            continue
        todo_hecho = not r["faltan"]
        titulo = f"{center} · {turno}: {r['hechas']}/{r['total']}"
        cuerpo = ("Todo hecho ✓" if todo_hecho
                  else "Falta: " + ", ".join(r["faltan"][:3])
                       + (f" y {len(r['faltan']) - 3} más" if len(r["faltan"]) > 3 else ""))
        await push_center_event(center, titulo, cuerpo, "/panel/checklist-operativo")

        # Telegram: el mismo contenido pero sin recortar, que ahí sí cabe.
        lineas = [f"{'✅' if todo_hecho else '⚠️'} <b>{center} · turno de {turno}</b>",
                  f"{r['hechas']} de {r['total']} tareas hechas"]
        if r["quien"]:
            lineas.append("Las marcaron: " + ", ".join(r["quien"]))
        if r["faltan"]:
            lineas.append("\n<b>Sin hacer:</b>")
            lineas += [f"• {t}" for t in r["faltan"]]
        await _telegram_aviso("\n".join(lineas))
        enviados.append({"center": center, **{k: r[k] for k in ("hechas", "total")},
                         "faltan": len(r["faltan"])})

    if not enviados:
        logger.info("Resumen de turno %s %s: ningún centro con checklist", shift, date)
    return enviados


# =========================
# A QUIÉN SE AVISA — destinatarios de los resúmenes por centro
# =========================
# Los teléfonos NO van en el código. Son datos personales de gente real y el
# repositorio se sincroniza entre ordenadores y sube a GitHub: un número escrito
# en un fichero .py se queda ahí para siempre y en el historial de git. Viven en
# la base, editables desde Configuración.
_AVISOS_TIPOS = {"resumen_diario", "cierre_turno"}


def _tel_normaliza(crudo: str) -> str:
    """+34 seguido de dígitos. Sin esto entra '625 84 70 35' y WhatsApp lo
    rechaza: la API exige el número en formato internacional, sin espacios."""
    t = re.sub(r"[^\d+]", "", str(crudo or ""))
    if not t:
        return ""
    if t.startswith("00"):
        t = "+" + t[2:]
    if not t.startswith("+"):
        t = ("+34" + t) if len(t) == 9 else ("+" + t)
    if not re.fullmatch(r"\+\d{8,15}", t):
        raise HTTPException(400, f"Teléfono no válido: {crudo}")
    return t


@api_router.get("/avisos/destinatarios")
async def listar_destinatarios(user: dict = Depends(require_admin)):
    """Quién recibe cada resumen. Sólo de los centros que este usuario ve."""
    rows = await db.aviso_destinatarios.find({}, {"_id": 0}).sort("nombre", 1).to_list(200)
    return {"rows": [r for r in rows
                     if not r.get("centers") or any(_user_can_see_center(user, c) for c in r["centers"])]}


@api_router.post("/avisos/destinatarios")
async def guardar_destinatario(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Alta o edición de un destinatario."""
    nombre = str(data.get("nombre") or "").strip()[:80]
    if not nombre:
        raise HTTPException(400, "Falta el nombre")
    centers = [str(c).strip()[:30] for c in _lista_cuerpo(data.get("centers")) if str(c).strip()]
    for c in centers:
        if not _user_can_see_center(user, c):
            raise HTTPException(403, f"No tienes acceso a {c}")
    avisos = [a for a in _lista_cuerpo(data.get("avisos")) if a in _AVISOS_TIPOS] or ["resumen_diario"]
    email = str(data.get("email") or "").strip().lower()[:120]
    if email and not re.fullmatch(r"[^@\s]+@[^@\s]+\.[a-z]{2,}", email):
        raise HTTPException(400, f"Correo no válido: {email}")
    doc = {"nombre": nombre, "telefono": _tel_normaliza(data.get("telefono")),
           "email": email or None,
           "centers": centers, "avisos": avisos, "activo": bool(data.get("activo", True)),
           "updated_at": datetime.now(timezone.utc).isoformat(), "updated_by": user.get("name")}
    did = str(data.get("id") or "")
    if did:
        r = await db.aviso_destinatarios.update_one({"id": did}, {"$set": doc})
        if not r.matched_count:
            raise HTTPException(404, "Destinatario no encontrado")
        return {"ok": True, "id": did}
    doc["id"] = str(uuid.uuid4())
    doc["created_at"] = doc["updated_at"]
    await db.aviso_destinatarios.insert_one(dict(doc))
    return {"ok": True, "id": doc["id"]}


@api_router.delete("/avisos/destinatarios/{did}")
async def borrar_destinatario(did: str, _=Depends(require_admin)):
    r = await db.aviso_destinatarios.delete_one({"id": did})
    if not r.deleted_count:
        raise HTTPException(404, "Destinatario no encontrado")
    return {"ok": True}


async def _danos_nuevos_hoy(center: str, dia: str) -> list:
    """Golpes nuevos de hoy en ese centro: qué golpe, en qué furgoneta y quién.

    Sale de las inspecciones del día cruzadas con las furgonetas del centro:
    `inspections` no guarda el centro (gotcha 6), así que se acota por
    vehicle_id, igual que hace el resto del panel.

    El conductor sale del CUADRANTE del día, no de quien hizo la foto: quien
    revisa por la mañana no tiene por qué ser quien luego lleva la furgoneta.
    Si el cuadrante no dice quién, se queda sin nombre — poner uno a dedo en un
    parte de daños es exactamente lo que no se puede hacer.
    """
    ids = await db.vehicles.distinct(
        "id", {"center": {"$regex": re.escape(center), "$options": "i"},
               "status": {"$nin": ["deleted", "baja"]}})
    if not ids:
        return []
    insps = await db.inspections.find(
        {"deleted": {"$ne": True}, "vehicle_id": {"$in": ids},
         "created_at": {"$regex": f"^{dia}"}},
        {"_id": 0, "vehicle_id": 1, "analysis": 1, "driver_name": 1}).to_list(2000)

    asig = await db.daily_assignments.find_one(
        {"date": dia, "center": {"$regex": re.escape(center), "$options": "i"}}, {"_id": 0})
    cond_por_veh = {s.get("vehicle_id"): (s.get("driver_name") or "")
                    for s in (asig or {}).get("slots", []) if s.get("vehicle_id")}

    con_dano = {}
    for i in insps:
        nuevos = [d for d in ((i.get("analysis") or {}).get("new_damages") or [])
                  if isinstance(d, dict)]
        if nuevos:
            con_dano.setdefault(i["vehicle_id"], []).extend(nuevos)
    if not con_dano:
        return []

    placas = {v["id"]: v.get("license_plate") or "—" for v in await db.vehicles.find(
        {"id": {"$in": list(con_dano)}}, {"_id": 0, "id": 1, "license_plate": 1}).to_list(200)}
    out = []
    for vid, danos in con_dano.items():
        for d in danos:
            out.append({
                "matricula": placas.get(vid, "—"),
                "parte": d.get("part") or d.get("panel") or "—",
                "gravedad": (d.get("severity") or "").lower() or None,
                "conductor": cond_por_veh.get(vid) or None,
            })
    return sorted(out, key=lambda x: (x["matricula"], x["parte"]))


async def _vehiculos_de_sede(center: str, excluir=("deleted", "baja")) -> list:
    """Los ids de los vehículos de una sede.

    `inspections` e `incidents` NO guardan la sede (gotcha 6): se acotan por los
    vehículos de la sede, que es lo que hace el resto del panel.
    """
    return await db.vehicles.distinct(
        "id", {"center": {"$regex": re.escape(center), "$options": "i"},
               "status": {"$nin": list(excluir)}})


async def _inspecciones_del_dia(center: str, dia: str) -> dict:
    """Cuántos vehículos de la sede se han inspeccionado hoy, de cuántos.

    Se cuentan VEHÍCULOS distintos, no inspecciones: dos revisiones de la misma
    furgoneta el mismo día son una furgoneta revisada, y contarlas dos veces
    daría un «42 de 41» que nadie se cree.

    Los que están en el taller no cuentan en el total: no se pueden revisar, y
    meterlos en el denominador haría parecer que se ha dejado trabajo sin hacer.
    """
    ids = await _vehiculos_de_sede(center, ("deleted", "baja", "taller"))
    if not ids:
        return {"hechas": 0, "flota": 0}
    revisados = await db.inspections.distinct(
        "vehicle_id", {"deleted": {"$ne": True}, "vehicle_id": {"$in": ids},
                       "created_at": {"$regex": f"^{dia}"}})
    return {"hechas": len(revisados), "flota": len(ids)}


# Lo que cuenta como «grave» en una incidencia. Los canónicos son los del
# validador (`leve`, `moderado`, `grave`, `critico`); se aceptan también las
# variantes que se han visto escritas en datos viejos, para no contar de menos.
_INCIDENCIA_GRAVE = ("grave", "critico", "crítico", "critica", "crítica", "critical")


async def _incidencias_flota_dia(center: str, dia: str) -> dict:
    """Incidencias de flota abiertas HOY en la sede, y cuántas son graves."""
    ids = await _vehiculos_de_sede(center)
    if not ids:
        return {"nuevas": 0, "graves": 0}
    q = {"vehicle_id": {"$in": ids}, "created_at": {"$regex": f"^{dia}"}}
    return {"nuevas": await db.incidents.count_documents(q),
            "graves": await db.incidents.count_documents(
                {**q, "severity": {"$in": list(_INCIDENCIA_GRAVE)}})}


async def resumen_dia_centro(center: str, dia: str) -> dict:
    """El día de un centro en cinco datos, listos para una plantilla.

    Es el resumen corto de cada sede: vehículos revisados, checklist, golpes
    nuevos e incidencias. Nada más — la versión larga ya existe y va al grupo a
    las 22:00.

    Ninguno de los cinco campos puede quedar vacío: WhatsApp rechaza el envío
    si un parámetro de plantilla va en blanco, así que donde no hay dato se
    dice que no lo hay ("sin datos", "ninguno") en vez de mandar "".
    """
    ins = await _inspecciones_del_dia(center, dia)
    inspecciones = (f"{ins['hechas']} de {ins['flota']}" if ins["flota"]
                    else "sin vehículos activos")

    turnos = []
    partes = []
    for shift in ("manana", "tarde"):
        r = await _resumen_turno(center, dia, shift)
        if not r:
            continue
        doc = await db.daily_checklists.find_one(
            {"center": center, "date": dia, "shift": shift}, {"_id": 0, "items": 1})
        turnos.append({"turno": "mañana" if shift == "manana" else "tarde",
                       "hechas": r["hechas"], "total": r["total"],
                       "items": (doc or {}).get("items") or []})
        partes.append(f"{'mañana' if shift == 'manana' else 'tarde'} {r['hechas']}/{r['total']}")
    checklist = " · ".join(partes) or "sin checklist"

    danos = await _danos_nuevos_hoy(center, dia)
    placas = sorted({d["matricula"] for d in danos})
    golpes = f"{len(danos)} · {', '.join(placas[:6])}" if danos else "ninguno"
    inc = await _incidencias_flota_dia(center, dia)

    d, m, y = dia[8:10], dia[5:7], dia[0:4]
    return {"center": center, "fecha": f"{d}/{m}/{y}",
            "inspecciones": inspecciones, "checklist": checklist, "golpes": golpes,
            "placas": placas, "danos": danos, "turnos": turnos,
            "incidencias": inc}


def _texto_resumen_largo(r: dict) -> str:
    """La versión detallada, para Telegram y push.

    La corta (cinco campos) sigue existiendo para la plantilla de WhatsApp: los
    parámetros de plantilla de Meta NO admiten saltos de línea, así que un
    mensaje con listas no cabe ahí de ninguna manera. Son dos formatos del
    mismo dato a propósito, no una duplicación por descuido.
    """
    L = [f"📋 <b>{r['center']} — {r['fecha']}</b>", ""]

    L.append(f"🚐 <b>Revisados:</b> {r['inspecciones']}")
    inc = r.get("incidencias") or {}
    if inc.get("nuevas"):
        graves = f" ({inc['graves']} graves)" if inc.get("graves") else ""
        L.append(f"   ⚠️ {inc['nuevas']} incidencias nuevas{graves}")
    else:
        L.append("   Sin incidencias nuevas")

    L.append("")
    danos = r.get("danos") or []
    if danos:
        L.append(f"🔧 <b>Golpes nuevos ({len(danos)})</b>")
        for d in danos[:10]:
            grav = f" ({d['gravedad']})" if d.get("gravedad") else ""
            quien = f" · {d['conductor']}" if d.get("conductor") else " · sin conductor en el cuadrante"
            L.append(f"   • {d['matricula']} — {d['parte']}{grav}{quien}")
        if len(danos) > 10:
            L.append(f"   …y {len(danos) - 10} más")
    else:
        L.append("🔧 <b>Golpes nuevos:</b> ninguno")

    for t in (r.get("turnos") or []):
        L.append("")
        ok = t["hechas"] == t["total"]
        L.append(f"{'✅' if ok else '⚠️'} <b>Checklist {t['turno']} — {t['hechas']}/{t['total']}</b>")
        for it in t["items"]:
            if it.get("done"):
                hora = (it.get("done_at") or "")[11:16]
                quien = it.get("done_by") or "—"
                L.append(f"   ✓ {it.get('text', '')} · {quien} {hora}")
            else:
                L.append(f"   ✗ {it.get('text', '')} — <b>sin hacer</b>")
    if not r.get("turnos"):
        L.append("")
        L.append("📝 <b>Checklist:</b> no hay ninguno creado hoy")
    return "\n".join(L)


async def _telegram_aviso(texto: str) -> bool:
    """Manda un texto al grupo de Telegram. False si no está configurado.

    Existía la misma llamada copiada en cinco sitios; cada copia con su propio
    manejo de errores y sus propios olvidos.
    """
    try:
        config = await db.telegram_config.find_one({}, {"_id": 0})
        if not config or not config.get("enabled") or not config.get("bot_token"):
            return False
        import aiohttp as _ai
        async with _ai.ClientSession() as s:
            for cid in config.get("chat_ids", []):
                if cid.strip():
                    await s.post(
                        f"https://api.telegram.org/bot{config['bot_token']}/sendMessage",
                        json={"chat_id": cid, "text": texto[:4000], "parse_mode": "HTML"},
                        timeout=_ai.ClientTimeout(total=10))
        return True
    except Exception as e:
        logger.warning(f"Telegram aviso: {e}")
        return False


def _html_resumen(r: dict) -> str:
    """El resumen en un correo que se lee de un vistazo en el móvil.

    Estilos en línea y sin CSS externo a propósito: Gmail y Outlook tiran las
    hojas de estilo, y un correo que llega sin formato es peor que uno feo.

    El correo es la vía que no depende de nadie: sin plantillas que aprobar,
    sin restricciones de cuenta y sin coste por mensaje. Y a diferencia de una
    plantilla de WhatsApp, aquí sí cabe el detalle entero.
    """
    esc = lambda s: (str(s or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))
    G = "#0b0d10"; T = "#e9edf3"; S = "#8b94a3"; L = "#1c2027"
    P = []
    P.append(f'<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:{G};'
             f'color:{T};padding:24px;max-width:640px;margin:0 auto;border-radius:14px">')
    P.append(f'<div style="font-size:13px;color:{S};letter-spacing:.12em;text-transform:uppercase">'
             f'{esc(r["fecha"])}</div>')
    P.append(f'<h1 style="margin:4px 0 20px;font-size:26px;font-weight:700">{esc(r["center"])}</h1>')

    # Vehículos revisados
    P.append(f'<div style="background:{L};border-radius:10px;padding:16px;margin-bottom:14px">')
    P.append(f'<div style="font-size:12px;color:{S};margin-bottom:4px">VEHÍCULOS REVISADOS</div>')
    P.append(f'<div style="font-size:19px;font-weight:600">{esc(r["inspecciones"])}</div>')
    inc = r.get("incidencias") or {}
    if inc.get("nuevas"):
        graves = f' ({inc["graves"]} graves)' if inc.get("graves") else ""
        P.append(f'<div style="margin-top:8px;color:#fbbf24;font-size:14px">'
                 f'⚠️ {esc(str(inc["nuevas"]) + " incidencias nuevas" + graves)}</div>')
    P.append('</div>')

    # Golpes
    danos = r.get("danos") or []
    P.append(f'<div style="background:{L};border-radius:10px;padding:16px;margin-bottom:14px">')
    P.append(f'<div style="font-size:12px;color:{S};margin-bottom:8px">'
             f'GOLPES NUEVOS ({len(danos)})</div>')
    if danos:
        for d in danos[:15]:
            grav = f' <span style="color:{S}">({esc(d["gravedad"])})</span>' if d.get("gravedad") else ""
            quien = (f'<div style="font-size:13px;color:{S}">{esc(d["conductor"])}</div>'
                     if d.get("conductor") else
                     f'<div style="font-size:13px;color:{S}">sin conductor en el cuadrante</div>')
            P.append(f'<div style="padding:8px 0;border-top:1px solid #2a2f38">'
                     f'<b style="font-family:monospace">{esc(d["matricula"])}</b> — {esc(d["parte"])}{grav}'
                     f'{quien}</div>')
    else:
        P.append('<div style="font-size:15px;color:#34d399">Ninguno ✓</div>')
    P.append('</div>')

    # Checklist, tarea por tarea
    for t in (r.get("turnos") or []):
        ok = t["hechas"] == t["total"]
        P.append(f'<div style="background:{L};border-radius:10px;padding:16px;margin-bottom:14px">')
        P.append(f'<div style="font-size:12px;color:{S};margin-bottom:8px">'
                 f'CHECKLIST {esc(t["turno"]).upper()} — '
                 f'<b style="color:{"#34d399" if ok else "#fbbf24"}">{t["hechas"]}/{t["total"]}</b></div>')
        for it in t["items"]:
            if it.get("done"):
                P.append(f'<div style="padding:5px 0;font-size:14px">'
                         f'<span style="color:#34d399">✓</span> {esc(it.get("text"))} '
                         f'<span style="color:{S};font-size:13px">· {esc(it.get("done_by") or "—")} '
                         f'{esc((it.get("done_at") or "")[11:16])}</span></div>')
            else:
                P.append(f'<div style="padding:5px 0;font-size:14px;color:#fca5a5">'
                         f'✗ {esc(it.get("text"))} — sin hacer</div>')
        P.append('</div>')

    P.append(f'<a href="https://flotadsp.com/panel" style="display:inline-block;margin-top:6px;'
             f'background:#ea6800;color:#fff;text-decoration:none;padding:11px 20px;'
             f'border-radius:9px;font-weight:600;font-size:14px">Abrir el panel</a>')
    P.append(f'<div style="margin-top:18px;font-size:12px;color:{S}">'
             f'Resumen automático de FlotaDSP. Si no quieres seguir recibiéndolo, '
             f'dilo y se quita en Configuración.</div>')
    P.append('</div>')
    return "".join(P)


async def enviar_resumen_diario(dia: Optional[str] = None, solo_id: Optional[str] = None) -> list:
    """El resumen corto del día a cada destinatario de su centro.

    Un mensaje por persona y día, no uno por cada cosa que pasa: en WhatsApp se
    paga por mensaje y por destinatario, así que tres avisos sueltos a dos
    personas son seis mensajes donde cabe uno.

    Mientras la salida de WhatsApp no exista, el mismo texto va a Telegram, que
    es lo que hay hoy. Cuando esté la clave y la plantilla aprobada, lo único
    que cambia es por dónde sale — el contenido ya es este.
    """
    dia = dia or _dia_negocio()
    q = {"avisos": "resumen_diario"}
    if solo_id:
        # Prueba dirigida: va aunque esté en pausa — se está comprobando que
        # llega, no repartiendo el aviso de verdad.
        q["id"] = solo_id
    else:
        q["activo"] = True
    dest = await db.aviso_destinatarios.find(q, {"_id": 0}).to_list(200)
    if not dest:
        logger.info("Resumen diario: sin destinatarios configurados")
        return []

    centros = sorted({c for d in dest for c in (d.get("centers") or [])})
    salida = []
    for center in centros:
        r = await resumen_dia_centro(center, dia)
        quienes = [d for d in dest if center in (d.get("centers") or [])]
        # TODO WhatsApp: falta la clave de Superchat y la plantilla aprobada por
        # Meta. Los cinco campos cortos de `r` son sus cinco variables; esta
        # versión larga es la que va por Telegram y push, que no tienen
        # plantillas y sí admiten saltos de línea.
        # Una prueba dirigida a una persona NO va al grupo: probar que algo
        # llega no puede costarle un mensaje a todo el mundo.
        if not solo_id:
            await _telegram_aviso(_texto_resumen_largo(r)
                                  + "\n\n<i>Para: " + ", ".join(d["nombre"] for d in quienes) + "</i>")

        # Correo: la vía que no depende de nadie. Sin plantillas que aprobar,
        # sin restricciones de cuenta de Meta y sin coste por mensaje.
        html = _html_resumen(r)
        asunto = f"{r['center']} — {r['fecha']} · {r['inspecciones']} revisados"
        correos = []
        for d in quienes:
            if not d.get("email"):
                continue
            if await _enviar_email(d["email"], asunto, html):
                correos.append(d["email"])
            else:
                logger.warning("Resumen diario: no se pudo enviar a %s", d["email"])

        # ── Y POR WHATSAPP, si esta encendido y hay numero ────────────────────
        # La version CORTA, no la larga: los parametros de plantilla de Meta no
        # admiten saltos de linea, asi que el texto con listas no cabe ahi de
        # ninguna manera. Son dos formatos del mismo dato, no una duplicacion.
        #
        # Se manda uno por persona y dia: en WhatsApp se paga por mensaje y por
        # destinatario, asi que tres avisos sueltos a dos personas son seis
        # mensajes donde cabe uno.
        wasap = []
        if await whatsapp.puede_avisar(db, "avisar_resumen"):
            cfgw = await whatsapp.config(db)
            for d in quienes:
                tel = d.get("telefono") or d.get("phone")
                if not tel or d.get("whatsapp_opt_in") is False:
                    continue
                # `golpes` es TEXTO ('3 · 1234ABC, 5678DEF' o 'ninguno'), no un
                # numero: se saca la cifra de delante. Tratarlo como diccionario
                # revienta con AttributeError dentro del cron de las 21:00, que
                # es donde peor se ve.
                _g = str(r.get("golpes") or "ninguno")
                _n_golpes = _g.split(" ·")[0] if _g != "ninguno" else "0"
                rw = await whatsapp.enviar_plantilla(
                    db, tel, cfgw["plantilla_resumen"],
                    [f"{r['center']} {r['fecha']}",
                     str(r.get("inspecciones") or "—"),
                     _n_golpes,
                     str(r.get("checklist") or "—")],
                    motivo="resumen_diario")
                if rw.get("ok"):
                    wasap.append(d.get("nombre") or tel)

        salida.append({**{k: r[k] for k in ("center", "fecha", "entrega", "checklist", "golpes")},
                       "incidencias": r["incidencias"], "danos": r["danos"],
                       "turnos": [{k: t[k] for k in ("turno", "hechas", "total")} for t in r["turnos"]],
                       "destinatarios": [d["nombre"] for d in quienes],
                       "correos": correos, "whatsapp": wasap})
    return salida


@api_router.post("/avisos/enviar-resumen-diario")
async def trigger_resumen_diario(data: dict = Body(default={}), _=Depends(require_admin)):
    """Dispara el resumen del día ahora, para verlo sin esperar a la hora.

    Con `id` va SOLO a esa persona y sin copia al grupo: es la prueba de "¿le
    llega a Judyt?" sin molestar a nadie más.
    """
    return {"enviados": await enviar_resumen_diario(data.get("date"), data.get("id"))}


_HORARIOS_DEF = {"resumen_diario": 21, "turno_manana": 15, "turno_tarde": 22}


async def _horarios_avisos() -> dict:
    """A qué hora sale cada aviso. Se lee de la BD en CADA vuelta del bucle.

    Leerlo una sola vez al arrancar obligaría a redesplegar el servidor para
    cambiar una hora, que es justo lo que no puede hacer quien la necesita
    cambiar. Así se toca en Configuración y surte efecto ese mismo día.
    """
    doc = await db.app_meta.find_one({"_id": "horarios_avisos"}) or {}
    out = dict(_HORARIOS_DEF)
    for k in out:
        v = doc.get(k)
        if isinstance(v, int) and 0 <= v <= 23:
            out[k] = v
    return out


@api_router.get("/avisos/horarios")
async def get_horarios_avisos(_=Depends(require_admin)):
    return await _horarios_avisos()


@api_router.put("/avisos/horarios")
async def set_horarios_avisos(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Cambia las horas de envío. Surte efecto sin redesplegar."""
    cambios = {}
    for k in _HORARIOS_DEF:
        if k in data:
            try:
                h = int(data[k])
            except (TypeError, ValueError):
                raise HTTPException(400, f"{k} debe ser una hora (0-23)")
            if not 0 <= h <= 23:
                raise HTTPException(400, f"{k} debe estar entre 0 y 23")
            cambios[k] = h
    if not cambios:
        raise HTTPException(400, "Nada que cambiar")
    cambios["updated_by"] = user.get("name")
    cambios["updated_at"] = datetime.now(timezone.utc).isoformat()
    await db.app_meta.update_one({"_id": "horarios_avisos"}, {"$set": cambios}, upsert=True)
    return await _horarios_avisos()


async def _ya_enviado_hoy(clave: str, dia: str) -> bool:
    """Cerrojo para no mandar dos veces el mismo día.

    Vive en la BD y no en memoria porque Fly reinicia la máquina cuando le
    parece: con el cerrojo en memoria, un reinicio a las 21:05 volvería a
    mandar el resumen a todo el mundo.
    """
    try:
        r = await db.app_meta.update_one(
            {"_id": f"envio_{clave}", "dia": {"$ne": dia}},
            {"$set": {"dia": dia, "at": datetime.now(timezone.utc).isoformat()}},
            upsert=True,
        )
    except DuplicateKeyError:
        # YA ESTABA ENVIADO. Con el documento ya puesto a ese dia, el filtro
        # (`dia != dia`) no casa con nada y el upsert intenta INSERTAR otro con
        # el mismo _id: Mongo lanza duplicado. Eso no es un fallo, es
        # exactamente la respuesta que se estaba preguntando — pero como
        # excepcion tumbaba el endpoint entero con un 500.
        #
        # Solo se veia si la clave llevaba dentro la fecha (`dcr_OGA5_2026-08-29`),
        # porque entonces la pareja clave+dia no cambia nunca de un dia para
        # otro. Con las claves de siempre el `dia` cambiaba y el update casaba.
        # Un cerrojo que revienta es peor que no tener cerrojo.
        return True
    return not (r.modified_count or r.upserted_id)


async def _bucle_aviso(clave: str, hora_key: str, accion):
    """Mira el reloj cada minuto y dispara cuando toca.

    Se comprueba cada minuto en vez de dormir hasta la hora exacta para que un
    cambio de horario en Configuración se note el mismo día, sin reiniciar.
    """
    from zoneinfo import ZoneInfo
    madrid = ZoneInfo("Europe/Madrid")
    while True:
        try:
            horas = await _horarios_avisos()
            now = datetime.now(madrid)
            if now.hour == horas[hora_key] and not await _ya_enviado_hoy(clave, now.strftime("%Y-%m-%d")):
                logger.info("Aviso %s: disparando (hora %02d)", clave, horas[hora_key])
                await accion()
        except Exception as e:
            logger.error("Bucle de aviso %s: %s", clave, e)
        await asyncio.sleep(60)


# ── AVISO DE ESPACIO ────────────────────────────────────────────────────────
# `/admin/salud` ya mide el disco desde hace tiempo, con su limite configurable
# y todo. Lo que le faltaba es que AVISE solo: una tarjeta que hay que abrir no
# sirve de nada para algo que se llena despacio y de golpe deja de escribir.
#
# Esto es solo el aviso. La medida sale de alli, no de una copia — el 30-08-2026
# escribi un segundo medidor con el limite 512 puesto a mano, ignorando el
# `ATLAS_LIMITE_MB=10240` que ya estaba configurado en el propio servidor, y
# avise de que la base se llenaba en cinco dias estando al 4,8 %.
#
# La leccion no es del numero: es que BUSQUE ANTES DE CONSTRUIR. La solucion
# estaba escrita, con la advertencia incluida, y aun asi la reinvente peor.

ESPACIO_AVISA_PCT = 80           # avisa a partir de este porcentaje
ESPACIO_AVISA_MESES = 6          # o si al ritmo actual quedan menos meses


async def avisar_espacio() -> dict:
    """Avisa por Telegram cuando el disco empiece a apretar de verdad."""
    try:
        e = await _espacio_desde_salud()
    except Exception as ex:                                      # noqa: BLE001
        logger.warning("aviso de espacio: %s", ex)
        return {"error": str(ex)}
    m = (e or {}).get("mongo") or {}
    pct = m.get("porcentaje") or 0
    meses = m.get("meses_restantes")
    urge = pct >= ESPACIO_AVISA_PCT or (meses is not None and meses <= ESPACIO_AVISA_MESES)
    if not urge:
        return e
    if await _ya_enviado_hoy("espacio_aviso", datetime.now(timezone.utc).strftime("%Y-%m-%d")):
        return e
    lineas = ["🗄️ <b>La base de datos empieza a apretar</b>",
              "%s MB de %s (%s%%)" % (m.get("usado_mb"), m.get("limite_mb"), pct)]
    if meses is not None:
        lineas.append("Al ritmo de ahora quedan <b>%s meses</b>." % meses)
    # Se dice SIEMPRE si el limite es medido o supuesto: un porcentaje sobre un
    # limite equivocado parece igual de fiable que uno bueno.
    lineas.append("Límite %s." % ("configurado" if m.get("limite_configurado")
                                  else "POR DEFECTO — compruébalo en Atlas"))
    await _telegram_aviso("\n".join(lineas))
    return e


async def _espacio_desde_salud() -> dict:
    """Los mismos numeros que /admin/salud, sin pasar por el permiso.

    El endpoint pide super-admin y esto lo llama un cron sin sesion. Se rehace
    la cuenta minima en vez de duplicar el medidor entero.
    """
    total = 0.0
    for n in await client.list_database_names():
        if n in ("admin", "local", "config"):
            continue
        try:
            st = await client[n].command("dbStats", scale=1024 * 1024)
        except Exception:                                        # noqa: BLE001
            continue
        total += float(st.get("dataSize") or 0) + float(st.get("indexSize") or 0)
    total = round(total, 1)
    pct = round(total / max(LIMITE_ATLAS_MB, 1) * 100, 1)
    return {"mongo": {"usado_mb": total, "limite_mb": LIMITE_ATLAS_MB,
                      "porcentaje": pct, "meses_restantes": None,
                      "limite_configurado": bool(os.environ.get("ATLAS_LIMITE_MB"))}}


async def revisar_facturacion() -> list:
    """Compara lo pagado con lo usado en TODOS los DSP y avisa de los desfases.

    Va al grupo de Telegram del dueño, no al cliente: la app le dice al cliente
    cuántas tiene (eso lo ve en su panel), pero la conversación de "estás
    pagando 20 y llevas 24" es una conversación comercial, y esas no las tiene
    un robot por su cuenta.
    """
    orgs = await global_db.organizations.find(
        {"account_type": "dsp", "status": {"$in": ["active", "trial"]}},
        {"_id": 0, "id": 1, "name": 1, "slug": 1, "plan": 1,
         "db_name": 1, "vehiculos_pagados": 1}).to_list(500)
    desfases = []
    for o in orgs:
        pagadas = o.get("vehiculos_pagados")
        if not isinstance(pagadas, int):
            continue                       # sin cantidad medida no hay nada que comparar
        en_flota = await _vehiculos_facturables(_tenant_db_name(o))
        if en_flota != pagadas:
            desfases.append({"dsp": o.get("name") or o.get("slug") or o["id"],
                             "pagadas": pagadas, "en_flota": en_flota,
                             "diferencia": en_flota - pagadas})
    if desfases:
        lineas = ["💶 <b>Furgonetas facturadas vs. reales</b>"]
        for d in sorted(desfases, key=lambda x: -abs(x["diferencia"])):
            signo = "+" if d["diferencia"] > 0 else ""
            lineas.append(f"• {d['dsp']}: paga {d['pagadas']} · tiene {d['en_flota']} "
                          f"({signo}{d['diferencia']})")
        await _telegram_aviso("\n".join(lineas))
    return desfases


async def avisar_itv_por_whatsapp() -> list:
    """Un WhatsApp al conductor de cada furgoneta con la ITV caducada.

    UNA VEZ AL DIA Y NO AL ABRIR LA PANTALLA. Enganchado a la pantalla de
    Vencimientos, cada refresco mandaria mensajes otra vez: en WhatsApp eso son
    mensajes cobrados y, sobre todo, gente que deja de leerlos a los dos dias.

    Solo CADUCADAS, no las que estan por vencer. Lo que hay que decirle al
    conductor es "esta no puede salir", y eso solo es cierto cuando ya venció.
    Las proximas son trabajo de oficina —pedir cita— y para eso esta la
    pantalla; molestar al conductor con ellas convierte el aviso en ruido.

    Circular con la ITV caducada son 200 EUR sin margen de un dia y la Guardia
    Civil puede inmovilizar el vehiculo donde lo pare, asi que la persona que
    tiene que enterarse es la que la va a conducir.
    """
    if not await whatsapp.puede_avisar(db, "avisar_itv"):
        return []
    from datetime import date as _date
    hoy = _date.today()
    cfgw = await whatsapp.config(db)

    # A quien se le dio hoy cada furgoneta. La asignacion del dia manda sobre
    # `current_driver_id`, que puede llevar semanas sin tocarse.
    hoy_iso = hoy.strftime("%Y-%m-%d")
    conductor_de = {}
    async for a_doc in db.daily_assignments.find({"date": hoy_iso}, {"_id": 0, "slots": 1}):
        for sl in (a_doc.get("slots") or []):
            if sl.get("vehicle_id") and sl.get("driver_id"):
                conductor_de[sl["vehicle_id"]] = sl["driver_id"]

    salida = []
    async for v in db.vehicles.find(
            {"status": {"$nin": ["deleted", "baja", "taller"]},
             "itv_date": {"$nin": [None, ""]}},
            {"_id": 0, "id": 1, "license_plate": 1, "itv_date": 1, "current_driver_id": 1}):
        try:
            y, m, d = [int(x) for x in str(v["itv_date"]).split("-")]
            dias = (hoy - _date(y, m, d)).days
        except (ValueError, TypeError):
            continue
        if dias <= 0:
            continue                      # aun en regla: no es cosa del conductor
        did = conductor_de.get(v["id"]) or v.get("current_driver_id")
        if not did:
            continue
        drv = await db.drivers.find_one({"id": did},
                                        {"_id": 0, "name": 1, "phone": 1, "telefono": 1,
                                         "whatsapp_opt_in": 1})
        if not drv or drv.get("whatsapp_opt_in") is False:
            continue
        tel = drv.get("phone") or drv.get("telefono")
        if not tel:
            continue
        r = await whatsapp.enviar_plantilla(
            db, tel, cfgw["plantilla_itv"],
            [v.get("license_plate") or v["id"], str(dias)],
            motivo="itv_vencida")
        salida.append({"matricula": v.get("license_plate"), "dias": dias,
                       "conductor": drv.get("name"), "ok": r.get("ok"),
                       "error": r.get("error")})
    if salida:
        logger.info("WhatsApp ITV: %d avisos (%d con fallo)",
                    len(salida), sum(1 for x in salida if not x["ok"]))
    return salida


@app.on_event("startup")
async def start_itv_whatsapp_scheduler():
    """Los avisos de ITV salen a la misma hora que el resumen del dia.

    A la hora del resumen y no por la manana a proposito: por la manana la gente
    esta cargando y no va a parar a leer un WhatsApp; por la tarde da tiempo a
    organizar la cita para el dia siguiente.
    """
    asyncio.create_task(_bucle_aviso("itv_whatsapp", "resumen_diario", avisar_itv_por_whatsapp))
    # El seguimiento del taller va a MEDIA MANANA, no con el resto: es cuando
    # el taller ya ha abierto y ha visto lo que tiene, y le da todo el dia para
    # contestar. A la hora del resumen (tarde) muchos ya han cerrado.
    # El seguimiento NO va con `_bucle_aviso`. Aquel dispara una vez al dia a
    # una hora fija (las 15:00), y la pauta deja configurar la franja horaria:
    # con 9-19 funcionaba POR CASUALIDAD, porque las 15:00 caen dentro. En
    # cuanto alguien pusiera 10-14, `es_hora` habria devuelto False a las 15:00
    # y el seguimiento se habria apagado PARA SIEMPRE, sin un solo error.
    # Configuracion que parece que funciona y apaga el sistema en silencio.
    # Con su propio bucle, la franja que se configura es la que manda de verdad.
    asyncio.create_task(_bucle_seguimiento())
    # La IA cierra sola lo que puede decidir; a la persona le queda la duda.
    asyncio.create_task(_bucle_autorrevision())
    # El disco no avisa: un Atlas M0 lleno deja de aceptar escrituras de golpe.
    # Va con el resumen del dia porque no es una urgencia de minutos, pero si
    # algo que hay que ver TODOS los dias mientras apriete.
    asyncio.create_task(_bucle_aviso("espacio_bd", "resumen_diario", avisar_espacio))
    # Y que avise si algun bucle se ha muerto. Un latido que hay que ir a mirar
    # no lo mira nadie.
    asyncio.create_task(_bucle_aviso("bucles_vivos", "resumen_diario", avisar_bucles_muertos))


