@app.on_event("startup")
async def start_resumen_diario_scheduler():
    """Resumen corto por centro, a la hora que diga Configuración.

    Por defecto a las 21:00, antes del cierre largo de las 22:00 que va al
    grupo: son mensajes distintos para gente distinta y no tienen por qué
    coincidir.
    """
    asyncio.create_task(_bucle_aviso("resumen_diario", "resumen_diario", enviar_resumen_diario))


@api_router.post("/checklist/enviar-resumen")
async def checklist_enviar_resumen(data: dict = Body(default={}),
                                   _=Depends(require_admin)):
    """Dispara el cierre de turno ahora, para probarlo sin esperar a la hora."""
    shift = data.get("shift") or "manana"
    if shift not in ("manana", "tarde"):
        raise HTTPException(400, "shift debe ser manana o tarde")
    return {"enviados": await enviar_resumen_turno(shift, data.get("date"))}


@app.on_event("startup")
async def start_checklist_summary_scheduler():
    """Cierre de turno a la hora en que cada turno acaba.

    Las horas son configurables porque no las puedo saber: un turno que acaba a
    las 14:00 y otro a las 15:30 dan resúmenes distintos, y mandarlo antes de
    tiempo cuenta como "sin hacer" lo que aún da tiempo a hacer.
    """
    for shift, hora_key in (("manana", "turno_manana"), ("tarde", "turno_tarde")):
        asyncio.create_task(_bucle_aviso(
            f"turno_{shift}", hora_key,
            functools.partial(enviar_resumen_turno, shift)))


# =========================
# CHAT INTERNO POR CENTRO (entre admins del mismo centro)
# =========================
# 1 sala = 1 centro. Cada org tiene N salas (una por centro de la org).
# Solo ven la sala los admins con allowed_centers compatible.
# Polling cada N s desde el cliente (no hay WS — KISS).

async def _chat_room_can_access(user: dict, center: str) -> bool:
    return _user_can_see_center(user, center)


# =========================
# WEB PUSH — notificaciones al móvil de los coordinadores del panel (PWA)
# =========================
VAPID_PRIVATE_KEY = os.environ.get("VAPID_PRIVATE_KEY", "")
VAPID_PUBLIC_KEY = os.environ.get("VAPID_PUBLIC_KEY", "")
VAPID_SUBJECT = os.environ.get("VAPID_SUBJECT", "mailto:hola@flotadsp.com")
_push_enabled = bool(VAPID_PRIVATE_KEY and VAPID_PUBLIC_KEY)
if _push_enabled:
    try:
        from pywebpush import webpush as _webpush, WebPushException as _WebPushException
    except Exception as _pe:
        logger.warning(f"pywebpush no disponible, push desactivado: {_pe}")
        _push_enabled = False


@api_router.get("/push/vapid-key")
async def push_vapid_key(_=Depends(require_any_auth)):
    """Clave pública VAPID para que el navegador se suscriba (admins Y conductores)."""
    return {"key": VAPID_PUBLIC_KEY, "enabled": _push_enabled}


@api_router.post("/push/subscribe")
async def push_subscribe(data: dict, user: dict = Depends(require_any_auth)):
    """Guarda la suscripción push del dispositivo (coordinador o conductor)."""
    sub = _dict_cuerpo(data.get("subscription"))
    if not sub.get("endpoint"):
        raise HTTPException(400, "Suscripción inválida")
    await global_db.push_subscriptions.update_one(
        {"endpoint": sub["endpoint"]},
        {"$set": {
            "endpoint": sub["endpoint"],
            "subscription": sub,
            "user_id": user.get("sub"),
            "role": user.get("role"),
            "org_id": user.get("org_id"),
            "db_name": user.get("db_name"),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }},
        upsert=True,
    )
    return {"ok": True}


@api_router.post("/push/unsubscribe")
async def push_unsubscribe(data: dict, user: dict = Depends(require_any_auth)):
    ep = _texto_cuerpo(data.get("endpoint"))
    if ep:
        await global_db.push_subscriptions.delete_one({"endpoint": ep})
    return {"ok": True}


def _do_webpush(sub, payload_json):
    _webpush(subscription_info=sub, data=payload_json,
             vapid_private_key=VAPID_PRIVATE_KEY,
             vapid_claims={"sub": VAPID_SUBJECT}, timeout=10)


async def send_web_push_to_users(user_ids: list, title: str, body: str, url: str = "/panel"):
    """Envía push a los dispositivos de esos usuarios. Fire-and-forget: tolera
    fallos y borra las suscripciones caducadas (404/410). No bloquea el event loop."""
    if not (_push_enabled and user_ids):
        return
    try:
        subs = await global_db.push_subscriptions.find(
            {"user_id": {"$in": list(set(user_ids))}}, {"_id": 0}
        ).to_list(1000)
    except Exception:
        return
    if not subs:
        return
    payload = json.dumps({"title": (title or "")[:80], "body": (body or "")[:180], "url": url})
    loop = asyncio.get_running_loop()
    for s in subs:
        sub = s.get("subscription")
        if not sub:
            continue
        try:
            await loop.run_in_executor(_executor, _do_webpush, sub, payload)
        except _WebPushException as e:
            code = getattr(getattr(e, "response", None), "status_code", None)
            if code in (404, 410):
                await global_db.push_subscriptions.delete_one({"endpoint": s.get("endpoint")})
            else:
                logger.debug(f"web push {code}")
        except Exception as ex:
            logger.debug(f"web push error: {ex}")


async def _push_org_id() -> Optional[str]:
    """org_id de la organización del contexto actual (por su BD de tenant)."""
    try:
        org = await global_db.organizations.find_one(
            {"db_name": _current_db_name.get()}, {"_id": 0, "id": 1})
        return org.get("id") if org else None
    except Exception:
        return None


async def _center_recipient_ids(org_id, center, exclude_id=None) -> list:
    """IDs de admins de la org que pueden ver ese centro (destinatarios de push)."""
    if not org_id:
        return []
    try:
        users = await global_db.admin_users.find(
            {"org_id": org_id}, {"_id": 0, "id": 1, "allowed_centers": 1}).to_list(500)
    except Exception:
        return []
    out = []
    for u in users:
        if exclude_id and u.get("id") == exclude_id:
            continue
        ac = u.get("allowed_centers")
        if ac is None or (center or "") in ac:
            out.append(u.get("id"))
    return out


async def push_center_event(center, title, body, url, exclude_id=None):
    """Resuelve destinatarios del centro y lanza el push en segundo plano."""
    if not _push_enabled:
        return
    try:
        org_id = await _push_org_id()
        ids = await _center_recipient_ids(org_id, center, exclude_id=exclude_id)
        if ids:
            asyncio.create_task(send_web_push_to_users(ids, title, body, url))
    except Exception as e:
        logger.debug(f"push_center_event: {e}")


# ─── QUIEN ESTA CONECTADO Y MENSAJES PRIVADOS ──────────────────────────────
# El chat de la nave es una sala abierta; esto es lo otro que hace falta para
# que la oficina no tenga que llamar por telefono: ver quien esta delante de la
# pantalla ahora mismo y poder escribirle SOLO a esa persona.
#
# La presencia no se inventa con un «conectado/desconectado» que alguien pulsa:
# se anota la ultima vez que su panel hablo con el servidor (`_presencia_marcar`
# se llama desde /auth/me, que el panel pide cada 2 min, y desde el propio
# chat). Por debajo de _PRESENCIA_MIN se considera que esta; por encima se dice
# «hace N min», que es informacion util y no una etiqueta falsa.
#
# Los privados viven en la BD de la empresa (nunca en la global): son datos
# suyos. La clave de la conversacion es el par de ids ORDENADO, asi que da
# igual quien escriba primero.
_PRESENCIA_MIN = 3          # por debajo de esto, se considera que esta delante
_PRESENCIA_COL = "admin_presencia"


async def _presencia_marcar(user: dict) -> None:
    """Deja constancia de que este usuario esta usando el panel AHORA."""
    uid = user.get("sub")
    if not uid or user.get("role") != "admin":
        return
    try:
        await global_db[_PRESENCIA_COL].update_one(
            {"_id": uid},
            {"$set": {"en": datetime.now(timezone.utc).isoformat(),
                      "org_id": user.get("org_id") or ""}},
            upsert=True)
    except Exception as e:                                       # noqa: BLE001
        logger.debug(f"presencia: {e}")


def _hace_min(iso: str) -> Optional[int]:
    if not iso:
        return None
    try:
        d = datetime.fromisoformat(iso)
    except ValueError:
        return None
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return max(0, int((datetime.now(timezone.utc) - d).total_seconds() // 60))


def _conv_id(a: str, b: str) -> str:
    return ":".join(sorted([a or "", b or ""]))


def _mensajes_org(user: dict) -> str:
    """La empresa de quien escribe, o 403. NUNCA «todas»: el chat privado cruza
    a personas de `global_db.admin_users`, que es UNA sola coleccion para todas
    las empresas. Con un token sin `org_id` la version anterior caia en `{}` —
    o sea en TODOS los usuarios de TODAS las empresas— y dejaba listar y
    escribir a gente de otro cliente, en silencio y con HTTP 200 (gotcha 26:
    nunca fiarse de un valor por defecto). Hoy los 14 usuarios llevan
    `org_id: "owner"`, asi que no cambia nada para ellos."""
    org = user.get("org_id")
    if not org:
        raise HTTPException(403, "Tu sesión no tiene empresa: cierra sesión y vuelve a entrar")
    return org


@api_router.get("/mensajes/gente")
async def mensajes_gente(user: dict = Depends(require_admin)):
    """La gente de ESTA empresa, con su foto y si esta conectada ahora."""
    await _presencia_marcar(user)
    # Las cuentas desactivadas no pueden entrar, asi que no tiene sentido
    # ofrecerlas como con quien hablar.
    q = {"org_id": _mensajes_org(user), "disabled": {"$ne": True}}
    gente = await global_db.admin_users.find(
        q, {"_id": 0, "id": 1, "name": 1, "username": 1, "photo_url": 1,
            "allowed_centers": 1, "role": 1}).to_list(200)
    ids = [g["id"] for g in gente if g.get("id")]
    pres = {p["_id"]: p.get("en") for p in await global_db[_PRESENCIA_COL].find(
        {"_id": {"$in": ids}}, {"_id": 1, "en": 1}).to_list(len(ids) or 1)}
    # Los no leidos de cada conversacion, en UNA consulta y no una por persona.
    sin_leer = {}
    for r in await db.chat_dm.aggregate([
            {"$match": {"para": user.get("sub"), "leido_en": None}},
            {"$group": {"_id": "$de", "n": {"$sum": 1}}}]).to_list(200):
        sin_leer[r["_id"]] = r["n"]
    salida = []
    for g in gente:
        if g.get("id") == user.get("sub"):
            continue
        m = _hace_min(pres.get(g.get("id")) or "")
        salida.append({
            "id": g.get("id"), "nombre": g.get("name") or g.get("username") or "—",
            "foto": g.get("photo_url") or "", "centros": g.get("allowed_centers") or [],
            "en_linea": m is not None and m < _PRESENCIA_MIN,
            "hace_min": m, "sin_leer": sin_leer.get(g.get("id"), 0),
        })
    salida.sort(key=lambda x: (not x["en_linea"], -x["sin_leer"],
                               (x["nombre"] or "").lower()))
    return {"gente": salida, "minutos_en_linea": _PRESENCIA_MIN}


@api_router.get("/chat/{center}/ia")
async def chat_ia_estado(center: str, user: dict = Depends(require_admin)):
    """Si FlotaDSP AI esta ahora en la conversacion de ese centro.

    Se la llama escribiendo su nombre (`@flota ...`). Se queda una hora desde
    la ultima vez que alguien la llamo: estar siempre no significaria nada, y
    marcharse al momento haria pensar que no esta disponible.
    """
    if not await _chat_room_can_access(user, center):
        raise HTTPException(403, "No tienes acceso a este chat")
    dentro = await _ia_sala_presente(center)
    return {"dentro": bool(dentro), "hasta": (dentro or {}).get("hasta"),
            "nombre": _IA_SALA_NOMBRE, "foto": _IA_SALA_FOTO,
            "como_llamarla": "@flota"}


@api_router.get("/mensajes/con/{otro_id}")
async def mensajes_con(otro_id: str, since: Optional[str] = None,
                       limit: int = 100, user: dict = Depends(require_admin)):
    """La conversacion privada con esa persona. Al abrirla se marca leida."""
    await _presencia_marcar(user)
    yo = user.get("sub")
    otro = await global_db.admin_users.find_one(
        {"id": otro_id, "org_id": _mensajes_org(user)},
        {"_id": 0, "id": 1, "name": 1, "username": 1, "photo_url": 1})
    if not otro:
        raise HTTPException(404, "Esa persona no está en tu empresa")
    q = {"conv": _conv_id(yo, otro_id)}
    if since:
        q["creado_en"] = {"$gt": since}
    limit = max(1, min(limit, 200))
    msgs = await db.chat_dm.find(q, {"_id": 0}).sort("creado_en", -1).to_list(limit)
    msgs.reverse()
    await db.chat_dm.update_many(
        {"conv": q["conv"], "para": yo, "leido_en": None},
        {"$set": {"leido_en": datetime.now(timezone.utc).isoformat()}})
    return {"mensajes": msgs,
            "con": {"id": otro.get("id"), "nombre": otro.get("name") or otro.get("username") or "—",
                    "foto": otro.get("photo_url") or ""}}


@api_router.post("/mensajes/con/{otro_id}")
async def mensajes_enviar(otro_id: str, data: dict = Body(...),
                          user: dict = Depends(require_admin)):
    texto = _texto_cuerpo(data.get("texto"), 2000)
    if not texto:
        raise HTTPException(400, "Escribe algo primero")
    yo = user.get("sub")
    if otro_id == yo:
        raise HTTPException(400, "No puedes escribirte a ti mismo")
    otro = await global_db.admin_users.find_one(
        {"id": otro_id, "org_id": _mensajes_org(user), "disabled": {"$ne": True}},
        {"_id": 0, "id": 1, "name": 1})
    if not otro:
        raise HTTPException(404, "Esa persona no está en tu empresa")
    doc = {"id": str(uuid.uuid4()), "conv": _conv_id(yo, otro_id),
           "de": yo, "de_nombre": user.get("name") or user.get("username") or "—",
           "para": otro_id, "texto": texto,
           "creado_en": datetime.now(timezone.utc).isoformat(), "leido_en": None}
    await db.chat_dm.insert_one(dict(doc))
    # Al movil de esa persona y SOLO de esa persona: un privado que avisara al
    # centro entero seria justo lo contrario de lo que se pide aqui.
    if _push_enabled:
        try:
            asyncio.create_task(send_web_push_to_users(
                [otro_id], f"💬 {doc['de_nombre']}", texto[:120], "/panel/chat"))
        except Exception as e:                                   # noqa: BLE001
            logger.debug(f"push privado: {e}")
    # LA IA TAMBIEN ENTRA EN UN PRIVADO. Dani la llamo el 19-09-2026 en su
    # conversacion con Mery -«@flota dile a mery quien es su peor conductor»- y
    # no contestaba: solo estaba montada en la sala del centro. Aqui contesta a
    # los DOS (el mensaje va con la misma clave de conversacion), y el no leido
    # se le cuelga al otro, que es quien no esta mirando la pantalla.
    respuesta_ia = None
    if _ia_la_llaman(texto):
        centro = await _ia_centro_de(user, _texto_cuerpo(data.get("center"), 20), texto)
        dicho, tarjeta = await _ia_pensar(centro, texto, user, hilo="dm:%s" % doc["conv"])
        respuesta_ia = {
            "id": str(uuid.uuid4()), "conv": doc["conv"],
            "de": _IA_SALA_ID, "de_nombre": _IA_SALA_NOMBRE, "foto": _IA_SALA_FOTO,
            "es_ia": True, "tarjeta": tarjeta, "para": otro_id,
            "texto": dicho[:2000],
            "creado_en": datetime.now(timezone.utc).isoformat(), "leido_en": None}
        await db.chat_dm.insert_one(dict(respuesta_ia))
        if _push_enabled:
            try:
                asyncio.create_task(send_web_push_to_users(
                    [otro_id], f"🤖 {_IA_SALA_NOMBRE}", dicho[:120], "/panel/chat"))
            except Exception as e:                               # noqa: BLE001
                logger.debug(f"push IA privado: {e}")
    return {"ok": True, "mensaje": doc, "respuesta_ia": respuesta_ia}


# Lo que se puede mandar por el chat. Lista BLANCA por extension y el tipo lo
# pone el servidor: el que diga el navegador no vale, y un .html o un .svg
# servido desde el dominio del almacen ejecutaria codigo de quien lo subio.
_CHAT_ADJUNTOS = {
    "pdf": "application/pdf", "png": "image/png", "jpg": "image/jpeg",
    "jpeg": "image/jpeg", "webp": "image/webp", "gif": "image/gif",
    "doc": "application/msword",
    "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "xls": "application/vnd.ms-excel",
    "xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "ppt": "application/vnd.ms-powerpoint",
    "pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    "csv": "text/csv", "txt": "text/plain", "zip": "application/zip",
}
_CHAT_ADJUNTO_MAX = 15 * 1024 * 1024


@api_router.post("/mensajes/con/{otro_id}/archivo")
async def mensajes_enviar_archivo(otro_id: str, file: UploadFile = File(...),
                                  texto: str = Form(default=""),
                                  user: dict = Depends(require_admin)):
    """Manda un documento (o una foto) a una persona de la empresa.

    Va en la misma conversacion privada que el texto, como un mensaje mas con
    `adjunto`. Solo lo ve quien esta en esa conversacion: la URL del almacen lleva
    un identificador al azar y ademas no se devuelve a nadie mas.
    """
    yo = user.get("sub")
    if otro_id == yo:
        raise HTTPException(400, "No puedes escribirte a ti mismo")
    otro = await global_db.admin_users.find_one(
        {"id": otro_id, "org_id": _mensajes_org(user), "disabled": {"$ne": True}},
        {"_id": 0, "id": 1, "name": 1})
    if not otro:
        raise HTTPException(404, "Esa persona no está en tu empresa")
    nombre = re.sub(r"[\r\n\/]+", "_", (file.filename or "documento")).strip()[:120] or "documento"
    ext = nombre.rsplit(".", 1)[-1].lower() if "." in nombre else ""
    if ext not in _CHAT_ADJUNTOS:
        raise HTTPException(400, "Ese tipo de archivo no se puede enviar (PDF, imágenes, Word, Excel, PowerPoint, CSV, TXT o ZIP)")
    contenido = await file.read(_CHAT_ADJUNTO_MAX + 1)
    if not contenido:
        raise HTTPException(400, "El archivo está vacío")
    if len(contenido) > _CHAT_ADJUNTO_MAX:
        raise HTTPException(413, "Archivo demasiado grande (máximo 15 MB)")
    s3 = get_r2()
    if not s3:
        raise HTTPException(502, "El almacenamiento de archivos no está configurado")
    clave = "chat/%s/%s.%s" % (_mensajes_org(user), uuid.uuid4().hex, ext)
    tipo = _CHAT_ADJUNTOS[ext]
    es_imagen = tipo.startswith("image/")
    try:
        await asyncio.get_running_loop().run_in_executor(
            _executor, lambda: s3.put_object(
                Bucket=R2_BUCKET, Key=clave, Body=contenido, ContentType=tipo,
                # Lo que no es imagen se descarga en vez de abrirse en el dominio,
                # y con SU nombre: sin `filename` el navegador lo guarda como el
                # identificador interno (`0181a4...txt`), y el atributo `download`
                # del enlace no vale entre dominios. `filename*` lleva UTF-8, que
                # es lo que admite tildes y eñes en el nombre.
                ContentDisposition=("inline" if es_imagen else
                                    "attachment; filename*=UTF-8''%s" % _url_quote(nombre, safe=""))))
    except Exception as e:                                       # noqa: BLE001
        logger.warning("Chat: no se pudo subir %s: %s", clave, e)
        raise HTTPException(502, "No se pudo guardar el archivo. Inténtalo otra vez")
    r2_public = os.environ.get("R2_PUBLIC_URL", "").rstrip("/")
    doc = {"id": str(uuid.uuid4()), "conv": _conv_id(yo, otro_id),
           "de": yo, "de_nombre": user.get("name") or user.get("username") or "—",
           "para": otro_id, "texto": _texto_cuerpo(texto, 500),
           "adjunto": {"nombre": nombre, "url": "%s/%s" % (r2_public, clave) if r2_public else clave,
                       "tipo": tipo, "tam": len(contenido), "imagen": es_imagen},
           "creado_en": datetime.now(timezone.utc).isoformat(), "leido_en": None}
    await db.chat_dm.insert_one(dict(doc))
    if _push_enabled:
        try:
            asyncio.create_task(send_web_push_to_users(
                [otro_id], "💬 %s" % doc["de_nombre"], "📎 %s" % nombre, "/panel/chat"))
        except Exception as e:                                   # noqa: BLE001
            logger.debug(f"push privado: {e}")
    return {"ok": True, "mensaje": doc}


@api_router.get("/chat/{center}")
async def chat_get(center: str, since: Optional[str] = None,
                   limit: int = 100, user: dict = Depends(require_admin)):
    """Devuelve los últimos N mensajes de la sala del centro (o desde 'since' ISO si se pasa)."""
    await _require_plan_feature(user, "chat")
    if not await _chat_room_can_access(user, center):
        raise HTTPException(403, "No tienes acceso a este chat")
    q = {"center": center}
    if since:
        q["created_at"] = {"$gt": since}
    limit = max(1, min(limit, 200))
    msgs = await db.chat_messages.find(q, {"_id": 0}).sort("created_at", -1).to_list(limit)
    msgs.reverse()  # cronológico ascendente para el cliente
    # La foto la pone el SERVIDOR con el id del autor: el cliente no tiene por
    # que saber de donde sale la foto de otra persona, y asi cambiarla se nota
    # en los mensajes viejos tambien.
    await _presencia_marcar(user)
    ids = {m.get("author_id") for m in msgs if m.get("author_id")}
    if ids:
        fotos = {a["id"]: a.get("photo_url") or "" for a in await global_db.admin_users.find(
            {"id": {"$in": list(ids)}}, {"_id": 0, "id": 1, "photo_url": 1}).to_list(len(ids))}
        for m in msgs:
            m["author_photo"] = fotos.get(m.get("author_id"), "")
    return {"messages": msgs}


# ─── FLOTADSP AI DENTRO DE LA SALA ─────────────────────────────────────────
# Se la llama por su nombre (`@flota`, «flota, ...») y contesta AHI, delante de
# todos, en vez de en una burbuja privada. Lo pidio Dani el 19-09-2026: «tipo
# flota, ensenale a Mery cuales son sus peores conductores».
#
# Tres decisiones, y las tres son para que no moleste:
#   · SOLO CONTESTA SI LA LLAMAN. Un asistente que responde a todo convierte la
#     sala del turno en un hilo suyo; aqui la sala es de las personas.
#   · SE QUEDA UNA HORA. Mientras alguien la llame sigue «en la conversacion» y
#     sale en la lista de gente, para que se sepa que esta a mano. Sin que nadie
#     la llame en una hora, se va sola — estar siempre no significa nada.
#   · SI FALLA, LO DICE. Un asistente mudo parece que se ha ido; y peor todavia,
#     el mensaje de la persona ya esta guardado y quedaria sin respuesta.
_IA_SALA_ID = "flotadsp-ai"
_IA_SALA_NOMBRE = "FlotaDSP AI"
_IA_SALA_FOTO = "/logo-fd-sinlema.png"
_IA_SALA_MINUTOS = 60

# COMO SE LA LLAMA, y sobre todo como NO. Solo tres formas, y las tres son
# inequivocas: `@flota` en cualquier sitio, el mensaje que EMPIEZA por «flota,»
# o «flota:» —que es como se le habla a una persona— y «flotadsp ai» entero.
# Con un simple «flota» suelto se metia en frases como «manana repasamos la
# flota entera», que es exactamente lo que no puede hacer: la sala es de las
# personas y ella solo entra si la llaman.
_IA_LLAMADA = re.compile(
    r"(?:(?:^|\s)@flot(?:a|ia)(?:\s+ai)?\b)"      # @flota / @flotia / @flotia ai
    r"|(?:^\s*flot(?:a|ia)(?:\s+ai)?\s*[,:])"     # «flota, ...» / «flotia: ...» al empezar
    r"|(?:\bflotia\s+ai\b)",                      # su nombre completo
    re.I)


def _ia_la_llaman(texto: str) -> bool:
    return bool(_IA_LLAMADA.search(texto or ""))


def _ia_sin_llamarla(texto: str) -> str:
    """El mensaje sin el «flota,» de delante: lo que de verdad se le pide.

    Con el nombre dentro, el modelo contesta a su propio nombre.
    """
    return _IA_LLAMADA.sub(" ", texto or "", count=1).strip(" ,:")


async def _ia_sala_presente(center: str) -> Optional[dict]:
    """Si esta «en la conversacion» de ese centro, hasta cuando."""
    d = await db.chat_ia_presencia.find_one({"_id": center}, {"_id": 0, "hasta": 1})
    if not d or not d.get("hasta"):
        return None
    m = _hace_min(d["hasta"])
    # `_hace_min` da 0 para el futuro: si aun no ha pasado, sigue dentro.
    return {"hasta": d["hasta"]} if m == 0 else None


# ─── DE QUÉ ESTÁBAMOS HABLANDO ───────────────────────────────────────────────
#
# La IA se llama desde TRES sitios —la pantalla del asistente, la sala del
# centro y un privado— y hasta el 20-09-2026 los tres compartían el mismo
# historial: `ai_chat_msgs`, filtrado solo por usuario y centro. Con eso pasaba
# lo que Dani reportó: escribió «@flota y ahora?» en su privado con Mery y le
# contestó de la plantilla diaria, porque lo anterior en ese historial era una
# conversación del PANEL sobre la plantilla.
#
# Medido en producción antes de arreglarlo: de los 148 mensajes del hilo del
# panel, **7 se habían escrito en realidad en el chat**, y ahí está la respuesta
# a «y ahora?» hablando de Cortex y de furgonetas.
#
# Ahora cada sitio tiene su hilo. Y para el chat el historial NO es una copia:
# son los mensajes de verdad de esa conversación —lo que se han dicho las
# personas, con sus nombres—, que es lo que hace que conteste como uno más y no
# como un formulario. La IA ya guarda ahí sus propias respuestas, así que no
# hace falta duplicar nada.
#
# El hilo lo manda el cliente, así que se comprueba en el SERVIDOR que quien
# pregunta está de verdad en esa conversación: sin eso, cualquier administrador
# podría leer los privados de otros dos pidiéndole a la IA que «recuerde» la
# conversación.
_IA_HILO = re.compile(r"^(sala|dm):([A-Za-z0-9 _.@:-]{1,90})$")
_IA_HILO_MENSAJES = 14          # lo último, no la conversación entera
_IA_HILO_LARGO = 400            # por mensaje


async def _ia_hilo_historial(user: dict, hilo: str) -> Optional[list]:
    """Lo último dicho en esa conversación, ya formateado. None si no procede.

    Devuelve None —no una lista vacía— cuando el hilo no es válido o quien
    pregunta no está en él: el que llama distingue así «no hay contexto» de «no
    te toca», y en el segundo caso no se le da ninguno.
    """
    m = _IA_HILO.match(hilo or "")
    if not m:
        return None
    clase, resto = m.group(1), m.group(2)
    yo = user.get("sub") or user.get("id")

    if clase == "sala":
        if not await _chat_room_can_access(user, resto):
            return None
        msgs = await db.chat_messages.find(
            {"center": resto}, {"_id": 0, "author_name": 1, "text": 1, "created_at": 1},
            sort=[("created_at", -1)], limit=_IA_HILO_MENSAJES).to_list(_IA_HILO_MENSAJES)
        msgs.reverse()
        return [("%s: %s" % (x.get("author_name") or "—", (x.get("text") or "")[:_IA_HILO_LARGO]))
                for x in msgs if (x.get("text") or "").strip()]

    # Un privado: quien pregunta tiene que ser una de las dos partes. La clave
    # de conversacion es "idA:idB" ordenada, asi que basta con mirar si esta.
    if yo not in resto.split(":"):
        return None
    msgs = await db.chat_dm.find(
        {"conv": resto}, {"_id": 0, "de_nombre": 1, "texto": 1, "creado_en": 1},
        sort=[("creado_en", -1)], limit=_IA_HILO_MENSAJES).to_list(_IA_HILO_MENSAJES)
    msgs.reverse()
    return [("%s: %s" % (x.get("de_nombre") or "—", (x.get("texto") or "")[:_IA_HILO_LARGO]))
            for x in msgs if (x.get("texto") or "").strip()]


# Lo que se le dice a la IA cuando entra en una conversación entre personas.
# Sin esto contesta como si le hubieran abierto una ventana de soporte: saluda,
# repite la pregunta y se presenta. Dentro de un chat eso se lee fatal.
_IA_HILO_INSTRUCCION = (
    "ESTÁS DENTRO DE UNA CONVERSACIÓN DEL CHAT INTERNO, no en tu pantalla.\n"
    "Abajo va lo último que se han dicho, en orden y con el nombre de cada uno.\n"
    "Contesta como uno más de la conversación: llama a la gente por su nombre,\n"
    "da por sabido lo que acabáis de hablar —si preguntan «y ahora?» o «¿y él?»\n"
    "se refieren a lo de las líneas de arriba, no a otra cosa—, no saludes ni te\n"
    "presentes, no repitas la pregunta y no cierres con «¿algo más?». Si alguien\n"
    "le pide a otra persona que haga algo, no lo hagas tú: aporta el dato.\n"
    "ÚLTIMOS MENSAJES:"
)


async def _ia_pensar(center: str, texto: str, user: dict,
                     hilo: str = "") -> tuple:
    """Lo que contesta, sin saber donde se va a escribir.

    Lo usan la sala del centro y los privados: el sitio cambia, la respuesta no.
    Si falla, DEVUELVE un texto diciendolo — quedarse muda parece que se ha ido.
    """
    pregunta = _ia_sin_llamarla(texto) or texto
    try:
        salida = await ai_asistente_hablar(
            _IAAsistenteEntrada(mensaje=pregunta, center=center, hilo=hilo), user)
        return ((salida or {}).get("respuesta") or ""), (salida or {}).get("tarjeta")
    except HTTPException as e:
        return "No he podido mirarlo: %s" % (e.detail or "algo ha fallado"), None
    except Exception as e:                                       # noqa: BLE001
        logger.error("IA (%s): %s", center, e)
        return "No he podido mirarlo ahora mismo. Vuelve a llamarme en un minuto.", None


async def _ia_centro_de(user: dict, center: str = "", texto: str = "") -> str:
    """Con que nave mira los datos.

    Un privado no es de ninguna nave, asi que hasta ahora se cogia la del que
    pregunta y punto. Con eso, Dani escribio «y el de dga1? @flota» y le
    contesto «yo solo veo este centro, OGA5»: tiene tres naves y no podia
    preguntar por dos de ellas.

    Ahora manda lo que DIGA el mensaje. Solo se acepta un codigo que sea una
    nave de verdad de su empresa y que el pueda ver -un centro inventado o uno
    ajeno no cambia nada-, y si nombra dos no se adivina: se queda la suya y ya
    dira la IA que solo ve una (misma regla que `_centro_norm`: no adivinar).
    """
    permitidos = user.get("allowed_centers") or []
    suyo = _texto_cuerpo(center, 20) or (permitidos[0] if permitidos else "") or _centro_por_defecto()
    if not texto:
        return suyo
    try:
        naves = await _centros_de_la_empresa()
    except Exception:                                            # noqa: BLE001
        return suyo
    visibles = [n for n in naves if not permitidos or n in permitidos]
    dichas = [n for n in visibles
              if re.search(r"\b%s\b" % re.escape(n), texto, re.I)]
    return dichas[0] if len(dichas) == 1 else suyo


async def _ia_sala_responder(center: str, texto: str, user: dict) -> Optional[dict]:
    """Contesta en la sala del centro. Devuelve el mensaje ya guardado."""
    respuesta, tarjeta = await _ia_pensar(center, texto, user, hilo="sala:%s" % center)
    ahora = datetime.now(timezone.utc).isoformat()
    doc = {
        "id": str(uuid.uuid4()), "center": center,
        "text": respuesta[:2000], "author_id": _IA_SALA_ID,
        "author_name": _IA_SALA_NOMBRE, "author_photo": _IA_SALA_FOTO,
        "es_ia": True, "tarjeta": tarjeta,
        "created_at": ahora, "pinned_to_checklist": False,
    }
    await db.chat_messages.insert_one(dict(doc))   # copia: insert_one muta (gotcha 42)
    await db.chat_ia_presencia.update_one(
        {"_id": center},
        {"$set": {"hasta": (datetime.now(timezone.utc)
                            + timedelta(minutes=_IA_SALA_MINUTOS)).isoformat(),
                  "ultima": ahora}}, upsert=True)
    # Al movil de los demas, igual que un mensaje de una persona: quien pregunto
    # esta mirando la pantalla, pero la respuesta es para toda la sala.
    try:
        await push_center_event(center, f"🤖 {_IA_SALA_NOMBRE} · {center}",
                                respuesta[:120], url="/panel/chat")
    except Exception as e:                                       # noqa: BLE001
        logger.debug("push IA sala: %s", e)
    return doc


@api_router.post("/chat/{center}")
async def chat_post(center: str, data: dict = Body(...), user: dict = Depends(require_admin)):
    """Envía un mensaje a la sala del centro."""
    await _require_plan_feature(user, "chat")
    if not await _chat_room_can_access(user, center):
        raise HTTPException(403, "No tienes acceso a este chat")
    text = _texto_cuerpo(data.get("text"))
    if not text:
        raise HTTPException(400, "Mensaje vacío")
    if len(text) > 2000:
        raise HTTPException(400, "Mensaje demasiado largo (máx 2000)")
    now = datetime.now(timezone.utc).isoformat()
    doc = {
        "id": str(uuid.uuid4()),
        "center": center,
        "text": text[:2000],
        "author_id": user.get("sub"),
        "author_name": user.get("name") or user.get("username") or "—",
        "created_at": now,
        "pinned_to_checklist": False,
    }
    await db.chat_messages.insert_one(doc)
    doc.pop("_id", None)  # insert_one añade _id (ObjectId) que FastAPI no serializa
    # Push al móvil de los demás miembros del centro
    await push_center_event(
        center, f"💬 {doc['author_name']} · {center}", text,
        url="/panel/chat", exclude_id=user.get("sub"))

    # LA IA SOLO HABLA SI LA LLAMAN. El mensaje de la persona ya esta guardado
    # antes de esto a proposito: si la IA falla, lo que escribio no se pierde.
    respuesta_ia = None
    if _ia_la_llaman(text):
        respuesta_ia = await _ia_sala_responder(center, text, user)
    return {"ok": True, "message": doc, "respuesta_ia": respuesta_ia}


@api_router.post("/chat/{center}/{message_id}/to-checklist")
async def chat_pin_to_checklist(center: str, message_id: str,
                                 data: dict = Body(default={}),
                                 user: dict = Depends(require_admin)):
    """Convierte un mensaje de chat en un item de la checklist del turno actual.
    Marca el mensaje como 'pinned_to_checklist' para feedback visual."""
    if not await _chat_room_can_access(user, center):
        raise HTTPException(403, "No tienes acceso a este chat")
    msg = await db.chat_messages.find_one({"id": message_id, "center": center}, {"_id": 0})
    if not msg:
        raise HTTPException(404, "Mensaje no encontrado")
    # Decidir turno: el cliente puede pasarlo, si no, basado en hora UTC.
    shift = data.get("shift")
    if shift not in ("manana", "tarde"):
        h = datetime.now(timezone.utc).hour
        shift = "manana" if h < 14 else "tarde"
    date = _texto_cuerpo(data.get("date"), 10) or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    now = datetime.now(timezone.utc).isoformat()
    # Asegurar doc checklist + añadir item.
    doc = await db.daily_checklists.find_one({"center": center, "date": date, "shift": shift}, {"_id": 0})
    if not doc:
        doc = {
            "id": str(uuid.uuid4()), "center": center, "date": date, "shift": shift,
            "items": _default_items_for_shift(shift),
            "created_at": now, "updated_at": now,
        }
        await db.daily_checklists.insert_one(doc)
    items = doc.get("items", [])
    items.append({
        "id": str(uuid.uuid4()),
        "text": (msg["text"][:280] + ("…" if len(msg["text"]) > 280 else "")),
        "done": False, "done_by": None, "done_at": None,
        "from_chat_id": message_id, "from_chat_author": msg.get("author_name"),
    })
    await db.daily_checklists.update_one(
        {"center": center, "date": date, "shift": shift},
        {"$set": {"items": items, "updated_at": now}}
    )
    await db.chat_messages.update_one({"id": message_id}, {"$set": {"pinned_to_checklist": True, "pinned_shift": shift, "pinned_date": date}})
    return {"ok": True, "shift": shift, "date": date}


# =========================
# AI FRAUD GUARD (S3) — detecta intentos de engaño del conductor
# =========================
# 3 heurísticas:
#  1) EXIF DateTimeOriginal MUY anterior al upload → "foto antigua"
#  2) Perceptual hash coincide con inspección anterior reciente del mismo vehículo → "reusa foto"
#  3) plate_text del análisis ≠ matrícula del vehículo asignado → "matrícula no coincide"
# Score 0-100. Notifica Telegram si ≥85.

_FRAUD_OLD_PHOTO_HOURS = 24      # foto con EXIF >24h antes del upload → flag
_FRAUD_PHASH_DISTANCE = 8        # distancia Hamming <8 = misma foto (de 64 bits)
_FRAUD_PHASH_LOOKBACK_DAYS = 30  # ventana para buscar foto reusada


def _normalize_plate(p: str) -> str:
    """Quita espacios, guiones y pasa a mayúsculas para comparar matrículas.
    (Definición única: antes había un duplicado más abajo que la pisaba.)"""
    return "".join(ch for ch in (p or "").upper() if ch.isalnum())


def _exif_datetime(img_bytes: bytes):
    """Lee EXIF DateTimeOriginal de la foto. None si no hay."""
    try:
        from PIL import Image as PILImage
        import io as _io
        img = PILImage.open(_io.BytesIO(img_bytes))
        exif = img._getexif() if hasattr(img, "_getexif") else None
        if not exif:
            return None
        # tag 36867 = DateTimeOriginal
        raw = exif.get(36867) or exif.get(306)
        if not raw:
            return None
        return datetime.strptime(raw, "%Y:%m:%d %H:%M:%S")
    except Exception:
        return None


def _phash_bytes(img_bytes: bytes) -> str:
    """Perceptual hash (pHash) como string hex. None si falla."""
    try:
        import imagehash
        from PIL import Image as PILImage
        import io as _io
        img = PILImage.open(_io.BytesIO(img_bytes))
        return str(imagehash.phash(img))
    except Exception as e:
        logger.warning(f"phash failed: {e}")
        return None


def _phash_distance(h1: str, h2: str) -> int:
    """Distancia Hamming entre 2 phash hex (64 bits)."""
    try:
        import imagehash
        return imagehash.hex_to_hash(h1) - imagehash.hex_to_hash(h2)
    except Exception:
        return 999


async def _calculate_fraud_score(inspection_id: str) -> dict:
    """Calcula fraud_score y guarda en la inspección. Devuelve {score, reasons}."""
    insp = await db.inspections.find_one({"id": inspection_id}, {"_id": 0})
    if not insp:
        return {"score": 0, "reasons": []}
    vehicle = await db.vehicles.find_one({"id": insp.get("vehicle_id")}, {"_id": 0}) or {}
    reasons = []
    score = 0
    now = datetime.now(timezone.utc)

    # 3) Plate check (rápido, sin descargar fotos)
    plate_text = (insp.get("analysis") or {}).get("plate_text") or insp.get("plate_text") or ""
    expected_plate = vehicle.get("license_plate") or ""
    if plate_text and expected_plate:
        if _normalize_plate(plate_text) != _normalize_plate(expected_plate):
            reasons.append({
                "type": "plate_mismatch",
                "detail": f"IA leyó '{plate_text}' pero el vehículo asignado es '{expected_plate}'",
                "weight": 40,
            })
            score += 40

    # 1+2) EXIF + pHash sobre la primera foto (suficiente para detección rápida)
    photos = (insp.get("photos") or [])[:3]   # primeras 3 fotos máximo
    if photos:
        photo_bytes = await _fetch_photo_bytes(photos[0])
        if photo_bytes:
            # EXIF: comparar con created_at del upload
            exif_dt = _exif_datetime(photo_bytes)
            if exif_dt:
                # Asumimos zona local (no hay TZ en EXIF); margen amplio.
                try:
                    upload_dt = datetime.fromisoformat((insp.get("created_at") or "").replace("Z", "+00:00"))
                    delta_h = abs((upload_dt.replace(tzinfo=None) - exif_dt).total_seconds()) / 3600.0
                    if delta_h > _FRAUD_OLD_PHOTO_HOURS:
                        reasons.append({
                            "type": "old_photo",
                            "detail": f"Foto tomada hace {delta_h:.0f}h (EXIF {exif_dt.isoformat()}), subida posterior",
                            "weight": 35,
                        })
                        score += 35
                except Exception:
                    pass

            # pHash: comparar con inspecciones anteriores del mismo vehículo (últimos 30 días)
            this_phash = _phash_bytes(photo_bytes)
            if this_phash:
                cutoff = (now - timedelta(days=_FRAUD_PHASH_LOOKBACK_DAYS)).isoformat()
                prev = await db.inspections.find(
                    {"vehicle_id": insp.get("vehicle_id"),
                     "id": {"$ne": inspection_id},
                     "deleted": {"$ne": True},
                     "created_at": {"$gte": cutoff},
                     "first_phash": {"$exists": True}},
                    {"_id": 0, "id": 1, "first_phash": 1, "created_at": 1}
                ).limit(50).to_list(50)
                for p in prev:
                    d = _phash_distance(this_phash, p.get("first_phash", ""))
                    if d < _FRAUD_PHASH_DISTANCE:
                        reasons.append({
                            "type": "reused_photo",
                            "detail": f"Foto casi idéntica (distancia pHash {d}) a inspección anterior {p.get('id','')[:8]} del {(p.get('created_at') or '')[:10]}",
                            "weight": 50,
                        })
                        score += 50
                        break
                # Guarda el phash para futuras comparaciones (en TODAS las inspecciones, no solo fraud).
                await db.inspections.update_one({"id": inspection_id}, {"$set": {"first_phash": this_phash}})

    score = min(100, score)
    await db.inspections.update_one(
        {"id": inspection_id},
        {"$set": {"fraud_score": score, "fraud_reasons": reasons,
                  "fraud_checked_at": now.isoformat()}}
    )
    logger.info(f"fraud check insp={inspection_id[:8]} score={score} reasons={[r['type'] for r in reasons]}")

    # Notificación Telegram si alto.
    if score >= 85:
        try:
            cfg = await db.telegram_config.find_one({}, {"_id": 0})
            if cfg and cfg.get("enabled") and cfg.get("bot_token"):
                txt = (f"🚨 <b>POSIBLE FRAUDE</b>\n\nInspección <code>{inspection_id[:8]}</code> · "
                       f"vehículo {expected_plate} · score {score}/100\n\n" +
                       "\n".join(f"• {r['detail']}" for r in reasons))
                async with _aiohttp.ClientSession() as s:
                    for cid in cfg.get("chat_ids", []):
                        if cid.strip():
                            await s.post(f"https://api.telegram.org/bot{cfg['bot_token']}/sendMessage",
                                         json={"chat_id": cid, "text": txt, "parse_mode": "HTML"},
                                         timeout=_aiohttp.ClientTimeout(total=8))
        except Exception as e:
            logger.warning(f"Telegram fraud alert failed: {e}")
    return {"score": score, "reasons": reasons}


@api_router.post("/inspections/{inspection_id}/recheck-fraud")
async def recheck_fraud(inspection_id: str, _=Depends(require_admin)):
    """Fuerza recálculo del fraud_score (útil tras ediciones)."""
    return await _calculate_fraud_score(inspection_id)


