import aiohttp as _aiohttp

# =========================
# WHATSAPP BUSINESS (Cloud API de Meta)
# =========================
# El envio vive en `backend/whatsapp.py`. Aqui solo van los endpoints: el
# webhook que verifica Meta, el interruptor de cada aviso y la prueba.
#
# LA URL QUE HAY QUE PEGAR EN META es, con el prefijo del router incluido:
#     https://flotadsp-backend.fly.dev/api/webhooks/whatsapp
# y el "token de verificacion" es el valor de WHATSAPP_VERIFY_TOKEN.


@api_router.get("/webhooks/whatsapp")
async def whatsapp_webhook_verificar(request: Request):
    """El reto de verificacion de Meta. Publico y sin sesion, a la fuerza.

    Meta llama con ?hub.mode=subscribe&hub.verify_token=X&hub.challenge=Y y hay
    que devolver el challenge TAL CUAL y en texto plano. Si se devuelve JSON o
    con comillas, Meta lo da por fallido sin decir por que.

    OJO AL ORDEN DE RUTAS: esta es estatica y va declarada antes que cualquier
    `/webhooks/{algo}`. Puesta despues, la palabra 'whatsapp' entraria como si
    fuera un parametro (el mismo fallo del /work-orders/export).
    """
    p = request.query_params
    esperado = os.environ.get("WHATSAPP_VERIFY_TOKEN") or ""
    if p.get("hub.mode") == "subscribe" and esperado and p.get("hub.verify_token") == esperado:
        return PlainTextResponse(p.get("hub.challenge") or "")
    logger.warning("WhatsApp webhook: verificacion rechazada (token no coincide)")
    raise HTTPException(status_code=403, detail="Token de verificacion incorrecto")


async def _seg_tenant_por_telefono(tel: str):
    """De qué DSP es el taller que escribe desde ese teléfono.

    Gotcha 26: este camino NO tiene sesión, y `db` sin `set_current_org_db`
    caería siempre en la base principal. Hoy acertaría por casualidad porque la
    de Dani ES la principal; el día que haya un segundo cliente, el mensaje de
    su taller se guardaría en los datos de otro.

    Se busca el teléfono en los talleres de cada DSP y se devuelve el primero
    que lo tenga. Se compara por los ÚLTIMOS 9 DÍGITOS: el mismo número está
    escrito '+34 981 58 48 24', '981584824' y '0034981584824', y un igual a
    secas no casaría ninguno con otro.
    """
    fin = "".join(c for c in str(tel or "") if c.isdigit())[-9:]
    if len(fin) < 9:
        return None, None
    orgs = await global_db.organizations.find(
        {"status": {"$in": ["active", "trial"]}},
        {"_id": 0, "id": 1, "db_name": 1, "account_type": 1, "name": 1}).to_list(500)
    for o in (orgs or [None]):
        nombre = _tenant_db_name(o)
        try:
            async for w in client[nombre].workshops.find(
                    {}, {"_id": 0, "id": 1, "name": 1, "phone": 1}):
                d = "".join(c for c in str(w.get("phone") or "") if c.isdigit())
                if d and d[-9:] == fin:
                    return nombre, w
        except Exception as e:                                   # noqa: BLE001
            logger.warning("buscando taller en %s: %s", nombre, e)
    return None, None


def _seg_textos_del_webhook(cuerpo: dict) -> list:
    """[(telefono, texto)] de un webhook de Meta. Lista vacía si no hay ninguno.

    Un webhook trae también acuses de entrega y cambios de estado; aquí solo
    interesan los mensajes de texto de una persona.
    """
    out = []
    for entry in (cuerpo or {}).get("entry") or []:
        for ch in entry.get("changes") or []:
            val = ch.get("value") or {}
            for m in val.get("messages") or []:
                if m.get("type") != "text":
                    continue
                t = ((m.get("text") or {}).get("body") or "").strip()
                if t:
                    out.append((m.get("from") or "", t))
    return out


async def procesar_entrante_taller(cuerpo: dict, omitir: frozenset = frozenset()) -> dict:
    """Un mensaje de WhatsApp de un taller: se guarda, para el reloj y avisa.

    Esto es lo que hace que el canal vaya en los DOS sentidos. Si el taller
    termina el martes y a nosotros no nos tocaba preguntar hasta el jueves,
    aquí es donde nos enteramos.

    `omitir`: los ultimos-9 de los numeros que ya se sabe que son de un
    CONDUCTOR (van al hilo de Conversaciones). Sin saltarlos, lo que escribe un
    conductor se apuntaba tambien como «sin asignar», que es ruido.
    """
    hechos = []
    anterior = _current_db_name.get()
    try:
        for tel, texto in _seg_textos_del_webhook(cuerpo):
            if _wa_ultimos9(tel) in omitir:
                continue
            base, taller = await _seg_tenant_por_telefono(tel)
            if not base:
                # No sabemos de quién es. Se apunta igual en global: un mensaje
                # perdido es el silencio que esto viene a quitar, y el número
                # sirve para darlo de alta luego.
                await global_db.whatsapp_sin_asignar.insert_one({
                    "telefono": tel, "texto": texto[:2000],
                    "at": datetime.now(timezone.utc).isoformat(),
                    "expira_en": datetime.now(timezone.utc) + timedelta(days=90)})
                hechos.append({"telefono": tel, "estado": "sin taller conocido"})
                continue

            set_current_org_db(base)
            abiertas = await db.ordenes_trabajo.find(
                {"taller_id": taller.get("id"),
                 "estado": {"$in": list(seguimiento.ESTADOS_QUE_SE_SIGUEN)}},
                {"_id": 0}).to_list(50)
            ident = seguimiento.identifica_orden(texto, abiertas)
            r = await registrar_novedad_taller(
                ident["orden"], texto, "whatsapp",
                {"telefono": tel, "certeza": ident["certeza"],
                 "motivo_identificacion": ident["motivo"],
                 "taller_id": taller.get("id"), "taller_nombre": taller.get("name")})
            hechos.append({"taller": taller.get("name"), "orden": r.get("orden"),
                           "certeza": ident["certeza"], "pista": r.get("pista")})
    finally:
        set_current_org_db(anterior)
    if hechos:
        logger.info("Taller por WhatsApp: %d mensaje(s) procesados", len(hechos))
    return {"procesados": hechos}


@api_router.post("/webhooks/whatsapp")
async def whatsapp_webhook_recibir(request: Request):
    """Mensajes entrantes y acuses de entrega. De momento solo se apuntan.

    SE DEVUELVE 200 PASE LO QUE PASE. Meta reintenta lo que no responde 200 y,
    tras varios fallos, DESACTIVA la suscripcion del webhook entera. Un error
    nuestro procesando un mensaje no puede acabar en quedarnos sin webhook.

    Se guarda en `global_db` y no en la base del DSP a proposito: este endpoint
    no lleva sesion, y `db` resolveria a la base por defecto pasara lo que
    pasara (gotcha 26). Cuando haga falta repartirlo por empresa, el
    `phone_number_id` del propio mensaje es la clave para saber de quien es.
    """
    try:
        cuerpo = await request.json()
    except Exception:                                        # noqa: BLE001
        return {"ok": True}
    try:
        await global_db.whatsapp_webhook_events.insert_one({
            "recibido_en": datetime.now(timezone.utc).isoformat(),
            "cuerpo": json.loads(json.dumps(cuerpo)[:20000]),
            "expira_en": datetime.now(timezone.utc) + timedelta(days=30),
        })
    except Exception as e:                                   # noqa: BLE001
        logger.warning(f"WhatsApp webhook: no se pudo guardar: {e}")

    # Y AHORA SE PROCESA. Hasta hoy solo se apuntaba, asi que un taller podia
    # contestar "ya esta lista" y no enterarse nadie: el canal iba en un solo
    # sentido. Va dentro de su propio try porque el contrato de arriba manda —
    # Meta desactiva el webhook entero si no le devolvemos 200.
    # Primero la CONVERSACION (todo mensaje, de quien sea, y los acuses de lo que
    # mandamos); despues el flujo de talleres, que sigue igual.
    de_conductor: set = set()
    try:
        de_conductor = await registrar_entrantes_whatsapp(cuerpo)
        await aplicar_estados_whatsapp(cuerpo)
    except Exception as e:                                   # noqa: BLE001
        logger.error(f"WhatsApp webhook: conversaciones: {e}")
    try:
        await procesar_entrante_taller(cuerpo, omitir=frozenset(de_conductor))
    except Exception as e:                                   # noqa: BLE001
        logger.error(f"WhatsApp webhook: procesando entrante: {e}")
    return {"ok": True}


# ─── CONVERSACIONES: LO QUE DICEN Y LO QUE SE LES DICE ──────────────────────
#
# El numero de WhatsApp es UNO para toda la plataforma y los mensajes llegan a
# un webhook sin sesion, asi que lo primero es saber de que empresa es cada uno
# (gotcha 26). Se decide asi, por este orden:
#   1. la empresa a la que se le MANDO algo a ese numero mas recientemente: la
#      conversacion es de quien la empezo;
#   2. si nadie le escribio, la empresa que tiene ese numero en una ficha de
#      conductor (movil personal o telefono) o en un taller.
# Se compara por los ULTIMOS 9 DIGITOS: el mismo numero esta escrito de seis
# maneras (gotcha 47). Lo que no encaja en ninguna empresa NO se guarda aqui: lo
# recoge el flujo de talleres en `whatsapp_sin_asignar`, como siempre.

_WA_VENTANA_H = 24
_WA_RANGO_ESTADO = {"sent": 1, "delivered": 2, "read": 3, "failed": 9}
_WA_TIPOS_ADJUNTO = {"image": "imagen", "video": "vídeo", "document": "documento",
                     "audio": "audio", "voice": "nota de voz", "sticker": "sticker"}


def _wa_ultimos9(tel) -> str:
    return "".join(c for c in str(tel or "") if c.isdigit())[-9:]


def _wa_iso(ts) -> str:
    """De la marca de tiempo de Meta (segundos, como texto) a ISO en UTC."""
    try:
        return datetime.fromtimestamp(int(ts), timezone.utc).isoformat()
    except (TypeError, ValueError, OverflowError, OSError):
        return datetime.now(timezone.utc).isoformat()


def _wa_mensajes_del_webhook(cuerpo: dict) -> list:
    """Cada mensaje entrante de un webhook de Meta, de CUALQUIER tipo.

    Una foto o una nota de voz no se descargan, pero SI se apuntan («[imagen]»):
    un hilo que se salta lo que la persona mando parece que no contesto.
    """
    out = []
    for entry in (cuerpo or {}).get("entry") or []:
        for ch in entry.get("changes") or []:
            val = ch.get("value") or {}
            perfiles = {str(c.get("wa_id") or ""): ((c.get("profile") or {}).get("name") or "")
                        for c in val.get("contacts") or []}
            for m in val.get("messages") or []:
                if not isinstance(m, dict):
                    continue
                tipo = str(m.get("type") or "otro")
                if tipo == "text":
                    texto = str((m.get("text") or {}).get("body") or "")
                elif tipo == "button":
                    texto = str((m.get("button") or {}).get("text") or "")
                elif tipo == "interactive":
                    i = m.get("interactive") or {}
                    texto = str(((i.get("button_reply") or i.get("list_reply")) or {}).get("title") or "")
                elif tipo in _WA_TIPOS_ADJUNTO:
                    pie = str((m.get(tipo) or {}).get("caption") or "").strip()
                    texto = "[%s]%s" % (_WA_TIPOS_ADJUNTO[tipo], (" " + pie) if pie else "")
                elif tipo == "location":
                    loc = m.get("location") or {}
                    texto = "[ubicación] %s,%s" % (loc.get("latitude"), loc.get("longitude"))
                else:
                    texto = "[%s]" % tipo
                tel = str(m.get("from") or "")
                if not tel:
                    continue
                out.append({"telefono": tel, "texto": texto.strip()[:2000], "tipo": tipo,
                            "wamid": str(m.get("id") or ""), "at": _wa_iso(m.get("timestamp")),
                            "perfil": perfiles.get(tel, "")[:80]})
    return out


def _wa_estados_del_webhook(cuerpo: dict) -> list:
    """Los acuses de lo que MANDAMOS: enviado / entregado / leido / fallido."""
    out = []
    for entry in (cuerpo or {}).get("entry") or []:
        for ch in entry.get("changes") or []:
            for s in (ch.get("value") or {}).get("statuses") or []:
                if not isinstance(s, dict) or not s.get("id"):
                    continue
                est = str(s.get("status") or "")
                if est not in _WA_RANGO_ESTADO:
                    continue
                err = ((s.get("errors") or [{}])[0]) if s.get("errors") else {}
                out.append({"id": str(s["id"]), "estado": est, "at": _wa_iso(s.get("timestamp")),
                            "error": str(err.get("title") or err.get("message") or "")[:200]
                            if est == "failed" else ""})
    return out


def _wa_ventana(entrantes_at: list, ahora: datetime = None) -> dict:
    """¿Se puede escribir texto libre? Solo dentro de las 24 h del ultimo mensaje
    DE ELLA. Fuera, WhatsApp solo admite plantillas."""
    ahora = ahora or datetime.now(timezone.utc)
    ultimo = max((a for a in entrantes_at if a), default=None)
    if not ultimo:
        return {"abierta": False, "cierra_en": None, "ultimo_entrante": None}
    try:
        cierra = datetime.fromisoformat(ultimo) + timedelta(hours=_WA_VENTANA_H)
    except ValueError:
        return {"abierta": False, "cierra_en": None, "ultimo_entrante": ultimo}
    return {"abierta": cierra > ahora, "cierra_en": cierra.isoformat(), "ultimo_entrante": ultimo}


async def _wa_personas(tdb) -> dict:
    """ultimos-9-digitos -> {tipo, id, nombre} de los conductores y talleres de UNA
    empresa. El movil personal manda sobre el telefono de la ficha (que puede ser
    el de la ruta del dia)."""
    mapa: dict = {}
    for w in await tdb.workshops.find({}, {"_id": 0, "id": 1, "name": 1, "phone": 1}).to_list(2000):
        f = _wa_ultimos9(w.get("phone"))
        if f:
            mapa.setdefault(f, {"tipo": "taller", "id": w.get("id"), "nombre": w.get("name") or ""})
    for d in await tdb.drivers.find(
            {"active": {"$ne": False}},
            {"_id": 0, "id": 1, "name": 1, "phone": 1, "movil_personal": 1}).to_list(5000):
        for campo in ("phone", "movil_personal"):        # el personal va DESPUES: gana
            f = _wa_ultimos9(d.get(campo))
            if f:
                mapa[f] = {"tipo": "conductor", "id": d.get("id"), "nombre": d.get("name") or ""}
    return mapa


async def _wa_tenant_de_telefono(tel: str):
    """(nombre_de_base, persona | None) de la empresa a la que pertenece ese numero."""
    fin = _wa_ultimos9(tel)
    if len(fin) < 9:
        return None, None
    orgs = await global_db.organizations.find(
        {"status": {"$in": ["active", "trial"]}},
        {"_id": 0, "id": 1, "db_name": 1, "account_type": 1, "name": 1}).to_list(500)
    bases = [_tenant_db_name(o) for o in (orgs or [None])]
    mejor = None
    for nombre in bases:
        try:
            e = await client[nombre][whatsapp.COLECCION_ENVIOS].find(
                {"telefono": {"$regex": fin + "$"}}, {"_id": 0, "at": 1}
            ).sort("at", -1).limit(1).to_list(1)
        except Exception as ex:                                  # noqa: BLE001
            logger.warning("whatsapp: buscando envios en %s: %s", nombre, ex)
            continue
        if e and (mejor is None or e[0].get("at", "") > mejor[0]):
            mejor = (e[0].get("at", ""), nombre)
    if mejor:
        nombre = mejor[1]
        return nombre, (await _wa_personas(client[nombre])).get(fin)
    for nombre in bases:
        try:
            persona = (await _wa_personas(client[nombre])).get(fin)
        except Exception as ex:                                  # noqa: BLE001
            logger.warning("whatsapp: buscando personas en %s: %s", nombre, ex)
            continue
        if persona:
            return nombre, persona
    return None, None


async def registrar_entrantes_whatsapp(cuerpo: dict) -> set:
    """Guarda cada mensaje en la conversacion de SU empresa.

    Devuelve los ultimos-9 de los numeros que son de un CONDUCTOR: el flujo de
    talleres los salta, en vez de apuntar como «sin asignar» lo que ya tiene
    dueño. Idempotente por `wamid`: Meta reenvia el webhook si tarda.
    """
    de_conductor: set = set()
    anterior = _current_db_name.get()
    try:
        for m in _wa_mensajes_del_webhook(cuerpo):
            base, persona = await _wa_tenant_de_telefono(m["telefono"])
            if not base:
                continue
            set_current_org_db(base)
            if persona and persona.get("tipo") == "conductor":
                de_conductor.add(_wa_ultimos9(m["telefono"]))
            wamid = m["wamid"] or "sin-id-" + secrets.token_hex(6)
            try:
                await db[whatsapp.COLECCION_MENSAJES].update_one(
                    {"wamid": wamid},
                    {"$setOnInsert": {
                        "wamid": wamid, "telefono": whatsapp.normaliza_telefono(m["telefono"])
                        or m["telefono"], "sentido": "entrante", "texto": m["texto"],
                        "tipo": m["tipo"], "at": m["at"], "perfil": m["perfil"],
                        "leido": False,
                        # 180 dias y caduca solo (indice TTL: tiene que ser una fecha).
                        "expira_en": datetime.now(timezone.utc) + timedelta(days=180)}},
                    upsert=True)
            except DuplicateKeyError:
                pass          # ya estaba: el reenvio de Meta de siempre
    finally:
        set_current_org_db(anterior)
    return de_conductor


async def aplicar_estados_whatsapp(cuerpo: dict) -> int:
    """Pone en cada envio lo que Meta dice de el. Un «enviado» que luego falla
    (numero sin WhatsApp, bloqueo) solo se sabe por aqui, y sin esto el hilo
    diria «enviado» de algo que no llego nunca."""
    estados = _wa_estados_del_webhook(cuerpo)
    if not estados:
        return 0
    orgs = await global_db.organizations.find(
        {"status": {"$in": ["active", "trial"]}},
        {"_id": 0, "id": 1, "db_name": 1, "account_type": 1}).to_list(500)
    n = 0
    for s in estados:
        rango = _WA_RANGO_ESTADO[s["estado"]]
        for o in (orgs or [None]):
            try:
                r = await client[_tenant_db_name(o)][whatsapp.COLECCION_ENVIOS].update_one(
                    # Los acuses pueden llegar desordenados (leido antes que
                    # entregado): solo se sube de rango, nunca se baja.
                    {"message_id": s["id"],
                     "$or": [{"estado_rango": {"$exists": False}}, {"estado_rango": {"$lt": rango}}]},
                    {"$set": {"estado": s["estado"], "estado_rango": rango, "estado_en": s["at"],
                              **({"estado_error": s["error"]} if s["error"] else {})}})
            except Exception as ex:                              # noqa: BLE001
                logger.warning("whatsapp: aplicando estado: %s", ex)
                continue
            if r.matched_count:
                n += 1
                break
    return n


def _wa_estado_visible(d: dict) -> str:
    """Lo que dice el hilo de un mensaje NUESTRO."""
    if d.get("ok") is False:
        return "fallido"
    return d.get("estado") or "enviado"


