@api_router.get("/whatsapp/conversaciones")
async def wa_conversaciones(q: str = "", _=Depends(require_admin)):
    """Un renglon por persona: el ultimo mensaje, de quien y cuantos sin leer."""
    ent = await db[whatsapp.COLECCION_MENSAJES].aggregate([
        {"$sort": {"at": -1}},
        {"$group": {"_id": "$telefono", "at": {"$first": "$at"}, "texto": {"$first": "$texto"},
                    "no_leidos": {"$sum": {"$cond": [{"$ne": ["$leido", True]}, 1, 0]}}}}]).to_list(1000)
    sal = await db[whatsapp.COLECCION_ENVIOS].aggregate([
        {"$match": {"telefono": {"$regex": "^[0-9]{9,15}$"}}},
        {"$sort": {"at": -1}},
        {"$group": {"_id": "$telefono", "at": {"$first": "$at"}, "texto": {"$first": "$texto"},
                    "plantilla": {"$first": "$plantilla"}}}]).to_list(1000)
    hilos: dict = {}
    for r in sal:
        hilos[r["_id"]] = {"telefono": r["_id"], "ultimo_at": r["at"], "ultimo_sentido": "saliente",
                           "ultimo_texto": r.get("texto") or ("[plantilla %s]" % r.get("plantilla")
                                                              if r.get("plantilla") else ""),
                           "no_leidos": 0}
    for r in ent:
        h = hilos.setdefault(r["_id"], {"telefono": r["_id"], "ultimo_at": "", "no_leidos": 0})
        h["no_leidos"] = r["no_leidos"]
        if (r["at"] or "") >= (h.get("ultimo_at") or ""):
            h.update({"ultimo_at": r["at"], "ultimo_sentido": "entrante", "ultimo_texto": r.get("texto") or ""})
    personas = await _wa_personas(db)
    filas = []
    for h in hilos.values():
        p = personas.get(_wa_ultimos9(h["telefono"])) or {}
        h["nombre"], h["tipo"] = p.get("nombre") or "", p.get("tipo") or ""
        filas.append(h)
    if q.strip():
        k = _clave_nombre(q)
        filas = [h for h in filas if k in _clave_nombre(h["nombre"])
                 or k in _clave_nombre(h.get("ultimo_texto")) or q.strip() in h["telefono"]]
    filas.sort(key=lambda h: (h.get("ultimo_at") or "", h["telefono"]), reverse=True)
    return {"conversaciones": filas[:200], "total": len(filas)}


@api_router.get("/whatsapp/conversaciones/{tel}")
async def wa_conversacion(tel: str, _=Depends(require_admin)):
    """El hilo entero con una persona, lo suyo y lo nuestro juntos y por hora."""
    e164 = whatsapp.normaliza_telefono(tel)
    if not e164:
        raise HTTPException(400, "Ese numero no es valido")
    ent = await db[whatsapp.COLECCION_MENSAJES].find(
        {"telefono": e164}, {"_id": 0, "wamid": 1, "texto": 1, "tipo": 1, "at": 1,
                             "perfil": 1, "leido": 1}).sort("at", -1).to_list(300)
    sal = await db[whatsapp.COLECCION_ENVIOS].find(
        {"telefono": e164}, {"_id": 0}).sort("at", -1).to_list(300)
    mensajes = [{"id": m["wamid"], "sentido": "entrante", "texto": m.get("texto") or "",
                 "tipo": m.get("tipo") or "text", "at": m["at"], "leido": bool(m.get("leido"))}
                for m in ent]
    for d in sal:
        mensajes.append({
            "id": d.get("message_id") or d["at"], "sentido": "saliente",
            "texto": d.get("texto") or ("[plantilla %s]" % d.get("plantilla") if d.get("plantilla") else ""),
            "tipo": d.get("tipo") or "plantilla", "at": d["at"],
            "estado": _wa_estado_visible(d), "motivo": d.get("motivo") or "",
            "error": (d.get("estado_error") or d.get("error") or "") if _wa_estado_visible(d) == "fallido" else ""})
    mensajes.sort(key=lambda m: m["at"])
    persona = (await _wa_personas(db)).get(_wa_ultimos9(e164)) or {}
    return {"telefono": e164, "nombre": persona.get("nombre") or "", "tipo": persona.get("tipo") or "",
            "mensajes": mensajes[-300:],
            "ventana": _wa_ventana([m["at"] for m in ent])}


