# TALLERES — CRUD + sugerencias por daño (v5.1)
# =========================

def _normalize_center_code(center_raw: Optional[str]) -> str:
    """Convierte 'AMZL OGA5 SANTIAGO XPT' → 'OGA5'.

    Llevaba los tres centros de Dani ESCRITOS A MANO —OGA5, DGA1, DGA2— y
    devolvia '' para cualquier otro. Con una empresa nueva eso no era un
    detalle: la cola de Revision Rapida compara el centro pedido contra esto,
    asi que **filtrar por centro devolvia siempre CERO** aunque hubiera
    inspecciones esperando. Medido el 31-08-2026 con una empresa recien
    creada: la cola tenia una y `?center=IN1` devolvia ninguna. El panel manda
    siempre el centro seleccionado, o sea que era el caso normal, no el raro.

    Ahora delega en `_centro_norm`, que ya existia y hace lo correcto: saca el
    codigo cuando lo reconoce y, cuando no, **devuelve el original** en vez de
    borrarlo. Para OGA5/DGA1/DGA2 da exactamente lo mismo que antes.
    """
    return _centro_norm(center_raw)


_MOTIVOS_NO_EVALUABLE = ("borrosa", "oscura", "lejos", "tapada", "sucia")


def _zonas_no_evaluables(data: dict) -> list:
    """Sanea lo que devuelve la IA en `zonas_no_evaluables`.

    Se filtra a una lista CERRADA de motivos y se recorta a 12 porque un LLM,
    si le dejas, escribe parrafos: los `image_quality_warnings` que ya hay en
    produccion son ensayos de tres lineas que nadie lee. Un motivo de una
    palabra se puede contar, agrupar y enseñar; un parrafo no.
    """
    salida = []
    for z in _lista_cuerpo(data.get("zonas_no_evaluables"))[:12]:
        if not isinstance(z, dict):
            continue
        motivo = str(z.get("motivo") or "").strip().lower()
        if motivo not in _MOTIVOS_NO_EVALUABLE:
            # Un motivo fuera de la lista no se tira: se guarda como "otra",
            # porque perder el aviso seria peor que no clasificarlo.
            motivo = "otra"
        try:
            foto = int(z.get("foto") or 0)
        except (TypeError, ValueError):
            foto = 0
        salida.append({"foto": foto, "zona": str(z.get("zona") or "")[:80], "motivo": motivo})
    return salida


def _damage_category(damage: dict) -> str:
    """Infiere la categoría de trabajo necesaria a partir del daño.
    Devuelve: 'lunas' | 'mecanica' | 'chapa' (default)."""
    haystack = " ".join([
        str(damage.get("part") or ""),
        str(damage.get("description") or ""),
        str(damage.get("repair_suggestion") or ""),
    ]).lower()
    if any(k in haystack for k in ("luna", "cristal", "parabrisas", "vidrio")):
        return "lunas"
    if any(k in haystack for k in ("motor", "transmis", "embrague", "freno", "suspen", "dirección", "direccion")):
        return "mecanica"
    if any(k in haystack for k in ("neumát", "neumat", "rueda", "llanta")):
        return "neumaticos"
    return "chapa"


def _provider_matches(workshop: dict, provider: str) -> bool:
    """¿El taller tiene convenio con este proveedor?"""
    if not provider:
        return False
    convenios = workshop.get("convenios") or []
    if "*" in convenios:
        return True
    pup = provider.upper()
    for c in convenios:
        cup = str(c).upper()
        if cup and (cup in pup or pup in cup):
            return True
    return False


# ==========================================================================
# ORDENES DE TRABAJO Y PORTAL DEL TALLER
# ==========================================================================
#
# El objetivo es quitar las llamadas y los correos: el taller escribe EL MISMO
# y la informacion cae en la app. Para que eso ocurra de verdad, la barrera de
# entrada tiene que ser CERO -> un enlace que se abre en el movil, sin usuario,
# sin contrasena y sin instalar nada. Un taller de tres mecanicos no se da de
# alta en un portal, eso esta comprobado en cualquier sector.
#
# OJO CON LA MULTIEMPRESA. `db` resuelve la organizacion desde el token de
# sesion y, si no hay contexto, cae en la BD POR DEFECTO sin fallar. Un
# endpoint publico no tiene sesion, asi que escribiria en la BD principal
# pasara lo que pasara: hoy acertaria por casualidad (la de Dani ES la
# principal) y el dia que haya un segundo cliente, el enlace de un taller
# suyo tocaria datos ajenos, en silencio y sin ningun error.
# Por eso el registro de enlaces vive en `global_db` y guarda el nombre de la
# BD: el endpoint publico lo lee y fija el contexto A MANO antes de tocar `db`.

OT_ESTADOS = {
    "abierta": "Abierta",
    "recibido": "Vehículo recibido",
    "diagnostico": "Diagnosticando",
    "esperando_piezas": "Esperando piezas",
    "reparando": "En reparación",
    "listo": "Listo para recoger",
    "entregado": "Entregado",
    "anulada": "Anulada",
}

# Una orden CERRADA es la que ya no cuenta: el vehiculo volvio o el trabajo se
# anulo. Existe como constante porque escribirla a mano salio mal dos veces:
# habia un `$nin ["entregada", "anulada"]` y un `$nin ["cerrada", "anulada"]`, y
# NINGUNO de esos dos estados existe —el real es "entregado", masculino—. Un
# filtro por un valor que no existe no da error: no excluye nada (gotcha 33).
# El efecto era que una furgoneta ya devuelta seguia contando como parada en
# "no consta cuando vuelven" y en "furgonetas paradas". Con dos ordenes en la
# base no se veia; con cincuenta, los dos numeros de la portada serian falsos.
OT_ESTADOS_CERRADOS = ("entregado", "anulada")

# Lo que puede poner EL TALLER. 'entregado' y 'anulada' las pone la oficina a
# proposito: el taller no decide que un vehiculo ya esta devuelto ni que un
# trabajo se cancela, porque eso mueve el estado de la furgoneta en la flota.
OT_ESTADOS_TALLER = ("recibido", "diagnostico", "esperando_piezas", "reparando", "listo")
OT_ABIERTAS = ("abierta", "recibido", "diagnostico", "esperando_piezas", "reparando", "listo")


def _ot_transicion_invalida(actual, nuevo) -> Optional[str]:
    """Por que NO se puede pasar de `actual` a `nuevo`, o None si se puede.

    Una orden cerrada es terminal. Forzado por API el 02-09-2026: una orden
    `entregado` volvia a `reparando` con un 200, la furgoneta se quedaba
    `active` en la flota mientras la orden decia que estaba en el taller
    —las "dos verdades" que la creacion de ordenes evita—, y una `entregado`
    pasaba a `anulada` sin deshacer nada. Si hay que volver al taller, se
    abre otra orden: asi cada visita tiene su fecha de entrada y su parte.
    Repetir el mismo estado no es una transicion y no molesta.
    """
    if nuevo not in OT_ESTADOS:
        return "Ese estado no existe"
    if actual == nuevo:
        return None
    if actual in OT_ESTADOS_CERRADOS:
        return ("La orden ya está %s y no se puede reabrir. Si la furgoneta vuelve "
                "al taller, abre una orden nueva." % OT_ESTADOS.get(actual, actual).lower())
    return None

# Cambios que merecen aviso inmediato. El resto se ve en la pantalla y ya:
# avisar de todo es no avisar de nada.
OT_AVISA = ("listo", "esperando_piezas")

# A partir de aqui una orden esta "parada": el taller no ha tocado nada en
# todo este tiempo. No es un fallo del taller necesariamente —puede estar
# esperando una pieza— pero es exactamente la furgoneta de la que nadie se
# acuerda, y esa es la que cuesta dinero.
OT_DIAS_PARADA = 4


class OrdenTrabajoCrear(BaseModel):
    vehicle_id: str
    workshop_id: str
    problema: str = ""
    fecha_entrada: Optional[str] = None
    fecha_entrega_estimada: Optional[str] = None
    incident_id: Optional[str] = None
    # Apunte del libro de daños del que sale esta orden. Al crearla se marca
    # ese daño como "en taller" para que no salga otra vez en la lista.
    ledger_id: Optional[str] = None
    # VARIOS daños en la misma orden. `ledger_id` se queda por lo que ya
    # llamaba asi, pero lo normal es esto: una furgoneta va al taller con
    # todo lo que tiene, no con un golpe.
    ledger_ids: Optional[List[str]] = None


async def _ot_fotos_del_dano(danos: list) -> dict:
    """Para cada daño del libro, la foto donde se ve. {ledger_id: {...}}

    POR QUE ESTO ES LA PIEZA QUE FALTABA. Mandar una furgoneta al taller
    obligaba a explicar el golpe por telefono o por correo, y el taller a
    buscarlo dando vueltas al vehiculo. Todo lo necesario ya estaba guardado y
    sin conectar: cada apunte del libro sabe en que inspeccion se vio
    (`first_seen_inspection`) y esa inspeccion tiene las fotos.

    SE PREFIERE LA FOTO ANOTADA. `annotated_photos` es un array PARALELO a
    `photos` con la marca de la IA encima del golpe, y `None` en las fotos
    donde no detecto nada. Una foto anotada le dice al taller donde mirar; la
    misma foto sin anotar es un lateral de furgoneta cualquiera. Si no hay
    anotada se manda la normal, que sigue siendo mejor que nada — pero nunca
    se manda una posicion vacia del array como si fuera una URL.
    """
    ids = [d.get("first_seen_inspection") for d in danos if d.get("first_seen_inspection")]
    if not ids:
        return {}
    insp = {i["id"]: i async for i in db.inspections.find(
        {"id": {"$in": list(set(ids))}},
        {"_id": 0, "id": 1, "photos": 1, "annotated_photos": 1, "created_at": 1})}
    out = {}
    for d in danos:
        i = insp.get(d.get("first_seen_inspection"))
        if not i:
            continue
        fotos = [f for f in (i.get("photos") or []) if f]
        anot = [f for f in (i.get("annotated_photos") or []) if f]
        elegidas = (anot or fotos)[:4]
        if not elegidas:
            continue
        out[str(d.get("_id"))] = {
            "fotos": elegidas,
            "anotadas": bool(anot),
            "vista_en": (i.get("created_at") or "")[:10],
        }
    return out


def _ot_linea_dano(d: dict) -> str:
    """Una linea de parte a partir de un apunte del libro.

    'Puerta corredera izq (puerta) — grave, visto el 2026-07-13'. Es lo que el
    taller necesita leer, y sale igual escriba quien escriba: un parte a mano
    depende del dia que tenga quien lo redacta.
    """
    trozos = [str(d.get("part") or d.get("panel") or "Daño sin describir").strip()]
    if d.get("panel") and d.get("part") and d["panel"] not in d["part"]:
        trozos[0] += " (%s)" % d["panel"]
    cola = []
    if d.get("severity"):
        cola.append(str(d["severity"]))
    if d.get("first_seen"):
        cola.append("visto el %s" % str(d["first_seen"])[:10])
    return trozos[0] + (" — " + ", ".join(cola) if cola else "")


def _ot_ahora() -> str:
    return datetime.now(timezone.utc).isoformat()


def _ot_apunte(quien: str, que: str, detalle: str = "") -> dict:
    """Una linea del historial. Es lo unico que no se puede editar nunca."""
    return {"cuando": _ot_ahora(), "quien": quien[:80], "que": que[:60],
            "detalle": (detalle or "")[:400]}


def _ot_fecha_valida(v) -> Optional[str]:
    """'YYYY-MM-DD' Y ADEMAS una fecha que pueda ser de verdad.

    El formato no basta. Un `<input type="date">` va emitiendo el valor a
    medio escribir mientras se teclea, asi que llegan cosas como
    '0002-02-02' — y eso es una fecha PERFECTAMENTE VALIDA para strptime
    (el ano 2 existe), asi que entraba tal cual y quedaba guardada. Paso en
    produccion el 25-08-2026: el historial de la OT-1002 tiene dos
    "Fecha de entrega: 0002-02-02".

    El rango es ancho a proposito —esta funcion valida tambien la fecha de
    ENTRADA, que puede ser de hace meses si se registra una orden antigua—:
    solo tiene que matar lo imposible, no acotar lo raro.
    """
    s = str(v or "").strip()[:10]
    if len(s) != 10:
        return None
    try:
        d = datetime.strptime(s, "%Y-%m-%d")
    except ValueError:
        return None
    hoy = datetime.now(timezone.utc).replace(tzinfo=None)
    if d.year < 2015 or d > hoy + timedelta(days=365 * 5):
        return None
    return s


def _ot_importe(v) -> Optional[float]:
    """Importe en euros. Coma o punto, y nunca negativo."""
    if v is None or str(v).strip() == "":
        return None
    try:
        n = float(str(v).replace(",", ".").replace(" ", ""))
    except ValueError:
        return None
    if n < 0 or n > 1_000_000:
        return None
    return round(n, 2)


async def _ot_numero() -> str:
    """Numero correlativo por empresa: OT-1001, OT-1002...

    Con `find_one_and_update` y upsert el contador es atomico: dos ordenes
    creadas a la vez NO pueden llevarse el mismo numero.
    """
    doc = await db.contadores.find_one_and_update(
        {"_id": "ordenes_trabajo"}, {"$inc": {"valor": 1}},
        upsert=True, return_document=ReturnDocument.AFTER)
    return "OT-%d" % (1000 + int((doc or {}).get("valor") or 1))


async def _ot_historial_vehiculo(orden: dict) -> list:
    """Por que ha pasado antes esta furgoneta. Para el TALLER.

    Ahorra el trabajo de diagnosticar dos veces lo mismo: si hace tres meses
    se cambiaron los discos, eso explica la mitad de los ruidos de hoy.

    NO se dice en que taller estuvo, a proposito. Es informacion comercial de
    la flota y a Midas no le incumbe que unas lunas las hiciera Carglass; lo
    util para reparar es QUE se hizo, no quien lo hizo.
    """
    filas = await db.ordenes_trabajo.find(
        {"vehicle_id": orden.get("vehicle_id"), "id": {"$ne": orden.get("id")},
         "estado": "entregado"},
        {"_id": 0, "fecha_entrada": 1, "fecha_entrega_real": 1,
         "problema": 1, "descripcion_trabajo": 1}
    ).sort("fecha_entrada", -1).to_list(5)
    return [{
        "fecha": f.get("fecha_entrega_real") or f.get("fecha_entrada"),
        "que": (f.get("descripcion_trabajo") or f.get("problema") or "")[:180],
    } for f in filas if (f.get("descripcion_trabajo") or f.get("problema"))]


async def _ot_publica(orden: dict) -> dict:
    """Lo que ve el TALLER. Lista blanca a proposito, no lista negra.

    Aqui no puede salir NADA de la persona que conduce: el enlace se reenvia
    por WhatsApp y acaba en telefonos que no controlamos. El taller necesita
    la matricula y el problema; el nombre del conductor no le hace falta para
    cambiar unos frenos.
    """
    return {
        "numero": orden.get("numero"),
        "matricula": orden.get("matricula"),
        "modelo": orden.get("modelo"),
        "taller": orden.get("taller_nombre"),
        "estado": orden.get("estado"),
        "estado_txt": OT_ESTADOS.get(orden.get("estado"), orden.get("estado")),
        "problema": orden.get("problema"),
        "descripcion_trabajo": orden.get("descripcion_trabajo"),
        "fecha_entrada": orden.get("fecha_entrada"),
        "fecha_entrega_estimada": orden.get("fecha_entrega_estimada"),
        "motivo_retraso": orden.get("motivo_retraso"),
        "entrega_la_dijo_taller": bool(orden.get("entrega_la_dijo_taller")),
        "motivos": [{"id": k, "txt": v} for k, v in OT_MOTIVOS.items()],
        "importe_estimado": orden.get("importe_estimado"),
        "importe_final": orden.get("importe_final"),
        "presupuesto": orden.get("presupuesto", "sin_presupuesto"),
        "fotos": orden.get("fotos") or [],
        # Cada golpe con SUS fotos. Doce fotos seguidas no dicen cual es cual.
        "partes": orden.get("partes") or [],
        "historial": orden.get("historial") or [],
        "estados_posibles": [{"id": e, "txt": OT_ESTADOS[e]} for e in OT_ESTADOS_TALLER],
        "cerrada": orden.get("estado") in ("entregado", "anulada"),
        # El paso en el que va, para pintarlo como un recorrido y no como una
        # etiqueta suelta: de un vistazo se ve cuanto queda.
        "paso": (list(OT_ESTADOS_TALLER).index(orden.get("estado")) + 1)
                if orden.get("estado") in OT_ESTADOS_TALLER else 0,
        "pasos": [{"id": e, "txt": OT_ESTADOS[e]} for e in OT_ESTADOS_TALLER],
        "ya_estuvo": await _ot_historial_vehiculo(orden),
    }


async def _ot_por_token(token: str) -> dict:
    """Resuelve el enlace publico y DEJA FIJADA la empresa correcta.

    Devuelve la orden. Lanza 404 si el enlace no vale: nunca se distingue
    'no existe' de 'revocado' de 'caducado', porque decirlo ayuda a quien
    este probando tokens a ciegas.
    """
    tok = (token or "").strip()
    if len(tok) < 20 or len(tok) > 120:
        raise HTTPException(404, "Este enlace no es válido")
    enlace = await global_db.taller_enlaces.find_one({"token": tok}, {"_id": 0})
    # `orden_id` NO es opcional: en esta coleccion conviven los enlaces de una
    # orden con los del taller (`tipo: taller`) y los de un apoyo en ruta
    # (`tipo: apoyo`), y sin esta comprobacion el `enlace["orden_id"]` de abajo
    # reventaba con KeyError -> 500 en un endpoint PUBLICO (gotcha 59). Sus dos
    # hermanos (`portal_taller_lista`, `_apoyo_por_token`) ya exigian el suyo.
    if not enlace or enlace.get("revocado") or not enlace.get("orden_id"):
        raise HTTPException(404, "Este enlace no es válido")
    if enlace.get("expira_en") and enlace["expira_en"] < _ot_ahora():
        raise HTTPException(404, "Este enlace ha caducado. Pídele uno nuevo a la oficina.")

    # LA LINEA QUE EVITA EL DESASTRE MULTIEMPRESA.
    set_current_org_db(enlace.get("db_name"))

    orden = await db.ordenes_trabajo.find_one({"id": enlace["orden_id"]}, {"_id": 0})
    if not orden:
        raise HTTPException(404, "Este enlace no es válido")
    return orden


def _ot_puede_escribir(orden: dict):
    """Una orden entregada o anulada es historia: no se toca mas."""
    if orden.get("estado") in ("entregado", "anulada"):
        raise HTTPException(409, "Esta orden ya está cerrada. Si hay algo más, "
                                 "avisa a la oficina y te abren una nueva.")


# Freno para los endpoints publicos. No hay login, asi que lo unico que
# separa un taller de un bot es esto. En memoria y por token: con una sola
# maquina basta, y si algun dia hay dos, lo peor que pasa es que el limite
# sea el doble de generoso — nunca que deje de existir.
_OT_GOLPES: dict = {}


def _ot_freno(token: str, limite: int = 40):
    ahora = datetime.now(timezone.utc).timestamp()
    golpes = [x for x in _OT_GOLPES.get(token, []) if ahora - x < 60]
    if len(golpes) >= limite:
        raise HTTPException(429, "Demasiadas peticiones seguidas. Espera un minuto.")
    golpes.append(ahora)
    _OT_GOLPES[token] = golpes
    if len(_OT_GOLPES) > 5000:            # que no crezca sin fin
        for k in [k for k, v in _OT_GOLPES.items() if not v or ahora - v[-1] > 300]:
            _OT_GOLPES.pop(k, None)


PREFIJO_WA_DEFECTO = os.environ.get("WHATSAPP_PREFIJO_PAIS", "34")


def enlace_wa(telefono: str, texto: str = "") -> str:
    """Un enlace `wa.me` que abre WhatsApp con el mensaje YA ESCRITO.

    POR QUE ESTO IMPORTA MAS DE LO QUE PARECE. La API de WhatsApp de Meta esta
    bloqueada: no llegan los codigos de verificacion a NINGUN numero, y sin eso
    no hay envio automatico. Pero `wa.me` es un enlace PUBLICO — no usa la API,
    no pide credenciales, no hay nada que verificar. Funciona hoy.

    Con esto, "reenviar el recordatorio a mano" pasa de copiar un texto, buscar
    el contacto y pegarlo, a pulsar un enlace y darle a enviar. La diferencia
    entre esas dos cosas es si se hace o no se hace un martes con cuarenta
    rutas fuera. Y el taller contesta al WhatsApp de siempre, que ya se lee.

    Los 46 talleres tienen telefono y NINGUNO correo (medido el 31-08-2026), asi
    que este es el unico canal que llega a todos sin depender de Meta.
    """
    d = "".join(c for c in str(telefono or "") if c.isdigit())
    if not d:
        return ""
    if d.startswith("00"):
        d = d[2:]
    elif len(d) == 9:
        # Sin prefijo, wa.me abre una conversacion con un numero que no existe.
        d = PREFIJO_WA_DEFECTO + d
    return "https://wa.me/%s%s" % (
        d, ("?text=" + _url_quote(texto[:1500])) if texto else "")


async def _ot_avisa(orden: dict, texto: str, enlace_directo: str = ""):
    """Avisa a la oficina por Telegram. Que falle no puede tumbar la peticion:
    el taller ya ha hecho su parte y perder su cambio seria mucho peor."""
    cuerpo = "%s · %s\n%s" % (orden.get("numero"), orden.get("matricula"), texto)
    if enlace_directo:
        cuerpo += "\n\n👉 Mandarlo por WhatsApp: %s" % enlace_directo
    try:
        await _telegram_aviso(cuerpo)
    except Exception as e:
        logger.warning("OT: no se pudo avisar por Telegram: %s", e)


# ── ADMIN ─────────────────────────────────────────────────────────────────

# ═══════════════════════════════════════════════════════════════════════════
# ATRIBUCION DE DANOS
# ═══════════════════════════════════════════════════════════════════════════
# QUE HACE. Para cada golpe del libro busca la ULTIMA foto en la que la
# furgoneta estaba limpia, y con eso acota cuando aparecio y quien la llevaba.
# Hoy nadie sabe quien rompe las furgonetas: se ve el golpe y ya.
#
# POR QUE AQUI SI SE PUEDE. Las herramientas del mercado piden cambiar el
# proceso —que el conductor siguiente firme al recoger— y solo sirven hacia
# delante. Aqui sale de datos que YA existen: 3.804 inspecciones con foto,
# hora y conductor. Se puede mirar hacia atras sin pedirle nada a nadie.
#
# ═══ ESTO SENALA A PERSONAS, ASI QUE LAS REGLAS SON DURAS ═══
# Un falso positivo aqui no es un numero mal contado: es acusar a alguien de
# romper una furgoneta que no rompio.
#
#  1. Solo se SENALA a una persona si la ventana es de un dia o menos Y hay
#     un unico conductor. Con dos dias hay dos turnos y dos personas.
#  2. Nunca se dice "lo hizo": se dice "la llevaba". La app sabe quien
#     conducia, no quien golpeo — pudo ser un tercero en un parking.
#  3. Sin foto limpia previa no se atribuye nada. Que un golpe aparezca en la
#     primera inspeccion no significa que se hiciera ese dia: pudo venir de
#     fabrica o de antes de que existiera la app.
#  4. Los danos LEVES quedan fuera del senalamiento. Un arañazo fino aparece
#     de un dia para otro por lavado, ramas o roce de aparcamiento, y no se
#     le cuelga a nadie.
#  5. Siempre viajan las DOS fotos. Sin la prueba delante esto no es un dato,
#     es una acusacion.

_ATR_LEVES = ("leve",)


def _atr_pieza(texto: str) -> str:
    """Nombre canonico de la pieza, o el texto tal cual si no se reconoce.

    Devolver el original cuando no casa es a proposito: una pieza sin canonico
    tiene que SEGUIR VIENDOSE, no desaparecer (gotcha 17, el cajon de sobras).
    """
    try:
        c = piezas.canon(texto or "")
    except Exception:                                            # noqa: BLE001
        return texto or ""
    return c[0][0] if c and c[0][0] else (texto or "")


def _atr_una_persona(ids: list, persona: dict) -> list:
    """Deja un id por PERSONA, no por ficha (gotcha 15).

    Conserva el orden y el primer id de cada persona, que es el que se usa
    para enlazar con su ficha.
    """
    fuera, vistas = [], set()
    for i in ids:
        k = persona.get(i) or i
        if k in vistas:
            continue
        vistas.add(k)
        fuera.append(i)
    return fuera


def _atr_certeza(dias: int, conductores: list, severidad: str) -> tuple:
    """(certeza, motivo). 'alta' es la unica que senala a una persona."""
    if severidad in _ATR_LEVES:
        return "baja", "daño leve: puede salir de un roce o del lavado"
    if dias is None or dias > 3:
        return "baja", "pasaron más de tres días sin foto"
    if len(conductores) != 1:
        return ("media", "%d personas la llevaron en esa ventana" % len(conductores)) \
            if conductores else ("baja", "no consta quién la llevaba")
    if dias <= 1:
        return "alta", None
    return "media", "ventana de %d días" % dias


@api_router.get("/damages/atribucion")
async def danos_atribucion(center: str = "", dias: int = 120, solo_alta: bool = False,
                           _=Depends(require_admin)):
    """Cada golpe con la ultima foto limpia, la ventana y quien la llevaba."""
    desde = (datetime.now(timezone.utc) - timedelta(days=max(7, min(dias, 400)))).strftime("%Y-%m-%d")
    # `archived` NO es un daño: es lo que quedó de una reconstrucción de flota
    # (`archived_reason: rebuild_fleet`). Eran 466 de 681 —el 68 % de la
    # pantalla— y salían mezclados con los vivos como si fueran golpes reales.
    # `repaired` sí se queda: se hizo, se arregló, y saber quién lo hizo es
    # justamente para lo que existe esta pantalla.
    q_dan: dict = {"first_seen": {"$gte": desde},
                   "status": {"$nin": ["archived", "descartada", "deleted"]}}
    # Sin tope: cortaba en 600 teniendo 681, y como ordena por fecha se comía
    # los más antiguos de la ventana en silencio (gotcha 10). Se pide uno más
    # que el máximo para poder DECIR que se cortó, en vez de callarlo.
    _TOPE = 3000
    danos = await db.vehicle_damage_ledger.find(q_dan).sort(
        "first_seen", -1).to_list(_TOPE + 1)
    truncado = len(danos) > _TOPE
    danos = danos[:_TOPE]
    if not danos:
        return {"danos": [], "resumen": {}, "total": 0}

    vids = list({d.get("vehicle_id") for d in danos if d.get("vehicle_id")})
    # Una furgoneta de baja o borrada no cuenta en nada (gotcha 13): sus golpes
    # no se le pueden reclamar a nadie y solo ensucian la lista. Eran 32.
    vs = {v["id"]: v async for v in db.vehicles.find(
        {"id": {"$in": vids}, "status": {"$nin": ["deleted", "baja"]}},
        {"_id": 0, "id": 1, "license_plate": 1, "center": 1, "status": 1})}

    # Todas las inspecciones de esas furgonetas, ordenadas por fecha.
    porveh: dict = {}
    async for i in db.inspections.find(
            {"vehicle_id": {"$in": vids}},
            {"_id": 0, "id": 1, "vehicle_id": 1, "created_at": 1, "driver_id": 1,
             "photos": 1, "annotated_photos": 1}):
        porveh.setdefault(i["vehicle_id"], []).append(i)
    for v in porveh:
        porveh[v].sort(key=lambda x: x.get("created_at") or "")

    nombres, persona = {}, {}
    async for dr in db.drivers.find({}, {"_id": 0, "id": 1, "name": 1, "email": 1}):
        nombres[dr["id"]] = dr.get("name")
        # Se empareja por CORREO, nunca por nombre: dos tocayos distintos
        # acabarían siendo la misma persona (gotcha 15).
        c = str(dr.get("email") or "").strip().lower()
        if c:
            persona[dr["id"]] = c

    def _foto(ins):
        anot = [f for f in (ins.get("annotated_photos") or []) if f]
        return (anot or [f for f in (ins.get("photos") or []) if f] or [None])[0]

    out, resumen = [], {"alta": 0, "media": 0, "baja": 0}
    for d in danos:
        vid = d.get("vehicle_id")
        v = vs.get(vid)
        if not v:
            continue                       # de baja, borrada o sin ficha
        if center and center not in ("Todos", "todos"):
            if not re.search(re.escape(center.strip()), str(v.get("center") or ""), re.I):
                continue
        fs = str(d.get("first_seen") or "")[:10]
        lista = porveh.get(vid) or []
        actual = next((i for i in lista if i.get("id") == d.get("first_seen_inspection")), None)
        # Comparar por DÍA descartaba la inspección limpia de esa misma mañana:
        # con `< fs`, una revisión a las 08:00 sin el golpe y otra a las 20:00
        # con él quedaban en el mismo día y la primera no contaba como previa.
        # La ventana se ensanchaba a la víspera, o se perdía entera. Pasaba en 5
        # casos. Contra el INSTANTE de la que vio el golpe sale exacto.
        if actual and actual.get("created_at"):
            previas = [i for i in lista
                       if (i.get("created_at") or "") < actual["created_at"]]
        else:
            previas = [i for i in lista if (i.get("created_at") or "")[:10] < fs]
        limpia = previas[-1] if previas else None

        ventana = None
        if limpia:
            try:
                ventana = (datetime.strptime(fs, "%Y-%m-%d")
                           - datetime.strptime((limpia.get("created_at") or "")[:10], "%Y-%m-%d")).days
            except Exception:                                # noqa: BLE001
                ventana = None

        # Quien la llevo ENTRE la foto limpia y la que ve el golpe. Sale de las
        # propias inspecciones: quien inspecciona una furgoneta es quien la
        # saca. Es mas fiable que el cuadrante, que es una intencion.
        desde_f = (limpia.get("created_at") or "")[:10] if limpia else fs
        cond_ids = []
        for i in lista:
            f = (i.get("created_at") or "")[:10]
            if desde_f <= f <= fs and i.get("driver_id"):
                if i["driver_id"] not in cond_ids:
                    cond_ids.append(i["driver_id"])
        # Hay 13 personas con dos fichas (gotcha 15). Contadas por separado
        # serían «dos personas la llevaron» y la certeza caería de alta a media
        # sin que haya pasado nada. Hoy no coincide ninguna en la misma ventana
        # —medido: 0 casos—, pero eso es suerte del reparto de este mes, no una
        # garantía, y el día que coincidan el fallo sería invisible.
        cond_ids = _atr_una_persona(cond_ids, persona)

        certeza, motivo = _atr_certeza(ventana, cond_ids, str(d.get("severity") or ""))
        if not limpia:
            certeza, motivo = "baja", "no hay ninguna foto anterior sin ese golpe"
        # Regla 5 de este módulo: «siempre viajan las DOS fotos; sin la prueba
        # delante esto no es un dato, es una acusación». Estaba escrita arriba y
        # no se comprobaba en ninguna parte.
        if certeza == "alta" and not ((_foto(limpia) if limpia else None)
                                      and (_foto(actual) if actual else None)):
            certeza, motivo = "media", "falta una de las dos fotos: no se señala a nadie"
        # El resumen cuenta SIEMPRE, aunque luego no se enseñe: con `solo_alta`
        # el contador decía «58 altas, 0 medias, 0 bajas» y parecía que no había
        # más que mirar.
        resumen[certeza] = resumen.get(certeza, 0) + 1
        if solo_alta and certeza != "alta":
            continue

        out.append({
            "ledger_id": str(d.get("_id")),
            "vehicle_id": vid,
            "matricula": v.get("license_plate") or vid,
            "center": v.get("center") or "",
            "part": d.get("part") or d.get("panel") or "",
            # La misma pieza está escrita de dos formas ('Paragolpes delantero'
            # 30 veces y 'paragolpes delantero' otras 26), así que agrupar o
            # contar por el texto crudo parte cada pieza en dos. `piezas.canon`
            # es el vocabulario que ya usa el resto del backend y tiene 37 casos
            # de prueba; aquí faltaba y por eso esta pantalla contaba distinto
            # que las demás.
            "pieza": _atr_pieza(d.get("part") or d.get("panel") or ""),
            "panel": d.get("panel") or "",
            "severity": d.get("severity") or "",
            "status": d.get("status") or "",
            "aparecio": fs,
            "ventana_dias": ventana,
            "certeza": certeza,
            "motivo": motivo,
            "conductores": [{"id": c, "nombre": nombres.get(c) or "?"} for c in cond_ids],
            # Las dos fotos, que son la prueba. Sin ellas esto no es un dato.
            "foto_limpia": _foto(limpia) if limpia else None,
            "foto_limpia_fecha": (limpia.get("created_at") or "")[:10] if limpia else None,
            "foto_golpe": _foto(actual) if actual else None,
        })

    return {"danos": out, "resumen": resumen, "total": len(out),
            "truncado": truncado}


# ── ¿DA LA FLOTA PARA EL TRABAJO DE MAÑANA? ────────────────────────────────────────
# La cadena del producto es VEHÍCULO -> TALLER -> DISPONIBILIDAD -> TRABAJO, y
# el eslabón que faltaba es el último. La app sabe qué vehículo está roto y
# sabe cuántos salen cada día, pero nadie junta las dos cosas — y esa unión es
# la pregunta que se hace cualquier jefe de flota por la mañana.
#
# Un inspector de vehículos dice "esta furgoneta tiene un golpe". Esto dice
# "el martes te faltan dos vehículos". No es la misma frase ni el mismo
# producto.
#
# Todo sale de datos que ya están: el estado de la flota, las órdenes de taller
# con su fecha de vuelta, la ITV, los daños graves y cuántos vehículos se han
# usado de verdad los últimos días. Nada de esto hay que teclearlo.

DISPO_DIAS_DEMANDA = 21      # cuantos dias atras se mira para saber el pico
DISPO_ITV_AVISO = 30         # dias de antelacion con los que preocupa una ITV
DISPO_MARGEN_MIN = 2         # por debajo de esto, un imprevisto deja un servicio sin vehículo


async def _dispo_demanda(centro: str) -> dict:
    """Cuántos vehículos se han usado cada día: pico, media y último día.

    Se mide de la ASIGNACIÓN DIARIA —qué vehículo salió con quién—, que es lo que
    la flota ha tenido que cubrir de verdad, y no de lo que se haya planificado:
    la pregunta es si con los operativos de hoy se aguanta un día como el peor de
    las últimas semanas.

    Se cuentan vehículos DISTINTOS por día: si hay dos documentos del mismo día
    y sede (dos turnos), la misma furgoneta en los dos cuenta una vez.
    """
    desde = (datetime.now(timezone.utc)
             - timedelta(days=DISPO_DIAS_DEMANDA)).strftime("%Y-%m-%d")
    q: dict = {"date": {"$gte": desde}}
    if centro:
        q["center"] = {"$regex": re.escape(centro), "$options": "i"}
    por_dia: dict = {}
    async for a in db.daily_assignments.find(q, {"_id": 0, "date": 1, "slots": 1}):
        usados = {sl.get("vehicle_id") for sl in (a.get("slots") or [])
                  if isinstance(sl, dict) and sl.get("vehicle_id")}
        if usados and a.get("date"):
            por_dia.setdefault(a["date"], set()).update(usados)
    dias = sorted(((d, len(v)) for d, v in por_dia.items()), reverse=True)
    if not dias:
        return {"pico": None, "media": None, "dias": 0}
    ns = [n for _, n in dias]
    return {"pico": max(ns), "media": round(sum(ns) / len(ns), 1), "dias": len(ns),
            "ultimo": {"dia": dias[0][0], "vehiculos": dias[0][1]},
            "serie": [{"dia": d, "vehiculos": n} for d, n in dias[:14]]}


@api_router.get("/fleet/disponibilidad")
async def fleet_disponibilidad(center: str = "", _=Depends(require_admin)):
    """Si la flota da para el trabajo, y qué la puede dejar corta."""
    centro = ""
    if center and center not in ("Todos", "todos"):
        centro = _centro_norm(center, await _centros_conocidos())
    qv: dict = {}
    if centro:
        qv["center"] = {"$regex": re.escape(centro), "$options": "i"}

    vs = await db.vehicles.find(
        {**qv, "status": {"$ne": "deleted"}},
        {"_id": 0, "id": 1, "license_plate": 1, "status": 1, "itv_date": 1,
         "taller_desde": 1}).to_list(1000)
    por_estado: dict = {}
    for v in vs:
        por_estado[v.get("status") or "sin estado"] = por_estado.get(v.get("status") or "sin estado", 0) + 1
    operativas = [v for v in vs if v.get("status") == "active"]
    ids_op = {v["id"] for v in operativas}

    demanda = await _dispo_demanda(centro)

    # ── Lo que puede dejarlas fuera ──────────────────────────────────────────
    hoy = datetime.now(timezone.utc).date()
    limite = (hoy + timedelta(days=DISPO_ITV_AVISO)).strftime("%Y-%m-%d")
    hoy_s = hoy.strftime("%Y-%m-%d")
    # DOS COSAS DISTINTAS, Y NO PUEDEN PESAR IGUAL EN PANTALLA.
    #
    #   clase "riesgo"      algo va mal AHORA: circulan con la ITV caducada,
    #                       con daños graves, o les caduca en menos de un mes.
    #   clase "falta_dato"  no sabemos si va mal, porque el dato no está: sin
    #                       fecha de ITV, sin fecha de vuelta del taller.
    #
    # Se arreglan de formas distintas —una se lleva al taller, la otra se
    # rellena en una ficha— y mezclarlas con el mismo aviso hace que 28 huecos
    # administrativos griten igual que 5 furgonetas circulando ilegalmente.
    # Con todo al mismo peso, el que mira acaba sin distinguir ninguna de las
    # dos: es exactamente lo que pasaba en la pantalla el 01-09-2026.
    riesgos = []

    itv_vencida = [v for v in operativas
                   if v.get("itv_date") and str(v["itv_date"])[:10] < hoy_s]
    if itv_vencida:
        riesgos.append({
            "tipo": "itv_vencida", "gravedad": "alta", "clase": "riesgo",
            "n": len(itv_vencida),
            "matriculas": [v.get("license_plate") for v in itv_vencida[:12]],
            "que_pasa": "Circulan con la ITV caducada",
            "cuesta": "200 € de multa, inmovilización en carretera, y la aseguradora "
                      "puede repetir lo que pague si hay un accidente",
            "cuando": "ya",
        })
    itv_pronto = [v for v in operativas
                  if v.get("itv_date") and hoy_s <= str(v["itv_date"])[:10] <= limite]
    if itv_pronto:
        riesgos.append({
            "tipo": "itv_pronto", "gravedad": "media", "clase": "riesgo",
            "n": len(itv_pronto),
            "matriculas": [v.get("license_plate") for v in itv_pronto[:12]],
            "que_pasa": "Les caduca la ITV en menos de %d días" % DISPO_ITV_AVISO,
            "cuesta": "Cada una es un día fuera si se pasa la cita",
            "cuando": "este mes",
        })
    sin_itv = [v for v in operativas if not v.get("itv_date")]
    if sin_itv:
        riesgos.append({
            "tipo": "itv_sin_dato", "gravedad": "media", "clase": "falta_dato",
            "n": len(sin_itv),
            "matriculas": [v.get("license_plate") for v in sin_itv[:12]],
            "que_pasa": "No consta cuándo les toca la ITV",
            # Esto no es un aviso de mantenimiento: es que NO SE PUEDE SABER si
            # hay riesgo. Un hueco no es una tranquilidad.
            "cuesta": "De estas no se puede decir si están en regla",
            "cuando": "—",
        })

    # Daños graves en furgonetas que están CIRCULANDO. No sacan la furgoneta
    # hoy, pero son las candidatas a entrar en taller: es la cola del taller.
    graves_ids = set()
    cur = db.vehicle_damage_ledger.aggregate([
        {"$match": {"status": "open", "severity": {"$in": ["grave", "critico"]},
                    "vehicle_id": {"$in": list(ids_op)}}},
        {"$group": {"_id": "$vehicle_id", "n": {"$sum": 1}}}])
    graves = {}
    async for r in cur:
        graves[r["_id"]] = r["n"]
        graves_ids.add(r["_id"])
    if graves:
        pl = {v["id"]: v.get("license_plate") for v in operativas}
        riesgos.append({
            "tipo": "danos_graves_circulando", "gravedad": "alta", "clase": "riesgo",
            "n": len(graves),
            "matriculas": [pl.get(i) for i in list(graves)[:12]],
            "que_pasa": "Circulan con %d daños graves o críticos sin reparar"
                        % sum(graves.values()),
            "cuesta": "Son las que van a entrar en taller: la cola que viene",
            "cuando": "próximas semanas",
        })

    # ── Las que están dentro: ¿cuándo vuelven? ───────────────────────────────
    en_taller = [v for v in vs if v.get("status") == "taller"]
    ordenes = {}
    async for o in db.ordenes_trabajo.find(
            {"estado": {"$nin": list(OT_ESTADOS_CERRADOS)}},
            {"_id": 0, "vehicle_id": 1, "numero": 1, "fecha_entrega_estimada": 1,
             "taller_nombre": 1}):
        ordenes.setdefault(o.get("vehicle_id"), o)
    vuelven, sin_fecha = [], []
    for v in en_taller:
        o = ordenes.get(v["id"])
        f = (o or {}).get("fecha_entrega_estimada")
        if f:
            vuelven.append({"matricula": v.get("license_plate"), "fecha": str(f)[:10],
                            "orden": o.get("numero"), "taller": o.get("taller_nombre")})
        else:
            dias = None
            if v.get("taller_desde"):
                try:
                    dias = (datetime.now(timezone.utc) - datetime.fromisoformat(
                        str(v["taller_desde"]).replace("Z", "+00:00"))).days
                except Exception:                            # noqa: BLE001
                    pass
            sin_fecha.append({"matricula": v.get("license_plate"), "dias": dias})
    vuelven.sort(key=lambda x: x["fecha"])
    if sin_fecha:
        riesgos.append({
            "tipo": "taller_sin_fecha_vuelta", "gravedad": "media", "clase": "falta_dato",
            "n": len(sin_fecha),
            "matriculas": [x["matricula"] for x in sin_fecha[:12]],
            "que_pasa": "Están en el taller y no consta cuándo vuelven",
            # Este es el que impide planificar de verdad: sin fecha de vuelta,
            # la unica prevision posible es "las de hoy", que es no prever nada.
            "cuesta": "Sin fecha de vuelta no se puede prever la flota de la semana",
            "cuando": "—",
        })

    # ── El margen ────────────────────────────────────────────────────────────
    n_op = len(operativas)
    pico = demanda.get("pico")
    margen_pico = (n_op - pico) if pico is not None else None
    # Peor caso realista: el día de más uso Y las de ITV vencida fuera. No se
    # suman los daños graves porque esos siguen circulando: contarlos como bajas
    # daria un numero alarmista que nadie se creeria a la segunda vez.
    n_riesgo = len(itv_vencida)
    margen_ajustado = (n_op - n_riesgo - pico) if pico is not None else None

    return {
        "center": centro or "todos",
        "flota": {"operativas": n_op, "por_estado": por_estado,
                  "total": len(vs), "en_taller": len(en_taller)},
        "demanda": demanda,
        "margen": {
            "en_el_pico": margen_pico,
            "ajustado": margen_ajustado,
            "suficiente": (margen_ajustado is not None and margen_ajustado >= DISPO_MARGEN_MIN),
            "minimo": DISPO_MARGEN_MIN,
            "explica": ("%d operativos contra un pico de %d vehículos en uso en los últimos %d días"
                        % (n_op, pico, demanda.get("dias") or 0)) if pico is not None
                       else "Todavía no hay asignaciones para saber cuántos se usan",
        },
        "riesgos": sorted(riesgos, key=lambda r: 0 if r["gravedad"] == "alta" else 1),
        "vuelven": vuelven,
        "sin_fecha_vuelta": len(sin_fecha),
    }


@api_router.get("/work-orders/danos-pendientes")
async def ot_danos_pendientes(center: str = "", solo_graves: bool = False,
                              _=Depends(require_admin)):
    """Daños abiertos que todavia no han ido al taller, los peores primero.

    Sale de `vehicle_damage_ledger`, que es el libro donde se acumula lo que
    ven las inspecciones y las personas. Se excluyen los que ya tienen orden:
    la lista existe para actuar, y una lista con cosas ya hechas deja de
    mirarse a los tres dias.
    """
    q = {"status": "open", "orden_id": {"$in": [None, ""]}}
    if solo_graves:
        q["severity"] = {"$in": ["grave", "critico"]}
    danos = await db.vehicle_damage_ledger.find(q).sort("updated_at", -1).to_list(400)
    if not danos:
        return {"danos": [], "total": 0, "graves": 0}

    ids = {d.get("vehicle_id") for d in danos if d.get("vehicle_id")}
    vs = {v["id"]: v async for v in db.vehicles.find(
        {"id": {"$in": list(ids)}},
        {"_id": 0, "id": 1, "license_plate": 1, "model": 1, "center": 1, "status": 1})}

    # El orden importa: primero lo que puede dejar una furgoneta parada.
    peso = {"critico": 0, "grave": 1, "moderado": 2, "leve": 3}
    out = []
    for d in danos:
        v = vs.get(d.get("vehicle_id")) or {}
        if center and center not in ("Todos", "todos"):
            if not re.search(re.escape(center.strip()), str(v.get("center") or ""), re.I):
                continue
        # Una furgoneta de baja no se manda al taller.
        if (v.get("status") or "") in ("baja", "deleted"):
            continue
        out.append({
            "ledger_id": str(d.get("_id")),
            "vehicle_id": d.get("vehicle_id"),
            "matricula": v.get("license_plate") or "?",
            "modelo": v.get("model"),
            "center": (v.get("center") or "").strip(),
            "pieza": d.get("part"),
            "panel": d.get("panel"),
            "severidad": d.get("severity"),
            "origen": d.get("source"),
            "visto": d.get("first_seen"),
            "dias": _ot_dias_desde(d.get("first_seen")),
        })
    out.sort(key=lambda x: (peso.get(x["severidad"], 9), -(x["dias"] or 0)))

    # ── AGRUPADO POR FURGONETA ───────────────────────────────────────────────
    # UN DAÑO NO ES UN PARTE; UNA FURGONETA SI. Va al taller una vez y le
    # arreglan todo lo que lleva encima, no cinco viajes para cinco golpes.
    # La lista suelta tenia 170 lineas y por eso no la vaciaba nadie; agrupada
    # son 83 furgonetas, y solo 30 llevan algo grave. Eso ya se puede terminar.
    #
    # Ademas evita el fallo caro: crear cinco ordenes de la misma matricula y
    # mandarla cinco veces, o peor, arreglar el golpe leve y devolverla con el
    # grave todavia puesto.
    grupos: dict = {}
    for d in out:
        g = grupos.setdefault(d["vehicle_id"], {
            "vehicle_id": d["vehicle_id"], "matricula": d["matricula"],
            "modelo": d["modelo"], "center": d["center"], "danos": [],
        })
        g["danos"].append(d)
    for g in grupos.values():
        sevs = [x["severidad"] for x in g["danos"]]
        g["n"] = len(g["danos"])
        g["peor"] = min(sevs, key=lambda x: peso.get(x, 9)) if sevs else None
        g["graves"] = sum(1 for x in sevs if x in ("grave", "critico"))
        g["dias"] = max((x["dias"] or 0) for x in g["danos"])
        # El texto que va al taller, ya redactado: es lo que hace que crear el
        # parte sea un clic y no un rato escribiendo.
        g["problema"] = " · ".join(
            "%s (%s)" % (x["pieza"] or "sin describir", x["severidad"] or "?")
            for x in g["danos"][:8])
        # De donde sale cada cosa, para que quien decide sepa cuanto fiarse.
        g["confirmados"] = sum(1 for x in g["danos"] if x["origen"] == "human")
    lista_g = sorted(grupos.values(),
                     key=lambda x: (peso.get(x["peor"], 9), -x["graves"], -x["dias"]))

    return {"danos": out, "total": len(out),
            "graves": sum(1 for x in out if x["severidad"] in ("grave", "critico")),
            "por_furgoneta": lista_g,
            "furgonetas": len(lista_g),
            "furgonetas_graves": sum(1 for g in lista_g if g["graves"] > 0)}


def _ot_dias_desde(f) -> int:
    """Dias desde una fecha 'YYYY-MM-DD'. 0 si no se puede leer.

    Un daño que lleva 40 dias abierto no es el mismo problema que uno de ayer,
    y en la lista tiene que notarse.
    """
    try:
        d = datetime.strptime(str(f)[:10], "%Y-%m-%d")
        return max(0, (datetime.now(timezone.utc).replace(tzinfo=None) - d).days)
    except Exception:
        return 0


@api_router.get("/work-orders/parte/{vehicle_id}")
async def ot_parte_furgoneta(vehicle_id: str, _=Depends(require_admin)):
    """Todo lo que le pasa a UNA furgoneta, con las fotos, listo para el taller.

    Es el paso previo a crear la orden. La lista de daños pendientes
    (`/work-orders/danos-pendientes`) mira la flota entera para decidir A QUIEN
    mandar; esto mira una sola furgoneta para decidir QUE mandar, que es la
    otra mitad y no existia.

    UNA ORDEN CON TODO, NO UNA POR GOLPE. Hoy solo se podia crear una orden
    por cada apunte del libro. Con 213 daños abiertos repartidos en 123
    furgonetas, eso son varias ordenes de la misma matricula al mismo taller
    la misma semana — que nadie manda, y por eso el modulo esta sin usar. El
    taller quiere una entrada y una salida.
    """
    v = await db.vehicles.find_one(
        {"id": vehicle_id},
        {"_id": 0, "id": 1, "license_plate": 1, "model": 1, "center": 1, "status": 1})
    if not v:
        raise HTTPException(404, "Esa furgoneta no existe")

    danos = await db.vehicle_damage_ledger.find(
        {"vehicle_id": vehicle_id, "status": "open",
         "orden_id": {"$in": [None, ""]}}).to_list(200)
    fotos = await _ot_fotos_del_dano(danos)

    peso = {"critico": 0, "grave": 1, "moderado": 2, "leve": 3}
    danos.sort(key=lambda d: (peso.get(str(d.get("severity") or ""), 9),
                              str(d.get("first_seen") or "")))
    items = []
    for d in danos:
        lid = str(d.get("_id"))
        f = fotos.get(lid) or {}
        items.append({
            "ledger_id": lid,
            "panel": d.get("panel") or "",
            "part": d.get("part") or "",
            "severity": d.get("severity") or "",
            "first_seen": str(d.get("first_seen") or "")[:10],
            "linea": _ot_linea_dano(d),
            "fotos": f.get("fotos") or [],
            "anotadas": bool(f.get("anotadas")),
        })

    # Las incidencias abiertas de esta furgoneta van aparte: no son golpes de
    # chapa, son averias (frenos, ruidos, luces) y el taller las trata en otro
    # sitio del parte. Mezclarlas en la misma lista hacia que se perdieran.
    incs = await db.incidents.find(
        {"vehicle_id": vehicle_id, "status": {"$ne": "resolved"}},
        {"_id": 0, "id": 1, "title": 1, "description": 1, "severity": 1,
         "photos": 1, "created_at": 1}).sort("created_at", -1).to_list(30)

    return {
        "vehiculo": v,
        "danos": items,
        "incidencias": [{
            "id": i.get("id"),
            "titulo": (i.get("title") or i.get("description") or "").strip()[:200],
            "severity": i.get("severity") or "",
            "fotos": [f for f in (i.get("photos") or []) if f][:4],
            "fecha": (i.get("created_at") or "")[:10],
        } for i in incs],
        "total_danos": len(items),
        "graves": sum(1 for i in items if i["severity"] in ("grave", "critico")),
    }


@api_router.get("/work-orders/paradas")
async def ot_furgonetas_paradas(center: str = "", _=Depends(require_admin)):
    """Las furgonetas que no estan trabajando, con el reloj corriendo.

    Es la pantalla que faltaba. `status: "taller"` era una etiqueta sin fecha:
    nadie sabia desde cuando ni quien llamo por ultima vez. Medido el
    28-08-2026: 14 paradas, tres desde hacia 52 dias, 319 dias-furgoneta
    acumulados y ni un sitio donde se viera.

    Para las que ya estaban dentro antes de existir `taller_desde` se usa
    `updated_at` como aproximacion y se marca `fecha_estimada: true`, para que
    la pantalla pueda decir "desde el 7 de julio (aprox.)" en vez de inventarse
    una precision que no tiene.
    """
    q = {"status": "taller"}
    vs = await db.vehicles.find(q, {"_id": 0}).to_list(500)
    ordenes = {}
    async for o in db.ordenes_trabajo.find(
            {"estado": {"$nin": list(OT_ESTADOS_CERRADOS)}},
            {"_id": 0, "vehicle_id": 1, "numero": 1, "taller_nombre": 1,
             "fecha_entrega_estimada": 1, "estado": 1}):
        ordenes.setdefault(o.get("vehicle_id"), o)

    out = []
    for v in vs:
        if center and center not in ("Todos", "todos"):
            if not re.search(re.escape(center.strip()), str(v.get("center") or ""), re.I):
                continue
        desde = v.get("taller_desde")
        estimada = False
        if not desde:
            desde = v.get("updated_at") or v.get("created_at")
            estimada = True
        o = ordenes.get(v.get("id")) or {}
        out.append({
            "vehicle_id": v.get("id"),
            "matricula": v.get("license_plate") or "?",
            "modelo": v.get("model") or "",
            "center": (v.get("center") or "").strip(),
            "desde": str(desde)[:10] if desde else None,
            "fecha_estimada": estimada,
            "dias": _ot_dias_desde(desde) if desde else None,
            # Si no hay orden abierta, la furgoneta esta parada y ademas NADIE
            # la esta gestionando. Eso es peor que llevar 50 dias con parte.
            "orden": o.get("numero"),
            "taller": o.get("taller_nombre"),
            "entrega_estimada": o.get("fecha_entrega_estimada"),
        })
    out.sort(key=lambda x: -(x["dias"] or 0))
    return {
        "paradas": out,
        "total": len(out),
        "dias_acumulados": sum(x["dias"] or 0 for x in out),
        "sin_orden": sum(1 for x in out if not x["orden"]),
        "mas_de_30": sum(1 for x in out if (x["dias"] or 0) > 30),
    }


@api_router.get("/work-orders/preparar/{vehicle_id}")
async def ot_preparar(vehicle_id: str, _=Depends(require_admin)):
    """Una orden de taller ya redactada, lista para revisar y mandar.

    POR QUE. El modulo de ordenes existe entero y no se usa: 13 furgonetas
    paradas —algunas desde hace mas de dos meses— y CERO ordenes vivas, con 39
    danos graves o criticos abiertos sin ninguna. Al mirar por que, no falta
    ninguna funcionalidad: falta que crear una orden sea barato. Hoy hay que
    elegir taller de entre 46, escribir el problema y acordarse de marcar los
    danos que van dentro.

    Todo eso ya esta en la base. Esto lo junta y devuelve el borrador; la
    persona revisa y confirma. No crea nada: preparar y decidir son cosas
    distintas, y una orden creada sola acabaria mandando furgonetas a talleres
    que nadie eligio.
    """
    v = await db.vehicles.find_one(
        {"id": vehicle_id, "status": {"$nin": ["deleted", "baja"]}}, {"_id": 0})
    if not v:
        raise HTTPException(404, "Esa furgoneta no está o está de baja")

    # ── Lo que tiene roto ────────────────────────────────────────────────────
    danos = await db.vehicle_damage_ledger.find(
        {"vehicle_id": vehicle_id, "status": "open",
         "orden_id": {"$in": [None, ""]}}).sort("rank", -1).to_list(60)
    fotos = await _ot_fotos_del_dano(danos)

    # ── Con que taller ───────────────────────────────────────────────────────
    # Del mismo centro, y de esos primero los que se puede AVISAR: un taller sin
    # telefono ni correo obliga a salir de la app, que es justo lo que sobra.
    centro = str(v.get("center") or "")
    q_w: dict = {}
    if centro:
        cod = _centro_norm(centro, await _centros_conocidos())
        # Los del centro Y los que no tienen ninguno. El propio panel da de
        # alta un taller SIN centro cuando el selector esta en "Todos", y esos
        # sirven para toda la empresa: dejarlos fuera hace que quien tenga sus
        # talleres asi no vea ninguno al preparar un parte, sin explicacion.
        q_w["$or"] = [{"center": {"$regex": re.escape(cod), "$options": "i"}},
                      {"center": {"$in": [None, ""]}},
                      {"center": {"$exists": False}}]
    talleres = await db.workshops.find(
        q_w, {"_id": 0, "id": 1, "name": 1, "phone": 1, "email": 1, "center": 1,
              "especialidad": 1}).to_list(100)

    # Cuantas ordenes lleva cada uno y como le fue. Con dos ordenes en total
    # esto no ordena nada todavia, pero es el sitio donde entrara el historial
    # en cuanto lo haya, y asi no hay que rehacer la pantalla.
    hechas: dict = {}
    cur = db.ordenes_trabajo.aggregate([
        {"$match": {"estado": {"$nin": ["anulada"]}}},
        {"$group": {"_id": "$taller_id", "n": {"$sum": 1}}}])
    async for r in cur:
        hechas[r["_id"]] = r["n"]

    def _puntua(w):
        return (1 if (w.get("phone") or w.get("email")) else 0,
                hechas.get(w.get("id"), 0))
    # Desempate por nombre: sin el, cual sale primero lo decide Mongo (gotcha 62).
    # `reverse=True` con un desempate por nombre lo ordenaria de la Z a la A:
    # se niegan los numeros y el nombre sube normal.
    talleres.sort(key=lambda w: (tuple(-x for x in _puntua(w)), str(w.get('name') or '')))

    # ── El problema, escrito ─────────────────────────────────────────────────
    # Redactado a partir del libro, que es lo que el taller necesita saber. Si
    # no hay danos apuntados NO se inventa un texto: se dice que hay que
    # escribirlo, porque una orden que llega al taller diciendo "revision
    # general" obliga a la llamada que esto venia a quitar.
    if danos:
        por_grav: dict = {}
        for d in danos:
            por_grav.setdefault(d.get("severity") or "sin gravedad", []).append(
                d.get("part") or d.get("panel") or "pieza sin nombre")
        trozos = []
        for sev in ("critico", "grave", "moderado", "leve", "sin gravedad"):
            if sev in por_grav:
                trozos.append("%s: %s" % (sev, ", ".join(sorted(set(por_grav[sev])))))
        problema = "; ".join(trozos)
    else:
        problema = ""

    dias_parada = None
    if v.get("taller_desde"):
        try:
            dias_parada = (datetime.now(timezone.utc) - datetime.fromisoformat(
                str(v["taller_desde"]).replace("Z", "+00:00"))).days
        except Exception:                                        # noqa: BLE001
            dias_parada = None

    return {
        "vehicle_id": vehicle_id,
        "matricula": v.get("license_plate") or vehicle_id,
        "center": centro,
        "en_taller": v.get("status") == "taller",
        "dias_parada": dias_parada,
        "problema": problema,
        "falta_problema": not problema,
        "ledger_ids": [str(d.get("_id")) for d in danos],
        "danos": [{
            "ledger_id": str(d.get("_id")),
            "part": d.get("part") or d.get("panel") or "",
            "pieza": _atr_pieza(d.get("part") or d.get("panel") or ""),
            "severity": d.get("severity") or "",
            "first_seen": d.get("first_seen"),
            "foto": (fotos.get(str(d.get("_id"))) or {}).get("url"),
        } for d in danos],
        "talleres": [{
            "id": w.get("id"), "name": w.get("name"), "center": w.get("center"),
            "phone": w.get("phone"), "email": w.get("email"),
            "contactable": bool(w.get("phone") or w.get("email")),
            "ordenes_previas": hechas.get(w.get("id"), 0),
        } for w in talleres[:15]],
        "sugerido": (talleres[0].get("id") if talleres else None),
        "fecha_entrada": (str(v.get("taller_desde") or "")[:10]
                          or datetime.now(timezone.utc).strftime("%Y-%m-%d")),
    }


@api_router.post("/work-orders")
async def crear_orden(data: OrdenTrabajoCrear, user: dict = Depends(require_admin)):
    v = await db.vehicles.find_one({"id": data.vehicle_id},
                                   {"_id": 0, "license_plate": 1, "model": 1, "center": 1})
    if not v:
        raise HTTPException(404, "Esa furgoneta no existe")
    w = await db.workshops.find_one({"id": data.workshop_id}, {"_id": 0, "name": 1, "phone": 1})
    if not w:
        raise HTTPException(404, "Ese taller no existe")

    quien = user.get("name") or user.get("username") or "oficina"

    # DESDE UNA INCIDENCIA YA ABIERTA.
    # En produccion hay decenas de incidencias con sus fotos del dano. Volver a
    # escribir lo mismo para el taller es trabajo tirado, y mandar la furgoneta
    # sin las fotos obliga al taller a buscar el golpe. Se arrastran las dos
    # cosas; el problema escrito a mano, si lo hay, manda sobre el de la
    # incidencia (quien crea la orden sabe mejor que le pasa hoy).
    fotos_previas: list = []
    partes: list = []
    problema = (data.problema or "").strip()

    # DESDE UN DAÑO DEL LIBRO.
    # Si quien crea la orden no escribio nada, se redacta solo con la pieza y
    # la gravedad: 'Paragolpes trasero — grave (visto el 2026-08-12)'. Es
    # exactamente lo que el taller necesita leer, y evita que la orden salga
    # con el problema en blanco por pereza.
    # VARIOS DAÑOS EN UNA ORDEN, CON SUS FOTOS.
    # El parte se redacta solo a partir del libro y se le enganchan las fotos
    # anotadas de la inspeccion donde se vio cada golpe. Es la diferencia entre
    # que el taller sepa donde mirar y que tenga que dar vueltas al vehiculo.
    lids = [str(x) for x in (data.ledger_ids or []) if str(x).strip()]
    if data.ledger_id and data.ledger_id not in lids:
        lids.append(str(data.ledger_id))
    if lids:
        from bson import ObjectId as _OId
        oids, planos = [], []
        for x in lids:
            try:
                oids.append(_OId(x))
            except Exception:
                planos.append(x)
        cond = [c for c in ({"_id": {"$in": oids}} if oids else None,
                            {"_id": {"$in": planos}} if planos else None) if c]
        multi = await db.vehicle_damage_ledger.find(
            cond[0] if len(cond) == 1 else {"$or": cond}).to_list(200)
        # Solo los de ESTA furgoneta. Un id de otra matricula colado en la
        # lista mandaria al taller el golpe de un vehiculo que no ha ido.
        multi = [d for d in multi if d.get("vehicle_id") == data.vehicle_id]
        if multi:
            peso = {"critico": 0, "grave": 1, "moderado": 2, "leve": 3}
            multi.sort(key=lambda d: peso.get(str(d.get("severity") or ""), 9))
            fotos_map = await _ot_fotos_del_dano(multi)
            lineas = ["- " + _ot_linea_dano(d) for d in multi]
            if not problema:
                problema = "Reparar:\n" + "\n".join(lineas)
            # EL PARTE VA AGRUPADO, no como un monton de fotos sueltas. Doce
            # fotos seguidas debajo de un texto no le dicen al taller cual es
            # cual; con cada golpe llevando las suyas, sabe donde mirar sin
            # preguntar. Esto es lo que se le enseña en el portal.
            for d in multi:
                f = (fotos_map.get(str(d.get("_id"))) or {}).get("fotos") or []
                partes.append({
                    "linea": _ot_linea_dano(d),
                    "panel": d.get("panel") or "",
                    "severity": d.get("severity") or "",
                    "fotos": f[:4],
                })
                for x in f:
                    if x not in fotos_previas:
                        fotos_previas.append(x)
            fotos_previas = fotos_previas[:24]
            lids = [str(d.get("_id")) for d in multi]
        else:
            lids = []

    dano_doc = None
    if data.ledger_id and not lids:
        try:
            from bson import ObjectId as _OId
            dano_doc = await db.vehicle_damage_ledger.find_one(
                {"_id": _OId(data.ledger_id)})
        except Exception:
            dano_doc = await db.vehicle_damage_ledger.find_one({"_id": data.ledger_id})
        if dano_doc and not problema:
            trozos = [str(dano_doc.get("part") or "").strip() or "Daño sin describir"]
            if dano_doc.get("severity"):
                trozos.append(str(dano_doc["severity"]))
            if dano_doc.get("first_seen"):
                trozos.append(f"visto el {str(dano_doc['first_seen'])[:10]}")
            problema = " — ".join(trozos[:2])
            if len(trozos) > 2:
                problema += f" ({trozos[2]})"

    if data.incident_id:
        inc = await db.incidents.find_one({"id": data.incident_id},
                                          {"_id": 0, "description": 1, "title": 1, "photos": 1})
        if inc:
            fotos_previas = list(inc.get("photos") or [])[:12]
            if not problema:
                problema = (inc.get("description") or inc.get("title") or "").strip()

    # SIN DECIR QUE LE PASA NO SALE.
    #
    # Arriba se redacta el problema solo a partir de los daños del libro o de
    # la incidencia. Cuando no hay ninguna de las dos cosas —y una empresa
    # recien dada de alta no tiene ninguna el primer dia— la orden salia con
    # el problema en BLANCO: el taller recibe el enlace por WhatsApp, abre, ve
    # la matricula y no ve que arreglar. Acaba llamando, que es justo lo que
    # este flujo existe para evitar.
    #
    # La pantalla ya avisaba, pero solo con un mensaje que no impedia guardar,
    # y el aviso ni siquiera aparece al abrir una orden desde cero. La regla
    # tiene que estar aqui, que es por donde pasan las dos formas de crearla.
    if not problema:
        raise HTTPException(
            400, "Escribe qué le pasa a la furgoneta: el taller solo ve lo que le "
                 "pongas aquí. Si el golpe ya está apuntado en el libro de daños, "
                 "márcalo y el texto se redacta solo.")

    # DOS CLICS, UNA ORDEN. Cinco peticiones iguales a la vez abrian cinco
    # ordenes para la misma furgoneta en el mismo taller (02-09-2026), y el
    # boton "abrir parte en un clic" se puede pulsar dos veces. Si ya hay una
    # abierta de esta furgoneta en este taller creada hace menos de dos
    # minutos, es la misma orden: se devuelve en vez de crear otra. Dos
    # ordenes distintas de verdad (otro taller, o mas tarde) siguen pudiendo.
    # Y tiene que ser ATOMICO: un `find_one` antes de insertar no vale, porque
    # dos peticiones a la vez miran las dos antes de que ninguna escriba
    # (medido: seguian saliendo 2). El cerrojo es un documento por `_id` en
    # `app_meta`, como `_ya_enviado_hoy` (gotcha 32): el upsert solo pasa si
    # no hay cerrojo o es viejo; si lo hay, Mongo lanza DuplicateKeyError y
    # esa es la señal de que la otra peticion va por delante.
    ahora = datetime.now(timezone.utc)
    hace_poco = (ahora - timedelta(minutes=2)).isoformat()
    cerrojo = "ot_cerrojo|%s|%s" % (data.vehicle_id, data.workshop_id)
    try:
        await db.app_meta.update_one({"_id": cerrojo, "at": {"$lt": hace_poco}},
                                     {"$set": {"at": ahora.isoformat()}}, upsert=True)
    except DuplicateKeyError:
        # La otra peticion puede no haber insertado todavia: se le da un
        # segundo. Si despues sigue sin haber orden abierta reciente, no era un
        # doble clic (por ejemplo: abrir, anular y volver a abrir en dos
        # minutos, que es legitimo) y se sigue adelante.
        repetida = None
        for _ in range(4):
            repetida = await db.ordenes_trabajo.find_one(
                {"vehicle_id": data.vehicle_id, "workshop_id": data.workshop_id,
                 "estado": {"$nin": list(OT_ESTADOS_CERRADOS)}, "creada_en": {"$gte": hace_poco}},
                {"_id": 0})
            if repetida:
                return repetida
            await asyncio.sleep(0.25)
        await db.app_meta.update_one({"_id": cerrojo}, {"$set": {"at": ahora.isoformat()}}, upsert=True)

    orden = {
        "id": str(uuid.uuid4()),
        "numero": await _ot_numero(),
        "vehicle_id": data.vehicle_id,
        "matricula": v.get("license_plate") or data.vehicle_id,
        "modelo": v.get("model") or "",
        "center": v.get("center") or "",
        "workshop_id": data.workshop_id,
        "taller_nombre": w.get("name") or "",
        "taller_telefono": w.get("phone") or "",
        "incident_id": data.incident_id or None,
        "estado": "abierta",
        "problema": problema[:2000],
        "descripcion_trabajo": "",
        "fecha_entrada": _ot_fecha_valida(data.fecha_entrada) or _ot_ahora()[:10],
        "fecha_entrega_estimada": _ot_fecha_valida(data.fecha_entrega_estimada),
        "fecha_entrega_real": None,
        "importe_estimado": None,
        "importe_final": None,
        "presupuesto": "sin_presupuesto",
        "presupuesto_por": None,
        "presupuesto_en": None,
        "fotos": fotos_previas,
        "partes": partes,
        "historial": [_ot_apunte(quien, "Orden creada", w.get("name") or "")]
                     + ([_ot_apunte(quien, "%d fotos del parte" % len(fotos_previas))]
                        if fotos_previas else []),
        "creada_por": quien,
        "creada_en": _ot_ahora(),
        "actualizada_en": _ot_ahora(),
    }
    # LA FURGONETA SE PONE EN TALLER SOLA.
    # Sin esto habia dos verdades a la vez: una orden abierta y la furgoneta
    # marcada como activa en la flota, asi que podia salir asignada a alguien
    # una manana estando en un taller. Se guarda el estado anterior para poder
    # devolverla a el —y no a un "activo" inventado— cuando se entregue.
    previo = await db.vehicles.find_one({"id": data.vehicle_id}, {"_id": 0, "status": 1})
    orden["vehiculo_estado_previo"] = (previo or {}).get("status") or "activo"
    if orden["vehiculo_estado_previo"] != "taller":
        await db.vehicles.update_one({"id": data.vehicle_id}, {"$set": {"status": "taller"}})
        # La misma funcion que usa la pagina de Vehiculos: asi la incidencia se
        # abre igual venga de donde venga y no hay dos caminos que mantener.
        await _auto_incident_on_workshop(data.vehicle_id,
                                         orden["vehiculo_estado_previo"], "taller")

    await db.ordenes_trabajo.insert_one(dict(orden))
    orden.pop("_id", None)
    # El daño queda marcado DESPUES de guardar la orden, no antes: si el
    # insert fallara, un daño marcado como "en taller" sin orden que lo
    # respalde desapareceria de la lista de pendientes y no lo veria nadie.
    for _lid in (lids or ([data.ledger_id] if data.ledger_id else [])):
        await _ot_marcar_dano(_lid, orden["id"], orden.get("numero"))
    # Se guarda de QUE daños sale la orden para poder cerrarlos al entregarla.
    # Sin esta lista habria que adivinarlo por matricula y fecha, y un daño
    # que se queda abierto despues de repararse ensucia el libro para siempre.
    if lids:
        await db.ordenes_trabajo.update_one({"id": orden["id"]},
                                            {"$set": {"ledger_ids": lids}})
        orden["ledger_ids"] = lids
    logger.info("OT creada %s (%s -> %s, %d daños)", orden["numero"], orden["matricula"],
                orden["taller_nombre"], len(lids))
    return orden


@api_router.get("/work-orders")
async def listar_ordenes(center: Optional[str] = None, estado: Optional[str] = None,
                         workshop_id: Optional[str] = None, vehicle_id: Optional[str] = None,
                         abiertas: bool = False, limit: int = 200,
                         _=Depends(require_admin)):
    q: dict = {}
    if center and center != "Todos":
        q["center"] = {"$regex": re.escape(center), "$options": "i"}
    if estado:
        q["estado"] = estado
    elif abiertas:
        q["estado"] = {"$in": list(OT_ABIERTAS)}
    if workshop_id:
        q["workshop_id"] = workshop_id
    if vehicle_id:
        q["vehicle_id"] = vehicle_id
    filas = await db.ordenes_trabajo.find(q, {"_id": 0}) \
        .sort("creada_en", -1).to_list(max(1, min(limit, 500)))
    return {"ordenes": filas, "total": len(filas), "estados": OT_ESTADOS}


@api_router.get("/work-orders/resumen")
async def resumen_ordenes(center: Optional[str] = None, _=Depends(require_admin)):
    """Los cuatro numeros de arriba y el reparto por estado."""
    q: dict = {}
    if center and center != "Todos":
        q["center"] = {"$regex": re.escape(center), "$options": "i"}

    por_estado = {}
    async for g in db.ordenes_trabajo.aggregate([{"$match": q},
                                                 {"$group": {"_id": "$estado", "n": {"$sum": 1}}}]):
        por_estado[g["_id"] or "?"] = g["n"]

    hoy = _ot_ahora()[:10]
    completadas_hoy = await db.ordenes_trabajo.count_documents(
        dict(q, estado="entregado", fecha_entrega_real={"$regex": "^" + hoy}))

    # Tiempo medio en taller, en dias, solo de las entregadas que tienen las
    # dos fechas. Sin ese filtro saldria un numero inventado.
    dias, n = 0.0, 0
    async for o in db.ordenes_trabajo.find(
            dict(q, estado="entregado"),
            {"_id": 0, "fecha_entrada": 1, "fecha_entrega_real": 1}).limit(500):
        try:
            d1 = datetime.strptime(o["fecha_entrada"][:10], "%Y-%m-%d")
            d2 = datetime.strptime(o["fecha_entrega_real"][:10], "%Y-%m-%d")
            dias += (d2 - d1).days
            n += 1
        except Exception:
            continue

    # Paradas: abiertas y sin una sola novedad del taller en OT_DIAS_PARADA.
    # Se compara contra la novedad del taller o, si nunca ha habido ninguna,
    # contra la creacion — que es el caso peor: ni la ha mirado.
    corte = (datetime.now(timezone.utc) - timedelta(days=OT_DIAS_PARADA)).isoformat()
    q_parada = dict(q)
    q_parada["estado"] = {"$in": list(OT_ABIERTAS)}
    q_parada["$or"] = [
        {"ultima_novedad_taller": {"$lt": corte}},
        {"ultima_novedad_taller": {"$exists": False}, "creada_en": {"$lt": corte}},
    ]
    paradas = await db.ordenes_trabajo.count_documents(q_parada)

    q_sin = dict(q)
    q_sin["estado"] = {"$in": list(OT_ABIERTAS)}
    q_sin["abierto_en"] = {"$exists": False}
    sin_abrir = await db.ordenes_trabajo.count_documents(q_sin)

    return {
        "paradas": paradas,
        "sin_abrir": sin_abrir,
        "dias_parada": OT_DIAS_PARADA,
        "activas": sum(por_estado.get(e, 0) for e in OT_ABIERTAS),
        "esperando_piezas": por_estado.get("esperando_piezas", 0),
        "completadas_hoy": completadas_hoy,
        "dias_medios": round(dias / n, 1) if n else None,
        "medidas_sobre": n,
        "presupuestos_pendientes": await db.ordenes_trabajo.count_documents(
            dict(q, presupuesto="pendiente")),
        "por_estado": por_estado,
    }


@api_router.get("/ai/para-revisar")
async def ia_para_revisar(limit: int = 20, center: Optional[str] = None,
                          user: dict = Depends(require_admin)):
    """Daños SUELTOS pendientes de validar, no inspecciones enteras.

    Es el arreglo de la señal muerta. Revisar una inspeccion cuesta abrirla,
    mirar cinco fotos y navegar; revisar un daño es mirar una foto y pulsar un
    boton. Con 1.568 inspecciones al mes y la IA callandose en el 86 %, lo que
    hay que revisar no son las inspecciones: son los ~14 % en los que habla.

    EL ORDEN NO ES CRONOLOGICO, ES POR LO QUE ENSEÑA. Primero las piezas de
    las que menos sabemos: una revision sobre una pieza con 2 ejemplos mueve
    la leccion mucho mas que la numero 94 del paragolpes trasero. Cuando ya
    hay 90 falsos positivos de una pieza, el 91 no aporta nada.
    """
    limit = max(1, min(limit, 50))
    # El modelo de fiabilidad, si ya esta entrenado. Sirve para dos cosas: para
    # que la pantalla diga de que se fia y de que no, y para ORDENAR la cola.
    modelo = await fiabilidad.cargar(db)

    # Cuantas validaciones tiene ya cada pieza: es el peso del orden.
    sabido: dict = {}
    async for g in db.ai_feedback.aggregate([
            {"$group": {"_id": {"$toLower": {"$trim": {"input": {"$ifNull": ["$damage.part", ""]}}}},
                        "n": {"$sum": 1}}}]):
        sabido[(g["_id"] or "").strip()] = g["n"]

    q: dict = {"analysis.new_damages": {"$exists": True, "$ne": []}}
    if center and center != "Todos":
        # `inspections` no tiene campo center (gotcha 6): se acota por las
        # furgonetas de ese centro.
        ids = [v["id"] async for v in db.vehicles.find(
            {"center": {"$regex": re.escape(center), "$options": "i"}}, {"_id": 0, "id": 1})]
        q["vehicle_id"] = {"$in": ids}

    # Se miran bastantes mas de las que se devuelven porque la mayoria ya
    # estaran revisadas y hay que descartarlas.
    inspecciones = await db.inspections.find(
        q, {"_id": 0, "id": 1, "vehicle_id": 1, "photos": 1, "created_at": 1,
            "analysis.new_damages": 1}).sort("created_at", -1).to_list(400)
    if not inspecciones:
        return {"pendientes": [], "total_sin_revisar": 0}

    # Lo ya revisado, de una sola consulta: (inspeccion, indice).
    ya = set()
    async for f in db.ai_feedback.find(
            {"inspection_id": {"$in": [i["id"] for i in inspecciones]}},
            {"_id": 0, "inspection_id": 1, "damage_index": 1}):
        ya.add((f.get("inspection_id"), f.get("damage_index")))

    # Matriculas de una sola vez, para no consultar por cada daño.
    vids = list({i.get("vehicle_id") for i in inspecciones if i.get("vehicle_id")})
    matriculas = {v["id"]: v.get("license_plate") async for v in db.vehicles.find(
        {"id": {"$in": vids}}, {"_id": 0, "id": 1, "license_plate": 1})}

    sueltos = []
    # Lo que se descarta y POR QUE. No se esconde: que casi la mitad de los
    # hallazgos de la IA lleguen sin señalar donde estan es en si mismo el
    # dato mas importante de esta pantalla.
    descartes = {"sin_foto": 0, "sin_recuadro": 0, "recuadro_invalido": 0}

    for insp in inspecciones:
        fotos = insp.get("photos") or []
        for idx, dmg in enumerate((insp.get("analysis") or {}).get("new_damages") or []):
            if not isinstance(dmg, dict) or (insp["id"], idx) in ya:
                continue

            # ── REGLA DURA: si no se puede señalar QUE mirar, no se pregunta.
            # Antes, un daño sin `photo_index` caia en `fotos[0]` y se enseñaba
            # esa foto como si fuera la evidencia. Eso es mentir al que revisa
            # y envenenar el aprendizaje con su respuesta.
            pi = dmg.get("photo_index")
            if not (isinstance(pi, int) and 1 <= pi <= len(fotos)):
                descartes["sin_foto"] += 1
                continue
            caja = dmg.get("box_2d")
            if not (isinstance(caja, (list, tuple)) and len(caja) == 4
                    and all(isinstance(x, (int, float)) for x in caja)):
                descartes["sin_recuadro"] += 1
                continue
            # [ymin, xmin, ymax, xmax] 0-1000. Un recuadro de area cero o
            # invertido no señala nada, y uno que ocupa casi toda la foto
            # tampoco: "esta en algun sitio de la furgoneta" no es una pista.
            y0, x0, y1, x1 = caja
            alto, ancho = y1 - y0, x1 - x0
            if alto <= 0 or ancho <= 0 or (alto / 1000.0) * (ancho / 1000.0) > 0.75:
                descartes["recuadro_invalido"] += 1
                continue

            foto = fotos[pi - 1]
            pieza = str(dmg.get("part") or "").strip()
            sueltos.append({
                "inspection_id": insp["id"], "damage_index": idx, "scope": "new",
                "matricula": matriculas.get(insp.get("vehicle_id")) or "",
                "foto": foto, "pieza": pieza,
                "severidad": dmg.get("severity"),
                "descripcion": dmg.get("description"),
                "box": caja,
                "confianza": dmg.get("confidence"),
                "fecha": (insp.get("created_at") or "")[:10],
                # Lo que sabemos ya de esa pieza. Se manda para poder decir en
                # pantalla POR QUE se pregunta esto y no otra cosa.
                "validaciones_pieza": sabido.get(pieza.lower(), 0),
                # Lo que la IA opina de si misma sobre ESTE dano.
                "fiabilidad": fiabilidad.puntuar(
                    modelo, dmg, (insp.get("analysis") or {}).get("total_damages_count"), idx),
                "pieza_canonica": (piezas.canon(pieza) or [(None, None, None)])[0][0],
            })

    for x in sueltos:
        x["veredicto_auto"] = fiabilidad.veredicto(x["fiabilidad"])

    # ── EL ORDEN LO MANDA LA DUDA, NO LA FECHA ───────────────────────────────
    # Con 44 revisiones en 30 dias, gastarlas al azar es tirarlas. Primero va
    # aquello sobre lo que el modelo esta mas indeciso, que es lo unico que le
    # ensena algo; a igualdad de duda, la pieza de la que menos sabemos.
    # Sin modelo entrenado todavia, se cae al orden de antes y no pasa nada.
    sueltos.sort(key=lambda x: (-fiabilidad.incertidumbre(x["fiabilidad"]),
                                x["validaciones_pieza"], x["fecha"]))
    return {
        "pendientes": sueltos[:limit],
        "total_sin_revisar": len(sueltos),
        # Lo descartado va en la respuesta a proposito: es una medida de la
        # calidad de la IA, no basura que ocultar. Si este numero es alto, el
        # problema no es la cola — es que la IA no esta diciendo donde mira.
        "no_validables": sum(descartes.values()),
        "descartes": descartes,
        # Como de bien se conoce a si misma. Va en la respuesta para que la
        # pantalla no tenga que jurarlo: son numeros de validacion cruzada.
        "modelo": (modelo[2] if modelo else None),
        "reparto_auto": {v: sum(1 for x in sueltos if x["veredicto_auto"] == v)
                         for v in ("confirmado", "dudoso", "descartado")},
    }


@api_router.get("/ai/modelo")
async def ia_modelo(_=Depends(require_admin)):
    """Como se juzga la IA a si misma, y con que derecho.

    Devuelve SIEMPRE metricas de validacion cruzada, nunca de entrenamiento: un
    modelo puntuandose con los datos que ya vio da un numero bonito y falso, y
    ese numero acaba en una pantalla delante de alguien que decide con el.
    """
    m = await fiabilidad.cargar(db)
    if not m:
        n = await db.ai_feedback.count_documents(
            {"verdict": {"$in": ["correct", "corrected", "wrong"]}})
        return {"entrenado": False, "revisiones": n,
                "hacen_falta": fiabilidad._MIN_MUESTRAS,
                "motivo": "sin_entrenar" if n >= fiabilidad._MIN_MUESTRAS else "pocas_revisiones"}
    return {"entrenado": True, **m[2]}


@api_router.post("/ai/modelo/entrenar")
async def ia_modelo_entrenar(_=Depends(require_admin)):
    """Reentrena a mano. Normalmente no hace falta: se reentrena solo."""
    return await fiabilidad.entrenar(db)


# Cada cuantas revisiones nuevas se vuelve a entrenar. 25 y no 1 porque
# entrenar recorre todo `ai_feedback` y una revision de mas no mueve el modelo;
# y no 500 porque entonces las correcciones de alguien no se notarian en su
# propia sesion y pareceria que revisar no sirve de nada — que es exactamente
# la razon por la que solo se revisa el 2,8 %.
_IA_REENTRENA_CADA = 25


async def _ia_reentrenar_si_toca():
    """Reentrena en cuanto hay suficientes revisiones nuevas.

    Es lo que cierra el bucle: cada correccion de una persona entra en el
    modelo que decide de que fiarse, sin que nadie tenga que acordarse de
    pulsar nada. Si falla, se traga el error a proposito: guardar el feedback
    del usuario nunca puede romperse porque el reentreno vaya mal.
    """
    try:
        n = await db.ai_feedback.count_documents(
            {"verdict": {"$in": ["correct", "corrected", "wrong"]}})
        m = await fiabilidad.cargar(db)
        ultimo = (m[2] or {}).get("muestras", 0) if m else 0
        if n - ultimo >= _IA_REENTRENA_CADA or (m is None and n >= fiabilidad._MIN_MUESTRAS):
            r = await fiabilidad.entrenar(db)
            logger.info(f"Modelo de fiabilidad reentrenado: {r}")
    except Exception as e:
        logger.warning(f"Reentreno de fiabilidad: {e}")


@api_router.get("/ai/autoexamen")
async def ia_autoexamen(semanas: int = 12, _=Depends(require_admin)):
    """Como de bien lo esta haciendo la IA, medido con lo que marcasteis vosotros.

    Existe porque hasta ahora esto NO SE VEIA EN NINGUN SITIO: para saber si
    la IA acierta habia que abrir una consola y agregar a mano. Y lo que no se
    ve no se arregla — se cambian cosas del prompt sin saber si mejoran o
    empeoran, que es exactamente como se llega a un 7 % de acierto sin que
    salte ninguna alarma.

    DOS AVISOS QUE VAN EN LA PROPIA RESPUESTA, porque sin ellos los numeros
    se leen mal:
      · Solo cuenta lo REVISADO. Nadie revisa las inspecciones en las que la
        IA dijo "sin daños", asi que el porcentaje de acierto de aqui es el de
        cuando HABLA, no el de su trabajo entero.
      · Si la cobertura es baja, los numeros son de una muestra pequeña y
        posiblemente sesgada. Se devuelve para poder decirlo en pantalla.
    """
    semanas = max(1, min(semanas, 52))

    def vacio():
        # 'no_evaluable' cuenta aparte a proposito: no es ni un acierto ni un
        # fallo de la IA, es una foto que no permitia juzgar. Mezclarlo con
        # los fallos culparia a la IA de la calidad de las fotos.
        return {"correct": 0, "wrong": 0, "corrected": 0, "missed": 0, "no_evaluable": 0}

    def reportados(v: dict) -> int:
        """Lo que la IA DIJO: aciertos + inventados + visto pero mal situado.

        Es el denominador de "acierta" y de "se inventa", y NO el total de
        veredictos. Un `missed` es un daño que la IA no reporto: meterlo aqui
        mezcla dos preguntas distintas y hunde a la pieza que acierta todo lo
        que dice — 3 correct / 0 wrong / 7 missed daba "30 % ok" cuando de lo
        que reporto acerto el 100 %, y la tarjeta se titula "donde mas se
        equivoca". Y `no_evaluable` no es ni acierto ni fallo suyo: es una
        foto que no dejaba juzgar.
        """
        return v["correct"] + v["wrong"] + v["corrected"]

    def reales(v: dict) -> int:
        """Los daños que EXISTEN, segun el humano: los que vio —aunque situara
        mal la caja— mas los que se le escaparon. Es el denominador de "se le
        escapan", que es otra pregunta (cuanto VE) y no se puede medir sobre
        lo que reporto: los que no reporto son justamente los que faltan."""
        return v["correct"] + v["corrected"] + v["missed"]

    # ── Global ────────────────────────────────────────────────────────
    total = vacio()
    async for g in db.ai_feedback.aggregate([
            {"$group": {"_id": "$verdict", "n": {"$sum": 1}}}]):
        if g["_id"] in total:
            total[g["_id"]] = g["n"]
    n = sum(total.values())

    # ── LA MISMA CUENTA, PERO RECIENTE ───────────────────────────────
    # La media de por vida entierra cualquier mejora. Medido: junio 9 %,
    # julio 6 % (1.128 revisiones, antes de arreglar las lecciones por
    # pieza) y agosto 57 %. Enseñar solo el acumulado decia que la IA
    # estaba al 8,7 % cuando la de ahora esta muy por encima.
    # 30 dias, no 90: TODOS los veredictos que hay son de los ultimos 90, asi
    # que esa ventana devolvia el acumulado entero y no separaba nada. 30 aisla
    # lo posterior a los arreglos de las lecciones por pieza, que es lo que
    # cambio el comportamiento del modelo.
    _corte_rec = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    reciente = vacio()
    async for g in db.ai_feedback.aggregate([
            {"$match": {"created_at": {"$gte": _corte_rec}}},
            {"$group": {"_id": "$verdict", "n": {"$sum": 1}}}]):
        if g["_id"] in reciente:
            reciente[g["_id"]] = g["n"]

    def _cuentas(v: dict) -> dict:
        """Las dos preguntas, separadas, y sin fingir precision.

        `existe` responde a lo unico que importa de verdad —¿hay un daño ahi
        o se lo ha inventado?— y ahi un `corrected` cuenta como acierto: el
        daño estaba, lo que fallo fue el recuadro. `sitio` responde a la otra,
        y solo se calcula sobre los que SI existen.

        Con menos de 30 veredictos no se devuelve porcentaje: 44 revisiones
        son un indicio, no una medida, y un numero redondo sobre una muestra
        asi es tan falso como el que se venia a arreglar.
        """
        rep = v["correct"] + v["wrong"] + v["corrected"]
        reales_n = v["correct"] + v["corrected"]
        fiable = rep >= 30
        return {
            "reportados": rep,
            "existe_n": reales_n,
            "inventados": v["wrong"],
            # ¿El daño existe? Es la pregunta que decide si esto se puede vender.
            "existe": round(100 * reales_n / rep, 1) if (rep and fiable) else None,
            "inventa": round(100 * v["wrong"] / rep, 1) if (rep and fiable) else None,
            # De los que existen, ¿acerto tambien donde?
            "sitio": round(100 * v["correct"] / reales_n, 1) if (reales_n >= 20) else None,
            "muestra_corta": not fiable,
        }

    # ── Por pieza ─────────────────────────────────────────────────────
    piezas: dict = {}
    async for g in db.ai_feedback.aggregate([
            {"$group": {"_id": {"p": {"$toLower": {"$trim": {"input": {"$ifNull": ["$damage.part", ""]}}}},
                                "v": "$verdict"},
                        "n": {"$sum": 1}}}]):
        p = (g["_id"].get("p") or "").strip()
        if not p:
            continue
        piezas.setdefault(p, vacio())
        if g["_id"].get("v") in piezas[p]:
            piezas[p][g["_id"]["v"]] = g["n"]

    lista = []
    for p, v in piezas.items():
        tot = sum(v.values())
        if tot < 3:              # 1 o 2 casos no son un patron, son ruido
            continue
        rep = reportados(v)
        lista.append({"pieza": p, "total": tot, **v,
                      "reportados": rep, "reales": reales(v),
                      "acierto": round(100 * v["correct"] / rep, 1) if rep else None,
                      # La pregunta buena por pieza: ¿EXISTE el daño? Un
                      # `corrected` cuenta como que si: el daño estaba, lo que
                      # fallo fue el recuadro.
                      "existe": (round(100 * (v["correct"] + v["corrected"]) / rep, 1)
                                 if rep else None)})
    lista.sort(key=lambda x: (-x["wrong"], -x["total"]))

    # ── Tendencia por semana ──────────────────────────────────────────
    desde = (datetime.now(timezone.utc) - timedelta(weeks=semanas)).isoformat()
    por_semana: dict = {}
    # `for` y no `async for`: `to_list()` devuelve una LISTA, no un cursor.
    for f in await db.ai_feedback.find(
            {"created_at": {"$gte": desde}},
            {"_id": 0, "created_at": 1, "verdict": 1}).to_list(20000):
        try:
            d = datetime.fromisoformat(str(f["created_at"]).replace("Z", "+00:00"))
        except Exception:
            continue
        # Lunes de esa semana. La clave es la FECHA, no el numero de semana ISO:
        # el numero se reinicia en enero y ordenar por el mezclaria dos años.
        lunes = (d - timedelta(days=d.weekday())).strftime("%Y-%m-%d")
        por_semana.setdefault(lunes, vacio())
        if f.get("verdict") in por_semana[lunes]:
            por_semana[lunes][f["verdict"]] += 1
    tendencia = []
    for k in sorted(por_semana):
        v = por_semana[k]
        tot = sum(v.values())
        rep = reportados(v)
        tendencia.append({"semana": k, "total": tot, **v,
                          "reportados": rep, "reales": reales(v),
                          "acierto": round(100 * v["correct"] / rep, 1) if rep else None})

    # ── Cobertura: cuanto de lo que analiza llega a revisarse ─────────
    corte30 = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    insp30 = await db.inspections.count_documents({"created_at": {"$gte": corte30}})
    rev30 = await db.ai_feedback.count_documents({"created_at": {"$gte": corte30}})

    # ── Cuando calla, ¿acierta? ───────────────────────────────────────
    # El dato que mas se malinterpreta: la IA dice "sin daños" en la gran
    # mayoria de inspecciones, y eso NO entra en los porcentajes de arriba.
    con_analisis = await db.inspections.count_documents({"analysis": {"$exists": True, "$ne": None}})
    sin_danos = await db.inspections.count_documents(
        {"analysis.new_damages": {"$in": [None, []]}, "analysis": {"$exists": True, "$ne": None}})

    # ── Zonas que la IA declara que no puede juzgar ───────────────────
    motivos: dict = {}
    async for g in db.inspections.aggregate([
            {"$match": {"analysis.zonas_no_evaluables": {"$exists": True, "$ne": []}}},
            {"$unwind": "$analysis.zonas_no_evaluables"},
            {"$group": {"_id": "$analysis.zonas_no_evaluables.motivo", "n": {"$sum": 1}}},
            {"$sort": {"n": -1}}]):
        motivos[g["_id"] or "otra"] = g["n"]

    rep_total, reales_total = reportados(total), reales(total)
    return {
        "revisadas": n,
        "global": total,
        # Los DOS denominadores, explicitos y en la respuesta, para que ninguna
        # pantalla tenga que elegir uno por su cuenta: "acierta" y "se inventa"
        # se miden sobre lo que la IA reporto; "se le escapan", sobre los daños
        # que existen de verdad. Son preguntas distintas y no comparten divisor.
        "reportados": rep_total,
        "reales": reales_total,
        "acierto": round(100 * total["correct"] / rep_total, 1) if rep_total else None,
        # LAS DOS PREGUNTAS, SEPARADAS. `acierto` de arriba se queda por
        # compatibilidad, pero mezclaba dos cosas y hacia parecer a la IA
        # cuatro veces peor de lo que es en lo unico que importa: si el daño
        # existe. Un `corrected` es una deteccion buena con la caja torcida.
        "cuentas": _cuentas(total),
        "cuentas_30d": _cuentas(reciente),
        "piezas": lista[:20],
        "tendencia": tendencia,
        "cobertura": {"inspecciones_30d": insp30, "revisadas_30d": rev30,
                      "porcentaje": round(100 * rev30 / insp30, 2) if insp30 else 0},
        "cuando_calla": {"con_analisis": con_analisis, "dijo_sin_danos": sin_danos,
                         "porcentaje": round(100 * sin_danos / con_analisis, 1) if con_analisis else 0},
        "no_evaluables": motivos,
        # ── LO QUE LA IA HACE PARA COMPROBARSE SOLA ──────────────────────────
        # El bucle ya no depende de que alguien revise: cada dano se puntua
        # antes de que lo vea nadie, y el modelo se reentrena con cada tanda de
        # revisiones. Las metricas son de validacion cruzada, asi que se pueden
        # enseñar sin mentir.
        "modelo": ((await fiabilidad.cargar(db)) or [None, None, None])[2],
        # Se manda el aviso desde el backend para que ninguna pantalla pueda
        # enseñar el porcentaje suelto sin la letra pequeña.
        "aviso": ("Estos porcentajes son solo de lo REVISADO, y se revisa sobre todo "
                  "cuando la IA reporta algo. No incluyen las inspecciones en las que "
                  "dijo 'sin daños', que son la mayoria."),
    }


# ═══════════════════════════════════════════════════════════════════════════
# SEGUIMIENTO AUTOMATICO DEL TALLER
# ═══════════════════════════════════════════════════════════════════════════
# EL PROBLEMA REAL. Una furgoneta entra al taller y desaparece. Nadie llama
# hasta que hace falta, y entonces resulta que llevaba dos semanas lista o que
# el taller esperaba una respuesta que nunca llego. Medido el 28-08-2026: 14
# furgonetas paradas, tres desde hacia 52 dias, 319 dias-furgoneta acumulados.
#
# LO QUE HACE. Cada dia mira las ordenes abiertas en las que el taller no ha
# tocado nada en N dias y le manda UN recordatorio con su enlace. No pide que
# escriba: el enlace tiene los botones.
#
# POR QUE ESTO NO ES SPAM.
#  - Un toque por orden cada `OT_DIAS_TOQUE` dias, no uno diario. Un taller que
#    recibe un mensaje al dia deja de leerlos al tercero.
#  - El reloj se reinicia con CUALQUIER movimiento suyo: si contesta, no se le
#    vuelve a escribir hasta que pasen otros N dias en silencio.
#  - No se toca una orden en estado 'listo': ahi el que tiene que moverse
#    somos nosotros, y darle prisa al taller seria absurdo.
#  - Nunca de noche ni en fin de semana. Un aviso a las 22:00 del sabado no lo
#    lee nadie y quema el canal.
#
# EL CANAL. Hoy queda apuntado y sale por Telegram a la oficina con el enlace
# listo para reenviar; en cuanto WhatsApp tenga credenciales sale solo. El
# motor —a quien, cuando, que decir, cuando callarse— es el mismo.

OT_DIAS_TOQUE = 3          # silencio del taller que dispara el recordatorio
OT_TOQUES_MAX = 4          # a partir de aqui el problema no es el recordatorio


def _ot_texto_toque(o: dict, dias: int, url: str) -> str:
    """Corto y con UNA pregunta. Un recordatorio largo no se lee."""
    return (
        "Hola, ¿cómo va la %s? Lleva %d días sin novedades.\n\n"
        "Con un toque en este enlace nos decís el estado o para cuándo estará, "
        "y así no os llamamos:\n%s"
    ) % (o.get("matricula") or "furgoneta", dias, url)


async def _ot_url_taller(orden_id: str) -> str:
    """El enlace vivo de esa orden, o uno nuevo si no tiene."""
    e = await global_db.taller_enlaces.find_one(
        {"orden_id": orden_id, "revocado": {"$ne": True}}, {"_id": 0, "token": 1})
    if not e:
        token = secrets.token_urlsafe(32)
        await global_db.taller_enlaces.insert_one({
            "token": token, "orden_id": orden_id, "db_name": _current_db_name.get(),
            "creado_por": "seguimiento automático", "creado_en": _ot_ahora(),
            "expira_en": (datetime.now(timezone.utc) + timedelta(days=90)).isoformat(),
            "revocado": False})
        e = {"token": token}
    return "%s/taller/%s" % (_PORTAL_BASE_FRONT.rstrip("/"), e["token"])


def _hoy_madrid() -> str:
    """La fecha de hoy (AAAA-MM-DD) en la hora de la empresa, no la del servidor."""
    from zoneinfo import ZoneInfo
    return datetime.now(ZoneInfo("Europe/Madrid")).strftime("%Y-%m-%d")


# ---------------------------------------------------------------------------
# ESCRIBIR UN CORREO DESDE contacto@flotadsp.com
# ---------------------------------------------------------------------------
"""Un correo escrito a mano, saliendo de la direccion de la empresa.

PARA QUE. A Dani le piden que conteste desde `contacto@flotadsp.com` y no
tiene forma de hacerlo: el buzon existe para recibir, pero escribir desde el
requiere configurar un cliente de correo con ese dominio. La aplicacion ya
manda correos por Resend desde esa misma direccion -avisos, restablecer
contrasena-, asi que lo unico que faltaba era una caja donde escribir.

TRES COSAS QUE NO SON DECORACION:

- SOLO EL SUPER-ADMIN. Cualquiera que pueda escribir desde la direccion de la
  empresa habla en nombre de la empresa. No es un permiso mas de la lista: va
  con `require_superadmin`.

- RESPONDER-A, SIEMPRE. El correo sale de contacto@, asi que la respuesta
  vuelve a contacto@. Si ese buzon no se lee a diario -o no existe como buzon,
  solo como remitente-, la contestacion se pierde y encima no se nota: para
  quien escribio, el correo se envio bien. Por defecto se pone el correo del
  que escribe.

- QUEDA APUNTADO. Quien, a quien, cuando y si salio. Un correo que se manda en
  nombre de la empresa y del que no queda rastro es imposible de reconstruir
  tres semanas despues, que es justo cuando alguien pregunta.

El cuerpo se escribe en texto y se escapa entero antes de meterlo en el HTML:
un `<` en un correo tiene que verse como un `<`, no romper el mensaje.
"""

_CORREOS_COL = "correos_enviados"
_CORREO_MAX_HORA = 40


def _correo_valido(x: str) -> bool:
    return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]{2,}$", (x or "").strip()))


def _correo_html(texto: str, firma: str = "") -> str:
    """El texto tal cual, escapado, con los saltos de linea respetados."""
    import html as _html
    cuerpo = _html.escape(texto or "").replace("\n", "<br>")
    pie = ("<p style='margin:22px 0 0;color:#6b7280;font-size:13px'>%s</p>"
           % _html.escape(firma)) if firma else ""
    return ("<div style=\"font-family:-apple-system,Segoe UI,Inter,sans-serif;"
            "font-size:15px;line-height:1.6;color:#111827\">%s%s</div>" % (cuerpo, pie))


@api_router.get("/admin/correo")
async def admin_correo_estado(user: dict = Depends(require_superadmin)):
    """Desde que direccion sale y los ultimos que se han mandado."""
    enviados = await global_db[_CORREOS_COL].find(
        {}, {"_id": 0, "cuerpo": 0}).sort("at", -1).to_list(30)
    return {
        "de": os.environ.get("EMAIL_FROM", ""),
        "configurado": bool(os.environ.get("RESEND_API_KEY")),
        "responder_a": (user.get("email") or ""),
        "enviados": enviados,
    }


@api_router.post("/admin/correo")
async def admin_correo_enviar(body: dict = Body(...), user: dict = Depends(require_superadmin)):
    para = _texto_cuerpo(body.get("para"), 160).lower()
    asunto = _texto_cuerpo(body.get("asunto"), 200)
    cuerpo = _texto_cuerpo(body.get("cuerpo"), 8000)
    responder = _texto_cuerpo(body.get("responder_a"), 160).lower()
    copia = [c for c in (_texto_cuerpo(x, 160).lower() for x in _lista_cuerpo(body.get("copia")))
             if _correo_valido(c)][:5]
    if not _correo_valido(para):
        raise HTTPException(400, "Ese correo de destino no es valido")
    # UNA LETRA ES UN ASUNTO. El minimo de dos dejaba el boton apagado sin
    # decir por que —paso al primer uso real, con el asunto «a»— y ademas no
    # protege de nada: quien escribe el correo sabe que asunto quiere ponerle.
    if not asunto:
        raise HTTPException(400, "Ponle un asunto")
    if not cuerpo:
        raise HTTPException(400, "El correo esta vacio")
    if responder and not _correo_valido(responder):
        raise HTTPException(400, "El correo de respuesta no es valido")
    if not os.environ.get("RESEND_API_KEY"):
        raise HTTPException(503, "El envio de correo no esta configurado")

    # Un tope por hora. No es por desconfianza: es que una tecla enganchada o
    # un doble clic en un boton que manda correos en nombre de la empresa se
    # arregla mal.
    hace_una_hora = (datetime.now(timezone.utc) - timedelta(hours=1)).isoformat()
    recientes = await global_db[_CORREOS_COL].count_documents(
        {"at": {"$gte": hace_una_hora}, "ok": True})
    if recientes >= _CORREO_MAX_HORA:
        raise HTTPException(429, "Has mandado %d correos en la ultima hora: espera un poco"
                            % recientes)

    quien = user.get("name") or user.get("username") or ""
    ok = await _enviar_email(
        para, asunto, _correo_html(cuerpo), responder_a=responder,
        copia=copia or None, texto=cuerpo)
    doc = {
        "id": str(uuid.uuid4()), "para": para, "copia": copia, "asunto": asunto,
        "cuerpo": cuerpo, "responder_a": responder,
        "por": quien, "at": datetime.now(timezone.utc).isoformat(), "ok": bool(ok),
    }
    await global_db[_CORREOS_COL].insert_one(dict(doc))   # copia (gotcha 42)
    if not ok:
        # SE DICE QUE NO SALIO. Un correo que se da por enviado y no llego es
        # peor que uno que falla: nadie vuelve a intentarlo.
        raise HTTPException(502, "No se ha podido enviar. Queda apuntado el intento.")
    return {"ok": True, "id": doc["id"], "para": para}


# ── EMPLEO: OFERTAS Y CANDIDATOS ─────────────────────────────────────────────
# El anuncio (Indeed, un grupo de WhatsApp, donde sea) apunta a la pagina
# publica de la oferta; quien se apunta rellena el formulario y, al marcarlo
# «contratado», se crea la ficha del conductor con lo que el mismo escribio.
# Ese ultimo paso es el que de verdad vale: si el alta la teclea alguien a
# mano salen fichas duplicadas y sin telefono.
#
# Reglas que aqui no son negociables:
#  · la pagina publica NO lleva sesion, asi que fija la empresa a mano con
#    `_set_tenant_by_slug` (gotcha 26) y devuelve LISTA BLANCA de campos;
#  · las respuestas que descartan NO viajan al candidato: si sabe cual le deja
#    fuera, contesta lo que haga falta;
#  · un descarte automatico se VE y se puede deshacer. Un filtro que aparta en
#    silencio es como no tener candidatos y no enterarse;
#  · son datos personales: caducan solos a los 12 meses (TTL) y hay borrado a
#    mano para cuando alguien lo pida.

# El tablero de la oficina (Judith, 17-09-2026): se llama, se espera respuesta
# y si cuadra se pasa a la ETT. «otra_estacion» guarda A CUAL quieren ir
# (`estacion`), para poder contarlos por estacion al pasarlos.
# «entrevista» y «prueba» eran las columnas de antes: siguen siendo validas
# para no dejar invisibles a quienes ya estan ahi (gotcha 17), pero ya no se
# ofrecen para mover.
EMPLEO_FASES = ("nuevo", "llamado", "ett", "otra_estacion", "contratado", "descartado",
                "entrevista", "prueba")
_EMPLEO_FASES_ANTES_DE_ETT = ("nuevo", "llamado", "entrevista", "prueba")
EMPLEO_TIPOS = ("si_no", "opcion", "varias", "texto", "numero")
_EMPLEO_MESES_GUARDA = 12
_EMPLEO_MAX_POR_IP_H = 5
# INTENTOS, no candidaturas. Alto a proposito: esto solo esta para frenar a un
# bot, no a una persona a la que le sale un error y vuelve a darle a enviar.
_EMPLEO_MAX_INTENTOS_H = 40
_EMPLEO_MAX_POR_OFERTA_DIA = 200
_EMPLEO_MAX_PREGUNTAS = 12
_EMPLEO_MAX_OPCIONES = 8


class PreguntaEmpleo(BaseModel):
    model_config = ConfigDict(extra="ignore")
    id: str = Field(default_factory=lambda: uuid.uuid4().hex[:8])
    texto: str
    tipo: str = "si_no"
    opciones: List[str] = []
    obligatoria: bool = True
    # Respuestas que apartan solas. Se guardan en forma canonica (minusculas,
    # sin acentos) para poder compararlas; lo que se enseña es `opciones`, que
    # conserva como se escribio.
    descarta: List[str] = []


class OfertaEmpleo(BaseModel):
    model_config = ConfigDict(extra="ignore")
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    slug: str = ""
    titulo: str
    centro: Optional[str] = None
    ciudad: str = ""
    jornada: str = ""
    salario: str = ""
    descripcion: str = ""
    requisitos: str = ""
    activa: bool = True
    preguntas: List[PreguntaEmpleo] = []
    creada_en: str = ""
    creada_por: str = ""


def _empleo_texto(v, maximo: int) -> str:
    """Texto que viene de fuera: recortado y sin caracteres de control."""
    s = "" if v is None else str(v)
    s = "".join(c for c in s if c == "\n" or ord(c) >= 32)
    return s.strip()[:maximo]


def _empleo_sin_tildes(s: str) -> str:
    """Quita tildes y eñes-con-diacritico. Con prefijo del modulo a proposito.

    No hay un unico normalizador de texto en este fichero —cada modulo tiene el
    suyo, ajustado a lo que compara— y meter uno generico llamado
    `_quitar_acentos` seria justo el gotcha 24: un nombre a nivel de modulo que
    puede estar pisando otro sin que Python diga nada.
    """
    return "".join(c for c in unicodedata.normalize("NFD", s or "")
                   if unicodedata.category(c) != "Mn")


def _empleo_clave(v) -> str:
    """Forma canonica de una respuesta, para poder compararla sin sustos.

    Minusculas, sin acentos y sin espacios de mas: «Sí» y «si» son la misma
    respuesta, y el que descarta se escribio en el panel de otra manera que la
    que marca el candidato. Comparar en crudo hacia que `descarta` no saltara
    nunca: un filtro que no filtra y ademas no avisa.
    """
    s = _empleo_sin_tildes(str(v or "")).lower().strip()
    return re.sub(r"\s+", " ", s)


def _empleo_slugificar(texto: str) -> str:
    s = _empleo_sin_tildes(str(texto or "")).lower()
    s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
    return s[:60] or "oferta"


async def _empleo_slug_libre(base: str, oferta_id: str = "") -> str:
    """Un slug que no choque con otro de la MISMA empresa.

    El slug va en la URL publica, asi que dos ofertas con el mismo titulo se
    pisarian y la segunda seria inalcanzable.
    """
    raiz = _empleo_slugificar(base)
    slug, n = raiz, 1
    while n < 50:
        otra = await db.ofertas_empleo.find_one({"slug": slug}, {"_id": 0, "id": 1})
        if not otra or otra.get("id") == oferta_id:
            return slug
        n += 1
        slug = "%s-%d" % (raiz, n)
    return "%s-%s" % (raiz, uuid.uuid4().hex[:6])


def _empleo_normaliza_preguntas(preguntas) -> list:
    """Valida el cuestionario y lo deja listo para guardar.

    Lo que se comprueba, y por que cada cosa:
      · el tipo tiene que existir: uno inventado no se pintaria en la pagina y
        la pregunta desapareceria sin dar ningun error;
      · «opcion» y «varias» necesitan al menos dos opciones, o no hay nada que
        marcar;
      · una respuesta de `descarta` que no este entre las opciones no puede
        saltar NUNCA. Ese es el caso peligroso: parece que filtras y no filtras.
    """
    out = []
    for i, p in enumerate(preguntas or []):
        if len(out) >= _EMPLEO_MAX_PREGUNTAS:
            raise HTTPException(400, "Como mucho %d preguntas" % _EMPLEO_MAX_PREGUNTAS)
        p = dict(p or {})
        texto = _empleo_texto(p.get("texto"), 160)
        if not texto:
            raise HTTPException(400, "La pregunta %d no tiene enunciado" % (i + 1))
        tipo = str(p.get("tipo") or "si_no").strip()
        if tipo not in EMPLEO_TIPOS:
            raise HTTPException(400, "Tipo de pregunta no valido: %s" % tipo)
        if tipo == "si_no":
            opciones = ["Si", "No"]
        elif tipo in ("opcion", "varias"):
            opciones = [_empleo_texto(o, 60) for o in (p.get("opciones") or [])]
            opciones = [o for o in opciones if o][:_EMPLEO_MAX_OPCIONES]
            if len(opciones) < 2:
                raise HTTPException(400, "«%s» necesita al menos dos opciones" % texto)
            if len({_empleo_clave(o) for o in opciones}) != len(opciones):
                raise HTTPException(400, "«%s» tiene dos opciones iguales" % texto)
        else:
            opciones = []
        validas = {_empleo_clave(o) for o in opciones}
        descarta = []
        for d in (p.get("descarta") or []):
            k = _empleo_clave(d)
            if not k:
                continue
            if tipo in ("texto", "numero"):
                raise HTTPException(400, "Una pregunta de texto libre no puede descartar sola")
            if k not in validas:
                raise HTTPException(
                    400, "«%s» no es una de las opciones de «%s», asi que no descartaria "
                         "nunca" % (d, texto))
            descarta.append(k)
        out.append(PreguntaEmpleo(
            id=str(p.get("id") or uuid.uuid4().hex[:8])[:16],
            texto=texto, tipo=tipo, opciones=opciones,
            obligatoria=bool(p.get("obligatoria", True)),
            descarta=sorted(set(descarta)),
        ).model_dump())
    return out


def _empleo_publica_oferta(o: dict) -> dict:
    """Lo que ve el candidato. LISTA BLANCA, y sin las respuestas que descartan.

    La pagina es publica y su enlace acaba en cualquier sitio, asi que va por
    lista blanca y no por lista negra (gotcha 26). Y `descarta` se cae aqui a
    proposito: si el candidato sabe que contestar para no quedar fuera, el
    cuestionario deja de medir nada.
    """
    return {
        "id": o.get("id"), "slug": o.get("slug"), "titulo": o.get("titulo"),
        "ciudad": o.get("ciudad") or "", "jornada": o.get("jornada") or "",
        "salario": o.get("salario") or "", "descripcion": o.get("descripcion") or "",
        "requisitos": o.get("requisitos") or "",
        "preguntas": [{"id": p.get("id"), "texto": p.get("texto"), "tipo": p.get("tipo"),
                       "opciones": p.get("opciones") or [],
                       "obligatoria": bool(p.get("obligatoria", True))}
                      for p in (o.get("preguntas") or [])],
    }


def _empleo_revisa_respuestas(preguntas: list, respuestas: dict):
    """Devuelve (respuestas_limpias, motivo_de_descarte_o_None).

    Pura a proposito, para poder probarla sin base de datos. Solo se guardan
    valores que estan entre las opciones de la pregunta: lo que llega por el
    cuerpo de una peticion publica no se cree.
    """
    limpias, fuera = {}, []
    for p in preguntas or []:
        pid = p.get("id")
        tipo = p.get("tipo")
        bruto = (respuestas or {}).get(pid)
        if tipo == "varias":
            crudas = bruto if isinstance(bruto, list) else [bruto]
            validas = {_empleo_clave(o): o for o in (p.get("opciones") or [])}
            vals, vistas = [], set()
            for x in crudas:
                k = _empleo_clave(_empleo_texto(x, 60))
                if k in validas and k not in vistas:
                    vistas.add(k)
                    vals.append(validas[k])
            marcado, valor = vals, vals
        elif tipo in ("si_no", "opcion"):
            validas = {_empleo_clave(o): o for o in (p.get("opciones") or [])}
            v = validas.get(_empleo_clave(_empleo_texto(bruto, 60)), "")
            marcado, valor = ([v] if v else []), v
        elif tipo == "numero":
            v = _empleo_texto(bruto, 12)
            marcado, valor = [], (v if re.match(r"^-?\d+([.,]\d+)?$", v) else "")
        else:
            marcado, valor = [], _empleo_texto(bruto, 500)
        if p.get("obligatoria") and (valor == "" or valor == []):
            raise HTTPException(400, "Falta contestar: %s" % p.get("texto"))
        limpias[pid] = valor
        for m in marcado:
            if _empleo_clave(m) in (p.get("descarta") or []):
                fuera.append("%s: %s" % (p.get("texto"), m))
    return limpias, ("; ".join(fuera)[:400] if fuera else None)


async def _empleo_oferta_publica(slug: str, oferta_slug: str) -> dict:
    """Resuelve empresa + oferta desde la URL publica. Fija la BD a mano."""
    await _set_tenant_by_slug(slug)
    o = await db.ofertas_empleo.find_one(
        {"slug": _empleo_slugificar(oferta_slug), "activa": True}, {"_id": 0})
    if not o:
        raise HTTPException(404, "Esta oferta ya no esta disponible")
    return o


async def _empleo_con_enlace(o: dict) -> dict:
    """La oferta con su URL publica montada y el texto para compartirla."""
    org = await global_db.organizations.find_one(
        {"db_name": _current_db_name.get()}, {"_id": 0, "slug": 1})
    if not org and _current_db_name.get() == _DEFAULT_DB_NAME:
        # La organizacion principal no guarda `db_name` (ver `_centro_por_defecto`).
        org = await global_db.organizations.find_one({"account_type": "owner"}, {"_id": 0, "slug": 1})
    slug = (org or {}).get("slug") or ""
    o = {k: v for k, v in o.items() if k != "_id"}
    url = "%s/empleo/%s/%s" % (_PORTAL_BASE_FRONT.rstrip("/"), slug, o.get("slug"))
    o["url"] = url
    o["url_indeed"] = url + "?de=indeed"
    o["texto"] = ("%s%s. Apuntate aqui: %s"
                  % (o.get("titulo") or "",
                     (" en " + o["ciudad"]) if o.get("ciudad") else "", url))
    return o


async def _empleo_centro_valido(valor) -> str:
    """El centro de una oferta se ELIGE, no se hereda de un valor por defecto.

    Una oferta de Coruña guardada en OGA5 mete a esos candidatos en el tablero
    de Santiago y, al contratarlos, la ficha nace en la nave equivocada: sale
    en el cuadrante que no es y no sale en el que toca. Es justo el fallo del
    gotcha 43 —un valor por defecto que parece inocente— pero con personas.
    Asi que aqui no hay defecto: si no viene centro, o no es uno de los de la
    empresa, se contesta 400 y lo arregla quien crea la oferta.
    """
    centro = _centro_norm(_empleo_texto(valor, 30) or "")
    org = await global_db.organizations.find_one(
        {"db_name": _current_db_name.get()}, {"_id": 0, "centers": 1})
    if not org and _current_db_name.get() == _DEFAULT_DB_NAME:
        org = await global_db.organizations.find_one({"account_type": "owner"}, {"_id": 0, "centers": 1})
    validos = [str(c).strip().upper() for c in ((org or {}).get("centers") or []) if str(c).strip()]
    if not validos:
        validos = sorted(c for c in await _centros_conocidos() if c)
    if not centro:
        raise HTTPException(400, "Elige a que centro va esta oferta (%s)" % ", ".join(validos))
    if validos and centro.upper() not in validos:
        raise HTTPException(400, "«%s» no es un centro de esta empresa (%s)"
                            % (centro, ", ".join(validos)))
    return centro.upper()


@api_router.get("/empleo/publicas")
async def empleo_ofertas_publicas(empresa: str = ""):
    """Las ofertas abiertas de una empresa, para su pagina de empleo. Sin sesion.

    POR QUE EXISTE. Hasta hoy una oferta solo se podia ver si alguien te pasaba
    SU enlace: no habia ningun sitio donde estuvieran todas. Quien llega a
    flotadsp.com buscando trabajo no tiene nada que abrir, y las tres ofertas
    de Vigo, Santiago y A Coruna solo circulaban por WhatsApp.

    LA EMPRESA VA EN LA URL, no por defecto. `empresa` es el slug publico
    (`/empleo/<slug>/<oferta>` usa el mismo), y sin el se toma la de este
    despliegue — flotadsp.com es de una empresa concreta—. Pero el tenant se
    fija A MANO en los dos casos (gotcha 26): sin eso, el listado de un DSP
    acabaria enseñando las ofertas de otro, con HTTP 200 y sin un error.

    LISTA BLANCA de campos, como la oferta suelta: esto lo abre cualquiera desde
    Google, y las preguntas del cuestionario —con sus respuestas que descartan—
    no pueden viajar aqui.
    """
    slug = _texto_cuerpo(empresa, 60)
    if slug:
        await _set_tenant_by_slug(slug)
    else:
        org = await global_db.organizations.find_one(
            {"db_name": _DEFAULT_DB_NAME}, {"_id": 0, "slug": 1, "name": 1})
        slug = (org or {}).get("slug") or ""
        set_current_org_db(_DEFAULT_DB_NAME)
    org = await global_db.organizations.find_one(
        {"db_name": _current_db_name.get()}, {"_id": 0, "name": 1, "slug": 1})

    docs = await db.ofertas_empleo.find(
        {"activa": True}, {"_id": 0}).sort("creada_en", -1).to_list(60)
    ofertas = []
    for o in docs:
        ofertas.append({
            "slug": o.get("slug"), "titulo": o.get("titulo"),
            "ciudad": o.get("ciudad") or "", "jornada": o.get("jornada") or "",
            "salario": o.get("salario") or "",
            # Un resumen, no la descripcion entera: la tarjeta de una lista se
            # lee de un vistazo y el detalle esta a un clic.
            "resumen": (o.get("descripcion") or "").strip()[:220],
            "url": "/empleo/%s/%s" % (slug, o.get("slug") or ""),
        })
    reclamo = await _tienda_reclamo()
    return {"empresa": (org or {}).get("name") or "", "slug": slug,
            "ciudades": sorted({o["ciudad"] for o in ofertas if o["ciudad"]}),
            "jornadas": sorted({o["jornada"] for o in ofertas if o["jornada"]}),
            "ofertas": ofertas,
            # La ropa tambien desde aqui: quien mira las ofertas es justo quien
            # todavia no conoce a la empresa.
            "tienda": reclamo["url"], "tienda_desde": reclamo["desde"],
            "tienda_prendas": reclamo["prendas"]}


@api_router.get("/empleo/publica/{slug}/{oferta_slug}")
async def empleo_oferta_publica(slug: str, oferta_slug: str):
    """La oferta tal y como la ve quien se va a apuntar. Sin sesion."""
    o = await _empleo_oferta_publica(slug, oferta_slug)
    d = _empleo_publica_oferta(o)
    # La tienda se anuncia al FINAL, cuando la candidatura ya esta enviada:
    # antes seria ruido justo donde la persona esta decidiendo apuntarse.
    # Viene aqui y no en una llamada aparte porque la pagina ya tiene esta
    # respuesta en la mano cuando llega a esa pantalla.
    reclamo = await _tienda_reclamo()
    d["tienda"] = reclamo["url"]
    d["tienda_desde"] = reclamo["desde"]
    d["tienda_prendas"] = reclamo["prendas"]
    return d


_EMPLEO_CV_MAX = 8 * 1024 * 1024
_EMPLEO_CV_TIPOS = (".pdf", ".doc", ".docx", ".jpg", ".jpeg", ".png", ".webp", ".heic")


async def _empleo_cuerpo(request: Request):
    """Devuelve (datos, nombre_cv, bytes_cv). Acepta multipart Y JSON.

    Las dos formas a proposito: la pagina manda multipart desde que hay
    curriculum, pero un navegador con la version anterior cacheada sigue
    mandando JSON durante horas. Romperle la candidatura a alguien que se esta
    apuntando por un despliegue nuestro no es aceptable.
    """
    ctype = (request.headers.get("content-type") or "").lower()
    if ctype.startswith("multipart/"):
        form = await request.form()
        try:
            datos = json.loads(str(form.get("datos") or "{}"))
        except Exception:
            raise HTTPException(400, "No hemos entendido el formulario")
        if not isinstance(datos, dict):
            raise HTTPException(400, "No hemos entendido el formulario")
        f = form.get("cv")
        if f is None or not hasattr(f, "read"):
            return datos, "", None
        nombre = str(getattr(f, "filename", "") or "")[:120]
        if not nombre.lower().endswith(_EMPLEO_CV_TIPOS):
            raise HTTPException(400, "El curriculum tiene que ser un PDF, un Word o una foto")
        contenido = await f.read()
        if len(contenido) > _EMPLEO_CV_MAX:
            raise HTTPException(413, "El curriculum no puede pasar de 8 MB")
        return datos, nombre, (contenido or None)
    cuerpo = await request.json()
    if not isinstance(cuerpo, dict):
        raise HTTPException(400, "No hemos entendido el formulario")
    return cuerpo, "", None


@api_router.post("/empleo/publica/{slug}/{oferta_slug}")
async def empleo_apuntarse(slug: str, oferta_slug: str, request: Request):
    """Alguien se apunta. Endpoint publico: todo lo que entra es sospechoso."""
    datos, cv_nombre, cv_bytes = await _empleo_cuerpo(request)
    # EL CAMPO TRAMPA. Un bot rellena todos los inputs que encuentra; una
    # persona no ve este porque esta escondido. Se responde OK y no se guarda:
    # devolviendo un error, el bot aprenderia a dejarlo vacio.
    if _empleo_texto(datos.get("web"), 50):
        return {"ok": True}
    # DOS TOPES, Y MIDEN COSAS DISTINTAS. El primero frena a quien machaca el
    # endpoint —un bot— y es holgado a proposito. El segundo, el de verdad, se
    # GASTA solo cuando la candidatura entra, y por eso aqui solo se mira. Con
    # un unico tope contando intentos, un error nuestro dejaba a la persona sin
    # poder apuntarse durante una hora, y con ella a todo el que compartiera su
    # IP —una oficina, una wifi, el 4G de una operadora—.
    _ip = _rl_key_ip(request)
    _rl_public_action("empleo-intentos:%s" % _ip, _EMPLEO_MAX_INTENTOS_H, 3600,
                      "Demasiados intentos seguidos. Espera unos minutos.")
    _rl_public_action("empleo:%s" % _ip, _EMPLEO_MAX_POR_IP_H, 3600,
                      "Has enviado varias candidaturas seguidas. Intentalo en un rato.",
                      contar=False)
    o = await _empleo_oferta_publica(slug, oferta_slug)

    nombre = _empleo_texto(datos.get("nombre"), 120)
    telefono = _telefono_limpio(datos.get("telefono"))
    if len(nombre) < 3:
        raise HTTPException(400, "Escribe tu nombre y apellidos")
    if len(_telefono_digitos(telefono)) < 9:
        raise HTTPException(400, "Ese telefono no parece completo")
    # EL DNI/NIE ES OBLIGATORIO: hace falta para el alta, y pedirlo despues por
    # telefono es una llamada mas y una persona menos. Se comprueba la FORMA, no
    # la letra: un NIE mal tecleado se corrige al llamar, pero rechazar uno bueno
    # por una regla nuestra es perder a alguien que si valia.
    dni = re.sub(r"[\s-]", "", _empleo_texto(datos.get("dni"), 20)).upper()
    if not (re.match(r"^\d{8}[A-Z]$", dni) or re.match(r"^[XYZ]\d{7}[A-Z]$", dni)):
        raise HTTPException(400, "Escribe tu DNI (8 cifras y una letra, 12345678A) o tu NIE (X, Y o Z, 7 cifras y una letra, X1234567A)")
    if not _empleo_texto(datos.get("disponibilidad"), 120):
        raise HTTPException(400, "Dinos cuando puedes empezar")
    # EL CARNET B, EN LA MANO — NO APROBADO, NI EN TRAMITE, NI EN EL PUEBLO.
    # Tener el examen aprobado y tener la tarjeta no es lo mismo, y sin la
    # tarjeta no se puede coger la furgoneta: es el requisito que decide si
    # alguien puede empezar el lunes o dentro de dos meses. Hasta hoy se
    # descubria por telefono —una llamada por candidato— o, peor, el dia del
    # alta. Va como campo FIJO y no como pregunta de la oferta: una pregunta
    # del cuestionario hay que acordarse de ponerla en cada oferta nueva, y el
    # dia que se olvide nadie lo echaria en falta (gotcha 27 con otra cara).
    # LA PAGINA QUE ALGUIEN TIENE ABIERTA NO SE ENTERA DE QUE HEMOS DESPLEGADO.
    # Este campo se añadio el 09-09-2026 y el backend salio ANTES que la pagina:
    # durante esos minutos, quien tenia la pestaña abierta desde antes mandaba
    # su candidatura sin el campo y se llevaba un 400 que ademas le hablaba de
    # un carnet que su pantalla no le habia preguntado. En el registro quedaron
    # dos intentos seguidos de la misma IP y detras once 429 de esa persona
    # dandole a enviar. Perder a un candidato por un despliegue nuestro no es
    # aceptable —es el gotcha 56: un despliegue no cierra el navegador de
    # nadie—, y seguiria pasando con cualquier pestaña que lleve horas abierta.
    #
    # Por eso se distingue NO PREGUNTADO de NO CONTESTADO:
    #  · la clave no viene -> pagina vieja: la candidatura ENTRA y el campo se
    #    queda vacio, que en el panel se pinta «no consta» y no como un «no»;
    #  · la clave viene vacia o con otra cosa -> pagina nueva, donde es
    #    obligatorio y el propio formulario ya lo bloquea: eso si es un 400.
    carnet_fisico = ""
    if "carnet_fisico" in datos:
        carnet_fisico = _empleo_clave(datos.get("carnet_fisico"))
        if carnet_fisico not in ("si", "no"):
            raise HTTPException(400, "Dinos si tienes el carnet B fisicamente")
    if not datos.get("consiento"):
        raise HTTPException(400, "Hay que aceptar que guardemos tus datos para el proceso")

    hoy = _hoy_madrid()
    cuantos = await db.candidatos.count_documents(
        {"oferta_id": o["id"], "creado_en": {"$regex": "^%s" % re.escape(hoy)}})
    if cuantos >= _EMPLEO_MAX_POR_OFERTA_DIA:
        raise HTTPException(429, "Hemos recibido muchas candidaturas hoy. Prueba mañana.")

    limpias, motivo = _empleo_revisa_respuestas(o.get("preguntas") or [],
                                                datos.get("respuestas") or {})
    ahora = datetime.now(timezone.utc)
    doc = {
        "id": str(uuid.uuid4()),
        "oferta_id": o["id"], "oferta_titulo": o.get("titulo") or "",
        "nombre": nombre, "telefono": telefono,
        "tel_clave": _telefono_digitos(telefono)[-9:],
        "email": _empleo_texto(datos.get("email"), 160).lower(),
        "ciudad": _empleo_texto(datos.get("ciudad"), 80),
        "centro": o.get("centro") or "",
        "carnet_desde": _empleo_texto(datos.get("carnet_desde"), 20),
        # "si", "no" o vacio. El vacio es NO CONSTA —la pagina de esa persona
        # no llego a preguntarlo— y no «no lo tiene»: leerlo como un no seria
        # acusar a alguien de algo que nunca dijo (gotcha 33).
        "carnet_fisico": carnet_fisico,
        # El DNI es dato sensible: viaja en la lista blanca del panel y NO sale
        # en ninguna respuesta publica. Se guarda tal cual lo escriba: validar
        # la letra dejaria fuera a los NIE y a quien lo teclee con un guion.
        "dni": dni,
        # La FECHA y el numero. El numero envejece —una candidatura de hoy dice
        # 24 y dentro de ocho meses sigue diciendo 24— y la fecha no; se guardan
        # las dos porque la fecha es opcional y el numero puede venir sin ella.
        "nacimiento": _empleo_texto(datos.get("nacimiento"), 10),
        "edad": (int(datos["edad"]) if str(datos.get("edad") or "").strip().isdigit()
                 and 14 <= int(datos["edad"]) <= 90 else None),
        "experiencia": _empleo_texto(datos.get("experiencia"), 60),
        "disponibilidad": _empleo_texto(datos.get("disponibilidad"), 120),
        "respuestas": limpias,
        # De donde viene: el enlace lleva `?de=indeed`, `?de=whatsapp`... Sin
        # esto no hay forma de saber que anuncio trae gente y cual se paga en balde.
        "origen": _empleo_texto(datos.get("origen"), 40) or "directo",
        "fase": "descartado" if motivo else "nuevo",
        "motivo_descarte": motivo or "",
        "descarte_automatico": bool(motivo),
        "notas": "", "driver_id": None,
        "creado_en": ahora.isoformat(),
        # Datos personales con fecha de caducidad: se van solos a los 12 meses.
        "expira_en": ahora + timedelta(days=30 * _EMPLEO_MESES_GUARDA),
    }
    # EL CURRICULUM SE SUBE ANTES DE GUARDAR NADA. Si falla la subida se
    # contesta el error y no queda un candidato a medias con un enlace roto;
    # y si el candidato ya estaba (409) no se ha gastado espacio en R2.
    if cv_bytes:
        s3 = get_r2()
        if s3:
            ext = cv_nombre.rsplit(".", 1)[-1].lower() if "." in cv_nombre else "pdf"
            clave = "cv/%s/%s.%s" % (o["id"], uuid.uuid4().hex, re.sub(r"[^a-z0-9]", "", ext)[:5] or "pdf")
            try:
                await asyncio.get_running_loop().run_in_executor(
                    _executor,
                    lambda: s3.put_object(Bucket=R2_BUCKET, Key=clave, Body=cv_bytes,
                                          ContentType="application/octet-stream"))
                base = os.environ.get("R2_PUBLIC_URL", "").rstrip("/")
                doc["cv_url"] = ("%s/%s" % (base, clave)) if base else clave
                doc["cv_nombre"] = cv_nombre
            except Exception as e:
                logger.warning("CV de candidato: %s", e)
    # Aqui SI se gasta el cupo: la candidatura es buena y se va a guardar.
    _rl_public_action("empleo:%s" % _ip, _EMPLEO_MAX_POR_IP_H, 3600,
                      "Has enviado varias candidaturas seguidas. Intentalo en un rato.")
    try:
        await db.candidatos.insert_one(dict(doc))   # copia: insert_one muta (gotcha 42)
    except DuplicateKeyError:
        raise HTTPException(409, "Ya nos llego tu candidatura para esta oferta. Gracias.")
    return {"ok": True, "nombre": nombre}


@api_router.post("/empleo/ofertas")
async def empleo_crear_oferta(datos: dict = Body(...), user: dict = Depends(require_admin)):
    titulo = _empleo_texto(datos.get("titulo"), 120)
    if len(titulo) < 3:
        raise HTTPException(400, "Ponle un titulo a la oferta")
    centro = await _empleo_centro_valido(datos.get("centro"))
    o = OfertaEmpleo(
        titulo=titulo, centro=centro,
        ciudad=_empleo_texto(datos.get("ciudad"), 80),
        jornada=_empleo_texto(datos.get("jornada"), 60),
        salario=_empleo_texto(datos.get("salario"), 60),
        descripcion=_empleo_texto(datos.get("descripcion"), 4000),
        requisitos=_empleo_texto(datos.get("requisitos"), 2000),
        activa=bool(datos.get("activa", True)),
        preguntas=_empleo_normaliza_preguntas(datos.get("preguntas")),
        creada_en=datetime.now(timezone.utc).isoformat(),
        creada_por=user.get("name") or user.get("username") or "",
    )
    doc = serialize_doc(o.model_dump())
    doc["slug"] = await _empleo_slug_libre("%s %s" % (titulo, doc.get("ciudad") or ""))
    await db.ofertas_empleo.insert_one(dict(doc))
    salida = await _empleo_con_enlace(doc)
    if doc.get("activa"):
        await _avisar_suscriptores_empleo(salida)
    return salida


@api_router.get("/empleo/ofertas")
async def empleo_listar_ofertas(center: Optional[str] = None, user: dict = Depends(require_admin)):
    q = _filtro_centro(user, center)
    if "center" in q:
        q["centro"] = q.pop("center")
    ofertas = await db.ofertas_empleo.find(q, {"_id": 0}).sort("creada_en", -1).to_list(200)
    ids = [o["id"] for o in ofertas]
    por: dict = {}
    origen: dict = {}
    if ids:
        async for r in db.candidatos.aggregate([
                {"$match": {"oferta_id": {"$in": ids}}},
                {"$group": {"_id": {"o": "$oferta_id", "f": "$fase"}, "n": {"$sum": 1}}}]):
            k = r["_id"]
            por.setdefault(k.get("o"), {})[k.get("f") or "nuevo"] = r["n"]
        async for r in db.candidatos.aggregate([
                {"$match": {"oferta_id": {"$in": ids}}},
                {"$group": {"_id": {"o": "$oferta_id", "d": "$origen"}, "n": {"$sum": 1}}}]):
            k = r["_id"]
            origen.setdefault(k.get("o"), {})[k.get("d") or "directo"] = r["n"]
    salida = []
    for o in ofertas:
        o = await _empleo_con_enlace(o)
        o["por_fase"] = por.get(o["id"], {})
        o["por_origen"] = origen.get(o["id"], {})
        o["candidatos"] = sum(o["por_fase"].values())
        salida.append(o)
    return {"ofertas": salida, "fases": list(EMPLEO_FASES), "tipos": list(EMPLEO_TIPOS)}


@api_router.patch("/empleo/ofertas/{oferta_id}")
async def empleo_editar_oferta(oferta_id: str, datos: dict = Body(...),
                               user: dict = Depends(require_admin)):
    o = await db.ofertas_empleo.find_one({"id": oferta_id}, {"_id": 0})
    if not o:
        raise HTTPException(404, "Esa oferta no existe")
    cambios: dict = {}
    # La direccion de la nave va en la LISTA BLANCA o se descarta en silencio
    # (gotcha 1): el PATCH solo copia lo que esta aqui.
    for campo, largo in (("titulo", 120), ("ciudad", 80), ("jornada", 60), ("salario", 60),
                         ("descripcion", 4000), ("requisitos", 2000),
                         ("direccion", 160), ("cp", 10), ("localidad", 80), ("provincia", 60)):
        if campo in datos:
            cambios[campo] = _empleo_texto(datos[campo], largo)
    if "centro" in datos:
        cambios["centro"] = await _empleo_centro_valido(datos.get("centro"))
    if "activa" in datos:
        cambios["activa"] = bool(datos["activa"])
    if "preguntas" in datos:
        cambios["preguntas"] = _empleo_normaliza_preguntas(datos["preguntas"])
    if cambios.get("titulo") and cambios["titulo"] != o.get("titulo"):
        cambios["slug"] = await _empleo_slug_libre(
            "%s %s" % (cambios["titulo"], cambios.get("ciudad", o.get("ciudad") or "")), oferta_id)
    if cambios:
        await db.ofertas_empleo.update_one({"id": oferta_id}, {"$set": cambios})
        o = await db.ofertas_empleo.find_one({"id": oferta_id}, {"_id": 0})
    return await _empleo_con_enlace(o)


@api_router.get("/empleo/candidatos/nuevos")
async def empleo_contar_nuevos(center: Optional[str] = None,
                               user: dict = Depends(require_admin)):
    """Cuantas candidaturas SIN MIRAR hay, para el aviso del menu.

    Solo `fase: "nuevo"`: en cuanto alguien la mueve —a en_proceso, descartado,
    contratado— deja de contar, que es justo lo que se pidio. Las que el
    formulario descarta solo (`descarte_automatico`) nacen ya en `descartado`,
    asi que tampoco suman: el numero es «personas a las que tengo que mirar».

    Endpoint propio y no la lista con `?fase=nuevo`, por lo mismo que
    `/shift-requests/pendientes`: esto lo pide el menu cada dos minutos desde
    TODAS las pantallas, y la lista devuelve hasta 500 candidatos enteros —con
    DNI y telefono— para acabar mirando su longitud.

    OJO AL ORDEN: declarado ANTES de `/empleo/candidatos/{cand_id}`, o
    'nuevos' entraria como si fuera un id.
    """
    q = _filtro_centro(user, center)
    if "center" in q:
        q["centro"] = q.pop("center")
    q["fase"] = "nuevo"
    n = await db.candidatos.count_documents(q)
    return {"nuevos": n}


# ---------------------------------------------------------------------------
# POR CONTACTAR: LA GENTE DE INDEED QUE AUN NO SE HA APUNTADO
# ---------------------------------------------------------------------------
"""Un nombre, un telefono y un WhatsApp ya escrito. Nada mas.

QUE PROBLEMA RESUELVE. En Indeed aparecen personas interesadas de las que solo
se tiene el nombre y el numero: no son candidatos todavia -no han rellenado
nada- pero hay que escribirles uno a uno el mismo mensaje pidiendoles que se
apunten en la web. Eso se hacia copiando el texto de una nota, cambiando el
nombre a mano y buscando el contacto en WhatsApp. Con veinte personas al dia
eso no se hace entero: se hace a medias, y luego nadie sabe a quien se escribio.

TRES DECISIONES:

- NO SON CANDIDATOS y no van a `candidatos`. Un candidato tiene DNI,
  disponibilidad y respuestas; esto es un nombre y un numero. Meterlos juntos
  llenaria el embudo de fichas vacias y las cuentas de «cuantos se apuntaron»
  dejarian de significar nada.

- ABRIR WHATSAPP NO ES HABER ESCRITO. El enlace deja el mensaje puesto, pero
  quien lo abre puede cerrarlo sin enviar. Se marca en otra llamada, igual que
  con las ETT: apuntar envios que no ocurrieron es peor que no apuntar nada,
  porque se deja de escribir a alguien creyendo que ya se hizo.

- SE CRUZAN SOLOS CON LOS CANDIDATOS por el telefono. Es todo el sentido de
  esto: saber a quien escribiste que SI acabo apuntandose y a quien no, para
  no volver a escribirle al que ya esta dentro.

El texto lo puede cambiar la oficina sin tocar codigo: vive en `app_meta`.
Y el enlace de WhatsApp lo arma SIEMPRE el backend con `enlace_wa` (gotcha 47).
"""

_INVITA_COL = "empleo_invitados"
_INVITA_MESES_GUARDA = 6
_INVITA_MAX = 500
_INVITA_ENLACE = "https://flotadsp.com/empleo"
# El texto que escribio Dani, con los saltos de linea puestos y el enlace en su
# propia linea: dentro de un parrafo WhatsApp lo enlaza igual, pero se toca
# peor y se lee peor, y esto lo abre alguien en el movil.
_INVITA_PLANTILLA = (
    "Hola {nombre}, he visto que te has apuntado en Indeed.\n"
    "\n"
    "Para seguir con el proceso necesitamos que te apuntes desde nuestra web:\n"
    "{enlace}\n"
    "\n"
    "Elige la oferta que mejor te venga por ubicación y tu candidatura le llega "
    "directamente a nuestro equipo de RRHH.\n"
    "\n"
    "Un saludo, y cualquier duda por aquí estoy.\n"
    "Gracias."
)


async def _invita_plantilla() -> str:
    """El texto de hoy: el guardado, o el de serie si no han tocado nada."""
    d = await db.app_meta.find_one({"_id": "empleo_invitacion"}, {"_id": 0})
    return ((d or {}).get("texto") or "").strip() or _INVITA_PLANTILLA


def _invita_mensaje(plantilla: str, nombre: str) -> str:
    """Rellena el hueco del nombre. Nunca revienta por una llave mal escrita.

    Alguien escribira {Nombre} o {nombre_completo} alguna vez. Que salga tal
    cual es feo; que el boton de WhatsApp deje de funcionar, peor.

    SOLO EL NOMBRE DE PILA. «Hola Bruno Filipe Loureiro Baltazar,» no lo
    escribe una persona, y este mensaje tiene que parecer escrito por una.
    """
    corto = (str(nombre or "").strip().split(" ") or [""])[0]
    try:
        return plantilla.format(nombre=corto, enlace=_INVITA_ENLACE)
    except (KeyError, IndexError, ValueError):
        return (plantilla.replace("{nombre}", corto)
                         .replace("{enlace}", _INVITA_ENLACE))


def _invita_publico(x: dict, ya: set, plantilla: str) -> dict:
    texto = _invita_mensaje(plantilla, x.get("nombre") or "")
    return {
        "id": x.get("id"), "nombre": x.get("nombre") or "",
        "telefono": x.get("telefono") or "", "nota": x.get("nota") or "",
        "escrito_en": x.get("escrito_en") or "", "escrito_por": x.get("escrito_por") or "",
        "creado_en": x.get("creado_en") or "",
        # Si viene vacio es que no hay telefono, y eso se DICE en la pantalla:
        # un boton que abre WhatsApp sin destinatario hace perder el tiempo
        # y parece cosa de WhatsApp (gotcha 47).
        "wa": enlace_wa(x.get("telefono") or "", texto),
        "mensaje": texto,
        # Lo que hace que esto sirva para algo: quien SI acabo apuntandose.
        "se_apunto": bool(x.get("tel_clave")) and x.get("tel_clave") in ya,
    }


@api_router.get("/empleo/invitados")
async def empleo_invitados(_=Depends(require_admin)):
    """A quien hay que escribir, a quien ya se escribio y quien se apunto."""
    docs = await db[_INVITA_COL].find({}, {"_id": 0}).sort("creado_en", -1).to_list(_INVITA_MAX)
    # Los telefonos que YA estan en el embudo. Una sola consulta para todos:
    # preguntarlo uno a uno serian quinientas idas y venidas (gotcha 63).
    claves = [x.get("tel_clave") for x in docs if x.get("tel_clave")]
    ya = set()
    if claves:
        ya = {c.get("tel_clave") for c in await db.candidatos.find(
            {"tel_clave": {"$in": claves}}, {"_id": 0, "tel_clave": 1}).to_list(2000)}
    plantilla = await _invita_plantilla()
    lista = [_invita_publico(x, ya, plantilla) for x in docs]
    return {
        "invitados": lista,
        "plantilla": plantilla,
        "enlace": _INVITA_ENLACE,
        "sin_escribir": sum(1 for x in lista if not x["escrito_en"]),
        "escritos": sum(1 for x in lista if x["escrito_en"]),
        "apuntados": sum(1 for x in lista if x["se_apunto"]),
    }


@api_router.post("/empleo/invitados")
async def empleo_invitado_crear(body: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda a alguien de Indeed. Nombre y telefono, nada mas."""
    nombre = _texto_cuerpo(body.get("nombre"), 120)
    telefono = _telefono_limpio(body.get("telefono"))
    if len(nombre) < 2:
        raise HTTPException(400, "Escribe el nombre")
    if len(_telefono_digitos(telefono)) < 9:
        raise HTTPException(400, "Ese telefono no parece completo")
    if await db[_INVITA_COL].count_documents({}) >= _INVITA_MAX:
        raise HTTPException(400, "Tienes %d en la lista: borra los que ya no valgan"
                            % _INVITA_MAX)
    ahora = datetime.now(timezone.utc)
    doc = {"id": str(uuid.uuid4()), "nombre": nombre, "telefono": telefono,
           "tel_clave": _telefono_digitos(telefono)[-9:],
           "nota": _texto_cuerpo(body.get("nota"), 200),
           "escrito_en": "", "escrito_por": "",
           "creado_en": ahora.isoformat(),
           "creado_por": user.get("name") or user.get("username") or "",
           # Datos personales de alguien que ni siquiera se ha apuntado: se van
           # solos a los 6 meses, antes que los de un candidato.
           "expira_en": ahora + timedelta(days=30 * _INVITA_MESES_GUARDA)}
    try:
        await db[_INVITA_COL].insert_one(dict(doc))   # copia: insert_one muta (gotcha 42)
    except DuplicateKeyError:
        raise HTTPException(409, "Ese telefono ya esta en la lista")
    return _invita_publico(doc, set(), await _invita_plantilla())


@api_router.post("/empleo/invitados/{invitado_id}/escrito")
async def empleo_invitado_escrito(invitado_id: str, body: dict = Body(default={}),
                                  user: dict = Depends(require_admin)):
    """Confirma que se le escribio. Lo dice una persona, no el boton.

    Se puede desmarcar: si te equivocas de fila, dejarlo marcado significa que
    esa persona no recibe el mensaje nunca.
    """
    marcar = bool(body.get("escrito", True))
    ahora = datetime.now(timezone.utc).isoformat() if marcar else ""
    r = await db[_INVITA_COL].update_one(
        {"id": invitado_id},
        {"$set": {"escrito_en": ahora,
                  "escrito_por": ((user.get("name") or user.get("username") or "")
                                  if marcar else "")}})
    if not r.matched_count:
        raise HTTPException(404, "Ese contacto ya no esta")
    return {"ok": True, "escrito_en": ahora}


@api_router.put("/empleo/invitados/plantilla")
async def empleo_invitados_plantilla(body: dict = Body(...), _=Depends(require_admin)):
    """Cambia el texto sin tocar codigo. Con `{nombre}` y `{enlace}` dentro."""
    texto = _texto_cuerpo(body.get("texto"), 1200)
    if len(texto) < 20:
        raise HTTPException(400, "El mensaje se ha quedado demasiado corto")
    if "{nombre}" not in texto:
        raise HTTPException(400, "Deja {nombre} en el texto: es donde va el suyo")
    if "{enlace}" not in texto and _INVITA_ENLACE not in texto:
        raise HTTPException(400, "Deja {enlace} en el texto, o no sabran donde apuntarse")
    await db.app_meta.update_one({"_id": "empleo_invitacion"},
                                 {"$set": {"texto": texto}}, upsert=True)
    return {"ok": True, "plantilla": texto}


@api_router.delete("/empleo/invitados/{invitado_id}")
async def empleo_invitado_borrar(invitado_id: str, _=Depends(require_admin)):
    r = await db[_INVITA_COL].delete_one({"id": invitado_id})
    if not r.deleted_count:
        raise HTTPException(404, "Ese contacto ya no esta")
    return {"ok": True}


# ---------------------------------------------------------------------------
# LAS ETT: A QUIEN SE LE PASA UN CANDIDATO
# ---------------------------------------------------------------------------
"""La agenda de empresas de trabajo temporal y el envio por WhatsApp.

QUE PROBLEMA RESUELVE. Pasar un candidato a Adecco eran siete pasos a mano:
copiar el telefono, abrir WhatsApp, buscar el contacto, escribir el mensaje con
el puesto y la disponibilidad, enviarlo, volver a la aplicacion y acordarse de
apuntar a quien se lo mandaste. Con cuarenta candidatos a la semana eso no se
hace entero: se hace a medias y luego nadie sabe a quien se envio cada uno.

DOS DECISIONES QUE NO SON OBVIAS:

- LA ETT NO ES UNA FASE, es un dato aparte. Un mismo candidato puede
  interesarle a Adecco Y a Gi Group, y una fase solo admite un valor: en cuanto
  se manda a la segunda se pierde la primera. Por eso `candidato.etts` es una
  LISTA, y las fases del embudo (`nuevo`, `llamado`...) se quedan como estaban
  -renombrarlas obligaria a repasar todo lo que las lee y no aporta nada
  (gotcha 20)-.

- ABRIR WHATSAPP NO ES HABER ENVIADO. El enlace `wa.me` deja el mensaje
  escrito, pero quien lo abre puede cerrarlo sin darle a enviar. Marcarlo solo
  por pulsar el boton llenaria la ficha de envios que no ocurrieron, y eso es
  peor que no apuntar nada: se deja de llamar a un candidato porque "ya esta
  mandado". El registro lo confirma una persona, en otra llamada.

Y el enlace lo arma el BACKEND con `enlace_wa`, nunca el movil: a mano sale sin
prefijo y abre un numero que no existe (gotcha 47).
"""

_ETT_COL = "etts"
# El mensaje que abre WhatsApp. Con las tildes puestas: lo lee una persona de
# la ETT, y un texto sin acentos parece escrito por una maquina.
# LOS DATOS EN LINEAS SUELTAS y no metidos en un parrafo: al otro lado alguien
# tiene que copiar el nombre y el telefono a su sistema, y de una frase corrida
# se copia mal. Cada dato en su linea se selecciona de un toque en el movil.
_ETT_PLANTILLA = (
    "Hola {contacto}, te adjunto este nuevo candidato para {puesto}.\n"
    "Ya hemos hablado con \u00e9l y le interesa. Te dejo sus datos:\n"
    "\n"
    "Nombre: {candidato}\n"
    "Tel\u00e9fono: {telefono}\n"
    "Disponibilidad: {disponibilidad}\n"
    "Ciudad: {ciudad}\n"
    "\n"
    "Un saludo."
)


def _ett_publica(e: dict) -> dict:
    """Lo que ve el panel."""
    return {k: v for k, v in e.items() if k != "_id"}


def _ett_mensaje(ett: dict, c: dict) -> str:
    """Rellena la plantilla de esa ETT con los datos del candidato.

    Lo que no se sepa se deja fuera: una linea que pone "Disponibilidad:" y
    nada detras cuenta peor de lo que calla, y ademas delata que el mensaje lo
    escribio una maquina a medias.
    """
    datos = {
        "candidato": (c.get("nombre") or "").strip(),
        "nombre": (c.get("nombre") or "").strip().split(" ")[0],
        "puesto": (c.get("oferta_titulo") or "reparto de paqueteria").strip(),
        "ciudad": (c.get("ciudad") or c.get("centro") or "").strip(),
        "disponibilidad": (c.get("disponibilidad") or "").strip(),
        "experiencia": (c.get("experiencia") or "").strip(),
        "telefono": (c.get("telefono") or "").strip(),
        "ett": (ett.get("nombre") or "").strip(),
        "contacto": (ett.get("contacto") or "").strip(),
    }
    txt = ett.get("plantilla") or _ETT_PLANTILLA
    salida = []
    for linea in txt.split("\n"):
        try:
            puesta = linea.format(**datos)
        except Exception:                                        # noqa: BLE001
            puesta = linea          # una llave mal escrita no puede tumbar el envio
        if re.match(r"^[^:]{1,24}:\s*$", puesta.strip()):
            continue                # "Tel\u00e9fono:" a secas no se manda
        salida.append(puesta)
    # LAS LINEAS EN BLANCO SE RESPETAN: separan el saludo de los datos y sin
    # ellas el mensaje sale como un ladrillo. Lo que se limpia es lo que deja
    # un hueco al sustituir —"Hola , te adjunto" cuando la ETT no tiene persona
    # de contacto— y los blancos de sobra si se cayo alguna linea entera.
    texto = "\n".join(salida)
    texto = re.sub(r"[ \t]{2,}", " ", texto)
    texto = re.sub(r"\s+([,.:;])", r"\1", texto)
    texto = re.sub(r"\n{3,}", "\n\n", texto)
    return texto.strip()


@api_router.get("/empleo/etts")
async def empleo_etts(_=Depends(require_admin)):
    """La agenda. Anadir una ETT nueva no toca el codigo."""
    docs = await db[_ETT_COL].find({}, {"_id": 0}).sort("nombre", 1).to_list(100)
    return {"etts": [_ett_publica(e) for e in docs], "plantilla_defecto": _ETT_PLANTILLA}


@api_router.post("/empleo/etts")
async def empleo_ett_crear(body: dict = Body(...), user: dict = Depends(require_admin)):
    nombre = _texto_cuerpo(body.get("nombre"), 60)
    if len(nombre) < 2:
        raise HTTPException(400, "Ponle un nombre a la ETT")
    tel = _telefono_limpio(body.get("telefono"))
    if not tel:
        raise HTTPException(400, "Hace falta un WhatsApp valido: sin el no se puede enviar")
    doc = {
        "id": str(uuid.uuid4()), "nombre": nombre, "telefono": tel,
        "contacto": _texto_cuerpo(body.get("contacto"), 60),
        "email": _texto_cuerpo(body.get("email"), 160).lower(),
        "plantilla": _texto_cuerpo(body.get("plantilla"), 900) or _ETT_PLANTILLA,
        "activa": bool(body.get("activa", True)),
        "creada_en": datetime.now(timezone.utc).isoformat(),
        "creada_por": user.get("name") or user.get("username") or "",
    }
    await db[_ETT_COL].insert_one(dict(doc))    # copia: insert_one muta (gotcha 42)
    return _ett_publica(doc)


@api_router.patch("/empleo/etts/{ett_id}")
async def empleo_ett_editar(ett_id: str, body: dict = Body(...), _=Depends(require_admin)):
    cambios: dict = {}
    if "nombre" in body:
        n = _texto_cuerpo(body.get("nombre"), 60)
        if len(n) < 2:
            raise HTTPException(400, "Ponle un nombre a la ETT")
        cambios["nombre"] = n
    if "telefono" in body:
        t = _telefono_limpio(body.get("telefono"))
        if not t:
            raise HTTPException(400, "Ese WhatsApp no vale: sin el no se puede enviar")
        cambios["telefono"] = t
    for campo, largo in (("contacto", 60), ("email", 160), ("plantilla", 900)):
        if campo in body:
            cambios[campo] = _texto_cuerpo(body.get(campo), largo)
    if "activa" in body:
        cambios["activa"] = bool(body["activa"])
    if not cambios:
        raise HTTPException(400, "No hay nada que cambiar")
    r = await db[_ETT_COL].update_one({"id": ett_id}, {"$set": cambios})
    if not r.matched_count:
        raise HTTPException(404, "Esa ETT no existe")
    return _ett_publica(await db[_ETT_COL].find_one({"id": ett_id}, {"_id": 0}) or {})


@api_router.delete("/empleo/etts/{ett_id}")
async def empleo_ett_borrar(ett_id: str, _=Depends(require_admin)):
    """La quita de la agenda. Los envios ya hechos NO se tocan.

    El nombre se guarda dentro de cada envio justo para esto: borrar una ETT no
    puede dejar el historial de un candidato diciendo "enviado a (nada)".
    """
    r = await db[_ETT_COL].delete_one({"id": ett_id})
    if not r.deleted_count:
        raise HTTPException(404, "Esa ETT no existe")
    return {"ok": True}


async def _etts_activas() -> list:
    """La agenda, UNA sola vez. Leerla por candidato serian 500 consultas para
    la misma respuesta (gotcha 63)."""
    return await db[_ETT_COL].find({"activa": {"$ne": False}},
                                   {"_id": 0}).sort("nombre", 1).to_list(100)


def _etts_para(c: dict, docs: list) -> list:
    """Las ETT activas, cada una con SU enlace de WhatsApp para este candidato."""
    ya = {x.get("ett_id"): x for x in (c.get("etts") or [])}
    fuera = []
    for e in docs:
        enviado = ya.get(e["id"]) or {}
        fuera.append({
            "id": e["id"], "nombre": e.get("nombre"), "contacto": e.get("contacto") or "",
            "wa": enlace_wa(e.get("telefono") or "", _ett_mensaje(e, c)),
            "enviado_en": enviado.get("en") or "", "enviado_por": enviado.get("por") or "",
        })
    return fuera


@api_router.post("/empleo/candidatos/{cand_id}/ett")
async def empleo_candidato_a_ett(cand_id: str, body: dict = Body(...),
                                 user: dict = Depends(require_admin)):
    """Apunta que este candidato se le ha ENVIADO a esa ETT.

    Lo confirma una persona despues de mandarlo (ver la nota de arriba): abrir
    WhatsApp no es haber enviado.
    """
    c = await db.candidatos.find_one({"id": cand_id}, {"_id": 0})
    if not c:
        raise HTTPException(404, "Ese candidato no existe")
    ett_id = _texto_cuerpo(body.get("ett"), 60)
    ett = await db[_ETT_COL].find_one({"id": ett_id}, {"_id": 0})
    if not ett:
        raise HTTPException(404, "Esa ETT no existe")
    quien = user.get("name") or user.get("username") or ""
    ahora = datetime.now(timezone.utc).isoformat()
    # El NOMBRE viaja dentro del apunte: si manana se borra la ETT de la agenda,
    # el historial tiene que seguir diciendo a quien se mando.
    apunte = {"ett_id": ett["id"], "nombre": ett.get("nombre"), "en": ahora, "por": quien}
    # Mandarlo a una ETT ES pasarlo a la ETT: la columna se mueve sola, o la
    # oficina tendria que hacer dos cosas para una y el conteo mentiria.
    fase = c.get("fase") or "nuevo"
    if fase in _EMPLEO_FASES_ANTES_DE_ETT:
        await db.candidatos.update_one({"id": cand_id, "fase": c.get("fase")}, {
            "$set": {"fase": "ett", "motivo_descarte": "", "descarte_automatico": False},
            "$push": {"historial": {"en": ahora, "por": quien, "de": fase, "a": "ett"}}})
    if any(x.get("ett_id") == ett["id"] for x in (c.get("etts") or [])):
        # Reenviar no duplica: se actualiza la fecha del que ya estaba.
        await db.candidatos.update_one(
            {"id": cand_id, "etts.ett_id": ett["id"]},
            {"$set": {"etts.$.en": ahora, "etts.$.por": quien,
                      "tocado_en": ahora, "tocado_por": quien}})
    else:
        await db.candidatos.update_one({"id": cand_id}, {
            "$push": {"etts": apunte,
                      "historial": {"en": ahora, "por": quien,
                                    "que": "enviado a %s" % (ett.get("nombre") or "")}},
            "$set": {"tocado_en": ahora, "tocado_por": quien}})
    d = await db.candidatos.find_one({"id": cand_id}, {"_id": 0, "expira_en": 0})
    return {"ok": True, "etts": d.get("etts") or [], "historial": d.get("historial") or []}


@api_router.delete("/empleo/candidatos/{cand_id}/ett/{ett_id}")
async def empleo_candidato_quitar_ett(cand_id: str, ett_id: str,
                                      user: dict = Depends(require_admin)):
    """Deshace un envio apuntado por error. Queda dicho en el historial."""
    quien = user.get("name") or user.get("username") or ""
    ahora = datetime.now(timezone.utc).isoformat()
    r = await db.candidatos.update_one({"id": cand_id}, {
        "$pull": {"etts": {"ett_id": ett_id}},
        "$push": {"historial": {"en": ahora, "por": quien, "que": "envio a ETT deshecho"}},
        "$set": {"tocado_en": ahora, "tocado_por": quien}})
    if not r.matched_count:
        raise HTTPException(404, "Ese candidato no existe")
    # Si ya no queda ninguna ETT, vuelve a «llamado»: seguir en la columna de
    # la ETT sin haberselo mandado a ninguna seria un conteo falso.
    await db.candidatos.update_one(
        {"id": cand_id, "fase": "ett", "etts.0": {"$exists": False}},
        {"$set": {"fase": "llamado"},
         "$push": {"historial": {"en": ahora, "por": quien, "de": "ett", "a": "llamado"}}})
    return {"ok": True}


# Quien firma el primer WhatsApp a un candidato, por empresa. Vacio por
# defecto: firmar con el nombre de otra empresa seria mentir en su nombre
# (gotcha 43), y sin firma el mensaje sale igual pero sin presentarse.
_EMPLEO_FIRMA_POR_BD: dict = {}


def _empleo_nombre_pila(nombre) -> str:
    pila = str(nombre or "").strip().split(" ")[0].strip()
    # Las fichas llegan en MAYUSCULAS o minusculas (gotcha 23): «ADRIAN» -> «Adrian».
    return pila.capitalize() if pila.isupper() or pila.islower() else pila


def _empleo_primer_mensaje(nombre, oferta, firma: str = "") -> str:
    """El primer WhatsApp: las cuatro preguntas que deciden si se pasa a la ETT
    (texto de Dani, 17-09-2026)."""
    pila = _empleo_nombre_pila(nombre)
    saludo = ("Hola %s, te escribimos" % pila) if pila else "Hola, te escribimos"
    presentacion = ("¡Hola! Soy %s. Antes de pasarte con la ETT" % firma) if firma \
        else "Antes de pasarte con la ETT"
    return (
        "%s por la oferta de %s.\n"
        "%s te pregunto un par de cosas rápidas:\n\n"
        "- ¿Tienes el carnet B en físico? (hace falta sí o sí, no vale solo el digital)\n"
        "- ¿Tienes los papeles en regla? (DNI/NIE, permiso de trabajo si toca...)\n"
        "- ¿Podrías empezar ya?\n"
        "- ¿Vives por la zona?\n\n"
        "Si todo eso lo tienes claro, dime y seguimos. "
        "Cualquier duda me preguntas, ¡sin problema!"
    ) % (saludo, (str(oferta or "").strip() or "reparto"), presentacion)


@api_router.get("/empleo/candidatos")
async def empleo_listar_candidatos(oferta: Optional[str] = None, fase: Optional[str] = None,
                                   center: Optional[str] = None,
                                   user: dict = Depends(require_admin)):
    q = _filtro_centro(user, center)
    if "center" in q:
        q["centro"] = q.pop("center")
    if oferta:
        q["oferta_id"] = oferta
    if fase:
        if fase not in EMPLEO_FASES:
            raise HTTPException(400, "Esa fase no existe")
        q["fase"] = fase
    cands = await db.candidatos.find(q, {"_id": 0, "expira_en": 0}).sort("creado_en", -1).to_list(500)
    agenda = await _etts_activas()
    firma = _EMPLEO_FIRMA_POR_BD.get(_current_db_name.get(), "")
    for c in cands:
        # El enlace de WhatsApp lo arma SIEMPRE el backend (gotcha 47): a mano
        # sale sin prefijo y abre un numero que no existe.
        c["wa"] = enlace_wa(c.get("telefono") or "",
                            _empleo_primer_mensaje(c.get("nombre"), c.get("oferta_titulo"), firma))
        # A que ETT se le ha mandado ya, para verlo sin abrir la ficha.
        c["etts"] = c.get("etts") or []
        c["etts_para"] = _etts_para(c, agenda)
    return {"candidatos": cands, "fases": list(EMPLEO_FASES)}


@api_router.patch("/empleo/candidatos/{cand_id}")
async def empleo_mover_candidato(cand_id: str, datos: dict = Body(...),
                                 user: dict = Depends(require_admin)):
    c = await db.candidatos.find_one({"id": cand_id}, {"_id": 0})
    if not c:
        raise HTTPException(404, "Ese candidato no existe")
    cambios: dict = {}
    if "fase" in datos:
        f = str(datos["fase"] or "").strip()
        if f not in EMPLEO_FASES:
            raise HTTPException(400, "Esa fase no existe")
        if f == "contratado" and not c.get("driver_id"):
            raise HTTPException(400, "Para contratar usa el boton que crea la ficha")
        cambios["fase"] = f
        if f != "descartado":
            # Deshacer un descarte automatico: se limpia el motivo, o quedaria
            # una persona en «llamado» con un cartel de descartada encima.
            cambios["motivo_descarte"] = ""
            cambios["descarte_automatico"] = False
    if "notas" in datos:
        cambios["notas"] = _empleo_texto(datos["notas"], 2000)
    if "estacion" in datos:
        cambios["estacion"] = _empleo_texto(datos["estacion"], 60)
    if "motivo_descarte" in datos:
        cambios["motivo_descarte"] = _empleo_texto(datos["motivo_descarte"], 400)
    # EL TELEFONO SE PUEDE ESCRIBIR A MANO: quien llega por JOIN suele dejarlo
    # solo en el curriculum. Escrito por una persona deja de ser «del CV».
    if "telefono" in datos:
        tel = _telefono_limpio(datos["telefono"])
        if datos["telefono"] and not tel:
            raise HTTPException(400, "Ese telefono no parece completo")
        cambios.update(telefono=tel, tel_clave=_telefono_digitos(tel) if tel else "",
                       telefono_de=_empleo_texto(datos.get("telefono_de"), 20) or "a_mano")
    if not cambios:
        return c
    orden: dict = {"$set": {**cambios, "tocado_en": datetime.now(timezone.utc).isoformat(),
                            "tocado_por": user.get("name") or user.get("username") or ""}}
    # QUIEN LO MOVIO Y CUANDO. Es lo que permite contestar «cuanto lleva este sin
    # que lo toque nadie», que es la pregunta que evita perder candidatos: a los
    # tres dias sin llamar ya estan en otra empresa. Se guarda solo el cambio de
    # fase, no cada tecla de las notas.
    if "fase" in cambios and cambios["fase"] != (c.get("fase") or "nuevo"):
        apunte = {"en": datetime.now(timezone.utc).isoformat(),
                  "por": user.get("name") or user.get("username") or "",
                  "de": c.get("fase") or "nuevo", "a": cambios["fase"]}
        if cambios["fase"] == "otra_estacion" and cambios.get("estacion"):
            apunte["que"] = "quiere ir a %s" % cambios["estacion"]
        orden["$push"] = {"historial": apunte}
    try:
        await db.candidatos.update_one({"id": cand_id}, orden)
    except DuplicateKeyError:
        raise HTTPException(409, "Ese telefono ya lo tiene otro candidato de esta oferta")
    return await db.candidatos.find_one({"id": cand_id}, {"_id": 0, "expira_en": 0})


@api_router.post("/empleo/candidatos/{cand_id}/contratar")
async def empleo_contratar(cand_id: str, user: dict = Depends(require_admin)):
    """Crea la ficha del conductor con lo que escribio el propio candidato.

    Es el motivo de todo el modulo: el alta a mano es de donde salen las fichas
    duplicadas y los teléfonos que faltan.
    """
    c = await db.candidatos.find_one({"id": cand_id}, {"_id": 0})
    if not c:
        raise HTTPException(404, "Ese candidato no existe")
    if c.get("driver_id"):
        raise HTTPException(409, "Este candidato ya tiene ficha de conductor")
    email = (c.get("email") or "").strip()
    if email:
        otra = await db.drivers.find_one(
            {"email": {"$regex": "^%s$" % re.escape(email), "$options": "i"},
             "active": {"$ne": False}}, {"_id": 0, "id": 1, "name": 1})
        if otra:
            raise HTTPException(409, "Ya hay un conductor activo con ese correo (%s)"
                                % (otra.get("name") or otra.get("id")))
    d = Driver(name=c.get("nombre") or "", phone=c.get("telefono") or "",
               email=email or None, center=c.get("centro") or None,
               telefono_por="empleo", telefono_en=datetime.now(timezone.utc).isoformat(),
               notas=("Alta desde la oferta «%s»." % (c.get("oferta_titulo") or "")).strip())
    doc = serialize_doc(d.model_dump())
    try:
        await db.drivers.insert_one(dict(doc))
    except DuplicateKeyError:
        raise HTTPException(409, "Ya hay un conductor activo con ese correo")
    await db.candidatos.update_one(
        {"id": cand_id},
        {"$set": {"fase": "contratado", "driver_id": d.id,
                  "contratado_en": datetime.now(timezone.utc).isoformat(),
                  "tocado_en": datetime.now(timezone.utc).isoformat(),
                  "tocado_por": user.get("name") or user.get("username") or "",
                  "contratado_por": user.get("name") or user.get("username") or ""},
         "$push": {"historial": {"en": datetime.now(timezone.utc).isoformat(),
                                 "por": user.get("name") or user.get("username") or "",
                                 "de": c.get("fase") or "nuevo", "a": "contratado"}}})
    return {"ok": True, "driver_id": d.id, "nombre": d.name}


@api_router.delete("/empleo/candidatos/{cand_id}")
async def empleo_borrar_candidato(cand_id: str, user: dict = Depends(require_admin)):
    """Borrado a mano: alguien pide que quitemos sus datos y hay que poder."""
    r = await db.candidatos.delete_one({"id": cand_id})
    if not r.deleted_count:
        raise HTTPException(404, "Ese candidato no existe")
    return {"ok": True}


# ── JOIN (join.com): LAS CANDIDATURAS QUE LLEGAN POR FUERA ──────────────────
# El 16-09-2026 habia 106 candidatos de la oferta de Santiago en JOIN y ninguno
# en el tablero: se miraban en otra web y se copiaban a mano. Y de esos 106,
# JOIN solo tenia el telefono de 28 — el resto lo escribio en el CURRICULUM,
# no en el formulario. Por eso la sincronizacion baja el CV y busca el numero
# dentro, y lo marca (`telefono_de: "cv"`) para que se sepa de donde salio.
#
# Dos puertas y un mismo guardado (`_join_guardar`):
#  · la API, con el token de CADA EMPRESA guardado en su propia base. Un token
#    en un secret del servidor seria el de Dani para todas las empresas: la
#    segunda veria los candidatos de la primera (gotcha 26);
#  · el CSV que exporta JOIN, que no necesita token pero trae el CV como un
#    enlace de join.com que solo abre quien tenga sesion alli.
# La clave es el id de la candidatura de JOIN (`join_id`), con indice unico por
# oferta: sincronizar dos veces, o el CSV despues de la API, no duplica nada.

_JOIN_API = "https://api.join.com/v2"
_JOIN_META = "join_conexion"
_JOIN_TAREAS: set = set()

# Un telefono en un CV. Se busca por orden de fiabilidad y se para en el
# primero: (1) detras de una palabra que lo anuncia, (2) con prefijo
# internacional, (3) un movil español de 9 cifras suelto. Un fijo suelto NO:
# en un curriculum hay años seguidos («1998 2000 2003») que dan nueve cifras
# empezando por 9, y un numero inventado es peor que ninguno (gotcha 57).
_JOIN_TEL_ETIQUETA = re.compile(
    r"(?:tel[eé]?f?o?n?o?|tlf|tfno|m[oó]vil|movil|cel(?:ular)?|phone|mobile|whats ?app|contacto)"
    r"\s*[:.]?\s*((?:\+|00)?[\d][\d\s().-]{7,18}\d)", re.I)
_JOIN_TEL_PREFIJO = re.compile(r"(?<![\w+])((?:\+|00)\s?\d{1,3}[\s.-]?(?:\(?\d+\)?[\s.-]?){2,6}\d)")
_JOIN_TEL_MOVIL = re.compile(
    r"(?<![\d.,/-])([67]\d{2}(?:[\s.-]?\d{3}[\s.-]?\d{3}|[\s.-]?\d{2}[\s.-]?\d{2}[\s.-]?\d{2}))(?![\d.,/-])")


def _join_tel_de_texto(texto: str) -> str:
    """El telefono mas fiable que aparezca en el texto, limpio, o ""."""
    t = str(texto or "")
    for patron in (_JOIN_TEL_ETIQUETA, _JOIN_TEL_PREFIJO, _JOIN_TEL_MOVIL):
        for m in patron.finditer(t):
            bruto = m.group(1).strip()
            if bruto.startswith("00"):
                bruto = "+" + bruto[2:]
            tel = _telefono_limpio(bruto)
            dig = _telefono_digitos(tel)
            if not tel or len(dig) < 9:
                continue
            # Sin prefijo, un numero español tiene exactamente 9 cifras y
            # empieza por 6, 7, 8 o 9. Otra cosa sin «+» no se sabe de donde es.
            if not tel.startswith("+"):
                solo = re.sub(r"\D", "", tel)
                if solo.startswith("34") and len(solo) == 11:
                    solo = solo[2:]
                if len(solo) != 9 or solo[0] not in "6789":
                    continue
                tel = solo
            return tel
    return ""


def _join_texto_de_cv(contenido: bytes, nombre: str) -> str:
    """Texto de un CV en PDF. Word e imagenes se quedan sin leer (se dice)."""
    if not contenido or not (nombre.lower().endswith(".pdf") or contenido[:5] == b"%PDF-"):
        return ""
    try:
        import pdfplumber
        with pdfplumber.open(io.BytesIO(contenido)) as pdf:
            return "\n".join((p.extract_text() or "") for p in pdf.pages[:4])
    except Exception as e:
        logger.info("CV de JOIN sin texto legible: %s", e)
        return ""


def _join_fecha(valor) -> Optional[datetime]:
    """Fecha de JOIN: ISO de la API o «2026-09-04 11:24:38» del CSV."""
    s = str(valor or "").strip()
    if not s:
        return None
    for fmt in (None, "%Y-%m-%d %H:%M:%S", "%d/%m/%Y %H:%M", "%d/%m/%Y"):
        try:
            d = datetime.fromisoformat(s.replace("Z", "+00:00")) if fmt is None else datetime.strptime(s, fmt)
            return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
        except ValueError:
            continue
    return None


async def _join_oferta(oferta_id: str) -> dict:
    o = await db.ofertas_empleo.find_one({"id": str(oferta_id or "")}, {"_id": 0})
    if not o:
        raise HTTPException(404, "Esa oferta no existe")
    return o


async def _join_guardar(o: dict, cand: dict) -> str:
    """Guarda una candidatura de JOIN. Devuelve nuevo | completado | igual | repetido.

    Si ya estaba (mismo `join_id`) solo se RELLENA lo que faltaba —telefono y
    curriculum—: lo que la oficina haya escrito o movido no se toca nunca.
    """
    join_id = str(cand.get("join_id") or "").strip()
    if not join_id:
        return "igual"
    telefono = _telefono_limpio(cand.get("telefono"))
    ya = await db.candidatos.find_one({"oferta_id": o["id"], "join_id": join_id}, {"_id": 0})
    if ya:
        cambios = {}
        if telefono and not ya.get("telefono"):
            cambios.update(telefono=telefono, tel_clave=_telefono_digitos(telefono),
                           telefono_de=cand.get("telefono_de") or "join")
        for campo in ("cv_url", "cv_nombre", "cv_join_url", "email", "ciudad", "respuestas_join"):
            if cand.get(campo) and not ya.get(campo):
                cambios[campo] = cand[campo]
        if not cambios:
            return "igual"
        try:
            await db.candidatos.update_one({"id": ya["id"]}, {"$set": cambios})
        except DuplicateKeyError:
            # Ese telefono ya lo tiene otro candidato de la oferta (se apunto
            # tambien por nuestra pagina): se completa todo menos el numero.
            for k in ("telefono", "tel_clave", "telefono_de"):
                cambios.pop(k, None)
            if not cambios:
                return "repetido"
            await db.candidatos.update_one({"id": ya["id"]}, {"$set": cambios})
        return "completado"
    creado = _join_fecha(cand.get("creado_en")) or datetime.now(timezone.utc)
    doc = {
        "id": str(uuid.uuid4()),
        "oferta_id": o["id"], "oferta_titulo": o.get("titulo") or "",
        "nombre": _empleo_texto(cand.get("nombre"), 120),
        "telefono": telefono,
        "tel_clave": _telefono_digitos(telefono) if telefono else "",
        "telefono_de": (cand.get("telefono_de") or "join") if telefono else "",
        "email": _empleo_texto(cand.get("email"), 160).lower(),
        "ciudad": _empleo_texto(cand.get("ciudad"), 80),
        "centro": o.get("centro") or "",
        # Lo que JOIN no pregunta queda VACIO, que el panel pinta «no consta»
        # y no como un «no» (gotcha 33).
        "carnet_desde": "", "carnet_fisico": "", "dni": "",
        "nacimiento": "", "edad": None, "experiencia": "", "disponibilidad": "",
        "respuestas": {},
        "respuestas_join": cand.get("respuestas_join") or [],
        "origen": "join",
        "join_id": join_id,
        "fase": "nuevo", "motivo_descarte": "", "descarte_automatico": False,
        "notas": "", "driver_id": None,
        # La fecha de la candidatura, no la de hoy: «cuantos dias lleva sin que
        # nadie le llame» se cuenta desde que se apunto.
        "creado_en": creado.isoformat(),
        "importado_en": datetime.now(timezone.utc).isoformat(),
        "expira_en": creado + timedelta(days=30 * _EMPLEO_MESES_GUARDA),
    }
    for campo in ("cv_url", "cv_nombre", "cv_join_url"):
        if cand.get(campo):
            doc[campo] = cand[campo]
    try:
        await db.candidatos.insert_one(dict(doc))   # copia: insert_one muta (gotcha 42)
    except DuplicateKeyError:
        return "repetido"
    return "nuevo"


def _join_csv_filas(contenido: bytes) -> list:
    """Filas del CSV de JOIN. Acepta el original (UTF-8, comas) y el que ha
    pasado por Excel en español (punto y coma, y a veces Windows-1252)."""
    texto = None
    for cod in ("utf-8-sig", "cp1252"):
        try:
            texto = contenido.decode(cod)
            break
        except UnicodeDecodeError:
            continue
    if texto is None:
        raise HTTPException(400, "No se puede leer el fichero: guardalo como CSV")
    primera = texto.split("\n", 1)[0]
    sep = ";" if primera.count(";") > primera.count(",") else ("\t" if "\t" in primera else ",")
    filas = list(csv.DictReader(io.StringIO(texto), delimiter=sep))
    if not filas or "Application ID" not in filas[0]:
        raise HTTPException(400, "Ese fichero no parece la exportacion de candidatos de JOIN")
    return filas


@api_router.post("/empleo/join/csv")
async def empleo_join_csv(file: UploadFile = File(...), oferta_id: str = Form(...),
                          _=Depends(require_admin)):
    """Importa la exportacion de candidatos de JOIN a una oferta."""
    o = await _join_oferta(oferta_id)
    contenido = await file.read()
    if len(contenido) > 5 * 1024 * 1024:
        raise HTTPException(413, "El fichero no puede pasar de 5 MB")
    cuenta = {"nuevo": 0, "completado": 0, "igual": 0, "repetido": 0, "sin_telefono": 0}
    for f in _join_csv_filas(contenido):
        tel_bruto = (f.get("Telephone") or "").strip()
        # Excel convierte 584245064615 en «5,84245E+11»: ese numero ya no es el
        # suyo y se descarta en vez de guardar uno inventado.
        if re.search(r"[eE][+-]?\d", tel_bruto):
            tel_bruto = ""
        cand = {
            "join_id": (f.get("Application ID") or "").strip(),
            "nombre": " ".join(x for x in ((f.get("First Name") or "").strip(),
                                           (f.get("Last Name") or "").strip()) if x),
            "email": f.get("E-Mail Address"),
            "telefono": tel_bruto, "telefono_de": "join",
            "ciudad": f.get("Country of Residence") or "",
            "creado_en": f.get("Application Date"),
            "cv_join_url": (f.get("URL to CV") or "").strip(),
        }
        cand["cv_url"] = cand["cv_join_url"]
        r = await _join_guardar(o, cand)
        cuenta[r] += 1
        if not _telefono_limpio(tel_bruto):
            cuenta["sin_telefono"] += 1
    return {"ok": True, **cuenta}


async def _join_token() -> str:
    doc = await db.app_meta.find_one({"_id": _JOIN_META}, {"_id": 0, "token": 1})
    return (doc or {}).get("token") or ""


async def _join_pedir(cli, ruta: str, token: str, params: Optional[dict] = None):
    """GET a la API de JOIN respetando su limite (cabeceras x-ratelimit-*)."""
    for _intento in range(5):
        r = await cli.get(_JOIN_API + ruta, params=params or {}, headers={"Authorization": token})
        if r.status_code == 429:
            await asyncio.sleep(min(int(r.headers.get("x-ratelimit-reset") or 5), 30))
            continue
        if r.status_code == 401:
            raise HTTPException(400, "JOIN no acepta el token: genera uno nuevo en join.com/user/api")
        r.raise_for_status()
        return r
    raise HTTPException(503, "JOIN esta limitando las peticiones: prueba en un minuto")


@api_router.get("/empleo/join")
async def empleo_join_estado(_=Depends(require_admin)):
    """Si hay token (solo sus cuatro ultimos caracteres) y como fue la ultima sincronizacion."""
    doc = await db.app_meta.find_one({"_id": _JOIN_META}, {"_id": 0}) or {}
    token = doc.pop("token", "")
    return {"conectado": bool(token), "token_fin": token[-4:] if token else "", **doc}


@api_router.put("/empleo/join/token")
async def empleo_join_token(body: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda (o quita, con token vacio) el token de la API de JOIN de ESTA empresa."""
    token = _texto_cuerpo(body.get("token"))[:400]
    if not token:
        await db.app_meta.update_one({"_id": _JOIN_META}, {"$unset": {"token": ""}}, upsert=True)
        return {"ok": True, "conectado": False}
    import httpx as _httpx
    async with _httpx.AsyncClient(timeout=20) as cli:
        try:
            await _join_pedir(cli, "/jobs", token, {"pageSize": 1})
        except _httpx.HTTPError:
            raise HTTPException(502, "No se ha podido hablar con JOIN: prueba en un minuto")
    await db.app_meta.update_one(
        {"_id": _JOIN_META},
        {"$set": {"token": token, "conectado_en": datetime.now(timezone.utc).isoformat(),
                  "conectado_por": user.get("name") or user.get("username") or ""}},
        upsert=True)
    return {"ok": True, "conectado": True, "token_fin": token[-4:]}


@api_router.get("/empleo/join/ofertas")
async def empleo_join_ofertas(_=Depends(require_admin)):
    """Las ofertas que hay en JOIN, para elegir cual va a cada oferta nuestra."""
    token = await _join_token()
    if not token:
        raise HTTPException(400, "Primero conecta JOIN con su token")
    import httpx as _httpx
    trabajos = []
    async with _httpx.AsyncClient(timeout=20) as cli:
        for pagina in range(1, 11):
            try:
                r = await _join_pedir(cli, "/jobs", token, {
                    "page": pagina, "pageSize": 50, "status": "ONLINE,OFFLINE,ARCHIVED"})
            except _httpx.HTTPError:
                raise HTTPException(502, "No se ha podido hablar con JOIN: prueba en un minuto")
            lote = r.json() if isinstance(r.json(), list) else []
            trabajos += [{"id": j.get("id"), "titulo": j.get("title") or "",
                          "estado": str(j.get("status") or "").lower()}
                         for j in lote if isinstance(j, dict)]
            if len(lote) < 50:
                break
    return {"ofertas": trabajos}


async def _join_sincronizar(o: dict, job_id: Optional[int], token: str):
    """Baja las candidaturas (y sus CV) y las guarda. Va en segundo plano:
    con cien CV tarda minutos y una peticion web no puede esperar tanto."""
    import httpx as _httpx
    prog = {"en_marcha": True, "oferta_id": o["id"], "empezado": datetime.now(timezone.utc).isoformat(),
            "vistas": 0, "nuevo": 0, "completado": 0, "igual": 0, "repetido": 0,
            "tel_del_cv": 0, "sin_telefono": 0, "cv_guardados": 0, "error": ""}

    async def apuntar():
        await db.app_meta.update_one({"_id": _JOIN_META}, {"$set": {"sync": dict(prog)}}, upsert=True)

    s3 = get_r2()
    base_r2 = os.environ.get("R2_PUBLIC_URL", "").rstrip("/")
    try:
        async with _httpx.AsyncClient(timeout=45, follow_redirects=True) as cli:
            for pagina in range(1, 101):
                params = {"page": pagina, "pageSize": 50}
                if job_id:
                    params["jobId"] = job_id
                r = await _join_pedir(cli, "/applications", token, params)
                lote = r.json() if isinstance(r.json(), list) else []
                for a in lote:
                    if not isinstance(a, dict):
                        continue
                    prog["vistas"] += 1
                    c = a.get("candidate") or {}
                    cand = {
                        "join_id": str(a.get("id") or ""),
                        "nombre": " ".join(x for x in ((c.get("firstName") or "").strip(),
                                                       (c.get("lastName") or "").strip()) if x),
                        "email": c.get("email"),
                        "telefono": c.get("phoneNumber") or "", "telefono_de": "join",
                        "ciudad": ((c.get("country") or {}).get("name") or ""),
                        "creado_en": a.get("createdAt"),
                        # Lista y no diccionario: `respuestas` va por id de
                        # pregunta de NUESTRA oferta y estas son de la de JOIN.
                        "respuestas_join": [
                            {"pregunta": _empleo_texto(q.get("question"), 200),
                             "respuesta": _empleo_texto(q.get("answer"), 500)}
                            for q in (a.get("screeningQuestions") or [])
                            if isinstance(q, dict) and q.get("question") and q.get("type") != "FILE"],
                    }
                    ya = await db.candidatos.find_one(
                        {"oferta_id": o["id"], "join_id": cand["join_id"]},
                        {"_id": 0, "telefono": 1, "cv_url": 1, "cv_join_url": 1})
                    # El CV solo se baja si hace falta: si ya lo tenemos en R2 y
                    # el telefono tambien, no se vuelve a pedir.
                    necesita_cv = not (ya and ya.get("telefono") and ya.get("cv_url")
                                       and not ya.get("cv_join_url"))
                    adj = next((x for x in (a.get("attachments") or [])
                                if isinstance(x, dict) and x.get("type") in ("CV", "JOIN_CV") and x.get("url")), None)
                    if adj and necesita_cv:
                        try:
                            rc = await cli.get(adj["url"])
                            if rc.status_code == 401:
                                rc = await cli.get(adj["url"], headers={"Authorization": token})
                            if rc.status_code == 200 and rc.content and len(rc.content) <= _EMPLEO_CV_MAX:
                                nombre_cv = adj["url"].split("?")[0].rsplit("/", 1)[-1][:120] or "cv.pdf"
                                if not _telefono_limpio(cand["telefono"]):
                                    texto = await asyncio.get_running_loop().run_in_executor(
                                        _executor, _join_texto_de_cv, rc.content, nombre_cv)
                                    tel = _join_tel_de_texto(texto)
                                    if tel:
                                        cand.update(telefono=tel, telefono_de="cv")
                                        prog["tel_del_cv"] += 1
                                if s3:
                                    ext = nombre_cv.rsplit(".", 1)[-1].lower() if "." in nombre_cv else "pdf"
                                    clave_r2 = "cv/%s/%s.%s" % (o["id"], uuid.uuid4().hex,
                                                                re.sub(r"[^a-z0-9]", "", ext)[:5] or "pdf")
                                    await asyncio.get_running_loop().run_in_executor(
                                        _executor, lambda: s3.put_object(
                                            Bucket=R2_BUCKET, Key=clave_r2, Body=rc.content,
                                            ContentType="application/octet-stream"))
                                    cand["cv_url"] = ("%s/%s" % (base_r2, clave_r2)) if base_r2 else clave_r2
                                    cand["cv_nombre"] = nombre_cv
                                    prog["cv_guardados"] += 1
                        except Exception as e:
                            logger.info("CV de JOIN %s: %s", cand["join_id"], e)
                    resultado = await _join_guardar(o, cand)
                    # Un CV que ya estaba con el enlace de join.com (del CSV)
                    # se sustituye por el nuestro, que abre sin sesion.
                    if ya and ya.get("cv_join_url") and cand.get("cv_url"):
                        await db.candidatos.update_one(
                            {"oferta_id": o["id"], "join_id": cand["join_id"]},
                            {"$set": {"cv_url": cand["cv_url"], "cv_nombre": cand.get("cv_nombre", "")},
                             "$unset": {"cv_join_url": ""}})
                        if resultado == "igual":
                            resultado = "completado"
                    prog[resultado] += 1
                    if not _telefono_limpio(cand["telefono"]) and not (ya and ya.get("telefono")):
                        prog["sin_telefono"] += 1
                    if prog["vistas"] % 10 == 0:
                        await apuntar()
                if len(lote) < 50:
                    break
    except HTTPException as e:
        prog["error"] = e.detail
    except Exception as e:
        logger.warning("Sincronizacion con JOIN: %s", e)
        prog["error"] = "JOIN no ha respondido bien: prueba en un rato"
    prog["en_marcha"] = False
    prog["terminado"] = datetime.now(timezone.utc).isoformat()
    await apuntar()


@api_router.post("/empleo/join/sincronizar")
async def empleo_join_sincronizar(body: dict = Body(...), _=Depends(require_admin)):
    """Arranca la sincronizacion de una oferta de JOIN con una oferta nuestra."""
    o = await _join_oferta(_texto_cuerpo(body.get("oferta_id")))
    token = await _join_token()
    if not token:
        raise HTTPException(400, "Primero conecta JOIN con su token")
    job = str(body.get("job_id") or "").strip()
    job_id = int(job) if job.isdigit() else None
    # SIN job_id, `/applications` de JOIN devuelve TODOS los puestos juntos, y
    # aqui se guardarian TODOS bajo la oferta interna que se haya elegido —da
    # igual cual sea. Con dos o mas puestos reales en JOIN eso mezcla naves:
    # medido el 17-09-2026, 113 candidatos de la oferta de Santiago (OGA5)
    # acabaron tambien en la de A Coruna (DGA1) por sincronizar "Todas las
    # ofertas de JOIN" con DGA1 seleccionada. "Todas" solo tiene sentido
    # cuando de verdad hay UN puesto en JOIN y no hay nada que confundir.
    if job_id is None:
        import httpx as _httpx
        n_puestos = 0
        async with _httpx.AsyncClient(timeout=20) as cli:
            try:
                r = await _join_pedir(cli, "/jobs", token,
                                      {"page": 1, "pageSize": 2, "status": "ONLINE,OFFLINE,ARCHIVED"})
                n_puestos = len(r.json()) if isinstance(r.json(), list) else 0
            except _httpx.HTTPError:
                pass
        if n_puestos > 1:
            raise HTTPException(
                400, "Hay varios puestos en JOIN: elige a cuál de ellos van estos candidatos, "
                     "\"Todas las ofertas\" mezclaría naves.")
    # UNA A LA VEZ POR EMPRESA, y lo decide la base: dos clics seguidos no
    # pueden lanzar dos descargas de los mismos cien CV. Una que lleve mas de
    # media hora «en marcha» se da por muerta (reinicio del servidor).
    hace_media_hora = (datetime.now(timezone.utc) - timedelta(minutes=30)).isoformat()
    r = await db.app_meta.update_one(
        {"_id": _JOIN_META, "$or": [{"sync.en_marcha": {"$ne": True}},
                                    {"sync.empezado": {"$lt": hace_media_hora}}]},
        {"$set": {"sync": {"en_marcha": True, "oferta_id": o["id"], "vistas": 0,
                           "empezado": datetime.now(timezone.utc).isoformat()}}})
    if not r.matched_count:
        raise HTTPException(409, "Ya hay una sincronizacion con JOIN en marcha")
    # Se guarda la tarea: una que nadie referencia la puede recoger el
    # recolector de basura a medias.
    tarea = asyncio.create_task(_join_sincronizar(o, job_id, token))
    _JOIN_TAREAS.add(tarea)
    tarea.add_done_callback(_JOIN_TAREAS.discard)
    return {"ok": True}


# ── EL CANAL CON EL TALLER, EN LOS DOS SENTIDOS ─────────────────────────────
# Lo que sale (los recordatorios) ya existía. Lo que faltaba es lo que ENTRA:
# si el taller termina la reparación el martes y a nosotros no nos tocaba
# preguntar hasta el jueves, tiene que poder decirlo y que nos salte. Si no, la
# furgoneta pasa dos días parada en la puerta del taller estando lista — la peor
# de las esperas, porque no la ve nadie.
#
# Todo lo que dice un taller acaba en `taller_bandeja`, venga por donde venga:
# WhatsApp, el portal o alguien copiándolo a mano. Un solo sitio donde mirar.

SEG_COL_PLANTILLAS = "taller_plantillas"
SEG_COL_PAUTA = "taller_pauta"
SEG_COL_BANDEJA = "taller_bandeja"


async def _seg_pauta() -> dict:
    """La pauta de este DSP, o la de fábrica si todavía no la ha tocado nadie."""
    d = await db[SEG_COL_PAUTA].find_one({"_id": "pauta"}) or {}
    d.pop("_id", None)
    return seguimiento.normaliza_pauta(d)


async def _seg_plantillas() -> dict:
    """{clave: texto}. Las de fábrica se siembran la primera vez.

    Se siembran en la BD en vez de leerlas del código cada vez para que se
    puedan EDITAR: si el texto viviera solo en el fichero, cambiarlo sería un
    despliegue, y entonces nadie lo cambiaría nunca.
    """
    hay = await db[SEG_COL_PLANTILLAS].count_documents({})
    if not hay:
        try:
            # `ordered=False` + tragarse el duplicado: entre el `count` y este
            # insert cabe otra peticion, y en una empresa nueva eso pasa el
            # primer dia —dos personas abriendo Ordenes de taller a la vez, o
            # un clic justo cuando corre el bucle de seguimiento—. La segunda
            # reventaba con BulkWriteError y salia un 500 en la cara del
            # cliente; que la plantilla ya exista es exactamente lo que se
            # queria conseguir, asi que no es un error. Es lo mismo que el
            # gotcha 32: un cerrojo que revienta es peor que no tenerlo.
            await db[SEG_COL_PLANTILLAS].insert_many([
                {"_id": p["clave"], "clave": p["clave"], "nombre": p["nombre"],
                 "texto": p["texto"], "orden": p["orden"], "de_fabrica": True,
                 "creada_en": _ot_ahora()}
                for p in seguimiento.PLANTILLAS_BASE], ordered=False)
        except (DuplicateKeyError, BulkWriteError):
            pass
    out = {}
    async for p in db[SEG_COL_PLANTILLAS].find({}, {"_id": 0}):
        out[p.get("clave")] = p
    return out


async def _seg_apunta(orden: dict, direccion: str, texto: str, canal: str,
                      extra: dict = None) -> str:
    """Guarda un mensaje en la bandeja y devuelve su id.

    `orden` puede ser None: un mensaje que no se sabe de qué furgoneta habla NO
    SE TIRA. Perder lo que dice un taller es exactamente el silencio que este
    canal viene a quitar, y un mensaje sin clasificar sigue siendo información.
    """
    doc = {
        "id": str(uuid.uuid4()),
        "orden_id": (orden or {}).get("id"),
        "numero": (orden or {}).get("numero"),
        "matricula": (orden or {}).get("matricula"),
        "taller_id": (orden or {}).get("taller_id"),
        "taller_nombre": (orden or {}).get("taller_nombre"),
        "direccion": direccion,            # "salida" (nosotros) | "entrada" (ellos)
        "canal": canal,                    # whatsapp | portal | oficina
        "texto": (texto or "").strip(),
        "at": _ot_ahora(),
        "leido": direccion == "salida",    # lo que mandamos ya está visto
    }
    doc.update(extra or {})
    await db[SEG_COL_BANDEJA].insert_one(doc)
    return doc["id"]


async def _portal_apunta(orden: dict, texto: str) -> None:
    """Lo que el taller hace EN EL PORTAL, a la bandeja del DSP.

    Sin esto, «Lo que dicen los talleres» solo se llenaba con los WhatsApp
    entrantes —lo unico que llamaba a `registrar_novedad_taller`—, y por el
    portal, que es el enlace que les mandamos y el unico camino que funciona
    mientras Meta siga sin aprobar el numero, no entraba nada. La pantalla que
    promete enseñar lo que dicen los talleres estaba vacia siempre.

    No avisa ni para el reloj: de eso ya se encargan `_ot_avisa` y
    `ultima_novedad_taller` en cada endpoint del portal. Aqui solo se APUNTA,
    para no mandar dos avisos por lo mismo.

    Y no puede tumbar la accion del taller: si el apunte falla, lo que el
    taller acaba de decir ya esta guardado en la orden. Perder la linea de la
    bandeja es malo; perder el cambio de estado, peor.
    """
    try:
        await _seg_apunta(orden, "entrada", texto, "portal",
                          {"taller_id": orden.get("workshop_id") or orden.get("taller_id")})
    except Exception as e:
        logger.warning("No se pudo apuntar en la bandeja la novedad del portal: %s", e)


async def registrar_novedad_taller(orden: dict, texto: str, canal: str,
                                   extra: dict = None) -> dict:
    """Una novedad del taller: se guarda, PARA EL RELOJ y nos avisa.

    Las tres cosas juntas y en este orden. Parar el reloj es lo que evita que se
    le siga escribiendo a un taller que acaba de contestar —la forma más rápida
    de que dejen de leernos—, y por eso se hace aunque el aviso falle.
    """
    ida = await _seg_apunta(orden, "entrada", texto, canal, extra)
    pista = seguimiento.pista_de_estado(texto)

    if orden and orden.get("id"):
        await db.ordenes_trabajo.update_one(
            {"id": orden["id"]},
            {"$set": {"ultima_novedad_taller": _ot_ahora(),
                      # Los toques se ponen a cero: si vuelve a callarse dentro
                      # de un mes, el ciclo empieza otra vez por el mensaje
                      # amable y no por el «es el cuarto mensaje sin respuesta».
                      "toques": 0},
             "$push": {"historial": _ot_apunte(
                 "novedad_taller", "El taller ha escrito",
                 (texto or "")[:300])}})

    # Y que nos salte. Sin esto lo anterior es un buzón que nadie abre.
    cab = "🔧 %s%s" % (
        (orden or {}).get("matricula") or "Una furgoneta",
        " · %s" % (orden or {}).get("numero") if (orden or {}).get("numero") else "")
    cuerpo = [cab, (texto or "").strip()[:600]]
    if not orden:
        cuerpo.append("⚠️ No se ha podido saber de qué furgoneta hablan: "
                      "míralo en la bandeja del taller.")
    elif pista == "listo":
        cuerpo.append("Parece que está LISTA para recoger.")
    elif pista == "esperando_piezas":
        cuerpo.append("Parece que están esperando piezas.")
    try:
        await _telegram_aviso("\n".join(x for x in cuerpo if x))
    except Exception as e:                                       # noqa: BLE001
        logger.warning("aviso de novedad de taller: %s", e)

    return {"bandeja_id": ida, "pista": pista,
            "orden": (orden or {}).get("numero"), "reloj_reiniciado": bool(orden)}


# ── INFORME PARA AMAZON ─────────────────────────────────────────────────────
# Amazon le exige a un DSP poder demostrar la cadena entera de un defecto:
# detectado -> registrado -> llevado a taller -> reparado -> vehiculo de vuelta.
# En la practica casi ningun DSP puede probar ni el primer eslabon, porque la
# inspeccion diaria se firma en papel o en una app que no guarda la foto.
#
# Nosotros SI podemos: 3.803 inspecciones en 90 dias, el 100 % con foto y el
# 99 % con el conductor identificado, una por furgoneta y dia. Eso es el DVIC
# que piden, con prueba.
#
# Y lo que NO podemos demostrar se DICE. El apartado `lagunas` no es un descargo
# de responsabilidad: es lo que hace creible el resto. Un informe que rellena
# huecos se cae en la primera pregunta; uno que separa lo probado de lo que
# falta aguanta que lo miren con lupa, que es justo lo que va a pasar.

EXPORT_VERSION = "1.0"


def _pct(n, total):
    return round(n / total * 100, 1) if total else None


@api_router.get("/taller/export")
async def taller_export(desde: str = "", hasta: str = "", center: str = "",
                        formato: str = "json", _=Depends(require_admin)):
    """Trazabilidad de flota y taller, en formato estable para entregar."""
    hoy = datetime.now(timezone.utc).date()

    def _dia(v, defecto):
        """Una fecha 'YYYY-MM-DD' de verdad, o el valor por defecto.

        Sin esto, `?desde=loquesea` reventaba en el `strptime` de mas abajo y
        salia un 500. Da igual que sea un parametro tonto: este endpoint lo
        consume AMAZON por su cuenta, y una tuberia que devuelve 500 porque
        alguien escribio mal una fecha deja de ser fiable el primer dia.
        Se ignora lo que no se entiende en vez de rechazar la peticion: quien
        pide un informe quiere el informe, no una leccion de formatos.
        """
        s = str(v or "")[:10]
        try:
            # Se devuelve REFORMATEADA, no la cadena de entrada: `strptime`
            # acepta '2026-2-3' sin ceros, y las fechas se comparan como TEXTO
            # en Mongo — '2026-2-3' es mayor que '2026-12-01' en ese orden. El
            # rango saldria mal sin dar ningun error.
            return datetime.strptime(s, "%Y-%m-%d").strftime("%Y-%m-%d")
        except ValueError:
            return defecto

    d_hasta = _dia(hasta, hoy.strftime("%Y-%m-%d"))
    d_desde = _dia(desde, (hoy - timedelta(days=90)).strftime("%Y-%m-%d"))
    if d_desde > d_hasta:
        d_desde, d_hasta = d_hasta, d_desde

    centro = ""
    if center and center not in ("Todos", "todos"):
        centro = _centro_norm(center, await _centros_conocidos())
    qv: dict = {"status": {"$nin": ["deleted"]}}
    if centro:
        qv["center"] = {"$regex": re.escape(centro), "$options": "i"}
    vehiculos = await db.vehicles.find(
        qv, {"_id": 0, "id": 1, "license_plate": 1, "brand": 1, "model": 1,
             "status": 1, "itv_date": 1, "center": 1}).to_list(1000)
    vids = [v["id"] for v in vehiculos]
    porplaca = {v["id"]: (v.get("license_plate") or v["id"]) for v in vehiculos}

    # ── 1. La inspeccion diaria (el DVIC) ────────────────────────────────────
    insp_por_veh: dict = {}
    insp_dias: dict = {}
    n_insp = n_foto = n_cond = 0
    async for i in db.inspections.find(
            {"vehicle_id": {"$in": vids},
             "created_at": {"$gte": d_desde, "$lte": d_hasta + "T23:59:59Z"}},
            {"_id": 0, "vehicle_id": 1, "created_at": 1, "driver_id": 1,
             "photos": 1, "annotated_photos": 1}):
        n_insp += 1
        dia = str(i.get("created_at") or "")[:10]
        insp_por_veh.setdefault(i["vehicle_id"], set()).add(dia)
        insp_dias.setdefault(dia, set()).add(i["vehicle_id"])
        if (i.get("photos") or i.get("annotated_photos")):
            n_foto += 1
        if i.get("driver_id"):
            n_cond += 1

    # ── 2. Los defectos ──────────────────────────────────────────────────────
    defectos = await db.vehicle_damage_ledger.find(
        {"vehicle_id": {"$in": vids},
         "first_seen": {"$gte": d_desde, "$lte": d_hasta},
         "status": {"$nin": ["archived", "descartada", "deleted"]}},
        {"_id": 1, "vehicle_id": 1, "part": 1, "severity": 1, "status": 1,
         "first_seen": 1, "orden_id": 1, "source": 1}).to_list(5000)
    por_grav: dict = {}
    def_por_veh: dict = {}
    con_orden = reparados = 0
    for d in defectos:
        por_grav[d.get("severity") or "sin clasificar"] = \
            por_grav.get(d.get("severity") or "sin clasificar", 0) + 1
        def_por_veh.setdefault(d.get("vehicle_id"), []).append(d)
        if d.get("orden_id"):
            con_orden += 1
        if d.get("status") == "repaired":
            reparados += 1

    # ── 3. El taller: ordenes y conversacion ─────────────────────────────────
    ordenes = await db.ordenes_trabajo.find(
        {"vehicle_id": {"$in": vids}}, {"_id": 0}).to_list(2000)
    ords_periodo = [o for o in ordenes
                    if d_desde <= str(o.get("creada_en") or "")[:10] <= d_hasta]
    avisos = await db[SEG_COL_BANDEJA].count_documents(
        {"direccion": "salida", "at": {"$gte": d_desde, "$lte": d_hasta + "T23:59:59Z"}})
    respuestas = await db[SEG_COL_BANDEJA].count_documents(
        {"direccion": "entrada", "at": {"$gte": d_desde, "$lte": d_hasta + "T23:59:59Z"}})

    # Cuanto tarda un taller en contestar. Es la metrica que convierte esto en
    # un proveedor medido y no en una lista de telefonos.
    tiempos = []
    for o in ordenes:
        c, r = o.get("creada_en"), o.get("ultima_novedad_taller")
        if c and r:
            try:
                h = (datetime.fromisoformat(str(r).replace("Z", "+00:00"))
                     - datetime.fromisoformat(str(c).replace("Z", "+00:00"))).total_seconds() / 3600
                if h >= 0:
                    tiempos.append(round(h, 1))
            except Exception:                                # noqa: BLE001
                pass

    # ── 4. Por vehiculo ──────────────────────────────────────────────────────
    dias_periodo = (datetime.strptime(d_hasta, "%Y-%m-%d")
                    - datetime.strptime(d_desde, "%Y-%m-%d")).days + 1
    filas = []
    for v in sorted(vehiculos, key=lambda x: porplaca.get(x["id"], "")):
        ds = def_por_veh.get(v["id"]) or []
        dias_insp = len(insp_por_veh.get(v["id"]) or ())
        filas.append({
            "matricula": porplaca[v["id"]],
            "marca": v.get("brand") or "", "modelo": v.get("model") or "",
            "estado": v.get("status") or "",
            "itv": str(v.get("itv_date") or "")[:10] or None,
            "dias_con_inspeccion": dias_insp,
            "cobertura_pct": _pct(dias_insp, dias_periodo),
            "defectos": len(ds),
            "defectos_graves": sum(1 for d in ds if d.get("severity") in ("grave", "critico")),
            "defectos_abiertos": sum(1 for d in ds if d.get("status") == "open"),
            "ordenes_taller": sum(1 for o in ordenes if o.get("vehicle_id") == v["id"]),
        })

    # ── 5. LO QUE NO SE PUEDE DEMOSTRAR ──────────────────────────────────────
    # Va en el informe, con su motivo. Es lo que hace creible lo demas.
    lagunas = []
    if defectos and not con_orden:
        lagunas.append({
            "que": "Ningún defecto del periodo tiene orden de taller asociada",
            "de": len(defectos),
            "porque": "Las reparaciones se están gestionando fuera de la aplicación "
                      "(teléfono y correo), así que no queda registro de cuál se "
                      "reparó ni cuándo.",
            "efecto": "Este informe demuestra la DETECCIÓN de defectos, no su reparación.",
        })
    sin_itv = [f for f in filas if not f["itv"] and f["estado"] == "active"]
    if sin_itv:
        lagunas.append({
            "que": "Furgonetas activas sin fecha de ITV registrada",
            "de": len(sin_itv),
            "porque": "El dato no está cargado en la aplicación.",
            "efecto": "De esas no se puede acreditar que estén en regla.",
        })
    baja_cob = [f for f in filas if f["estado"] == "active" and (f["cobertura_pct"] or 0) < 50]
    if baja_cob:
        lagunas.append({
            "que": "Furgonetas activas con menos del 50 % de días inspeccionados",
            "de": len(baja_cob),
            "porque": "O no salieron a ruta esos días, o la inspección no se registró.",
            "efecto": "La cobertura de inspección no es completa para esas unidades.",
        })

    informe = {
        "informe": {
            "version": EXPORT_VERSION,
            "generado": datetime.now(timezone.utc).isoformat(),
            "desde": d_desde, "hasta": d_hasta, "dias": dias_periodo,
            "centro": centro or "todos",
            "alcance": "Inspección diaria de vehículo, defectos detectados y "
                       "gestión de taller.",
        },
        "inspeccion_diaria": {
            "inspecciones": n_insp,
            "con_fotografia": n_foto, "con_fotografia_pct": _pct(n_foto, n_insp),
            "con_conductor_identificado": n_cond,
            "con_conductor_pct": _pct(n_cond, n_insp),
            "vehiculos_en_flota": len(vehiculos),
            "vehiculos_inspeccionados": len(insp_por_veh),
            "dias_con_actividad": len(insp_dias),
            "media_vehiculos_por_dia": round(
                sum(len(s) for s in insp_dias.values()) / max(len(insp_dias), 1), 1),
        },
        "defectos": {
            "detectados": len(defectos),
            "por_gravedad": por_grav,
            "con_orden_de_taller": con_orden,
            "con_orden_pct": _pct(con_orden, len(defectos)),
            "reparados": reparados,
            "abiertos": sum(1 for d in defectos if d.get("status") == "open"),
            "origen": {"deteccion_automatica": sum(1 for d in defectos if d.get("source") == "ai"),
                       "revision_humana": sum(1 for d in defectos if d.get("source") == "human")},
        },
        "taller": {
            "ordenes_en_el_periodo": len(ords_periodo),
            "ordenes_totales": len(ordenes),
            "avisos_enviados": avisos,
            "respuestas_recibidas": respuestas,
            "tiempo_medio_respuesta_h": round(sum(tiempos) / max(len(tiempos), 1), 1) if tiempos else None,
        },
        "vehiculos": filas,
        "lagunas": lagunas,
    }

    if (formato or "").lower() != "csv":
        return informe

    # CSV por vehiculo: es lo que se abre en Excel y se manda por correo. Las
    # cifras de cabecera van en las primeras filas para que el fichero se
    # entienda solo, sin el JSON al lado.
    import csv
    from fastapi import Response
    cab = ["matricula", "marca", "modelo", "estado", "itv", "dias_con_inspeccion",
           "cobertura_pct", "defectos", "defectos_graves", "defectos_abiertos",
           "ordenes_taller"]
    out = io.StringIO()
    w = csv.writer(out, delimiter=";")
    w.writerow(["FlotaDSP · informe de flota y taller", "v" + EXPORT_VERSION])
    w.writerow(["Periodo", "%s a %s" % (d_desde, d_hasta), "Centro", centro or "todos"])
    w.writerow(["Inspecciones", n_insp, "Con fotografia",
                "%s%%" % _pct(n_foto, n_insp), "Con conductor",
                "%s%%" % _pct(n_cond, n_insp)])
    w.writerow(["Defectos detectados", len(defectos), "Con orden de taller", con_orden,
                "Reparados", reparados])
    for lg in lagunas:
        w.writerow(["LIMITACION", lg["que"], lg["de"], lg["porque"]])
    w.writerow([])
    w.writerow(cab)
    for f in filas:
        w.writerow([f.get(k) if f.get(k) is not None else "" for k in cab])
    return Response(
        content=out.getvalue().encode("utf-8-sig"),      # BOM: Excel y las tildes
        media_type="text/csv; charset=utf-8",
        headers={"Content-Disposition":
                 'attachment; filename="flotadsp_%s_%s_%s.csv"'
                 % (centro or "todos", d_desde, d_hasta)})


# ── ACCESO PARA AMAZON ──────────────────────────────────────────────────────
# Lo que de verdad le importa a quien audita un DSP no es ver una pantalla: es
# poder sacar el dato a SUS sistemas, cuando quiera, sin depender de que alguien
# se lo mande. Un informe que hay que pedir por correo no es trazabilidad.
#
# Esto es esa vía, y está construida asumiendo tres cosas que no son negociables
# cuando le abres tus datos a un tercero:
#
#   1. El token se guarda HASHEADO. Si alguien se lleva la base de datos, no se
#      lleva las llaves. Se enseña UNA vez, al crearlo, y no vuelve a verse.
#   2. Solo lectura y con alcance. Un token de flota no abre nada más.
#   3. Cada consulta queda registrada. El DSP tiene que poder ver qué le han
#      mirado y cuándo — la transparencia va en los dos sentidos o no es
#      transparencia.
#
# Y NO SALE UN SOLO DATO PERSONAL. Ni nombres de conductores, ni teléfonos, ni
# quién conducía cuándo. Amazon audita la flota y el cumplimiento, no a las
# personas; mandarle nombres sería entregar datos de un tercero que no lo ha
# consentido, y además no lo ha pedido nadie.

PARTNER_COL = "partner_tokens"
PARTNER_ACCESOS = "partner_accesos"
PARTNER_SCOPES = ("flota",)
PARTNER_DIAS_DEF = 365


def _partner_hash(tok: str) -> str:
    return hashlib.sha256(("flotadsp-partner:" + str(tok or "")).encode()).hexdigest()


@api_router.post("/partner/tokens")
async def partner_crear_token(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Crea una llave de solo lectura para un tercero. Se enseña UNA vez."""
    nombre = str(data.get("partner") or "").strip()
    if not nombre:
        raise HTTPException(400, "Dile de quién es la llave (por ejemplo, «Cliente Norte»)")
    scopes = [s for s in (_lista_cuerpo(data.get("scopes")) or ["flota"])
              if s in PARTNER_SCOPES] or ["flota"]
    dias = _entero(data.get("dias"), "dias", defecto=PARTNER_DIAS_DEF, minimo=1, maximo=1095)
    centro = str(data.get("center") or "").strip()

    crudo = "fd_" + secrets.token_urlsafe(32)
    doc = {
        "id": str(uuid.uuid4()),
        "partner": nombre,
        "token_hash": _partner_hash(crudo),
        "db_name": _current_db_name.get(),
        "center": centro,
        "scopes": scopes,
        "creado_en": datetime.now(timezone.utc).isoformat(),
        "creado_por": user.get("name") or user.get("username") or "oficina",
        "expira_en": (datetime.now(timezone.utc) + timedelta(days=dias)).isoformat(),
        "revocado": False,
        "accesos": 0,
        "ultimo_uso": None,
    }
    await global_db[PARTNER_COL].insert_one(doc)
    logger.info("Llave de partner creada para %s (%d días)", nombre, dias)
    return {
        # La única vez que se ve. A partir de aquí solo existe su hash.
        "token": crudo,
        "aviso": "Cópiala ahora: no se puede volver a ver. Si se pierde, se revoca y se hace otra.",
        "id": doc["id"], "partner": nombre, "scopes": scopes,
        "expira_en": doc["expira_en"],
        "como_se_usa": "curl -H 'X-FlotaDSP-Key: <token>' %s/api/partner/v1/flota"
                       % os.environ.get("PUBLIC_BASE_URL", "https://flotadsp-backend.fly.dev"),
    }


@api_router.get("/partner/tokens")
async def partner_listar_tokens(_=Depends(require_admin)):
    """Las llaves entregadas y lo que han consultado. Nunca el token."""
    filas = await global_db[PARTNER_COL].find(
        {"db_name": _current_db_name.get()},
        {"_id": 0, "token_hash": 0}).sort("creado_en", -1).to_list(100)
    ahora = datetime.now(timezone.utc).isoformat()
    for f in filas:
        f["caducada"] = str(f.get("expira_en") or "") < ahora
        f["activa"] = not f.get("revocado") and not f["caducada"]
    return {"llaves": filas}


@api_router.delete("/partner/tokens/{token_id}")
async def partner_revocar_token(token_id: str, _=Depends(require_admin)):
    """Corta el acceso. No se borra la llave: se marca, para que quede el rastro
    de que existió y de lo que consultó mientras estuvo viva."""
    r = await global_db[PARTNER_COL].update_one(
        {"id": token_id, "db_name": _current_db_name.get()},
        {"$set": {"revocado": True,
                  "revocado_en": datetime.now(timezone.utc).isoformat()}})
    if not r.matched_count:
        raise HTTPException(404, "No existe esa llave")
    return {"ok": True, "revocada": token_id}


@api_router.get("/partner/accesos")
async def partner_ver_accesos(limite: int = 100, _=Depends(require_admin)):
    """Qué han consultado y cuándo. La transparencia va en los dos sentidos."""
    filas = await global_db[PARTNER_ACCESOS].find(
        {"db_name": _current_db_name.get()}, {"_id": 0}).sort(
        "at", -1).to_list(max(1, min(limite, 500)))
    return {"accesos": filas, "total": len(filas)}


async def _partner_auth(request: Request, scope: str) -> dict:
    """Valida la llave del tercero y deja la BD del DSP fijada.

    Gotcha 26: este camino NO tiene sesión de usuario. `db` sin
    `set_current_org_db` caería en la base por defecto, y el día que haya un
    segundo cliente, la llave de un DSP leería los datos de otro. El `db_name`
    va DENTRO de la llave y se fija aquí a mano.
    """
    tok = (request.headers.get("X-FlotaDSP-Key")
           or request.headers.get("x-flotadsp-key") or "").strip()
    if not tok:
        raise HTTPException(401, "Falta la cabecera X-FlotaDSP-Key")
    doc = await global_db[PARTNER_COL].find_one({"token_hash": _partner_hash(tok)})
    if not doc or doc.get("revocado"):
        # Mismo mensaje para una llave que no existe y una revocada: distinguirlas
        # le diría a quien prueba llaves cuáles existieron.
        raise HTTPException(401, "Llave no válida")
    if str(doc.get("expira_en") or "") < datetime.now(timezone.utc).isoformat():
        raise HTTPException(401, "Llave caducada")
    if scope not in (doc.get("scopes") or []):
        raise HTTPException(403, "Esta llave no da acceso a %s" % scope)
    set_current_org_db(doc.get("db_name") or _DEFAULT_DB_NAME)
    return doc


async def _partner_apunta(doc: dict, request: Request, recurso: str, params: dict):
    """Deja constancia de la consulta. Que falle no puede tumbar la respuesta."""
    try:
        await global_db[PARTNER_ACCESOS].insert_one({
            "at": datetime.now(timezone.utc).isoformat(),
            "partner": doc.get("partner"), "token_id": doc.get("id"),
            "db_name": doc.get("db_name"), "recurso": recurso, "params": params,
            "ip": (request.client.host if request.client else None),
            # 90 días: es un registro de auditoría, no un histórico eterno.
            "expira_en": datetime.now(timezone.utc) + timedelta(days=90),
        })
        await global_db[PARTNER_COL].update_one(
            {"id": doc.get("id")},
            {"$set": {"ultimo_uso": datetime.now(timezone.utc).isoformat()},
             "$inc": {"accesos": 1}})
    except Exception as e:                                       # noqa: BLE001
        logger.warning("registro de acceso de partner: %s", e)


@api_router.get("/partner/v1/flota")
async def partner_flota(request: Request, desde: str = "", hasta: str = "",
                        formato: str = "json"):
    """Trazabilidad de flota y taller, para un tercero autorizado.

    Misma información que ve el DSP, sin un solo dato personal. La versión va en
    la ruta (`/v1/`) a propósito: quien conecte esto a un proceso automático
    tiene que poder confiar en que las columnas no cambian de un día para otro.
    """
    doc = await _partner_auth(request, "flota")
    centro = doc.get("center") or ""
    await _partner_apunta(doc, request, "flota",
                          {"desde": desde, "hasta": hasta, "formato": formato})
    datos = await taller_export(desde=desde, hasta=hasta, center=centro,
                                formato=formato, _=None)
    if not isinstance(datos, dict):
        return datos                                   # el CSV sale tal cual
    datos["informe"]["emitido_para"] = doc.get("partner")
    datos["informe"]["contiene_datos_personales"] = False
    return datos


