@api_router.post("/taller/bandeja/{mensaje_id}/asignar")
async def taller_bandeja_asignar(mensaje_id: str, data: dict = Body(...),
                                 _=Depends(require_admin)):
    """Decir a mano de qué orden hablaba un mensaje que no se pudo clasificar."""
    m = await db[SEG_COL_BANDEJA].find_one({"id": mensaje_id}, {"_id": 0})
    if not m:
        raise HTTPException(404, "No existe ese mensaje")
    o = await db.ordenes_trabajo.find_one({"id": data.get("orden_id")}, {"_id": 0})
    if not o:
        raise HTTPException(404, "No existe esa orden")
    await db[SEG_COL_BANDEJA].update_one(
        {"id": mensaje_id},
        {"$set": {"orden_id": o["id"], "numero": o.get("numero"),
                  "matricula": o.get("matricula"), "leido": True,
                  "asignado_a_mano": True}})
    # Al asignarlo cuenta como novedad de esa orden: hasta ahora el reloj de esa
    # furgoneta seguía corriendo porque nadie sabía que el taller había escrito.
    await db.ordenes_trabajo.update_one(
        {"id": o["id"]},
        {"$set": {"ultima_novedad_taller": _ot_ahora(), "toques": 0},
         "$push": {"historial": _ot_apunte(
             "novedad_taller", "Mensaje del taller asignado a mano",
             (m.get("texto") or "")[:300])}})
    return {"ok": True, "orden": o.get("numero")}


@api_router.get("/taller/pauta")
async def taller_pauta_get(_=Depends(require_admin)):
    """Cada cuánto se pregunta, qué días y con qué mensajes."""
    pauta = await _seg_pauta()
    plantillas = await _seg_plantillas()
    # Se enseña CUÁNDO le toca a cada orden, no solo la regla: «el próximo el
    # jueves» se entiende y «cada 3 días» se cambia a ciegas.
    from zoneinfo import ZoneInfo
    ahora = datetime.now(ZoneInfo("Europe/Madrid"))
    proximos = []
    async for o in db.ordenes_trabajo.find(
            {"estado": {"$in": list(seguimiento.ESTADOS_QUE_SE_SIGUEN)}},
            {"_id": 0, "id": 1, "numero": 1, "matricula": 1, "estado": 1,
             "toques": 1, "ultimo_toque": 1, "ultima_novedad_taller": 1,
             "creada_en": 1, "taller_nombre": 1}):
        p = seguimiento.proximo_aviso(o, pauta, ahora)
        toca, motivo = seguimiento.toca_preguntar(o, pauta, ahora)
        proximos.append({
            "numero": o.get("numero"), "matricula": o.get("matricula"),
            "taller": o.get("taller_nombre"), "toques": int(o.get("toques") or 0),
            "proximo": p.strftime("%Y-%m-%d %H:%M") if p else None,
            "toca_ahora": toca, "motivo": motivo,
        })
    proximos.sort(key=lambda x: x["proximo"] or "9999")
    return {"pauta": pauta, "plantillas": sorted(
        plantillas.values(), key=lambda p: p.get("orden") or 0),
        "variables": seguimiento.VARIABLES, "proximos": proximos,
        "es_hora_ahora": seguimiento.es_hora(pauta, ahora)}


@api_router.patch("/taller/pauta")
async def taller_pauta_set(data: dict = Body(...), _=Depends(require_admin)):
    """Cambiar la cadencia. Se normaliza SIEMPRE antes de guardar."""
    p = seguimiento.normaliza_pauta({**(await _seg_pauta()), **(data or {})})
    await db[SEG_COL_PAUTA].update_one(
        {"_id": "pauta"}, {"$set": {**p, "actualizada_en": _ot_ahora()}}, upsert=True)
    return {"pauta": p}


@api_router.patch("/taller/plantillas/{clave}")
async def taller_plantilla_set(clave: str, data: dict = Body(...),
                               _=Depends(require_admin)):
    """Editar un mensaje. Avisa de las variables que no existen."""
    await _seg_plantillas()                       # siembra si hace falta
    texto = str(data.get("texto") or "")
    if not texto.strip():
        raise HTTPException(400, "El mensaje no puede quedar vacío")
    # No se rechaza: se avisa. Una variable de más no rompe nada —sale en
    # blanco— y bloquear el guardado por eso hace que se edite en un bloc de
    # notas y se pegue, que es peor.
    desconocidas = [v for v in seguimiento.variables_de(texto)
                    if v not in seguimiento.VARIABLES]
    r = await db[SEG_COL_PLANTILLAS].update_one(
        {"clave": clave},
        {"$set": {"texto": texto, "nombre": data.get("nombre") or clave,
                  "editada_en": _ot_ahora()}}, upsert=True)
    return {"ok": True, "clave": clave, "desconocidas": desconocidas,
            "ejemplo": seguimiento.render(texto, seguimiento.contexto(
                {"matricula": "1234 ABC", "numero": "OT-1001",
                 "taller_nombre": "Talleres Muñiz",
                 "problema": "golpe en la puerta corredera derecha",
                 "fecha_entrega_estimada": "2026-09-05"},
                "https://flotadsp.com/taller/ejemplo", 5)),
            "creada": bool(r.upserted_id)}


SEG_CADA_MIN = 30        # cada cuanto se mira si a alguien le toca


# ═══════════════════════════════════════════════════════════════════════════
# LA IA SE REVISA SOLA
# ═══════════════════════════════════════════════════════════════════════════
# El 02-09-2026 habia 2.324 inspecciones "sin mirar" y 2.219 de ellas (95 %)
# NO tenian ningun daño nuevo: no habia nada que decidir y aun asi esperaban
# un clic de una persona. De las 105 restantes, el puntuador de fiabilidad ya
# sabia decir con un 90 % de acierto medido cuales eran reales y cuales
# inventadas (fiabilidad.py), pero nadie actuaba sobre ese veredicto: solo
# servia para ORDENAR la cola. Dani no quiere revisar; quiere que la IA se
# corrija sola y le deje solo lo que no tiene claro.
#
# Reglas, y por que:
#   · Sin daños nuevos que decidir -> revisada por la IA. No hay pregunta.
#   · Todos los daños nuevos en los extremos (confirmado >= 0,75 o descartado
#     < 0,15) -> la IA aplica sus veredictos IGUAL que una persona (el
#     descartado sale del libro de daños) y cierra la inspeccion.
#   · Alguno dudoso -> se queda para una persona, con la puntuacion guardada
#     en el daño para que la pantalla diga cual es la duda.
#   · Lo que decide la IA NUNCA entra en `ai_feedback`: el modelo se
#     reentrena solo con veredictos humanos. Si la IA se diera la razon a si
#     misma, los porcentajes subirian y el modelo iria a peor sin que nadie se
#     enterara (probar_autovalidacion.py).
# Queda `reviewed_by: "ia"` y `reviewed_motivo`, asi que se puede filtrar,
# auditar y deshacer.

def _autorrevision_decision(veredictos: list) -> str:
    """'auto' si la IA puede cerrar sola la inspeccion; 'humano' si no.

    Sin daños que decidir es 'auto' (no hay pregunta). Con daños, solo si
    TODOS son confirmado o descartado; un solo dudoso —o un None, que es
    "sin modelo todavia"— y la decision es de una persona.
    """
    if not veredictos:
        return "auto"
    if all(v in ("confirmado", "descartado") for v in veredictos):
        return "auto"
    return "humano"


def _dano_pendiente_de_decidir(d) -> bool:
    """Un daño nuevo que aun no ha decidido nadie (ni persona ni IA).

    Los ya registrados en el libro (`is_new: False`, "[ya registrado …]") no
    se vuelven a preguntar: es la misma regla que aplica la pantalla.
    """
    if not isinstance(d, dict):
        return False
    if d.get("is_new", True) is False or "[ya registrado" in (d.get("description") or ""):
        return False
    return True


async def autorrevisar_inspecciones(limite: int = 300, ids=None) -> dict:
    """Cierra sola las inspecciones que la IA puede cerrar, en la empresa actual."""
    modelo = await fiabilidad.cargar(db)
    q: dict = {"reviewed": {"$ne": True}, "deleted": {"$ne": True}, "analysis_status": "ok"}
    if ids:
        q["id"] = {"$in": list(ids)}
    cur = db.inspections.find(
        q, {"_id": 0, "id": 1, "vehicle_id": 1, "analysis.new_damages": 1,
            "analysis.total_damages_count": 1}).sort("created_at", -1).limit(max(1, limite))
    res = {"revisadas": 0, "sin_nada": 0, "decididas": 0, "confirmados": 0,
           "descartados": 0, "dudosas": 0, "sin_modelo": 0}
    ahora = datetime.now(timezone.utc).isoformat()
    async for insp in cur:
        an = insp.get("analysis") or {}
        nuevos = an.get("new_damages") or []
        pendientes = [(i, d) for i, d in enumerate(nuevos) if _dano_pendiente_de_decidir(d)]
        if not pendientes:
            await db.inspections.update_one(
                {"id": insp["id"]},
                {"$set": {"reviewed": True, "reviewed_at": ahora, "reviewed_by": "ia",
                          "reviewed_motivo": "sin daños nuevos que decidir"}})
            res["revisadas"] += 1
            res["sin_nada"] += 1
            continue
        if not modelo:
            res["sin_modelo"] += 1
            continue
        veredictos, sets = [], {}
        for i, d in pendientes:
            p = fiabilidad.puntuar(modelo, d, an.get("total_damages_count"), i)
            v = fiabilidad.veredicto(p)
            veredictos.append(v)
            sets["analysis.new_damages.%d.fiabilidad" % i] = p
            sets["analysis.new_damages.%d.veredicto_ia" % i] = v
        # La puntuacion se guarda siempre: la pantalla enseña asi cual es la duda.
        await db.inspections.update_one({"id": insp["id"]}, {"$set": sets})
        if _autorrevision_decision(veredictos) != "auto":
            res["dudosas"] += 1
            continue
        n_ok = n_no = 0
        for (i, d), v in zip(pendientes, veredictos):
            if v == "descartado":
                # Lo mismo que hace el veredicto humano "inventado": fuera del
                # libro las entradas de la IA en ese panel; las humanas quedan.
                p = _canon_panel(d.get("part") or "")
                if p and insp.get("vehicle_id"):
                    await db.vehicle_damage_ledger.delete_many(
                        {"vehicle_id": insp["vehicle_id"], "panel": p, "status": "open", "source": "ai"})
                n_no += 1
            else:
                n_ok += 1
        await db.inspections.update_one(
            {"id": insp["id"]},
            {"$set": {"reviewed": True, "reviewed_at": ahora, "reviewed_by": "ia",
                      "reviewed_motivo": "%d confirmado(s) · %d descartado(s) por fiabilidad" % (n_ok, n_no)}})
        res["revisadas"] += 1
        res["decididas"] += 1
        res["confirmados"] += n_ok
        res["descartados"] += n_no
    return res


AUTORREV_CADA_MIN = 15


async def _bucle_autorrevision():
    """Cada cuarto de hora, en TODAS las empresas (gotcha 26: es un cron)."""
    await asyncio.sleep(120)
    while True:
        total = 0
        try:
            orgs = await global_db.organizations.find(
                {"status": {"$in": ["active", "trial"]}},
                {"_id": 0, "id": 1, "db_name": 1, "account_type": 1}).to_list(500) or [None]
            anterior = _current_db_name.get()
            try:
                for o in orgs:
                    set_current_org_db(_tenant_db_name(o))
                    r = await autorrevisar_inspecciones(limite=300)
                    total += r.get("revisadas", 0)
            finally:
                set_current_org_db(anterior)
            await _latido("autorrevision", revisadas=total, cada_min=AUTORREV_CADA_MIN, error=None)
        except Exception as e:                                   # noqa: BLE001
            logger.error("Bucle de autorrevision: %s", e)
            await _latido("autorrevision", error=str(e)[:200], cada_min=AUTORREV_CADA_MIN)
        await asyncio.sleep(AUTORREV_CADA_MIN * 60)


@api_router.post("/ai/autorrevisar")
async def disparar_autorrevision(data: dict = Body(default={}), _=Depends(require_admin)):
    """Que la IA cierre ahora lo que pueda, en esta empresa. Devuelve cuanto."""
    limite = int((data or {}).get("limite") or 500)
    r = await autorrevisar_inspecciones(limite=max(1, min(limite, 5000)))
    await _audit(_, "autorrevision_manual", r)
    return r


async def _bucle_seguimiento():
    """Mira cada media hora si a algun taller le toca que le preguntemos.

    Correr cada media hora no manda de mas: quien decide es
    `seguimiento.toca_preguntar`, que mira `ultimo_toque` y no repite dentro de
    los dias que diga la pauta. El bucle solo abre la puerta; la pauta decide
    quien pasa.
    """
    while True:
        try:
            r = await seguimiento_talleres()
            await _latido("seguimiento_talleres", enviados=len(r or []),
                          cada_min=SEG_CADA_MIN, error=None)
        except Exception as e:                                   # noqa: BLE001
            logger.error("Bucle de seguimiento de talleres: %s", e)
            await _latido("seguimiento_talleres", error=str(e)[:200],
                          cada_min=SEG_CADA_MIN)
        await asyncio.sleep(SEG_CADA_MIN * 60)


async def seguimiento_talleres(forzar: bool = False) -> list:
    """Pregunta a los talleres segun la PAUTA que haya puesta.

    Antes la cadencia estaba cosida al codigo —cada 3 dias, cuatro veces, de
    lunes a viernes de 9 a 19— y cambiarla era un despliegue. Ahora sale de
    `taller_pauta`, que se edita desde la app, y el texto de cada aviso de
    `taller_plantillas`. Lo que decide se prueba entero en
    `backend/tests/test_seguimiento_motor.py`, sin base de datos delante.
    """
    from zoneinfo import ZoneInfo
    ahora = datetime.now(ZoneInfo("Europe/Madrid"))
    pauta = await _seg_pauta()
    if not forzar and not seguimiento.es_hora(pauta, ahora):
        return []

    plantillas = await _seg_plantillas()
    abiertas = await db.ordenes_trabajo.find(
        {"estado": {"$in": list(seguimiento.ESTADOS_QUE_SE_SIGUEN)}},
        {"_id": 0}).to_list(300)

    salida = []
    for o in abiertas:
        toca, motivo = seguimiento.toca_preguntar(o, pauta, datetime.now(timezone.utc))
        if not toca and not forzar:
            continue

        ref = seguimiento._ultima_senal(o)
        dias = max(1, (datetime.now(timezone.utc) - ref).days) if ref else 1
        n = int(o.get("toques") or 0)
        url = await _ot_url_taller(o["id"])
        clave = seguimiento.plantilla_para(pauta, n)
        texto = seguimiento.render((plantillas.get(clave) or {}).get("texto") or "",
                                   seguimiento.contexto(o, url, dias))
        if not texto:
            # Si alguien deja una plantilla vacia NO se calla el aviso: se usa
            # el texto de siempre. Un mensaje mal editado no puede convertirse
            # en semanas de silencio.
            texto = _ot_texto_toque(o, dias, url)
        enviado = False

        tel = (o.get("taller_telefono") or "").strip()
        if (tel and "whatsapp" in pauta["canales"]
                and await whatsapp.puede_avisar(db, "avisar_incidencia")):
            r = await whatsapp.enviar_plantilla(
                db, tel, "taller_seguimiento",
                [o.get("matricula") or "", str(dias), url],
                motivo="seguimiento OT %s" % o.get("numero"))
            enviado = bool(r.get("ok"))

        if not enviado:
            # Sin WhatsApp, el recordatorio va a la oficina con el texto ya
            # escrito para reenviar. Que no salga solo no puede significar que
            # no salga: seria volver al silencio que esto viene a arreglar.
            # El enlace lleva el texto dentro: un clic y a enviar.
            await _ot_avisa(o, "Lleva %d días sin novedades del taller.\n\n%s" % (dias, texto),
                            enlace_wa(o.get("taller_telefono"), texto))

        # Queda apuntado en la bandeja, al lado de lo que ellos contestan: la
        # conversacion entera en un sitio y no la mitad en el historial.
        await _seg_apunta(o, "salida", texto, "whatsapp" if enviado else "oficina",
                          {"plantilla": clave, "toque": n + 1, "dias": dias})

        await db.ordenes_trabajo.update_one(
            {"id": o["id"]},
            {"$set": {"ultimo_toque": _ot_ahora()}, "$inc": {"toques": 1},
             "$push": {"historial": _ot_apunte(
                 "seguimiento", "Recordatorio al taller",
                 "%d días sin novedades%s" % (dias, "" if enviado else " · por WhatsApp no salió"))}})
        salida.append({"numero": o.get("numero"), "matricula": o.get("matricula"),
                       "taller": o.get("taller_nombre"), "dias": dias,
                       "por_whatsapp": enviado, "toque": n + 1,
                       "plantilla": clave, "motivo": motivo})

    if salida:
        logger.info("Seguimiento de talleres: %d recordatorios", len(salida))
    return salida


@api_router.post("/work-orders/seguimiento")
async def disparar_seguimiento(_=Depends(require_admin)):
    """Lanza el seguimiento ahora, sin esperar a su hora."""
    return {"recordatorios": await seguimiento_talleres(forzar=True)}


@api_router.get("/work-orders/export")
async def exportar_ordenes(center: Optional[str] = None, estado: Optional[str] = None,
                           workshop_id: Optional[str] = None, abiertas: bool = False,
                           _=Depends(require_admin)):
    """Las ordenes en un .xlsx, con los mismos filtros que la pantalla.

    OJO CON EL ORDEN DE LAS RUTAS: esto tiene que declararse ANTES que
    /work-orders/{orden_id}. FastAPI casa por orden de declaracion, asi que
    puesto despues, la palabra 'export' entraria como si fuera un id y la
    descarga devolveria un 404 sin que nadie entienda por que.
    """
    q: dict = {}
    if center and center != "Todos":
        q["center"] = {"$regex": re.escape(center), "$options": "i"}
    if estado:
        q["estado"] = estado
    elif abiertas:
        q["estado"] = {"$in": list(OT_ABIERTAS)}
    if workshop_id:
        q["workshop_id"] = workshop_id

    filas = await db.ordenes_trabajo.find(q, {"_id": 0}).sort("creada_en", -1).to_list(3000)

    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side

    wb = Workbook()
    ws = wb.active
    ws.title = "Ordenes de taller"
    cabeceras = ["Orden", "Matricula", "Modelo", "Centro", "Taller", "Estado",
                 "Entrada", "Entrega prevista", "Entrega real", "Dias en taller",
                 "Presupuesto", "Importe estimado", "Importe final",
                 "El taller lo abrio", "Ultima novedad", "Problema"]
    fino = Side(style="thin", color="D9D9D9")
    for j, c in enumerate(cabeceras, 1):
        cel = ws.cell(row=1, column=j, value=c)
        cel.font = Font(bold=True, size=10, color="FFFFFF")
        cel.fill = PatternFill("solid", fgColor="1F3864")
        cel.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

    def _dias(o):
        """Dias que estuvo (o lleva) fuera. Sin las dos fechas no se inventa."""
        ini = (o.get("fecha_entrada") or "")[:10]
        fin = (o.get("fecha_entrega_real") or "")[:10] or datetime.now(timezone.utc).isoformat()[:10]
        try:
            return (datetime.strptime(fin, "%Y-%m-%d") - datetime.strptime(ini, "%Y-%m-%d")).days
        except Exception:
            return None

    for i, o in enumerate(filas, 2):
        vals = [
            o.get("numero"), o.get("matricula"), o.get("modelo"), o.get("center"),
            o.get("taller_nombre"), OT_ESTADOS.get(o.get("estado"), o.get("estado")),
            o.get("fecha_entrada"), o.get("fecha_entrega_estimada"), o.get("fecha_entrega_real"),
            _dias(o),
            {"sin_presupuesto": "", "pendiente": "pendiente",
             "aprobado": "aprobado", "rechazado": "no aprobado"}.get(o.get("presupuesto"), ""),
            o.get("importe_estimado"), o.get("importe_final"),
            # Un "no" aqui es informacion, no un hueco: significa que el taller
            # ni miro el enlace.
            "si" if o.get("abierto_en") else "NO",
            (o.get("ultima_novedad_taller") or "")[:16].replace("T", " "),
            (o.get("problema") or "")[:300],
        ]
        for j, v in enumerate(vals, 1):
            cel = ws.cell(row=i, column=j, value=v)
            cel.font = Font(size=10)
            cel.border = Border(left=fino, right=fino, top=fino, bottom=fino)
        for col in (12, 13):
            ws.cell(row=i, column=col).number_format = '#,##0.00 "EUR"'
        if not o.get("abierto_en") and o.get("estado") in OT_ABIERTAS:
            ws.cell(row=i, column=14).font = Font(size=10, bold=True, color="C00000")

    for col, ancho in zip("ABCDEFGHIJKLMNOP",
                          [10, 11, 16, 8, 26, 17, 12, 14, 12, 9, 12, 13, 12, 12, 16, 50]):
        ws.column_dimensions[col].width = ancho
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = "A1:P%d" % max(1, len(filas) + 1)

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    nombre = "ordenes-taller-%s.xlsx" % datetime.now(timezone.utc).strftime("%Y-%m-%d")
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": 'attachment; filename="%s"' % nombre})


@api_router.get("/work-orders/por-taller")
async def ordenes_por_taller(center: Optional[str] = None, _=Depends(require_admin)):
    """Cual tarda menos y cual cobra mas. Para decidir a donde mandar la
    siguiente, que hoy se decide de memoria.

    Solo cuenta ordenes ENTREGADAS y con las dos fechas: la media de dias de
    una orden abierta no significa nada, y meterla ensuciaria el unico numero
    que sirve para comparar.

    Va declarada ANTES que /work-orders/{orden_id} — si no, 'por-taller'
    entraria como un id y esto daria 404.
    """
    q: dict = {"estado": "entregado"}
    if center and center != "Todos":
        q["center"] = {"$regex": re.escape(center), "$options": "i"}

    por: dict = {}
    # `async for` sobre el CURSOR, o `for` sobre el resultado de `to_list()`.
    # Mezclarlos revienta con "got _asyncio.Future" y no lo ve ni el compilador
    # ni pyflakes: solo salta al pedir la ruta.
    for o in await db.ordenes_trabajo.find(q, {"_id": 0, "workshop_id": 1, "taller_nombre": 1,
                                               "fecha_entrada": 1, "fecha_entrega_real": 1,
                                               "importe_final": 1, "importe_estimado": 1,
                                               "abierto_en": 1}).to_list(3000):
        e = por.setdefault(o.get("workshop_id") or "?", {
            "taller": o.get("taller_nombre") or "(sin nombre)", "ordenes": 0,
            "_dias": [], "_importes": [], "abrieron": 0})
        e["ordenes"] += 1
        if o.get("abierto_en"):
            e["abrieron"] += 1
        try:
            d1 = datetime.strptime((o.get("fecha_entrada") or "")[:10], "%Y-%m-%d")
            d2 = datetime.strptime((o.get("fecha_entrega_real") or "")[:10], "%Y-%m-%d")
            e["_dias"].append((d2 - d1).days)
        except Exception:
            pass
        imp = o.get("importe_final") if o.get("importe_final") is not None else o.get("importe_estimado")
        if imp is not None:
            e["_importes"].append(imp)

    salida = []
    for wid, e in por.items():
        salida.append({
            "workshop_id": wid, "taller": e["taller"], "ordenes": e["ordenes"],
            # None y no 0: "no lo sabemos" y "tarda cero dias" no son lo mismo.
            "dias_medios": round(sum(e["_dias"]) / len(e["_dias"]), 1) if e["_dias"] else None,
            "medidas_sobre": len(e["_dias"]),
            "gasto_total": round(sum(e["_importes"]), 2) if e["_importes"] else None,
            "importe_medio": round(sum(e["_importes"]) / len(e["_importes"]), 2) if e["_importes"] else None,
            "usan_el_enlace": round(100 * e["abrieron"] / e["ordenes"]) if e["ordenes"] else 0,
        })
    salida.sort(key=lambda x: (x["dias_medios"] is None, x["dias_medios"] or 0))
    return {"talleres": salida}


