@api_router.post("/vehicles/{vehicle_id}/bags/set")
async def set_bags(vehicle_id: str, data: dict, _=Depends(require_admin)):
    """Fija el stock de bolsas de una furgoneta."""
    cantidad = _entero(data.get("bags"), "bags", defecto=0, minimo=0, maximo=100000)
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")
    entry = {"date": datetime.now(timezone.utc).isoformat(), "change": cantidad - v.get("bags_remaining", 0),
             "note": data.get("note", "Ajuste de stock"), "remaining_after": cantidad}
    await db.vehicles.update_one({"id": vehicle_id},
        {"$set": {"bags_remaining": cantidad, "updated_at": datetime.now(timezone.utc)},
         "$push": {"bags_history": entry}})
    return {"success": True, "bags_remaining": cantidad}


@api_router.post("/vehicles/{vehicle_id}/bags/consume")
async def consume_bags(vehicle_id: str, data: dict, _=Depends(require_admin)):
    """Descuenta bolsas gastadas y registra cuándo."""
    gastadas = _entero(data.get("used"), "used", defecto=1, minimo=0, maximo=100000)
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")
    restantes = max(0, v.get("bags_remaining", 0) - gastadas)
    entry = {"date": datetime.now(timezone.utc).isoformat(), "change": -gastadas,
             "note": data.get("note", f"Gastadas {gastadas} bolsas"), "remaining_after": restantes}
    await db.vehicles.update_one({"id": vehicle_id},
        {"$set": {"bags_remaining": restantes, "updated_at": datetime.now(timezone.utc)},
         "$push": {"bags_history": entry}})
    # Aviso si quedan pocas
    if restantes <= 5:
        await db.alerts.insert_one(serialize_doc(Alert(
            vehicle_id=vehicle_id, inspection_id="",
            title=f"Quedan {restantes} bolsas en {v.get('license_plate','')}",
            description=f"Stock bajo de bolsas. Repón pronto.",
            severity="medium").model_dump()))
    return {"success": True, "bags_remaining": restantes}


@api_router.post("/vehicles/{vehicle_id}/oil/change")
async def register_oil_change(vehicle_id: str, data: dict, _=Depends(require_admin)):
    """Registra un cambio de aceite: km actuales + fecha + intervalo."""
    km = _entero(data.get("km"), "km", defecto=0, minimo=0, maximo=2_000_000)
    fecha = data.get("date") or datetime.now(timezone.utc).date().isoformat()
    intervalo = _entero(data.get("interval_km"), "interval_km", defecto=15000, minimo=1, maximo=500_000)
    aviso_antes = _entero(data.get("warning_before_km"), "warning_before_km", defecto=2500, minimo=0, maximo=500_000)
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")
    await db.vehicles.update_one({"id": vehicle_id}, {"$set": {
        "oil_last_change_km": km, "oil_last_change_date": fecha,
        "oil_interval_km": intervalo, "oil_warning_before_km": aviso_antes,
        "mileage": max(km, v.get("mileage") or 0), "updated_at": datetime.now(timezone.utc)}})
    await _log_mantenimiento(v, "oil", km, str(data.get("nota") or ""),
                             str(data.get("taller") or ""), origen="manual", fecha=fecha)
    return {"success": True, "next_change_km": km + intervalo,
            "warning_at_km": km + intervalo - aviso_antes}


# Mantenimientos por km adicionales (mismo patrón que el aceite)
_MAINT_KINDS = {
    "ruedas": {"label": "Cambio de ruedas", "default_interval": 40000, "default_warning": 3000},
    "pastillas": {"label": "Pastillas de freno", "default_interval": 30000, "default_warning": 3000},
}


@api_router.post("/vehicles/{vehicle_id}/maintenance/{kind}/change")
async def register_maintenance_change(vehicle_id: str, kind: str, data: dict, _=Depends(require_admin)):
    """Registra un mantenimiento por km (ruedas, pastillas): igual que el aceite."""
    spec = _MAINT_KINDS.get(kind)
    if not spec:
        raise HTTPException(status_code=400, detail=f"Tipo desconocido. Válidos: {list(_MAINT_KINDS)}")
    km = _entero(data.get("km"), "km", defecto=0, minimo=0, maximo=2_000_000)
    fecha = data.get("date") or datetime.now(timezone.utc).date().isoformat()
    intervalo = _entero(data.get("interval_km"), "interval_km", defecto=spec["default_interval"], minimo=1, maximo=500_000)
    aviso_antes = _entero(data.get("warning_before_km"), "warning_before_km", defecto=spec["default_warning"], minimo=0, maximo=500_000)
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")
    await db.vehicles.update_one({"id": vehicle_id}, {"$set": {
        f"{kind}_last_change_km": km, f"{kind}_last_change_date": fecha,
        f"{kind}_interval_km": intervalo, f"{kind}_warning_before_km": aviso_antes,
        "mileage": max(km, v.get("mileage") or 0), "updated_at": datetime.now(timezone.utc)}})
    # Al historial también: da igual desde dónde se registre el cambio, en la
    # ficha de la furgoneta tiene que constar.
    await _log_mantenimiento(v, kind, km, str(data.get("nota") or ""),
                             str(data.get("taller") or ""), origen="manual", fecha=fecha)
    return {"success": True, "kind": kind, "label": spec["label"],
            "next_change_km": km + intervalo, "warning_at_km": km + intervalo - aviso_antes}


# NOTA: la subida de foto de conductor vive en POST /drivers/{driver_id}/photo
# (definida más arriba). Aquí había un duplicado inalcanzable que se eliminó.


@api_router.post("/inspections/validate-photo")
async def validate_inspection_photo(
    vehicle_id: str = Form(...),
    expected_zone: str = Form(...),
    file: UploadFile = File(...),
    user: dict = Depends(require_any_auth),
):
    """Valida UNA foto en el momento de capturarla: zona correcta, nitidez y matrícula.
    FAIL-OPEN: si la IA no responde, la foto se acepta (nunca bloquear por fallo técnico)."""
    ZONES = {
        "frontal": "el FRONTAL (morro, parabrisas, matrícula delantera)",
        "trasera": "la TRASERA (portón/puertas traseras, matrícula trasera)",
        "lateral_izq": "el LATERAL IZQUIERDO completo",
        "lateral_izquierdo": "el LATERAL IZQUIERDO completo",
        "lateral_der": "el LATERAL DERECHO completo",
        "lateral_derecho": "el LATERAL DERECHO completo",
    }
    zone_desc = ZONES.get(expected_zone.lower().strip())
    if not zone_desc:
        return {"valid": True, "checked": False, "reason": "zona desconocida — no validada"}

    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "license_plate": 1})
    real_plate = ((v or {}).get("license_plate") or "").replace(" ", "").replace("-", "").upper()

    try:
        content = await file.read()
        img = Image.open(io.BytesIO(content)).convert("RGB")
        img.thumbnail((1024, 1024))
        buf = io.BytesIO()
        img.save(buf, format="JPEG", quality=75)
        img_bytes = buf.getvalue()

        from google import genai as genai_sdk
        from google.genai import types as genai_types

        use_vertex = os.environ.get("USE_VERTEX_AI", "").lower() in ("1", "true", "yes")
        if use_vertex:
            from google.oauth2 import service_account
            import json as _json
            import base64 as _b64
            sa_clean = os.environ.get("GCP_SERVICE_ACCOUNT_JSON", "").strip()
            if sa_clean and not sa_clean.startswith("{"):
                sa_clean = _b64.b64decode(sa_clean).decode("utf-8")
            credentials = service_account.Credentials.from_service_account_info(
                _json.loads(sa_clean), scopes=["https://www.googleapis.com/auth/cloud-platform"]
            ) if sa_clean else None
            client = genai_sdk.Client(
                vertexai=True, project=os.environ.get("GCP_PROJECT", ""),
                location=os.environ.get("GCP_LOCATION", "us-central1"), credentials=credentials
            )
        else:
            client = genai_sdk.Client(api_key=os.environ.get("GEMINI_API_KEY", ""))

        prompt = (
            f"Foto de inspección de una furgoneta de reparto. Debe mostrar {zone_desc} del vehículo.\n"
            "Evalúa y responde SOLO este JSON sin markdown:\n"
            '{"zone_ok": <true si la foto muestra esa zona del vehículo>, '
            '"zone_seen": "<frontal|trasera|lateral_izquierdo|lateral_derecho|otra|no_es_vehiculo>", '
            '"too_blurry": <true SOLO si está tan borrosa/oscura que no permite inspeccionar daños>, '
            '"plate": "<matrícula legible en la foto o vacío>", '
            '"is_vehicle": <true si se ve una furgoneta/vehículo>}\n'
            "Sé tolerante con ángulos imperfectos: zone_ok=true si la zona pedida es claramente la protagonista."
        )
        contents = [prompt, genai_types.Part.from_bytes(data=img_bytes, mime_type="image/jpeg")]
        gen_config = genai_types.GenerateContentConfig(temperature=0.0, response_mime_type="application/json")
        loop = asyncio.get_running_loop()
        async with _gemini_sem:
            response = await asyncio.wait_for(
                loop.run_in_executor(
                    _executor,
                    lambda: client.models.generate_content(
                        model=os.environ.get("GEMINI_MODEL", "gemini-2.5-flash"),
                        contents=contents, config=gen_config
                    )
                ),
                timeout=25.0
            )
        data = json.loads(_strip_markdown_json(response.text or "{}"))

        if not data.get("is_vehicle", True):
            return {"valid": False, "checked": True, "reason": "En la foto no se ve ninguna furgoneta. Haz la foto al vehículo."}
        if data.get("too_blurry"):
            return {"valid": False, "checked": True, "reason": "La foto está demasiado borrosa u oscura. Repítela con más luz y el móvil quieto."}
        if not data.get("zone_ok", True):
            seen = data.get("zone_seen", "otra zona")
            return {"valid": False, "checked": True,
                    "reason": f"Esta casilla es para {zone_desc.split('(')[0].strip()}, pero la foto muestra: {seen}. Haz la foto de la zona correcta."}
        # Matrícula: solo exigible en frontal/trasera y solo si se lee alguna
        detected = _texto_cuerpo(data.get("plate")).replace(" ", "").replace("-", "").upper()
        if detected and real_plate and detected != real_plate and expected_zone.lower() in ("frontal", "trasera"):
            return {"valid": False, "checked": True,
                    "reason": f"La matrícula de la foto ({data.get('plate')}) NO es la del vehículo seleccionado ({(v or {}).get('license_plate','')}). ¿Estás fotografiando la furgoneta correcta?"}
        return {"valid": True, "checked": True, "detected_plate": data.get("plate", "")}
    except Exception as e:
        logger.warning(f"validate-photo fail-open ({expected_zone}): {e}")
        return {"valid": True, "checked": False, "reason": "validación no disponible — foto aceptada"}


# ══════════════════════════════════════════════════════════════════════════
# ODOMETRO — reglas unicas. Todo km que entra al sistema pasa por aqui.
# Regla de oro: ante la duda NO se escribe. Un km inventado corrompe el
# historico para siempre (solo aceptamos subidas, asi que un valor alto
# erroneo bloquea todas las lecturas buenas posteriores).
# ══════════════════════════════════════════════════════════════════════════

ODO_MAX_KM_DIA = 500          # tope diario que pidio flota (furgo DSP real: 150-250)
ODO_MIN_CONFIANZA = 0.80      # por debajo, la lectura no vale
ODO_MAX_ABSOLUTO = ODO_KM_IMPOSIBLE  # ningun odometro de furgoneta DSP pasa de aqui


def _odo_lecturas(v: dict) -> list:
    """Las lecturas de kilometraje QUE CUENTAN, ordenadas por fecha.

    UN SOLO SITIO que decide esto. Al marcar 66 lecturas como `descartada`
    quedaron cuatro calculos leyendo `mileage_history` en crudo —el ritmo
    km/dia, la ultima fecha, la grafica y la prediccion de mantenimiento— y los
    cuatro seguian usando la basura que se acababa de descartar. Es el gotcha
    20: si cambias lo que guarda una estructura, busca TODOS los que la leen.
    """
    return sorted(
        (h for h in (v.get("mileage_history") or [])
         if isinstance(h, dict) and not h.get("descartada")
         and h.get("date") and isinstance(h.get("km"), (int, float))
         and not isinstance(h.get("km"), bool)),
        key=lambda h: str(h["date"]))


def _odo_ultima_fecha(v: dict):
    """Fecha de la ultima lectura registrada del vehiculo."""
    hist = _odo_lecturas(v)
    for e in reversed(hist):
        d = e.get("date")
        if not d:
            continue
        try:
            f = datetime.fromisoformat(str(d).replace("Z", "+00:00"))
        except Exception:
            continue
        # Una fecha sin zona («2026-08-10», de una importacion) reventaba al
        # restarla de `now(timezone.utc)`: 500 al subir la foto del cuadro.
        return f if f.tzinfo else f.replace(tzinfo=timezone.utc)
    upd = v.get("updated_at")
    if isinstance(upd, datetime):
        return upd if upd.tzinfo else upd.replace(tzinfo=timezone.utc)
    return None


def _odo_margen(v: dict):
    """Cuanto puede subir como maximo el km desde el ultimo registrado.

    Es 500 por dia transcurrido (minimo 1 dia). Asi el tope es el que pidio
    flota en el caso normal, pero una furgoneta parada un fin de semana o de
    vacaciones no se queda bloqueada al volver.
    """
    actual = int(v.get("mileage") or 0)
    # SIN EL CAMPO `mileage` NO HABIA GUARDA NINGUNA, Y ESO ES PEOR QUE NO
    # TENERLA: los dos `if actual and ...` de `_odo_validar` se saltan enteros,
    # asi que una ficha con el campo vacio aceptaba cualquier numero — 45.930
    # km o 1 km, da igual— teniendo DIECINUEVE lecturas en su historial.
    #
    # Paso de verdad el 20-09-2026 con la 5338NKG: serie de 8.585 a 10.600 km y
    # una inspeccion de la tarde entro con 45.930. No la rechazo nadie porque
    # el campo estaba vacio, y el historial, que lo decia todo, no se miraba.
    # Comprobado reproduciendolo: con `mileage` puesto rechaza las dos.
    #
    # El historial es la misma verdad que el campo, y ademas se limpia de
    # lecturas ya descartadas: si lo unico que hay es malo, no hay minimo, que
    # es justo lo que salvo a la 3328 NFY de abajo.
    if not actual:
        _h = v.get("mileage_history") or []
        _malos_h = {i for i, _ in _odo_sospechosas(_h)}
        _serie = [h.get("km") for i, h in enumerate(_h)
                  if i not in _malos_h and not h.get("descartada")
                  and isinstance(h.get("km"), (int, float)) and not isinstance(h.get("km"), bool)]
        if _serie:
            actual = int(max(_serie))
    # EL MINIMO NO PUEDE SER UN DATO QUE YA SABEMOS FALSO. Si la IA no lee el
    # cuentakilometros, el conductor escribe los km a mano y no se le deja
    # poner menos que lo registrado. En la 3328 NFY lo registrado era
    # 1.880.404: el conductor veia 25.000 en el salpicadero, no podia
    # escribirlo, y durante tres semanas cada uno copio el de ayer mas uno.
    # El formulario FABRICABA el dato falso. Ahora el minimo es el ultimo km
    # bueno de la serie; si no hay ninguno creible, no hay minimo.
    if actual > ODO_KM_IMPOSIBLE:
        actual = 0
    malos = _odo_sospechosas(v.get("mileage_history") or [])
    if actual and malos:
        hist = v.get("mileage_history") or []
        km_malos = {hist[i].get("km") for i, _ in malos}
        if actual in km_malos:
            buenos = [h.get("km") for j, h in enumerate(hist)
                      if j not in {i for i, _ in malos} and not h.get("descartada")
                      and isinstance(h.get("km"), (int, float))
                      and not isinstance(h.get("km"), bool)]
            actual = int(max(buenos)) if buenos else 0
    ultima = _odo_ultima_fecha(v)
    dias = 1
    if ultima:
        dias = max(1, min(60, (datetime.now(timezone.utc) - ultima).days or 1))
    # PRIMERA lectura (furgoneta sin km registrados): no hay contra que
    # comparar, asi que no hay techo de ritmo. Si no, dar de alta una furgoneta
    # usada de 87.000 km era imposible: el movil solo dejaba escribir hasta 500.
    if not actual:
        return 0, dias, ODO_MAX_ABSOLUTO
    return actual, dias, actual + ODO_MAX_KM_DIA * dias


def _odo_validar(v: dict, km):
    """¿Es creible este kilometraje para este vehiculo?

    Devuelve (ok, motivo, info). Nunca lanza: es un juicio, no un error.
    """
    actual, dias, tope = _odo_margen(v)
    info = {"actual": actual, "dias": dias, "maximo": tope, "minimo": actual}
    if not isinstance(km, (int, float)) or isinstance(km, bool):
        return False, "No se ha leido ningun numero.", info
    km = int(km)
    if km <= 0 or km > ODO_MAX_ABSOLUTO:
        return False, "El numero leido no es un kilometraje valido.", info
    if actual and km < actual:
        return False, (
            f"Marca {km:,} km, menos que los {actual:,} ya registrados. "
            "Un cuentakilometros no baja: seguramente sea el parcial (trip) "
            "o una lectura mal hecha."
        ).replace(",", "."), info
    if actual and km > tope:
        margen = ODO_MAX_KM_DIA * dias
        return False, (
            f"Marca {km:,} km: son {km - actual:,} mas que los {actual:,} "
            f"registrados, y el maximo creible es {margen:,} km "
            f"({ODO_MAX_KM_DIA}/dia x {dias}). Lectura descartada."
        ).replace(",", "."), info
    return True, None, info


# ── DEPOSITO Y KM REPETIDOS ──────────────────────────────────────────────────
# El conductor saca foto del indicador de combustible y marca el nivel que ve.
# El aviso sale de lo que MARCA (ve la aguja): una lectura automatica que se
# equivoque avisaria de un deposito vacio que esta lleno, y un aviso falso
# ensena a ignorarlos todos. La foto queda para comprobarlo.
_COMBUSTIBLE_NIVELES = (10, 25, 50, 75, 100)   # reserva, 1/4, 1/2, 3/4, lleno
_COMBUSTIBLE_AVISO_BAJO = 50                   # por DEBAJO de la mitad se avisa


def _combustible_nivel(valor) -> Optional[int]:
    """El nivel declarado, solo si es uno de los del portal. Otra cosa: None."""
    if isinstance(valor, bool):
        return None
    try:
        n = int(str(valor).strip())
    except (TypeError, ValueError):
        return None
    return n if n in _COMBUSTIBLE_NIVELES else None


def _combustible_texto(pct: int) -> str:
    return {10: "en reserva", 25: "a 1/4", 50: "a 1/2", 75: "a 3/4", 100: "lleno"}.get(pct, f"al {pct} %")


def _km_repetido(historial, km, hoy: str) -> Optional[str]:
    """Si `km` es EXACTAMENTE el ultimo registrado y aquel era de otro dia, la
    fecha de aquel dia. Puede ser una foto repetida o una furgoneta que no
    salio: se marca para mirarlo, nunca se bloquea."""
    try:
        km = int(km)
    except (TypeError, ValueError):
        return None
    ultimo = None
    for e in historial or []:
        if isinstance(e, dict) and e.get("km") is not None and e.get("date"):
            ultimo = e
    if not ultimo:
        return None
    try:
        km_ant = int(ultimo["km"])
    except (TypeError, ValueError):
        return None
    dia_ant = str(ultimo["date"])[:10]
    return dia_ant if km == km_ant and dia_ant and dia_ant < hoy else None


async def _combustible_registrar(vehicle_id: str, inspection_id: str, driver_id: str,
                                 pct: int, foto_url: str) -> None:
    ahora = datetime.now(timezone.utc).isoformat()
    dato = {"pct": pct, "fecha": ahora, "inspection_id": inspection_id,
            "driver_id": driver_id, "foto": foto_url}
    await db.inspections.update_one({"id": inspection_id}, {"$set": {"combustible": dato}})
    await db.vehicles.update_one({"id": vehicle_id}, {"$set": {"combustible": dato}})
    if pct >= _COMBUSTIBLE_AVISO_BAJO:
        return
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "license_plate": 1, "center": 1})
    placa = (v or {}).get("license_plate", "")
    titulo = f"Depósito bajo en {placa}"
    # `created_at` de las alertas se guarda en UTC: el dia se compara en UTC.
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    # Uno por furgoneta y dia: dos inspecciones el mismo dia no son dos avisos.
    ya = await db.alerts.find_one({"vehicle_id": vehicle_id, "title": titulo,
                                   "created_at": {"$regex": f"^{hoy}"}}, {"_id": 0, "id": 1})
    if ya:
        return
    ficha = await db.drivers.find_one({"id": driver_id}, {"_id": 0, "name": 1}) if driver_id else None
    quien = (ficha or {}).get("name") or "el conductor"
    desc = f"{placa} está {_combustible_texto(pct)} según {quien} al hacer la inspección."
    await db.alerts.insert_one(serialize_doc(Alert(
        vehicle_id=vehicle_id, inspection_id=inspection_id, title=titulo,
        description=desc, severity="medium", kind="combustible").model_dump()))
    await _telegram_aviso(f"⛽ <b>{titulo}</b>\n{desc}")
    try:
        await push_center_event((v or {}).get("center") or "", f"⛽ {titulo}", desc, "/panel/vehiculos")
    except Exception as e:                                   # noqa: BLE001
        logger.debug(f"push deposito: {e}")


async def _odo_registrar(vehicle_id: str, km: int, source: str, extra: dict = None):
    """UNICO sitio que escribe el kilometraje. Valida siempre antes de tocar nada.

    Devuelve (aplicado: bool, motivo: str|None, info: dict).
    """
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "mileage": 1,
                                                       "mileage_history": 1,
                                                       "updated_at": 1,
                                                       "license_plate": 1})
    if not v:
        return False, "Furgoneta no encontrada.", {}
    ok, motivo, info = _odo_validar(v, km)
    if not ok:
        logger.warning(f"Odometro RECHAZADO {v.get('license_plate','')} ({source}): "
                       f"{km} — {motivo}")
        return False, motivo, info
    km = int(km)
    entrada = {"date": datetime.now(timezone.utc).isoformat(), "km": km, "source": source}
    if extra:
        entrada.update(extra)
    await db.vehicles.update_one(
        {"id": vehicle_id},
        {"$set": {"mileage": km, "updated_at": datetime.now(timezone.utc)},
         "$push": {"mileage_history": entrada}},
    )
    logger.info(f"Odometro OK {v.get('license_plate','')} ({source}): "
                f"{info['actual']} -> {km}")
    return True, None, info


async def _odo_leer_foto(img_bytes: bytes, intentos: int = 2):
    """Lee el cuentakilometros de una foto. DOS lecturas independientes.

    Anti-falso-positivo principal: se pregunta dos veces con temperatura alta
    y solo se acepta si las dos lecturas dan EXACTAMENTE el mismo numero. Si
    la IA se inventa un digito, casi nunca se inventa el mismo dos veces.
    """
    from google import genai as genai_sdk
    from google.genai import types as genai_types

    use_vertex = os.environ.get("USE_VERTEX_AI", "").lower() in ("1", "true", "yes")
    if use_vertex:
        from google.oauth2 import service_account
        import json as _json
        import base64 as _b64
        sa_clean = os.environ.get("GCP_SERVICE_ACCOUNT_JSON", "").strip()
        if sa_clean and not sa_clean.startswith("{"):
            sa_clean = _b64.b64decode(sa_clean).decode("utf-8")
        credentials = service_account.Credentials.from_service_account_info(
            _json.loads(sa_clean), scopes=["https://www.googleapis.com/auth/cloud-platform"]
        ) if sa_clean else None
        client = genai_sdk.Client(
            vertexai=True, project=os.environ.get("GCP_PROJECT", ""),
            location=os.environ.get("GCP_LOCATION", "us-central1"), credentials=credentials
        )
    else:
        client = genai_sdk.Client(api_key=os.environ.get("GEMINI_API_KEY", ""))

    prompt = (
        "Foto del cuadro de instrumentos de una furgoneta. Tu unica tarea es leer "
        "el ODOMETRO TOTAL (kilometraje acumulado del vehiculo).\n"
        "REGLAS ESTRICTAS:\n"
        "1. Si el cuadro esta APAGADO (pantalla negra, sin luces, sin digitos), "
        "cuadro_encendido=false y km=null. NO adivines.\n"
        "2. El odometro TOTAL suele tener 5-6 digitos. El PARCIAL (trip/A/B) suele "
        "tener 3-4 digitos y un punto decimal. Si solo ves el parcial, es_parcial=true "
        "y km=null.\n"
        "3. Si esta borroso, reflejado, cortado o no distingues TODOS los digitos con "
        "total seguridad, legible=false y km=null. Es mejor no leer que equivocarse.\n"
        "4. NO incluyas decimales ni separadores. Solo el entero.\n"
        "5. confianza refleja lo seguro que estas de CADA digito.\n"
        'Responde SOLO este JSON: {"km": <entero o null>, "confianza": <0.0-1.0>, '
        '"legible": <true|false>, "cuadro_encendido": <true|false>, '
        '"es_parcial": <true|false>, "digitos": <numero de digitos que ves o null>}'
    )
    gen_config = genai_types.GenerateContentConfig(
        temperature=0.4, response_mime_type="application/json")
    contents = [prompt, genai_types.Part.from_bytes(data=img_bytes, mime_type="image/jpeg")]

    loop = asyncio.get_running_loop()

    async def _una():
        async with _gemini_sem:
            resp = await asyncio.wait_for(
                loop.run_in_executor(
                    _executor,
                    lambda: client.models.generate_content(
                        model=os.environ.get("GEMINI_MODEL", "gemini-2.5-flash"),
                        contents=contents, config=gen_config)),
                timeout=45.0)
        return json.loads(_strip_markdown_json(resp.text or ""))

    lecturas, servicio_caido = [], False
    for _ in range(max(1, intentos)):
        try:
            lecturas.append(await _una())
        except Exception as e:
            # 429 (cuota), 5xx o timeout = problema NUESTRO, no de la foto del
            # conductor. Hay que decirselo tal cual: culpar a su foto cuando el
            # servicio esta caido le hace repetirla diez veces para nada.
            txt = str(e)
            if ("429" in txt or "RESOURCE_EXHAUSTED" in txt or "quota" in txt.lower()
                    or "503" in txt or "500" in txt or "UNAVAILABLE" in txt
                    or isinstance(e, asyncio.TimeoutError)):
                servicio_caido = True
            logger.warning(f"Odometro: fallo una lectura — {e}")
    return {"lecturas": lecturas, "servicio_caido": servicio_caido}


def _odo_consenso(lecturas, servicio_caido: bool = False):
    """Une las lecturas. Solo hay numero si TODAS coinciden exactamente."""
    if isinstance(lecturas, dict):        # forma nueva de _odo_leer_foto
        servicio_caido = lecturas.get("servicio_caido", servicio_caido)
        lecturas = lecturas.get("lecturas") or []
    if not lecturas:
        return {"km": None, "confianza": 0.0, "legible": False, "cuadro_encendido": True,
                "es_parcial": False, "servicio_caido": servicio_caido,
                "motivo": ("El lector automatico no esta disponible en este momento. "
                           "Escribe los km a mano; tu foto se guarda igual.")
                          if servicio_caido else "No se pudo analizar la foto."}
    apagado = any(r.get("cuadro_encendido") is False for r in lecturas)
    parcial = any(r.get("es_parcial") is True for r in lecturas)
    ilegible = any(not r.get("legible") for r in lecturas)
    kms = [r.get("km") for r in lecturas]
    conf = min([float(r.get("confianza") or 0) for r in lecturas] or [0.0])
    validos = [k for k in kms if isinstance(k, (int, float)) and not isinstance(k, bool)]

    motivo = None
    if apagado:
        motivo = ("El cuadro esta apagado. Da el contacto para que se enciendan los "
                  "km y repite la foto.")
    elif parcial:
        motivo = ("Eso es el cuentakilometros PARCIAL (trip). Necesito el total del "
                  "vehiculo, el de 5-6 digitos.")
    elif ilegible or not validos:
        motivo = ("No se leen los km con claridad. Acercate mas, enfoca el cuadro y "
                  "evita reflejos.")
    elif len(validos) != len(lecturas) or len(set(int(k) for k in validos)) != 1:
        motivo = ("La lectura no es fiable: al revisar la foto dos veces salen numeros "
                  "distintos. Repitela mas cerca y enfocada.")
    elif conf < ODO_MIN_CONFIANZA:
        motivo = ("La foto no da seguridad suficiente para dar los km por buenos. "
                  "Acercate y enfoca el cuadro.")
    return {
        "km": int(validos[0]) if validos and not motivo else None,
        "confianza": round(conf, 2),
        "legible": motivo is None,
        "cuadro_encendido": not apagado,
        "es_parcial": parcial,
        "motivo": motivo,
    }


@api_router.post("/vehicles/{vehicle_id}/odometer-photo")
async def read_odometer_photo(vehicle_id: str, file: UploadFile = File(...), user: dict = Depends(require_any_auth)):
    """Lee los km del cuadro. NO escribe nada: solo dictamina si la foto vale.

    Devuelve siempre la misma forma, tambien cuando falla:
      aceptada       -> la lectura es fiable y plausible, se puede usar
      motivo         -> por que se rechaza (texto para el conductor)
      manual_permitido -> si el conductor puede teclear los km a mano
      manual_min/max -> rango exacto permitido a mano
    """
    v = await db.vehicles.find_one({"id": vehicle_id},
                                   {"_id": 0, "license_plate": 1, "mileage": 1,
                                    "mileage_history": 1, "updated_at": 1})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")
    content = await file.read()
    if not content or len(content) > 15 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="Imagen invalida o demasiado grande")

    actual, dias, tope = _odo_margen(v)
    base = {
        "aceptada": False, "km": None, "confianza": 0.0,
        "current_mileage": actual, "manual_permitido": True,
        "manual_min": actual, "manual_max": tope, "dias": dias,
    }

    try:
        img = Image.open(io.BytesIO(content)).convert("RGB")
        img.thumbnail((1280, 1280))
        buf = io.BytesIO()
        img.save(buf, format="JPEG", quality=85)
        lectura_raw = await _odo_leer_foto(buf.getvalue())
    except Exception as e:
        logger.error(f"Odometro: no se pudo procesar la foto — {e}")
        return {**base, "motivo": "No se ha podido analizar la foto ahora mismo."}

    r = _odo_consenso(lectura_raw)
    if r["motivo"]:
        logger.info(f"Odometro {v.get('license_plate','')}: RECHAZADA — {r['motivo']}")
        return {**base, "confianza": r["confianza"], "motivo": r["motivo"],
                "servicio_caido": bool(r.get("servicio_caido"))}

    # La lectura es limpia. ¿Es creible para ESTE vehiculo?
    ok, motivo, _info = _odo_validar(v, r["km"])
    if not ok:
        logger.info(f"Odometro {v.get('license_plate','')}: implausible — {motivo}")
        return {**base, "km": r["km"], "confianza": r["confianza"], "motivo": motivo}

    logger.info(f"Odometro {v.get('license_plate','')}: ACEPTADA {r['km']} "
                f"(confianza {r['confianza']})")
    return {**base, "aceptada": True, "km": r["km"], "confianza": r["confianza"],
            "manual_permitido": False, "motivo": None}


@api_router.post("/vehicles/{vehicle_id}/mileage")
async def update_mileage(vehicle_id: str, data: dict, user: dict = Depends(require_any_auth)):
    """Actualiza el kilometraje. Conductores solo su vehículo. Genera aviso de aceite si toca."""
    km = _entero(data.get("km"), "km", minimo=0, maximo=2_000_000)
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")
    if user["role"] == "driver" and v.get("current_driver_id") != user["sub"]:
        # Los conductores rotan por cuadrante diario: aceptar si HOY tiene
        # asignada esta furgoneta, o si acaba de inspeccionarla hoy.
        today = _dia_negocio()
        assigned_today = await db.daily_assignments.find_one({
            "date": today,
            "slots": {"$elemMatch": {"driver_id": user["sub"], "vehicle_id": vehicle_id}}
        }, {"_id": 0, "id": 1})
        inspected_today = None
        if not assigned_today:
            inspected_today = await db.inspections.find_one({
                "vehicle_id": vehicle_id, "driver_id": user["sub"],
                "created_at": {"$regex": f"^{today}"}
            }, {"_id": 0, "id": 1})
        if not assigned_today and not inspected_today:
            raise HTTPException(status_code=403, detail="Solo tu vehículo asignado")
    # Los admin mandan: pueden corregir a mano cualquier valor (p.ej. arreglar
    # un historico corrompido). Conductores pasan por las reglas de plausibilidad.
    if user.get("role") == "admin":
        # UN ADMIN TAMBIEN SE EQUIVOCA TECLEANDO, y aqui no habia ni una
        # comprobacion. De ahi salio la ultima alerta que genero el sistema:
        # "se ha pasado 61.677.151 km del cambio de aceite". Ninguna furgoneta
        # de reparto llega al millon; por encima de eso son digitos de mas.
        if km > _KM_MAXIMO_CREIBLE:
            raise HTTPException(
                status_code=400,
                detail=f"{km:,} km no es un kilometraje creible. Revisa el numero."
                       .replace(",", "."))
        km_entry = {"date": datetime.now(timezone.utc).isoformat(), "km": km,
                    "source": "admin"}
        await db.vehicles.update_one({"id": vehicle_id},
            {"$set": {"mileage": km, "updated_at": datetime.now(timezone.utc)},
             "$push": {"mileage_history": km_entry}})
    else:
        fuente = str(data.get("source") or "manual")[:32]
        aplicado, motivo, _inf = await _odo_registrar(
            vehicle_id, km, fuente,
            {"by": user.get("sub"), "by_role": user.get("role")})
        if not aplicado:
            raise HTTPException(status_code=400, detail=motivo or "Kilometraje no valido")

    # ¿Toca avisar de aceite?
    oil_km = v.get("oil_last_change_km")
    oil_alert = None
    if oil_km is not None:
        intervalo = v.get("oil_interval_km", 15000)
        aviso_antes = v.get("oil_warning_before_km", 2500)
        recorridos = km - oil_km
        restantes = intervalo - recorridos
        # NO SE AVISA CON UN NUMERO IMPOSIBLE. Si el kilometraje del ultimo
        # cambio esta mal —o lo estaba el de hoy—, `recorridos` sale absurdo y
        # la alerta dice una barbaridad. Y una alerta falsa hace mas dano que
        # ninguna: ensena a ignorarlas todas, que es exactamente lo que paso
        # aqui (50 alertas en total, la ultima en junio, y decia 61 millones de
        # kilometros). Mejor callar y que alguien arregle el dato.
        if recorridos < 0 or recorridos > _KM_SALTO_ABSURDO:
            logger.warning(
                "Aviso de aceite descartado en %s: %s km desde el ultimo cambio "
                "no es creible (actual %s, ultimo cambio %s)",
                v.get("license_plate"), recorridos, km, oil_km)
        elif restantes <= aviso_antes:
            if restantes <= 0:
                titulo = f"CAMBIO DE ACEITE VENCIDO en {v.get('license_plate','')}"
                desc = f"Se ha pasado {abs(restantes)} km del cambio de aceite."
                sev = "high"
            else:
                titulo = f"Cambio de aceite próximo en {v.get('license_plate','')}"
                desc = f"Quedan {restantes} km para el cambio de aceite (intervalo {intervalo} km)."
                sev = "medium"
            # Evitar duplicar el aviso si ya hay uno reciente sin leer
            existe = await db.alerts.find_one({"vehicle_id": vehicle_id, "title": titulo, "read": {"$ne": True}})
            if not existe:
                await db.alerts.insert_one(serialize_doc(Alert(
                    vehicle_id=vehicle_id, inspection_id="", title=titulo,
                    description=desc, severity=sev).model_dump()))
                oil_alert = {"remaining_km": restantes, "message": desc}
                # Notificar a Telegram también
                try:
                    config = await db.telegram_config.find_one({}, {"_id": 0})
                    if config and config.get("enabled") and config.get("bot_token"):
                        async with _aiohttp.ClientSession() as session:
                            for cid in config.get("chat_ids", []):
                                if cid.strip():
                                    await session.post(
                                        f"https://api.telegram.org/bot{config['bot_token']}/sendMessage",
                                        json={"chat_id": cid, "text": f"🛢️ <b>{titulo}</b>\n{desc}", "parse_mode": "HTML"},
                                        timeout=_aiohttp.ClientTimeout(total=8))
                except Exception as e:
                    logger.warning(f"Telegram aceite: {e}")

    # ¿Toca avisar de ruedas o pastillas? (mismo patrón que el aceite)
    for _mk, _mspec in (("ruedas", {"label": "CAMBIO DE RUEDAS", "emoji": "🛞", "interval": 40000, "warn": 3000}),
                        ("pastillas", {"label": "PASTILLAS DE FRENO", "emoji": "🛑", "interval": 30000, "warn": 3000})):
        last_km = v.get(f"{_mk}_last_change_km")
        if last_km is None:
            continue
        _interval = v.get(f"{_mk}_interval_km", _mspec["interval"])
        _warn = v.get(f"{_mk}_warning_before_km", _mspec["warn"])
        _rest = _interval - (km - last_km)
        if _rest <= _warn:
            if _rest <= 0:
                _tit = f"{_mspec['label']} VENCIDO en {v.get('license_plate','')}"
                _desc = f"Se ha pasado {abs(_rest)} km del cambio."
                _sev = "high"
            else:
                _tit = f"{_mspec['label'].capitalize()} próximo en {v.get('license_plate','')}"
                _desc = f"Quedan {_rest} km (intervalo {_interval} km)."
                _sev = "medium"
            _existe = await db.alerts.find_one({"vehicle_id": vehicle_id, "title": _tit, "read": {"$ne": True}})
            if not _existe:
                await db.alerts.insert_one(serialize_doc(Alert(
                    vehicle_id=vehicle_id, inspection_id="", title=_tit,
                    description=_desc, severity=_sev).model_dump()))
                try:
                    config = await db.telegram_config.find_one({}, {"_id": 0})
                    if config and config.get("enabled") and config.get("bot_token"):
                        async with _aiohttp.ClientSession() as session:
                            for cid in config.get("chat_ids", []):
                                if cid.strip():
                                    await session.post(
                                        f"https://api.telegram.org/bot{config['bot_token']}/sendMessage",
                                        json={"chat_id": cid, "text": f"{_mspec['emoji']} <b>{_tit}</b>\n{_desc}", "parse_mode": "HTML"},
                                        timeout=_aiohttp.ClientTimeout(total=8))
                except Exception as e:
                    logger.warning(f"Telegram {_mk}: {e}")

    return {"success": True, "mileage": km, "oil_alert": oil_alert}


@api_router.get("/fleet/calendar")
async def fleet_calendar(mes: str = "", center: Optional[str] = None,
                         user: dict = Depends(require_admin)):
    """Todo lo que vence en un MES, por furgoneta, para verlo de una vez.

    Nace de una queja concreta: para saber qué toca hay que entrar furgoneta por
    furgoneta, y con 84 nadie lo hace. Aquí se ve el mes entero.

    ── LO QUE TIENE FECHA Y LO QUE NO ────────────────────────────────────────
    No todo lo que vence vence en una fecha, y mezclarlo sería mentir:

      · ITV y fin de renting son FECHAS REALES (`itv_date`, `renting_end_date`).
        Van al día que les toca y punto.
      · Aceite, ruedas y pastillas se miden en KILÓMETROS. Su "fecha" sale de
        dividir los km que faltan entre los km/día que hace esa furgoneta: es
        una ESTIMACIÓN. Viaja marcada como tal (`exacto: false`) para que la
        pantalla pueda pintarla distinta. Un cambio de aceite estimado no es un
        compromiso con Tráfico como lo es una ITV.
      · Y si una furgoneta no tiene ritmo medible (sin histórico de km), NO se
        le inventa una fecha: se devuelve aparte, en `sin_estimacion`.

    Lo ya vencido tampoco se coloca en un día futuro: va en `vencidos`, que es
    una lista de cosas que ya deberían estar hechas, no una cita del calendario.

    ── CITAS PUESTAS A MANO ──────────────────────────────────────────────────
    Una previsión dice cuándo TOCARÍA; una cita dice cuándo VA. Si alguien
    aparta la furgoneta para el día 5 porque ese día hay hueco en el taller,
    esa fecha manda sobre la estimada y la SUSTITUYE: si no, saldrían las dos
    y el calendario diría dos cosas distintas del mismo cambio.

    Una cita cuyo día ya pasó y que nadie marcó como hecha no se queda en la
    rejilla como si aún fuese a pasar: cae a `vencidos`, que es donde va lo
    que debería estar hecho y no lo está.

    El filtro por centro se aplica AQUÍ, con `_filtro_centro`, que es el mismo
    que usa /vehicles: las de DGA1 no pueden aparecer en OGA5 ni al revés.
    """
    from datetime import date as _date
    hoy = _date.today()
    try:
        anio, mesn = (int(x) for x in (mes or hoy.strftime("%Y-%m")).split("-"))
        primero = _date(anio, mesn, 1)
    except Exception:
        raise HTTPException(400, "mes debe ser YYYY-MM")
    ultimo = _date(anio + (mesn == 12), (mesn % 12) + 1, 1) - timedelta(days=1)

    query = {"status": {"$nin": ["deleted", "baja"]}}
    query.update(_filtro_centro(user, center))
    vehiculos = await db.vehicles.find(query, {"_id": 0}).to_list(1000)

    eventos, vencidos, sin_estimacion = [], [], []

    def _ficha(v):
        # El kilometraje viaja para que al cerrar una cita el campo de km venga
        # ya puesto: pedirlo en blanco invita a inventárselo, y de ese número
        # sale la siguiente previsión.
        return {"vehicle_id": v.get("id"), "matricula": v.get("license_plate"),
                "modelo": " ".join(x for x in (v.get("brand"), v.get("model")) if x) or None,
                "center": v.get("center"), "mileage": v.get("mileage")}

    # Citas manuales pendientes de estas furgonetas. Se leen ANTES de calcular
    # nada: lo que tiene cita ya no se estima, se sabe.
    ids_veh = [v.get("id") for v in vehiculos if v.get("id")]
    citas = await db.fleet_appointments.find(
        {"vehicle_id": {"$in": ids_veh}, "estado": "pendiente"}, {"_id": 0}).to_list(5000)
    # Una cita tapa la previsión de lo que cubre, y sólo de eso: si se han
    # apartado las ruedas de DELANTE, las de atrás siguen contando sus km.
    fijadas: dict = {}
    for c in citas:
        clave = (c.get("vehicle_id"), c.get("tipo"))
        fijadas.setdefault(clave, set()).update(c.get("posiciones") or [None])

    def _tapado(vid, tipo, pos=None) -> bool:
        cubre = fijadas.get((vid, tipo))
        return cubre is not None and (pos is None or pos in cubre or None in cubre)

    for v in vehiculos:
        # ── Fechas reales ────────────────────────────────────────────────────
        for campo, tipo in (("itv_date", "itv"), ("renting_end_date", "renting")):
            if _tapado(v.get("id"), tipo):
                continue                      # hay cita: manda la cita
            crudo = v.get(campo)
            if not crudo:
                if tipo == "itv":
                    sin_estimacion.append({**_ficha(v), "tipo": "itv", "motivo": "sin_fecha"})
                continue
            try:
                y, m, d = (int(x) for x in str(crudo)[:10].split("-"))
                f = _date(y, m, d)
            except Exception:
                continue
            dias = (f - hoy).days
            fila = {**_ficha(v), "tipo": tipo, "fecha": f.isoformat(),
                    "dias": dias, "exacto": True}
            if dias < 0:
                vencidos.append(fila)
            elif primero <= f <= ultimo:
                eventos.append(fila)

        # ── Kilómetros: fecha ESTIMADA, y sólo si hay ritmo medible ──────────
        kpd = _km_por_dia(v)
        for kind, di, dw in (("oil", 15000, 2500), ("ruedas", 40000, 3000),
                             ("pastillas", 30000, 3000)):
            # El aceite es uno; ruedas y pastillas son dos ejes que se gastan
            # a ritmos distintos y se cambian por separado.
            for pos in _ejes_de(v, kind):
                if _tapado(v.get("id"), kind, pos):
                    continue                  # hay cita: manda la cita
                item = _build_maint_item(v, kind, di, dw, pos)
                if not item:
                    continue
                base = {**_ficha(v), "tipo": kind, "posicion": pos, "exacto": False,
                        "km_restantes": item.get("km_until_change")}
                if item.get("overdue"):
                    vencidos.append({**base, "fecha": None, "dias": None})
                    continue
                if not kpd:
                    # Sin km/día no hay forma honesta de poner esto en un día.
                    sin_estimacion.append({**base, "motivo": "sin_ritmo"})
                    continue
                dias = max(0, round(item["km_until_change"] / kpd))
                f = hoy + timedelta(days=dias)
                if primero <= f <= ultimo:
                    eventos.append({**base, "fecha": f.isoformat(), "dias": dias})

    # ── Las citas, ya con la ficha de su furgoneta ───────────────────────────
    por_id = {v.get("id"): v for v in vehiculos}
    for c in citas:
        v = por_id.get(c.get("vehicle_id"))
        if not v:
            continue
        try:
            y, m, d = (int(x) for x in str(c.get("fecha"))[:10].split("-"))
            f = _date(y, m, d)
        except Exception:
            continue
        fila = {**_ficha(v), "tipo": c.get("tipo"), "fecha": f.isoformat(),
                "dias": (f - hoy).days, "exacto": True, "cita": True,
                "cita_id": c.get("id"), "nota": c.get("nota") or None,
                "taller": c.get("taller") or None}
        if f < hoy:
            # Una cita que ya pasó y nadie cerró no es una cita, es un olvido.
            vencidos.append(fila)
        elif primero <= f <= ultimo:
            eventos.append(fila)

    eventos.sort(key=lambda e: (e["fecha"], e["tipo"]))
    vencidos.sort(key=lambda e: (e.get("dias") is None, e.get("dias") or 0))
    return {"mes": f"{anio:04d}-{mesn:02d}", "desde": primero.isoformat(),
            "hasta": ultimo.isoformat(), "vehiculos": len(vehiculos),
            "eventos": eventos, "vencidos": vencidos,
            "sin_estimacion": sin_estimacion,
            "citas": sum(1 for c in citas if c.get("vehicle_id") in por_id)}


# ── Citas de taller puestas a mano ───────────────────────────────────────────
# El calendario sabe cuándo TOCARÍA cada cosa. Esto es para decirle cuándo VA:
# adelantar un cambio porque el taller tiene hueco el martes, juntar el aceite
# con las pastillas en el mismo viaje, o apuntar una revisión que no sale de
# ningún kilometraje. Sin esto el calendario solo se puede mirar.
_TIPOS_CITA = {"itv", "renting", "oil", "ruedas", "pastillas", "taller", "otro"}
# Ruedas y pastillas van por ejes. Las de delante y las de atrás no se gastan
# igual (frenar carga el tren delantero), y en un reparto casi nunca se cambian
# las cuatro: contarlas juntas hacía que cambiar dos reiniciase el contador de
# las otras dos, que seguían gastadas y ya no avisaban.
_EJES = ("delante", "detras")
_POR_EJES = {"ruedas", "pastillas"}


def _ejes_de(v: dict, kind: str) -> tuple:
    """Por qué ejes hay que contar este mantenimiento en ESTA furgoneta.

    Mientras nadie haya apuntado un cambio por ejes, lo único que consta es un
    cambio "de ruedas" sin decir cuáles: partirlo en dos daría DOS avisos
    idénticos para un solo dato, que es inventarse información. Se cuenta como
    uno solo, sin eje, hasta que alguien resuelva un cambio marcando cuáles —
    y a partir de ahí ya sí van por separado.
    """
    if kind not in _POR_EJES:
        return (None,)
    if any(v.get(f"{kind}_{p}_last_change_km") is not None for p in _EJES):
        return _EJES
    return (None,)


def _valida_posiciones(crudo, tipo: str) -> Optional[list]:
    """Normaliza la lista de ejes. Vacía o ausente en un tipo por ejes = las 4."""
    if tipo not in _POR_EJES:
        return None
    if not crudo:
        return list(_EJES)
    if isinstance(crudo, str):
        crudo = [crudo]
    vals = [str(p).strip().lower() for p in crudo]
    malas = [p for p in vals if p not in _EJES]
    if malas:
        raise HTTPException(400, f"Posición inválida: {', '.join(malas)}")
    return [p for p in _EJES if p in vals]   # siempre en el mismo orden


def _valida_fecha_cita(crudo) -> str:
    from datetime import date as _date
    try:
        y, m, d = (int(x) for x in str(crudo)[:10].split("-"))
        return _date(y, m, d).isoformat()
    except Exception:
        raise HTTPException(400, "fecha debe ser YYYY-MM-DD")


async def _vehiculo_visible(vehicle_id: str, user: dict) -> dict:
    """La furgoneta, sólo si este usuario puede verla. Si no, 404.

    El filtro por centro del calendario no serviría de nada si luego se
    pudieran crear citas sobre furgonetas de otro centro mandando su id.
    """
    q = {"id": vehicle_id}
    q.update(_filtro_centro(user, None))
    v = await db.vehicles.find_one(q, {"_id": 0})
    if not v:
        raise HTTPException(404, "Furgoneta no encontrada")
    return v


@api_router.post("/fleet/calendar/citas")
async def crear_cita_flota(data: dict, user: dict = Depends(require_admin)):
    """Aparta un día para una furgoneta. Sustituye a la previsión de ese tipo."""
    vehicle_id = str(data.get("vehicle_id") or "").strip()
    tipo = str(data.get("tipo") or "").strip().lower()
    if not vehicle_id:
        raise HTTPException(400, "Falta vehicle_id")
    if tipo not in _TIPOS_CITA:
        raise HTTPException(400, f"tipo debe ser uno de: {', '.join(sorted(_TIPOS_CITA))}")
    fecha = _valida_fecha_cita(data.get("fecha"))
    v = await _vehiculo_visible(vehicle_id, user)

    # Una furgoneta no puede tener dos citas abiertas del mismo tipo: la segunda
    # mueve la primera, que es lo que de verdad se quiere al reprogramar.
    doc = {"vehicle_id": vehicle_id, "tipo": tipo, "fecha": fecha,
           "posiciones": _valida_posiciones(data.get("posiciones"), tipo),
           "nota": str(data.get("nota") or "")[:300] or None,
           "taller": str(data.get("taller") or "")[:120] or None,
           "estado": "pendiente", "updated_at": datetime.now(timezone.utc),
           "updated_by": user.get("sub")}
    ya = await db.fleet_appointments.find_one(
        {"vehicle_id": vehicle_id, "tipo": tipo, "estado": "pendiente"}, {"_id": 0, "id": 1})
    if ya:
        await db.fleet_appointments.update_many(
            {"vehicle_id": vehicle_id, "tipo": tipo, "estado": "pendiente"}, {"$set": doc})
        return {"success": True, "id": ya["id"], "movida": True}
    doc.update({"id": str(uuid.uuid4()), "created_at": datetime.now(timezone.utc),
                "created_by": user.get("sub"), "matricula": v.get("license_plate")})
    await db.fleet_appointments.insert_one(dict(doc))
    return {"success": True, "id": doc["id"], "movida": False}


@api_router.patch("/fleet/calendar/citas/{cita_id}")
async def editar_cita_flota(cita_id: str, data: dict, user: dict = Depends(require_admin)):
    """Mueve la fecha, cambia la nota o la cierra (`estado: hecho`)."""
    c = await db.fleet_appointments.find_one({"id": cita_id}, {"_id": 0})
    if not c:
        raise HTTPException(404, "Cita no encontrada")
    await _vehiculo_visible(c.get("vehicle_id"), user)

    cambios = {"updated_at": datetime.now(timezone.utc), "updated_by": user.get("sub")}
    if data.get("fecha"):
        cambios["fecha"] = _valida_fecha_cita(data["fecha"])
    if "nota" in data:
        cambios["nota"] = str(data.get("nota") or "")[:300] or None
    if "taller" in data:
        cambios["taller"] = str(data.get("taller") or "")[:120] or None
    if "posiciones" in data:
        cambios["posiciones"] = _valida_posiciones(data.get("posiciones"), c.get("tipo"))
    if data.get("estado") in ("pendiente", "hecho"):
        cambios["estado"] = data["estado"]
        cambios["done_at"] = datetime.now(timezone.utc) if data["estado"] == "hecho" else None
    await db.fleet_appointments.update_one({"id": cita_id}, {"$set": cambios})
    return {"success": True}


async def _log_mantenimiento(v: dict, tipo: str, km: Optional[int], nota: str = "",
                             taller: str = "", origen: str = "manual",
                             cita_id: Optional[str] = None, por: Optional[str] = None,
                             fecha: Optional[str] = None,
                             posiciones: Optional[list] = None) -> dict:
    """Apunta en el historial QUÉ se le hizo a una furgoneta y cuándo.

    Hasta ahora sólo se guardaba en el vehículo el km del ÚLTIMO cambio de cada
    cosa. Eso sirve para prever el siguiente, pero borra el anterior: no había
    forma de responder "¿cuándo se le cambiaron las ruedas y qué se le hizo?".
    Un mantenimiento sin historial es un mantenimiento que hay que recordar de
    memoria, y con 122 furgonetas eso no se sostiene.

    La nota es lo que de verdad se hizo ("ruedas traseras"), que casi nunca es
    exactamente el título de la cita.
    """
    doc = {
        "id": str(uuid.uuid4()),
        "vehicle_id": v.get("id"), "matricula": v.get("license_plate"),
        "center": v.get("center"), "tipo": tipo,
        "fecha": (fecha or datetime.now(timezone.utc).date().isoformat())[:10],
        "km": km, "nota": (nota or "").strip()[:300] or None,
        "taller": (taller or "").strip()[:120] or None,
        "origen": origen, "cita_id": cita_id, "posiciones": posiciones or None,
        # Qué había ANTES de este cambio, eje por eje. Es lo que permite
        # deshacerlo: un apunte equivocado que solo se borrase de la lista
        # dejaría el contador de km puesto a un cambio que no ocurrió, y esa
        # furgoneta pasaría 40.000 km sin avisar de nada.
        "prev": {
            (p or "_"): {"km": v.get(f"{tipo}_{p}_last_change_km" if p else f"{tipo}_last_change_km"),
                         "fecha": v.get(f"{tipo}_{p}_last_change_date" if p else f"{tipo}_last_change_date")}
            for p in (posiciones or [None])
        },
        "prev_km": v.get(f"{tipo}_last_change_km"),
        "prev_fecha": v.get(f"{tipo}_last_change_date"),
        "created_at": datetime.now(timezone.utc), "created_by": por,
    }
    await db.maintenance_log.insert_one(dict(doc))
    doc.pop("_id", None)
    return doc


@api_router.post("/fleet/calendar/citas/{cita_id}/resolver")
async def resolver_cita_flota(cita_id: str, data: dict, user: dict = Depends(require_admin)):
    """Cierra una cita diciendo qué se hizo, y lo deja hecho de verdad.

    Marcar "hecho" a secas sería mentir a medias: la cita desaparecería del
    calendario pero la furgoneta seguiría contando los kilómetros desde el
    cambio ANTERIOR, así que al día siguiente volvería a salir que le toca. Al
    resolver se hacen las tres cosas a la vez:

      1. se pone a cero el contador del tipo que sea (el km de ahora pasa a ser
         el del último cambio, y de ahí sale la siguiente previsión),
      2. se apunta en el historial de la furgoneta lo que se le hizo,
      3. y se cierra la cita.

    Para la ITV no hay kilómetros que reiniciar: lo que reinicia el ciclo es la
    fecha de la próxima, y por eso se pide (`itv_date`). Si no se da, se apunta
    lo hecho y la fecha se queda como estaba — nunca se inventa una.
    """
    c = await db.fleet_appointments.find_one({"id": cita_id}, {"_id": 0})
    if not c:
        raise HTTPException(404, "Cita no encontrada")
    v = await _vehiculo_visible(c.get("vehicle_id"), user)

    tipo = c.get("tipo")
    fecha = _valida_fecha_cita(data.get("fecha") or datetime.now(timezone.utc).date().isoformat())
    nota = str(data.get("nota") or "")[:300]
    taller = str(data.get("taller") or c.get("taller") or "")[:120]
    km = data.get("km")
    km = _entero(km, "km", defecto=0, minimo=0, maximo=2_000_000) if km not in (None, "") else None

    # Qué ejes se han tocado. Se reinicia el contador SOLO de esos: si se han
    # cambiado las de delante, las de atrás siguen con los km que llevaban.
    posiciones = _valida_posiciones(
        data.get("posiciones") if "posiciones" in data else c.get("posiciones"), tipo)

    cambios: dict = {"updated_at": datetime.now(timezone.utc)}
    if tipo in ("oil", "ruedas", "pastillas"):
        # Sin km no se puede reiniciar el contador. Se cae al kilometraje
        # conocido de la furgoneta antes que dejarlo sin reiniciar.
        base = km if km is not None else (v.get("mileage") or None)
        if base is None:
            raise HTTPException(400, "Hacen falta los kilómetros para reiniciar el contador")
        for p in (posiciones or [None]):
            pref = f"{tipo}_{p}" if p else tipo
            cambios[f"{pref}_last_change_km"] = base
            cambios[f"{pref}_last_change_date"] = fecha
        if posiciones and len(posiciones) == len(_EJES):
            # Las cuatro: el dato sin eje deja de significar nada distinto y se
            # actualiza también, que es de donde tiran las pantallas viejas.
            cambios[f"{tipo}_last_change_km"] = base
            cambios[f"{tipo}_last_change_date"] = fecha
        cambios["mileage"] = max(base, v.get("mileage") or 0)
        km = base
    elif tipo == "itv" and data.get("itv_date"):
        cambios["itv_date"] = _valida_fecha_cita(data["itv_date"])
    elif tipo == "renting" and data.get("renting_end_date"):
        cambios["renting_end_date"] = _valida_fecha_cita(data["renting_end_date"])
    elif km is not None:
        cambios["mileage"] = max(km, v.get("mileage") or 0)

    await db.vehicles.update_one({"id": v["id"]}, {"$set": cambios})
    entrada = await _log_mantenimiento(v, tipo, km, nota, taller, origen="cita",
                                       cita_id=cita_id, por=user.get("sub"), fecha=fecha,
                                       posiciones=posiciones)
    await db.fleet_appointments.update_one({"id": cita_id}, {"$set": {
        "estado": "hecho", "done_at": datetime.now(timezone.utc),
        "nota": nota or c.get("nota"), "taller": taller or None,
        "updated_at": datetime.now(timezone.utc), "updated_by": user.get("sub")}})
    return {"success": True, "entrada": entrada}


@api_router.get("/vehicles/{vehicle_id}/maintenance-log")
async def get_maintenance_log(vehicle_id: str, user: dict = Depends(require_admin)):
    """Todo lo que se le ha hecho a esta furgoneta, lo último primero."""
    await _vehiculo_visible(vehicle_id, user)
    rows = await db.maintenance_log.find({"vehicle_id": vehicle_id}, {"_id": 0}) \
        .sort("fecha", -1).to_list(200)
    return {"rows": rows}


@api_router.delete("/vehicles/{vehicle_id}/maintenance-log/{entry_id}")
async def borrar_apunte_mantenimiento(vehicle_id: str, entry_id: str,
                                      user: dict = Depends(require_admin)):
    """Quita un apunte del historial y DESHACE lo que hizo.

    Un apunte equivocado que solo desapareciera de la lista sería peor que no
    poder borrarlo: el contador de kilómetros seguiría creyendo que el cambio
    se hizo, y esa furgoneta se pasaría un intervalo entero sin avisar. Por eso
    cada apunte guarda qué había antes y aquí se restaura — si antes no había
    nada, se quita el dato, que es lo que había.
    """
    await _vehiculo_visible(vehicle_id, user)
    e = await db.maintenance_log.find_one({"id": entry_id, "vehicle_id": vehicle_id}, {"_id": 0})
    if not e:
        raise HTTPException(404, "Apunte no encontrado")

    tipo = e.get("tipo")
    if tipo in ("oil", "ruedas", "pastillas"):
        v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0}) or {}
        prev = e.get("prev") or {}
        poner, quitar = {}, {}
        claves = [(p, f"{tipo}_{p}") for p in (e.get("posiciones") or [])] or [(None, tipo)]
        if e.get("posiciones") and len(e["posiciones"]) == len(_EJES):
            claves.append((None, tipo))       # se tocó también el dato sin eje
        for p, pref in claves:
            # Solo se deshace si este apunte es el que manda ahora: borrar uno
            # antiguo no puede pisar un cambio posterior que sí se hizo.
            if v.get(f"{pref}_last_change_km") != e.get("km"):
                continue
            antes = prev.get(p or "_") or {}
            km_antes = antes.get("km", e.get("prev_km") if p is None else None)
            if km_antes is not None:
                poner[f"{pref}_last_change_km"] = km_antes
                poner[f"{pref}_last_change_date"] = antes.get("fecha") or e.get("prev_fecha")
            else:
                quitar[f"{pref}_last_change_km"] = ""
                quitar[f"{pref}_last_change_date"] = ""
        ops = {}
        if poner:
            ops["$set"] = poner
        if quitar:
            ops["$unset"] = quitar
        if ops:
            await db.vehicles.update_one({"id": vehicle_id}, ops)

    await db.maintenance_log.delete_one({"id": entry_id})
    # La cita vuelve a estar pendiente: si el apunte era mentira, el cambio
    # sigue sin hacerse y tiene que volver al calendario.
    if e.get("cita_id"):
        await db.fleet_appointments.update_one({"id": e["cita_id"]}, {"$set": {
            "estado": "pendiente", "done_at": None,
            "updated_at": datetime.now(timezone.utc), "updated_by": user.get("sub")}})
    return {"success": True}


@api_router.delete("/fleet/calendar/citas/{cita_id}")
async def borrar_cita_flota(cita_id: str, user: dict = Depends(require_admin)):
    """Quita la cita. La previsión por kilómetros vuelve a salir sola."""
    c = await db.fleet_appointments.find_one({"id": cita_id}, {"_id": 0})
    if not c:
        raise HTTPException(404, "Cita no encontrada")
    await _vehiculo_visible(c.get("vehicle_id"), user)
    await db.fleet_appointments.delete_one({"id": cita_id})
    return {"success": True}


# 60 dias y no 30: las furgonetas de carga de mas de 10 anos pasan ITV cada seis
# meses, y con 30 dias de aviso no daba tiempo a coger cita en temporada alta.
_ITV_AVISO_DIAS = int(os.environ.get("ITV_AVISO_DIAS") or 60)


# Ninguna furgoneta de reparto llega al millon de kilometros; por encima de eso
# son digitos de mas al teclear. Y entre dos cambios de aceite no caben 300.000
# km ni haciendo 800 al dia durante un ano.
_KM_MAXIMO_CREIBLE = int(os.environ.get("KM_MAXIMO_CREIBLE") or 1_000_000)
_KM_SALTO_ABSURDO = int(os.environ.get("KM_SALTO_ABSURDO") or 300_000)


@api_router.get("/alerts/itv")
async def get_itv_alerts(center: Optional[str] = None, user: dict = Depends(require_admin)):
    """Furgonetas con la ITV caducada, a punto, o SIN FECHA NINGUNA.

    Acotado al centro pedido y a los que el usuario puede ver: hasta el
    02-09-2026 ignoraba `center` y el dashboard lo filtraba en el navegador
    bajandose el listado entero de furgonetas para eso.

    LAS QUE NO TIENEN FECHA SON EL HALLAZGO, no un detalle. Antes habia aqui un
    `if not itv: continue` y esas furgonetas se saltaban el bucle: no salian
    como "pendiente de rellenar", salian como si estuvieran bien. Medido el
    28-08-2026: de 127 activas, 67 tenian fecha y **60 no** — el 47 % de la
    flota, invisible. Es el mismo fallo del gotcha 17 (lo que no entra en
    ningun cajon desaparece sin error) y aqui cuesta 200 EUR sin margen, la
    inmovilizacion del vehiculo en plena ruta y que la aseguradora te repita lo
    que pague si hay accidente.

    No saber si una ITV esta en regla NO es lo mismo que estar en regla. Sale
    con `status: "sin_fecha"` y `days_left: None` —nunca 0, que pareceria "hoy"—
    y se ordena justo detras de las caducadas, porque en la practica hay que
    tratarla igual hasta comprobarlo.

    Las furgonetas de carga de mas de 10 anos pasan ITV cada 6 meses en Espana,
    asi que la ventana de aviso es de 60 dias y no de 30: con 30 no daba tiempo
    a coger cita en temporada alta.
    """
    from datetime import date as _date
    hoy = _date.today()
    vehicles = await db.vehicles.find(
        {"status": {"$nin": ["deleted", "baja"]}, **_filtro_centro(user, center)},
        {"_id": 0, "mileage_history": 0}).to_list(2000)
    result = []
    for v in vehicles:
        base = {"vehicle_id": v.get("id"), "license_plate": v.get("license_plate"),
                "brand": v.get("brand"), "model": v.get("model"), "center": v.get("center")}
        itv = v.get("itv_date")
        fecha = None
        if itv:
            try:
                y, m, d = [int(x) for x in str(itv).split("-")]
                fecha = _date(y, m, d)
            except (ValueError, TypeError):
                fecha = None
        if fecha is None:
            # Sin fecha, o con una fecha que no se puede leer: las dos cosas son
            # lo mismo para quien tiene que actuar — no se sabe.
            result.append({**base, "itv_date": itv or None, "days_left": None,
                           "status": "sin_fecha"})
            continue
        dias = (fecha - hoy).days
        if dias <= _ITV_AVISO_DIAS:
            result.append({**base, "itv_date": itv, "days_left": dias,
                           "status": "caducada" if dias < 0
                           else ("urgente" if dias <= 7 else "proxima")})
    # Caducadas primero (la mas vencida arriba), luego las que no se saben, y
    # despues por dias que quedan. `sin_fecha` no puede ir al final: es
    # justamente lo que llevaba meses sin que nadie lo mirara.
    _orden = {"caducada": 0, "sin_fecha": 1, "urgente": 2, "proxima": 3}
    result.sort(key=lambda x: (_orden.get(x["status"], 9),
                               x["days_left"] if x["days_left"] is not None else 0))
    return result


@api_router.get("/alerts/renting")
async def get_renting_alerts(_=Depends(require_admin)):
    """Lista furgonetas con vencimiento de renting próximo (30 días) o vencido."""
    from datetime import date as _date
    hoy = _date.today()
    vehicles = await db.vehicles.find({"status": {"$nin": ["deleted", "baja"]}}, {"_id": 0}).to_list(2000)
    result = []
    for v in vehicles:
        rent = v.get("renting_end_date")
        if not rent:
            continue
        try:
            y, m, d = [int(x) for x in rent.split("-")]
            fecha = _date(y, m, d)
        except Exception:
            continue
        dias = (fecha - hoy).days
        if dias <= 30:
            result.append({
                "vehicle_id": v.get("id"), "license_plate": v.get("license_plate"),
                "brand": v.get("brand"), "model": v.get("model"), "center": v.get("center"),
                "provider": v.get("provider"), "renting_end_date": rent, "days_left": dias,
                "status": "vencido" if dias < 0 else ("urgente" if dias <= 7 else "proximo"),
            })
    result.sort(key=lambda x: x["days_left"])
    return result


@api_router.get("/vehicles/{vehicle_id}/history")
async def get_vehicle_history(vehicle_id: str, _=Depends(require_admin)):
    """Devuelve el histórico de km y bolsas de una furgoneta, listo para graficar."""
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")
    # Historial de km (ordenado por fecha)
    mh = _odo_lecturas(v)
    km_points = [{"date": str(e.get("date", ""))[:10], "km": e.get("km", 0)} for e in mh]
    # Historial de bolsas: reconstruir el valor restante tras cada movimiento
    bh = v.get("bags_history", [])
    bags_points = []
    for e in bh:
        bags_points.append({
            "date": e.get("date", "")[:10],
            "remaining": e.get("remaining_after", e.get("remaining", 0)),
            "change": e.get("change", 0),
        })
    return {
        "license_plate": v.get("license_plate"),
        "current_mileage": v.get("mileage"),
        "current_bags": v.get("bags_remaining", 0),
        "km_history": km_points,
        "bags_history": bags_points,
    }


def _build_maint_item(v: dict, kind: str, default_interval: int, default_warn: int,
                      pos: Optional[str] = None) -> Optional[dict]:
    """Estado de un mantenimiento. Con `pos`, el de UN eje (delante/detrás).

    Ruedas y pastillas casi nunca se cambian de cuatro en cuatro, y los ejes no
    se gastan igual: contar los dos juntos hacía que cambiar las de delante
    reiniciara también el contador de las de atrás, que seguían gastadas.

    Compatibilidad: las furgonetas que ya tenían un cambio apuntado sin eje
    (`ruedas_last_change_km`) usan ese dato como punto de partida de AMBOS ejes.
    Es lo único honesto que se puede hacer: sabemos cuándo se cambiaron algo,
    no cuáles.
    """
    last_km = v.get(f"{kind}_{pos}_last_change_km") if pos else None
    fecha_key = f"{kind}_{pos}_last_change_date" if pos and last_km is not None else f"{kind}_last_change_date"
    if last_km is None:
        last_km = v.get(f"{kind}_last_change_km")
    if last_km is None:
        return None
    km_actual = v.get("mileage") or last_km
    interval = v.get(f"{kind}_interval_km", default_interval)
    warn = v.get(f"{kind}_warning_before_km", default_warn)
    recorridos = km_actual - last_km
    restantes = interval - recorridos
    return {
        "posicion": pos,
        "last_change_km": last_km,
        "last_change_date": v.get(fecha_key),
        "interval_km": interval,
        "warning_before_km": warn,
        "km_until_change": restantes,
        "next_change_at_km": last_km + interval,
        "overdue": restantes <= 0,
        "warning": 0 < restantes <= warn,
    }


def _km_por_dia(v: dict) -> Optional[float]:
    """Ritmo real de la furgoneta en km/día, o None si no se puede medir.

    Pendiente entre el primer y el último apunte recientes de `mileage_history`.
    Exige 2 apuntes separados 7+ días para no extrapolar ruido: con dos lecturas
    del mismo día, un repostaje o un error de OCR se convertirían en un ritmo
    disparatado y de ahí saldría una fecha de taller falsa.

    Devolver None es una respuesta legítima y quien llama TIENE que respetarla:
    sin ritmo medido no hay días estimados. Ponerlos a ojo sería inventarlos.
    """
    hist = _odo_lecturas(v)
    if len(hist) < 2:
        return None
    cutoff = (datetime.now(timezone.utc) - timedelta(days=60)).strftime("%Y-%m-%d")
    recent = [h for h in hist if str(h["date"])[:10] >= cutoff] or hist[-5:]
    if len(recent) < 2:
        return None
    try:
        d0 = datetime.fromisoformat(str(recent[0]["date"])[:10])
        d1 = datetime.fromisoformat(str(recent[-1]["date"])[:10])
        span = (d1 - d0).days
        dk = recent[-1]["km"] - recent[0]["km"]
        if span >= 7 and dk > 0:
            return round(dk / span, 1)
    except Exception:
        return None
    return None


def _km_ultimo_apunte(v: dict) -> Optional[str]:
    """Fecha del apunte de km más reciente. El km de la ficha puede llevar
    semanas parado, y una cuenta atrás sobre un km viejo va adelantada sin que
    se note: la vista tiene que poder decir de cuándo es el dato."""
    fechas = [str(h.get("date"))[:10] for h in _odo_lecturas(v)]
    return max(fechas) if fechas else None


@api_router.get("/vehicles/{vehicle_id}/maintenance")
async def get_maintenance_info(vehicle_id: str, _=Depends(require_admin)):
    """Devuelve info de mantenimiento completa de una furgoneta (aceite, ruedas, pastillas).
    Incluye PREDICCIÓN: km/día reales (mileage_history, últimos 60 días) → días
    estimados hasta cada cambio, para planificar citas de taller con antelación."""
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0})
    if not v:
        raise HTTPException(status_code=404, detail="Furgoneta no encontrada")

    km_per_day = _km_por_dia(v)

    def _with_estimate(item):
        if item and km_per_day and isinstance(item.get("km_until_change"), (int, float)):
            item["days_left_estimate"] = max(0, round(item["km_until_change"] / km_per_day))
        return item

    def _kind(kind, di, dw):
        """El estado de un mantenimiento. Con ejes separados, el que manda es
        el que antes toca: si las delanteras están vencidas y las traseras no,
        lo que hay que ver en la ficha es que TOCAN RUEDAS."""
        ejes = _ejes_de(v, kind)
        items = [x for x in (_build_maint_item(v, kind, di, dw, p) for p in ejes) if x]
        if not items:
            return None
        principal = min(items, key=lambda x: x.get("km_until_change", 0))
        principal = dict(principal)
        if len(items) > 1:
            principal["por_eje"] = [_with_estimate(dict(x)) for x in items]
        return _with_estimate(principal)

    return {
        "mileage": v.get("mileage"),
        "bags_remaining": v.get("bags_remaining", 0),
        "bags_history": v.get("bags_history", [])[-10:],
        "provider": v.get("provider"),
        "km_per_day": km_per_day,
        "oil":       _kind("oil",       15000, 2500),
        "ruedas":    _kind("ruedas",    40000, 3000),
        "pastillas": _kind("pastillas", 30000, 3000),
    }


@api_router.get("/alerts/maintenance")
async def get_maintenance_alerts(_=Depends(require_admin)):
    """Todas las furgonetas con mantenimiento vencido o próximo, con la MISMA
    predicción que la ficha individual: km/día reales y días estimados.

    Con 81 furgonetas nadie entra una por una, y por eso los cambios se hacen
    tarde. `mileage_history` entra en la proyección justo para esto; el km/día
    lo calcula `_km_por_dia`, el mismo que usa /vehicles/{id}/maintenance, para
    que la cola de flota y la ficha no puedan dar días distintos.
    """
    # Sin lista de campos: con ruedas y pastillas por ejes, una proyección
    # cerrada se deja fuera los campos nuevos en silencio y los cambios por eje
    # dejarían de contar aquí sin que nada fallara.
    vehicles = await db.vehicles.find({"status": {"$nin": ["deleted", "baja"]}}, {"_id": 0}).to_list(500)

    alerts = []
    for v in vehicles:
        kpd = _km_por_dia(v)                  # None = sin ritmo medible
        km_at = _km_ultimo_apunte(v)
        for kind, default_i, default_w, label in [
            ("oil", 15000, 2500, "Aceite"),
            ("ruedas", 40000, 3000, "Ruedas"),
            ("pastillas", 30000, 3000, "Pastillas de freno"),
        ]:
            for pos in _ejes_de(v, kind):
                item = _build_maint_item(v, kind, default_i, default_w, pos)
                if item and (item["overdue"] or item["warning"]):
                    # Sin km/día NO hay días: la clave viaja como None y quien pinta
                    # tiene que decir "faltan X km" en vez de inventarse una fecha.
                    item["days_left_estimate"] = (
                        max(0, round(item["km_until_change"] / kpd))
                        if kpd and isinstance(item.get("km_until_change"), (int, float)) else None)
                    alerts.append({
                        "vehicle_id": v["id"],
                        "license_plate": v.get("license_plate"),
                        "brand": v.get("brand"),
                        "model": v.get("model"),
                        "center": v.get("center"),
                        "mileage": v.get("mileage"),
                        "mileage_last_at": km_at,
                        "vehicle_status": v.get("status"),
                        "provider": v.get("provider"),
                        "km_per_day": kpd,
                        "kind": kind,
                        "label": f"{label} ({pos})" if pos else label,
                        **item,
                    })
    alerts.sort(key=lambda a: a["km_until_change"])
    return alerts


@api_router.post("/import/diagnose")
async def diagnose_excel(file: UploadFile = File(...), _=Depends(require_admin)):
    """DIAGNÓSTICO TEMPORAL: analiza el Excel y devuelve qué hay en cada columna clave."""
    content = await file.read()
    import openpyxl, unicodedata
    def _sa(t): return "".join(c for c in unicodedata.normalize("NFD",t) if unicodedata.category(c)!="Mn")

    out = {}
    # Probar AMBOS modos de carga
    for modo in ["data_only_true", "data_only_false"]:
        wb = openpyxl.load_workbook(io.BytesIO(content), data_only=(modo=="data_only_true"))
        # Listar todas las hojas
        out["hojas"] = wb.sheetnames
        ws = wb.active
        out["hoja_activa"] = ws.title
        headers = [str(c.value).strip().lower() if c.value else "" for c in next(ws.iter_rows(min_row=1, max_row=1))]
        headers_norm = [_sa(h) for h in headers]
        # Índices de proveedor, matrícula, kilómetros
        def idx(name):
            k=_sa(name.lower())
            return headers_norm.index(k) if k in headers_norm else -1
        i_prov = idx("proveedor")
        i_mat = idx("matricula")
        # Leer las primeras 5 filas de datos, columna proveedor
        muestras = []
        cnt = 0
        for row in ws.iter_rows(min_row=2):
            if not any(c.value for c in row): continue
            if cnt >= 5: break
            mat = row[i_mat].value if i_mat>=0 else None
            prov_cell = row[i_prov] if i_prov>=0 else None
            muestras.append({
                "matricula": str(mat),
                "proveedor_valor": str(prov_cell.value) if prov_cell else "SIN_COLUMNA",
                "proveedor_tipo": type(prov_cell.value).__name__ if prov_cell else "N/A",
                "proveedor_data_type": prov_cell.data_type if prov_cell else "N/A"
            })
            cnt += 1
        out[modo] = {
            "indice_proveedor": i_prov,
            "indice_matricula": i_mat,
            "total_headers": len(headers),
            "muestras": muestras
        }
    return out


