@app.on_event("startup")
async def seed_rental_companies():
    """Siembra y actualiza el directorio de empresas de alquiler (upsert por nombre)."""
    try:
        for r in _SEED_RENTALS:
            existing = await db.rental_companies.find_one({"name": r["name"]})
            if existing:
                # Actualiza coordenadas y campos nuevos sin tocar id/created_at
                await db.rental_companies.update_one(
                    {"name": r["name"]},
                    {"$set": {k: v for k, v in r.items() if k not in ("name",)}}
                )
            else:
                doc = dict(r)
                doc["id"] = str(uuid.uuid4())
                doc["active"] = True
                doc["last_check"] = None
                doc["created_at"] = datetime.now(timezone.utc).isoformat()
                await db.rental_companies.insert_one(doc)
        logger.info(f"Seed rentals: {len(_SEED_RENTALS)} empresas sincronizadas")
    except Exception as e:
        logger.error(f"Seed rentals: {e}")


def _haversine_km(c1, c2):
    import math
    if not c1 or not c2:
        return None
    lat1, lon1 = c1
    lat2, lon2 = c2
    R = 6371
    dlat = math.radians(lat2 - lat1)
    dlon = math.radians(lon2 - lon1)
    a = math.sin(dlat/2)**2 + math.cos(math.radians(lat1))*math.cos(math.radians(lat2))*math.sin(dlon/2)**2
    return round(R * 2 * math.atan2(math.sqrt(a), math.sqrt(1-a)), 1)


@api_router.get("/rentals/nearby")
async def rentals_nearby(
    lat: float,
    lng: float,
    max_km: float = 20,
    limit: int = 20,
    current_user: dict = Depends(require_any_auth),
):
    """
    Devuelve casas de alquiler ordenadas por distancia al punto (lat, lng).
    Las que no tienen coordenadas se añaden al final ordenadas por nombre.
    """
    docs = await db.rental_companies.find({"active": {"$ne": False}}, {"_id": 0}).to_list(200)

    with_coords, without_coords = [], []
    for d in docs:
        if d.get("latitude") is not None and d.get("longitude") is not None:
            dist = _haversine_km((lat, lng), (d["latitude"], d["longitude"])) or 9999
            if dist <= max_km:
                d["distance_km"] = round(dist, 1)
                with_coords.append(d)
        else:
            without_coords.append(d)

    with_coords.sort(key=lambda x: x["distance_km"])
    without_coords.sort(key=lambda x: x.get("name", ""))

    return {"rentals": (with_coords + without_coords)[:limit], "user_lat": lat, "user_lng": lng}


@api_router.get("/rentals")
async def list_rentals(center: Optional[str] = None, _=Depends(require_admin)):
    """Empresas de alquiler de furgonetas, opcionalmente filtradas por centro."""
    query = {"active": {"$ne": False}}
    if center and center != "Todos":
        query["center"] = center
    docs = await db.rental_companies.find(query, {"_id": 0}).to_list(200)
    docs.sort(key=lambda d: d.get("name", ""))
    return docs


@api_router.post("/rentals")
async def create_rental(data: dict, _=Depends(require_admin)):
    """Añade una empresa de alquiler manualmente."""
    name = _texto_cuerpo(data.get("name"))
    center = _texto_cuerpo(data.get("center"))
    # Las naves de LA EMPRESA, no las de Dani escritas a mano: con la lista fija
    # ninguna otra empresa podia dar de alta una alquiladora, y Dani tampoco en
    # una nave nueva (medido con una empresa recien creada el 16-09-2026).
    center = center.upper()
    naves = await _centros_de_la_empresa()
    if not name or center not in naves:
        raise HTTPException(status_code=400, detail="Nombre y centro (%s) requeridos"
                            % "/".join(naves or ["tu nave"]))
    doc = {
        "id": str(uuid.uuid4()),
        "name": name, "center": center,
        "address": _texto_cuerpo(data.get("address")),
        "phone": re.sub(r"[^0-9+]", "", _texto_cuerpo(data.get("phone"))),
        "email": _texto_cuerpo(data.get("email")),
        "website": _texto_cuerpo(data.get("website")),
        "notes": _texto_cuerpo(data.get("notes")),
        "maps_url": "https://www.google.com/maps/search/?api=1&query="
                    + (_texto_cuerpo(data.get("address")) or name).replace(" ", "+"),
        "active": True, "last_check": None,
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    await db.rental_companies.insert_one(doc)
    doc.pop("_id", None)
    return {"success": True, "id": doc["id"]}


@api_router.patch("/rentals/{rental_id}")
async def update_rental(rental_id: str, data: dict, _=Depends(require_admin)):
    """Edita una empresa o registra una verificación de disponibilidad."""
    data.pop("_id", None)
    data.pop("id", None)
    if not data:
        raise HTTPException(status_code=400, detail="Sin campos que guardar")
    r = await db.rental_companies.update_one({"id": rental_id}, {"$set": data})
    # Con un id que no existe respondia "success": el panel decia "guardado"
    # sin haber tocado nada.
    if r.matched_count == 0:
        raise HTTPException(status_code=404, detail="Empresa no encontrada")
    return {"success": True}


@api_router.post("/rentals/{rental_id}/check")
async def verify_rental_availability(rental_id: str, data: dict, user: dict = Depends(get_current_user)):
    """Registra disponibilidad verificada por el equipo (tras llamar)."""
    if user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Solo administradores")
    check = {
        "date": datetime.now(timezone.utc).isoformat(),
        "by": user.get("name", "?"),
        "available": data.get("available"),          # nº de furgonetas o texto
        "note": _texto_cuerpo(data.get("note"))[:200],
    }
    result = await db.rental_companies.update_one(
        {"id": rental_id}, {"$set": {"last_check": check}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Empresa no encontrada")
    return {"success": True, "last_check": check}


@api_router.delete("/rentals/{rental_id}")
async def delete_rental(rental_id: str, _=Depends(require_admin)):
    r = await db.rental_companies.update_one({"id": rental_id}, {"$set": {"active": False}})
    if r.matched_count == 0:
        raise HTTPException(status_code=404, detail="Empresa no encontrada")
    return {"success": True}


# =========================
# CUADRANTE DE TURNOS (shifts) + solicitudes de días
#   shifts:        {center, driver_id, driver_name, date "YYYY-MM-DD", type,
#                   cod?, hora?}
#                  type ∈ trabaja | libre | extra   (lo que entiende la app)
#                  cod  = el codigo tal cual venia del cuadrante ("BKP", "V",
#                         "N/D"…). Opcional: los turnos guardados antes de que
#                         se empezara a guardar no lo tienen.
#                  hora = la hora entre parentesis de la celda ("05:43").
#   shift_requests:{id, center, driver_id, driver_name, date, type(libre|extra),
#                   status(pendiente|aprobado|rechazado), created_at, resolved_by, note}
#   shift_settings:{center, min_cobertura}  -> para auto-aprobar si sobra gente
# =========================

VALID_SHIFT_TYPE = {"trabaja", "libre", "extra"}

# Motivos por los que un conductor pide un día. El motivo cambia la decisión,
# así que se pide siempre y no se deja escribir libre a secas: con texto libre
# acaban poniendo "personal" y hay que preguntar igual.
MOTIVOS_PETICION = {
    "asuntos": "Asuntos propios",
    "medico": "Médico",
    "familia": "Asunto familiar",
    "viaje": "Viaje",
    "otro": "Otro",
}


def _puede(user: dict, clave: str) -> bool:
    """¿Tiene este usuario el permiso `clave`? Comprobado en el SERVIDOR.

    El panel esconde los botones según los permisos, pero esconder un botón no
    es proteger nada: quien sepa la dirección de la API llega igual. Para
    aprobar días —que decide si alguien trabaja o no— hace falta comprobarlo
    aquí, no solo en la pantalla.

    `permissions = None` significa sin restricción, que es como están los
    usuarios antiguos: quitarles el acceso de golpe sería peor que el problema.
    """
    if user.get("sa") or user.get("account_type") == "owner":
        return True
    perms = user.get("permissions")
    if perms is None:
        return True
    return clave in perms


async def _user_center(user: dict) -> Optional[str]:
    """Centro del usuario. Admin -> None (ve todos)."""
    if user.get("role") == "admin":
        return None
    d = await db.drivers.find_one({"id": user.get("sub")}, {"_id": 0, "center": 1})
    return d.get("center") if d else None


async def _min_cobertura(center: str) -> int:
    s = await db.shift_settings.find_one({"center": center}, {"_id": 0, "min_cobertura": 1})
    if s and isinstance(s.get("min_cobertura"), int):
        return s["min_cobertura"]
    return 0  # 0 = auto-aprobado desactivado (todo pasa a pendiente)


async def _coverage_for_date(center: str, date: str) -> int:
    """Conductores que ese día SACAN RUTA (no los que simplemente trabajan)."""
    return await db.shifts.count_documents(
        {"center": center, "date": date, **_FILTRO_RUTA})


async def _upsert_turno(filtro: dict, cambio: dict):
    """Upsert de un turno que aguanta dos peticiones a la vez.

    Con el unico `turno_unico`, el que pierde la carrera recibe
    `DuplicateKeyError` en vez de crear un segundo documento; entonces repite
    sin upsert, que ya encuentra el que insertó el otro (gotchas 9 y 46).
    """
    try:
        await db.shifts.update_one(filtro, cambio, upsert=True)
    except DuplicateKeyError:
        await db.shifts.update_one(filtro, cambio)


async def _bulk_turnos(ops: list):
    """bulk_write de upserts de turnos con la misma garantia que _upsert_turno.

    `ordered=False` aplica todos los que puede; si alguno choca con el unico,
    la segunda pasada los encuentra ya creados y solo actualiza. Volver a
    aplicar un `$set` identico es idempotente.
    """
    if not ops:
        return
    try:
        await db.shifts.bulk_write(ops, ordered=False)
    except BulkWriteError:
        await db.shifts.bulk_write(ops, ordered=False)


@api_router.get("/shifts")
async def get_shifts(center: Optional[str] = None, desde: Optional[str] = None,
                     hasta: Optional[str] = None, user: dict = Depends(require_admin)):
    # Los centros NO se mezclan. Sin esto, quien lleva DGA1 abría la pantalla
    # sin elegir centro y veía —y podía tocar— el cuadrante entero de OGA5.
    q = dict(_filtro_centro(user, center))
    if desde or hasta:
        rng = {}
        if desde:
            rng["$gte"] = desde
        if hasta:
            rng["$lte"] = hasta
        q["date"] = rng
    docs = await db.shifts.find(q, {"_id": 0}).to_list(20000)
    return {"shifts": docs}


@api_router.post("/shifts/bulk")
async def save_shifts_bulk(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda/actualiza varios turnos.

    body: {items:[{driver_id, driver_name, center, date, type, cod?, hora?}]}
    `cod` es el codigo del cuadrante ("BKP", "V", "N/D"...) y manda sobre
    `type` cuando los dos vienen y no cuadran: el codigo es lo que se vio en la
    pantalla al pintarlo.
    """
    items = _lista_cuerpo(data.get("items"))
    # Lo que no sea un objeto no es un turno: se descarta AQUI y no revienta
    # veinte lineas mas abajo con un error que no se parece a esto.
    items = [it for it in (_dict_cuerpo(x) for x in items) if it]
    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa_cod = dict(CODIGOS_CUADRANTE_DEF)
    mapa_cod.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    # ── LOS DIAS APROBADOS NO SE PISAN ─────────────────────────────────────
    # Un dia libre aprobado es un compromiso con una persona: se lo dijiste, se
    # organizo. Que cualquiera con acceso al panel pueda repintar esa casilla
    # —a mano, arrastrando, o sin querer al pegar el cuadrante del mes— y que
    # nadie se entere hasta que esa persona no aparece, es el fallo mas caro
    # que puede tener esta pantalla.
    #
    # Se comprueba AQUI y no solo escondiendo el boton: esconder un boton no
    # protege nada, quien sepa la direccion de la API llega igual.
    #
    # Quien SI puede quitarlo es quien puede aprobarlo (el permiso
    # 'aprobar-dias'), porque cambiar de opinion sobre un dia que tu mismo
    # concediste es una decision legitima, y porque si no lo pudiera tocar
    # nadie la unica salida seria editar la base de datos a mano.
    puede_tocar_aprobados = _puede(user, "aprobar-dias")
    protegidos = {}
    if not puede_tocar_aprobados and items:
        fechas = sorted({str(it.get("date") or "")[:10] for it in items if it.get("date")})
        conductores = sorted({it.get("driver_id") for it in items if it.get("driver_id")})
        if fechas and conductores:
            cur = db.shift_requests.find(
                {"status": "aprobado", "driver_id": {"$in": conductores},
                 "date": {"$gte": fechas[0], "$lte": fechas[-1]}},
                {"_id": 0, "driver_id": 1, "date": 1, "type": 1, "driver_name": 1})
            async for r in cur:
                protegidos[f"{r['driver_id']}|{r['date']}"] = r

    saved, bloqueados = 0, []
    for it in items:
        did = it.get("driver_id")
        date = it.get("date")
        center = it.get("center")
        typ = it.get("type")
        if not (did and date and center and typ in VALID_SHIFT_TYPE):
            continue
        # El codigo que se pinto en la rejilla. Se comprueba contra el mapa: si
        # no cuadra con el tipo, manda el codigo, porque es lo que se vio al
        # pintarlo. Sin codigo se guarda igual —turnos viejos y la app movil no
        # lo mandan— y la pantalla cae al color generico del tipo.
        cod = str(it.get("cod") or "").strip().upper()[:20]
        if cod and cod in mapa_cod and mapa_cod[cod]:
            typ = mapa_cod[cod]
        # Lo que se bloquea es el cambio que HACE DANO, no cualquier cambio.
        #
        # Comparar el codigo exacto ('N/T APROB') parecia lo obvio y era un
        # falso positivo garantizado: los turnos guardados antes de que se
        # empezara a guardar el codigo no lo tienen, asi que llegan como 'N/T'
        # y se habrian rechazado todos — la pantalla acusando de pisar dias
        # aprobados a quien solo estaba guardando el cuadrante sin tocarlos.
        #
        # Lo unico que no puede pasar es que un dia libre concedido se
        # convierta en dia de trabajo (o al reves con un extra concedido). Que
        # la celda ponga 'N/T' o 'N/T APROB' es cosmetico; que esa persona
        # aparezca puesta a ruta el dia que le diste libre, no.
        prot = protegidos.get(f"{did}|{date}")
        if prot is not None:
            aprobado = prot.get("type")
            rompe = ((aprobado == "libre" and typ in ("trabaja", "extra"))
                     or (aprobado == "extra" and typ == "libre"))
            if rompe:
                bloqueados.append({"driver_name": prot.get("driver_name") or "",
                                   "date": date, "type": aprobado})
                continue
        # Un turno de otro centro se ignora en silencio pero se deja anotado:
        # el cuadrante se envía entero desde la pantalla, y un 403 a mitad
        # dejaría la mitad guardada y la otra mitad no.
        if not _user_can_see_center(user, center):
            logger.warning("Turnos: %s intentó guardar en %s, sin acceso", user.get("name"), center)
            continue
        campos = {"driver_id": did, "driver_name": it.get("driver_name", ""),
                  "center": center, "date": date, "type": typ}
        # Lo que no viene se QUITA, no se guarda a vacio: si una celda que era
        # "V (05:43)" se repinta como "1", esa hora ya no significa nada y
        # dejarla ahi seria mentira. Y un campo no puede ir en $set y $unset a
        # la vez: Mongo rechaza la operacion entera y no se guardaria ni un
        # turno.
        cambio, quitar = {"$set": campos}, {}
        hora = str(it.get("hora") or "").strip()[:5]
        for clave, valor in (("cod", cod), ("hora", hora)):
            if valor:
                campos[clave] = valor
            else:
                quitar[clave] = ""
        if quitar:
            cambio["$unset"] = quitar
        await _upsert_turno({"driver_id": did, "date": date}, cambio)
        saved += 1
    if bloqueados:
        logger.info("Turnos: %s intento cambiar %d dias aprobados sin permiso",
                    user.get("name"), len(bloqueados))
    return {"success": True, "saved": saved, "bloqueados": bloqueados[:20],
            "n_bloqueados": len(bloqueados)}


@api_router.get("/shifts/coverage")
async def get_coverage(center: str, desde: str, hasta: str, _=Depends(require_admin)):
    """Nº de conductores disponibles (trabaja+extra) por día en el rango."""
    cur = db.shifts.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}, **_FILTRO_RUTA},
        {"_id": 0, "date": 1},
    )
    counts: dict = {}
    async for s in cur:
        counts[s["date"]] = counts.get(s["date"], 0) + 1
    return {"coverage": counts, "min": await _min_cobertura(center)}


@api_router.post("/shifts/settings")
async def set_shift_settings(data: dict = Body(...), _=Depends(require_admin)):
    center = _texto_cuerpo(data.get("center"), 30)
    mn = data.get("min_cobertura")
    if not center or not isinstance(mn, int):
        raise HTTPException(status_code=400, detail="center y min_cobertura (int) requeridos")
    await db.shift_settings.update_one(
        {"center": center}, {"$set": {"center": center, "min_cobertura": mn}}, upsert=True
    )
    return {"success": True}


@api_router.get("/shifts/mine")
async def get_my_shifts(desde: Optional[str] = None, hasta: Optional[str] = None,
                        user: dict = Depends(require_any_auth)):
    """Calendario propio del conductor: sus turnos + sus solicitudes."""
    did = user.get("sub")
    q = {"driver_id": did}
    if desde or hasta:
        rng = {}
        if desde:
            rng["$gte"] = desde
        if hasta:
            rng["$lte"] = hasta
        q["date"] = rng
    shifts = await db.shifts.find(q, {"_id": 0}).to_list(2000)
    reqs = await db.shift_requests.find(
        {"driver_id": did}, {"_id": 0}
    ).sort("date", 1).to_list(500)
    # Respuestas que todavía no ha leído. Van aparte para que la pantalla
    # pueda enseñarlas arriba del todo sin que el conductor tenga que ir a
    # buscarlas entre las suyas.
    sin_ver = [r for r in reqs
               if r.get("status") in ("aprobado", "rechazado") and not r.get("visto_at")]
    return {"shifts": shifts, "requests": reqs, "sin_ver": sin_ver}


# ─── BLOQUEAR LA PETICIÓN DE DÍAS ────────────────────────────────────────────
#
# Hay semanas en las que no se puede dar ni un día: pico de volumen, Navidad,
# Prime Day. Hasta ahora la única forma de gestionarlo era dejar que pidieran y
# rechazar uno por uno, que es trabajo para la oficina y un "no" para el
# conductor después de haberse hecho ilusiones.
#
# Un bloqueo dice ANTES que ese día no se puede pedir, y dice por qué. El
# conductor lo ve en su calendario y no lo marca siquiera.
#
# DOS ALCANCES, y la diferencia importa:
#   · de centro  → afecta a toda la nave.
#   · de persona → sólo a ese conductor. Sirve para el que ya ha gastado sus
#     días, o para quien está en un plan de mejora.
#
# Lo que NO hace: tocar las peticiones ya hechas. Un bloqueo puesto hoy no
# rechaza lo que se pidió ayer — eso sigue decidiéndolo una persona. Bloquear
# hacia atrás sería cambiarle a alguien una respuesta que ya estaba dada.


def _bloqueo_doc(b: dict) -> dict:
    return {
        "id": b.get("id") or str(uuid.uuid4()),
        "center": (b.get("center") or "").strip(),
        "driver_id": (b.get("driver_id") or "").strip() or None,
        "desde": (b.get("desde") or "").strip(),
        "hasta": (b.get("hasta") or "").strip(),
        "motivo": (b.get("motivo") or "").strip()[:200],
        "creado_por": b.get("creado_por"),
        "creado_en": b.get("creado_en") or datetime.now(timezone.utc).isoformat(),
    }


async def _bloqueos_que_afectan(driver_id: str, center: str, fechas: list) -> list:
    """Los bloqueos que pisan alguna de esas fechas para ese conductor."""
    if not fechas:
        return []
    docs = await db.shift_blocks.find(
        {"$and": [
            {"$or": [{"center": {"$regex": re.escape((center or "")[:4]), "$options": "i"}},
                     {"center": ""}]},
            {"$or": [{"driver_id": None}, {"driver_id": driver_id}]},
            {"desde": {"$lte": max(fechas)}},
            {"hasta": {"$gte": min(fechas)}},
        ]}, {"_id": 0}).to_list(200)
    fuera = []
    for b in docs:
        pisadas = [f for f in fechas if b["desde"] <= f <= b["hasta"]]
        if pisadas:
            fuera.append({**b, "dias_afectados": sorted(pisadas)})
    return fuera


@api_router.get("/shift-blocks")
async def listar_bloqueos(center: str = "", admin: dict = Depends(require_admin)):
    """Los bloqueos vigentes. Cada uno con a quién afecta."""
    q = {}
    if center and center not in ("Todos", "todos"):
        q["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}
    docs = await db.shift_blocks.find(q, {"_id": 0}).sort("desde", 1).to_list(500)
    # Sólo los de los centros que este admin puede ver: un bloqueo de otra nave
    # no es asunto suyo, igual que sus peticiones.
    docs = [d for d in docs if _user_can_see_center(admin, d.get("center") or "")]
    ids = [d["driver_id"] for d in docs if d.get("driver_id")]
    nombres = {}
    if ids:
        nombres = {d["id"]: d.get("name", "") for d in await db.drivers.find(
            {"id": {"$in": ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)}
    for d in docs:
        d["driver_name"] = nombres.get(d.get("driver_id")) if d.get("driver_id") else None
    return {"bloqueos": docs, "total": len(docs)}


@api_router.post("/shift-blocks")
async def crear_bloqueo(data: dict = Body(...), admin: dict = Depends(require_admin)):
    """Bloquea un rango de días. body: {center, desde, hasta, motivo, driver_id?}

    El motivo es obligatorio y lo lee el conductor. Un bloqueo sin explicación
    es un "no" sin cara: manda a preguntar por WhatsApp, que es lo que este
    módulo viene a quitar.
    """
    if not _puede(admin, "aprobar-dias"):
        raise HTTPException(status_code=403,
                            detail="No tienes permiso para bloquear días")
    b = _bloqueo_doc({**data, "creado_por": admin.get("name", "admin")})
    if not b["center"]:
        raise HTTPException(400, "Falta el centro")
    if not _user_can_see_center(admin, b["center"]):
        raise HTTPException(403, "Ese centro no es tuyo")
    for campo in ("desde", "hasta"):
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", b[campo] or ""):
            raise HTTPException(400, f"{campo} va en formato AAAA-MM-DD")
    if b["hasta"] < b["desde"]:
        raise HTTPException(400, "La fecha de fin es anterior a la de inicio")
    if len(b["motivo"]) < 4:
        raise HTTPException(400, "Escribe el motivo: lo va a leer el conductor")
    if b["driver_id"]:
        existe = await db.drivers.find_one({"id": b["driver_id"]}, {"_id": 0, "id": 1})
        if not existe:
            raise HTTPException(404, "Ese conductor no existe")
    await db.shift_blocks.insert_one(dict(b))
    logger.info("Bloqueo de dias: %s %s..%s (%s)", b["center"], b["desde"], b["hasta"],
                b["driver_id"] or "todo el centro")
    return {"success": True, "bloqueo": b}


@api_router.delete("/shift-blocks/{block_id}")
async def borrar_bloqueo(block_id: str, admin: dict = Depends(require_admin)):
    if not _puede(admin, "aprobar-dias"):
        raise HTTPException(status_code=403, detail="No tienes permiso")
    b = await db.shift_blocks.find_one({"id": block_id}, {"_id": 0})
    if not b:
        raise HTTPException(404, "Ese bloqueo ya no existe")
    if not _user_can_see_center(admin, b.get("center") or ""):
        raise HTTPException(403, "Ese bloqueo es de otro centro")
    await db.shift_blocks.delete_one({"id": block_id})
    return {"success": True}


@api_router.get("/shift-blocks/mios")
async def bloqueos_del_conductor(user: dict = Depends(get_current_user)):
    """Para el portal: qué días NO puede pedir, y por qué.

    Se devuelven los rangos tal cual, no día a día: la pantalla los pinta y
    enseña el motivo al tocarlos. Sólo de hoy en adelante — los de antes ya no
    le sirven para nada.
    """
    if user.get("role") != "driver":
        raise HTTPException(status_code=403, detail="Solo conductores")
    did = user["sub"]
    drv = await db.drivers.find_one({"id": did}, {"_id": 0, "center": 1, "email": 1, "id": 1})
    # Sus otras fichas cuentan igual: si esta duplicado, un bloqueo puesto sobre
    # la otra ficha tiene que valerle (gotcha 15).
    mis_ids, centro = await _fichas_misma_persona(drv or {"id": did})
    hoy = _dia_negocio()
    docs = await db.shift_blocks.find(
        {"hasta": {"$gte": hoy},
         "$or": [{"driver_id": None}, {"driver_id": {"$in": list(mis_ids)}}]},
        {"_id": 0}).sort("desde", 1).to_list(200)
    if centro:
        docs = [d for d in docs
                if not d.get("center")
                or re.search(re.escape(centro[:4]), d.get("center") or "", re.I)]
    return {"bloqueos": docs}


@api_router.post("/shift-requests/vistas")
async def marcar_respuestas_vistas(data: dict = Body(default={}),
                                   user: dict = Depends(require_any_auth)):
    """El conductor ha leído las respuestas: dejan de salir como novedad.

    Se marcan sólo las SUYAS y sólo las ya resueltas, y se pasa por `grupo` o
    por lista de ids para no borrar el aviso de una respuesta que no ha visto.
    """
    q = {"driver_id": user.get("sub"), "status": {"$in": ["aprobado", "rechazado"]},
         "visto_at": None}
    if data.get("grupo"):
        q["grupo"] = str(data["grupo"])
    elif data.get("ids"):
        q["id"] = {"$in": [str(x) for x in data["ids"]][:200]}
    r = await db.shift_requests.update_many(
        q, {"$set": {"visto_at": datetime.now(timezone.utc).isoformat()}})
    return {"ok": True, "marcadas": r.modified_count}


@api_router.post("/shift-requests")
async def create_shift_request(data: dict = Body(...), user: dict = Depends(require_any_auth)):
    """El conductor pide uno o varios días.

    Se manda `dates: ["YYYY-MM-DD", ...]` y se guarda UNA FILA POR DÍA, todas
    con el mismo `grupo`. Así la oficina lo ve como una sola petición ("Razavi,
    3 días") pero cada día sigue siendo su propio registro — que es lo que hace
    falta para poder aprobar unos días sí y otros no, y para que el día
    aprobado pueda ir al cuadrante por su cuenta.

    Se acepta `date` suelto por compatibilidad con la pantalla antigua.

    NADA se auto-aprueba. El cuadrante lo lleva la oficina, y una aprobación
    automática calculada sobre un cuadrante que puede no estar cargado sería
    exactamente el falso positivo que no se quiere: aprobar por no tener datos.
    """
    dates = _lista_cuerpo(data.get("dates")) or (
        [data["date"]] if _texto_cuerpo(data.get("date")) else [])
    typ = _texto_cuerpo(data.get("type")) or "libre"
    if typ not in {"libre", "extra"}:
        raise HTTPException(status_code=400, detail="type debe ser libre o extra")
    vistas, limpias = set(), []
    for d in dates:
        s = str(d)[:10]
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
            raise HTTPException(status_code=400, detail=f"Fecha no válida: {d}")
        if s not in vistas:
            vistas.add(s); limpias.append(s)
    if not limpias:
        raise HTTPException(status_code=400, detail="Marca al menos un día")
    if len(limpias) > 31:
        raise HTTPException(status_code=400, detail="Demasiados días en una sola petición (máx. 31)")

    motivo = _texto_cuerpo(data.get("motivo")) or "otro"
    if motivo not in MOTIVOS_PETICION:
        raise HTTPException(status_code=400, detail="Motivo no válido")

    # LA EXPLICACION ES OBLIGATORIA, y se exige AQUI ademas de en la pantalla.
    # Comprobarlo solo en el navegador no es exigirlo: una pestaña vieja abierta
    # de antes, o una llamada a mano, entrarian igual. El motivo de la chapa dice
    # la categoria ("Asuntos propios"); esto dice el caso, que es lo que necesita
    # quien tiene que decidir. Sin ello la oficina acaba preguntando por
    # WhatsApp, que es la conversacion que este modulo venia a quitar.
    nota = _texto_cuerpo(data.get("note")) or _texto_cuerpo(data.get("nota"))
    if len(nota) < 4:
        raise HTTPException(
            status_code=400,
            detail="Cuenta un poco de qué va: quien lo aprueba necesita saberlo")

    did = user.get("sub")
    drv = await db.drivers.find_one({"id": did}, {"_id": 0, "name": 1, "center": 1})
    if not drv:
        raise HTTPException(status_code=404, detail="Conductor no encontrado")

    # DIAS BLOQUEADOS: se comprueba AQUI, que es donde se decide de verdad.
    # La pantalla ya no los deja marcar, pero una pestaña abierta de antes del
    # bloqueo, o una llamada a mano, entrarian igual.
    choques = await _bloqueos_que_afectan(did, drv.get("center") or "", limpias)
    if choques:
        b = choques[0]
        dias = ", ".join(b["dias_afectados"][:5])
        raise HTTPException(
            status_code=409,
            detail=f"Esos dias estan bloqueados ({dias}): {b.get('motivo') or 'sin motivo'}")

    # Un día ya pedido y sin resolver no se pide dos veces: si no, la oficina
    # ve la misma petición repetida y no sabe cuál contestar.
    ya = await db.shift_requests.distinct(
        "date", {"driver_id": did, "date": {"$in": limpias}, "status": "pendiente"})
    nuevas = [d for d in limpias if d not in ya]
    if not nuevas:
        raise HTTPException(status_code=409, detail="Ya has pedido esos días y están sin contestar")

    grupo = str(uuid.uuid4())
    ahora = datetime.now(timezone.utc).isoformat()
    filas = [{
        "id": str(uuid.uuid4()), "grupo": grupo, "center": drv.get("center"),
        "driver_id": did, "driver_name": drv.get("name", ""),
        "date": d, "type": typ, "status": "pendiente",
        "motivo": motivo, "motivo_label": MOTIVOS_PETICION[motivo],
        "note": _texto_cuerpo(data.get("note"))[:300],
        "created_at": ahora, "resolved_by": None, "resolved_at": None,
    } for d in nuevas]
    await db.shift_requests.insert_many([dict(f) for f in filas])

    # Que la oficina se entere sin tener que estar mirando la pantalla.
    try:
        await push_center_event(
            drv.get("center") or "",
            f"📅 {drv.get('name', 'Un conductor')} pide {len(nuevas)} día{'s' if len(nuevas) > 1 else ''}",
            f"{MOTIVOS_PETICION[motivo]} · {', '.join(nuevas[:4])}",
            "/panel/turnos")
    except Exception as e:
        logger.debug("Push petición de días: %s", e)

    for f in filas:
        f.pop("_id", None)
    return {"success": True, "grupo": grupo, "dias": nuevas,
            "ignorados": [d for d in limpias if d in ya], "requests": filas}


@api_router.get("/shift-requests/pendientes")
async def contar_peticiones_pendientes(center: Optional[str] = None,
                                       user: dict = Depends(require_admin)):
    """Cuantas peticiones de dias estan sin contestar. Para el aviso del menu.

    SE CUENTAN PETICIONES, NO DIAS. En la base hay un documento POR DIA, pero
    el conductor las pidio de golpe y en pantalla salen como una sola fila:
    "4 dias, del 16 al 19". Contando documentos, siete peticiones de verdad
    daban 17 y el numero del menu no cuadraba con lo que se ve — pasó, y el
    aviso deja de servir en cuanto no coincide con la pantalla.

    La clave del grupo es `grupo`, y `id` cuando falta: exactamente la misma
    que usa la pantalla para juntar las filas. Si se cambia alli, hay que
    cambiarla aqui.

    Tampoco son personas: dos conductores con tres peticiones entre los dos son
    3, porque hay que contestar tres veces. `personas` va aparte por si alguna
    pantalla quiere decir "2 personas, 3 peticiones".

    Endpoint propio y no `/shift-requests?status=pendiente` porque esto lo pide
    el menu cada dos minutos en TODAS las pantallas: la lista devuelve hasta
    mil documentos enteros —con nombre y motivo— para acabar mirando su
    longitud. Aqui lo cuenta Mongo y viajan dos numeros.

    OJO AL ORDEN: va declarado ANTES que cualquier `/shift-requests/{algo}`.
    FastAPI casa por orden de declaracion y, puesto despues, la palabra
    'pendientes' entraria como si fuera un id (gotcha del /work-orders/export).
    """
    filtro = dict(_filtro_centro(user, center))
    filtro["status"] = "pendiente"
    filas = await db.shift_requests.aggregate([
        {"$match": filtro},
        {"$group": {"_id": {"$ifNull": ["$grupo", "$id"]},
                    "conductor": {"$first": "$driver_id"}}},
        {"$group": {"_id": None, "peticiones": {"$sum": 1},
                    "personas": {"$addToSet": "$conductor"}}},
    ]).to_list(1)
    if not filas:
        return {"pendientes": 0, "personas": 0, "dias": 0}
    r = filas[0]
    return {"pendientes": r["peticiones"],
            "personas": len([p for p in r["personas"] if p]),
            # Los dias sueltos, por si hacen falta: es el numero de documentos.
            "dias": await db.shift_requests.count_documents(filtro)}


@api_router.get("/shift-requests")
async def list_shift_requests(center: Optional[str] = None, status: Optional[str] = None,
                              desde: Optional[str] = None, hasta: Optional[str] = None,
                              driver_id: Optional[str] = None, q: Optional[str] = None,
                              limit: int = 1000,
                              user: dict = Depends(require_admin)):
    """Las peticiones de dias. Sirve para la bandeja y para el historial.

    `status` admite varios separados por coma ("aprobado,rechazado"), y hay
    rango de fechas, conductor y busqueda por nombre: sin eso, el historial de
    un ano son mil filas y encontrar "cuando le di el dia a Estela" es
    imposible.
    """
    # Igual que el cuadrante: sin filtro por centro, quien lleva un centro veía
    # las peticiones de días de TODA la empresa, con nombre y motivo.
    filtro = dict(_filtro_centro(user, center))
    if status:
        estados = [s.strip() for s in str(status).split(",") if s.strip()]
        filtro["status"] = estados[0] if len(estados) == 1 else {"$in": estados}
    if desde or hasta:
        rango = {}
        if desde:
            rango["$gte"] = str(desde)[:10]
        if hasta:
            rango["$lte"] = str(hasta)[:10]
        filtro["date"] = rango
    if driver_id:
        filtro["driver_id"] = driver_id
    if q:
        # Escapado: un nombre con un parentesis no puede tumbar la consulta.
        filtro["driver_name"] = {"$regex": re.escape(str(q).strip()), "$options": "i"}
    reqs = await db.shift_requests.find(filtro, {"_id": 0}).sort(
        "date", -1).to_list(max(1, min(int(limit or 1000), 3000)))
    return {"requests": reqs}


@api_router.post("/shift-requests/{req_id}/resolve")
async def resolve_shift_request(req_id: str, data: dict = Body(...),
                                admin: dict = Depends(require_admin)):
    """Aprobar o rechazar. body: {action: aprobar|rechazar, motivo}

    Rechazar EXIGE motivo. Un "no" a secas manda al conductor a preguntar por
    WhatsApp por qué, y la discusión vuelve al sitio del que se la quería sacar
    — que es el problema entero que resuelve tener esto por escrito.
    """
    action = _texto_cuerpo(data.get("action"), 20)
    if action not in {"aprobar", "rechazar"}:
        raise HTTPException(status_code=400, detail="action debe ser aprobar|rechazar")
    req = await db.shift_requests.find_one({"id": req_id}, {"_id": 0})
    if not req:
        raise HTTPException(status_code=404, detail="Solicitud no encontrada")
    if not _user_can_see_center(admin, req.get("center") or ""):
        raise HTTPException(status_code=403, detail="Esa petición es de otro centro")
    # Ver las peticiones lo puede hacer cualquiera del centro; DECIDIR no.
    if not _puede(admin, "aprobar-dias"):
        raise HTTPException(status_code=403,
                            detail="No tienes permiso para aprobar o rechazar días")
    motivo = _texto_cuerpo(data.get("motivo"))[:300]
    if action == "rechazar" and len(motivo) < 3:
        raise HTTPException(status_code=400,
                            detail="Para rechazar hay que escribir el motivo: lo va a leer el conductor")
    new_status = "aprobado" if action == "aprobar" else "rechazado"
    await db.shift_requests.update_one(
        {"id": req_id},
        # `resolved_at` faltaba: se guardaba QUIÉN contestó pero no CUÁNDO, así
        # que "¿cuándo me dijiste que no?" no tenía respuesta.
        # `visto_at: None` = el conductor todavía no ha leído la respuesta. El
        # push puede no llegar (avisos desactivados, iOS, móvil apagado), así
        # que la respuesta TAMBIÉN espera dentro de la app hasta que la abra.
        # Fiar el aviso sólo al push sería fiarlo a algo que falla en silencio.
        {"$set": {"status": new_status, "resolved_by": admin.get("name", "admin"),
                  "resolved_at": datetime.now(timezone.utc).isoformat(),
                  "motivo_respuesta": motivo or None, "visto_at": None}},
    )
    # Que se entere: si la respuesta no llega, el conductor vuelve a preguntar
    # de palabra y no hemos arreglado nada.
    try:
        await send_web_push_to_users(
            [req["driver_id"]],
            f"Tu petición del {req['date']}: {'aprobada' if new_status == 'aprobado' else 'rechazada'}",
            motivo or ("Ya puedes verlo en tus turnos." if new_status == "aprobado" else ""),
            # Al CONDUCTOR se le manda a SU portal. Estaba apuntando a
            # /panel/portal-conductor, que es la pantalla de administracion:
            # tocar el aviso le llevaba a un sitio donde no puede entrar.
            "/conductor")
    except Exception as e:
        logger.debug("Push respuesta petición: %s", e)
    if new_status == "aprobado":
        # Entra en el cuadrante en el acto, y con el CODIGO que le corresponde.
        # Sin `cod` la celda caia en el 'N/T' generico y en la rejilla no habia
        # forma de distinguir "libra porque toca" de "libra porque se lo
        # aprobaste" — que es justo lo que no se puede confundir, porque lo
        # segundo no se puede cambiar sin hablar con la persona.
        cod = "N/T APROB" if req["type"] == "libre" else "EXTRA"
        await _upsert_turno(
            {"driver_id": req["driver_id"], "date": req["date"]},
            {"$set": {"driver_id": req["driver_id"], "driver_name": req.get("driver_name", ""),
                      "center": req["center"], "date": req["date"], "type": req["type"],
                      "cod": cod, "aprobado_req": req_id},
             "$unset": {"hora": ""}},
        )
    elif req.get("status") == "aprobado":
        # Se ha desaprobado algo que ya estaba aprobado: la marca del cuadrante
        # tiene que irse con ello, o la celda seguiria bloqueada para siempre.
        await db.shifts.update_one(
            {"driver_id": req["driver_id"], "date": req["date"], "aprobado_req": req_id},
            {"$unset": {"aprobado_req": ""}},
        )
    return {"success": True, "status": new_status}


# ─── IMPORTAR EL CUADRANTE PEGÁNDOLO DESDE SHEETS ────────────────────────────
#
# El importador de Excel funciona, pero depende de que el fichero tenga la fila
# de días de la semana justo encima de la cabecera y la columna del nombre donde
# toca. Cuando el fichero no es exactamente ése —y en una nave real nunca lo
# es— falla o se deja filas por el camino.
#
# Pegar es más tosco y por eso más fiable: se selecciona el bloque en Sheets,
# se copia, se pega. Lo que se ve es lo que entra. Sin macros, sin formatos y
# sin que importe dónde esté cada cosa en el fichero original.
#
# ── LO QUE DE VERDAD FALLA AL IMPORTAR: LOS NOMBRES ──────────────────────────
# Medido con el cuadrante de agosto: el fichero traía 61 conductores y se
# guardaron 47. Los otros 14 se cayeron porque su nombre en el Sheets no es
# exactamente el de su ficha. Y con 17 personas dadas de alta dos veces y 26
# nombres con espacios de más (gotcha 15), eso va a pasar TODOS los meses.
#
# Por eso los alias: cuando dices una vez que "ROJAS PEREZ, SERGIO L." es
# Sergio Luis Rojas Pérez, queda guardado y el mes que viene entra solo.

_ALIAS_DOC = "alias_nombres_cuadrante"


async def _alias_cuadrante() -> dict:
    """Nombre tal y como viene en el cuadrante → id del conductor."""
    doc = await db.app_meta.find_one({"_id": _ALIAS_DOC}) or {}
    return {k: v for k, v in (doc.get("mapa") or {}).items() if v}


def _celdas_pegadas(texto: str) -> list:
    """Convierte lo pegado en una rejilla.

    Sheets y Excel copian con TABULADOR entre columnas. Se admite también el
    punto y coma por si alguien pega desde un CSV exportado a la española.
    """
    filas = []
    for linea in str(texto or "").replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if not linea.strip():
            continue
        sep = "\t" if "\t" in linea else (";" if linea.count(";") >= 3 else "\t")
        filas.append([c.strip() for c in linea.split(sep)])
    return filas


def _rejilla_pegada(filas: list) -> tuple:
    """Se orienta sola dentro de lo pegado. Devuelve (col_nombre, {col: dia}, i_datos).

    NO se puede dar por hecho que la primera celda sea el nombre. El cuadrante
    real de OGA5 tiene DOS columnas antes —'Orden' y 'Nombre'— y DOS filas de
    cabecera: una con los días de la semana y otra con los números del día. Al
    suponer que la primera celda era el nombre, se leían los números de orden
    ('1', '2', '3'…) como si fueran personas: 62 nombres sin encontrar y cero
    turnos guardados.

    La pista buena es la FILA DE NÚMEROS DE DÍA: es la única que tiene una
    tirada larga de enteros del 1 al 31 subiendo. De ella salen dos cosas:

      · dónde empieza el bloque de días, y por tanto dónde está el nombre
        (la última celda con texto justo antes);
      · QUÉ DÍA es cada columna. Esto es mejor que contar posiciones: si se pega
        media hoja, del 10 al 20, los números lo dicen y no hay que adivinarlo.
    """
    mejor = None
    for i, fila in enumerate(filas[:8]):        # la cabecera está arriba
        seguidos, ini = [], None
        for j, c in enumerate(fila):
            txt = str(c or "").strip()
            if txt.isdigit() and 1 <= int(txt) <= 31:
                n = int(txt)
                if seguidos and n == seguidos[-1][1] + 1:
                    seguidos.append((j, n))
                else:
                    if len(seguidos) >= 5:
                        break
                    seguidos, ini = [(j, n)], j
            elif seguidos:
                if len(seguidos) >= 5:
                    break
                seguidos, ini = [], None
        if len(seguidos) >= 5 and (mejor is None or len(seguidos) > len(mejor[1])):
            mejor = (i, seguidos)
    if not mejor:
        return None, None, None

    i_num, seguidos = mejor
    cols_dia = {j: n for j, n in seguidos}
    primera_col = min(cols_dia)

    # El nombre: la cabecera que ponga "NOMBRE", y si no, la última celda con
    # texto antes del bloque de días.
    col_nombre = None
    for fila in filas[:i_num + 1]:
        for j in range(min(primera_col, len(fila))):
            if "NOMBRE" in _sin_tildes(str(fila[j] or "")).upper():
                col_nombre = j
                break
        if col_nombre is not None:
            break
    if col_nombre is None:
        col_nombre = primera_col - 1 if primera_col > 0 else 0

    return col_nombre, cols_dia, i_num + 1


@api_router.post("/shifts/import-pegado")
async def import_shifts_pegado(data: dict = Body(...), _=Depends(require_admin)):
    """Importa el cuadrante pegado desde Sheets. body: {center, mes, texto, confirmar}

    Cada línea es un conductor: la primera celda es el nombre y las siguientes
    son los días 1, 2, 3… del mes, en orden.

    Si la primera línea son días de la semana (LUN, MAR…) se usa para COMPROBAR
    que el bloque empieza donde dice el mes elegido, igual que hace el
    importador de Excel. Si no viene, se avisa de que no se ha podido comprobar
    en vez de callarlo: un cuadrante corrido un día es peor que ninguno.

    Un mes a medias es legítimo — el cuadrante de agosto estaba relleno sólo
    hasta el día 23 — así que no se exige el mes entero. Lo que no se admite es
    pasarse de los días que tiene el mes.
    """
    center = _texto_cuerpo(data.get("center"))
    mes = _texto_cuerpo(data.get("mes"))
    confirmar = bool(data.get("confirmar"))
    if not center:
        raise HTTPException(400, "Falta el centro")
    m = re.fullmatch(r"(\d{4})-(\d{2})", mes)
    if not m:
        raise HTTPException(400, "El mes va como AAAA-MM")
    anio, mesn = int(m.group(1)), int(m.group(2))
    if not (1 <= mesn <= 12):
        raise HTTPException(400, "Mes fuera de rango")

    filas = _celdas_pegadas(data.get("texto"))
    if len(filas) < 2:
        raise HTTPException(400, "Pega al menos la cabecera y una fila de conductor")

    dias_mes = calendar.monthrange(anio, mesn)[1]

    col_nombre, cols_dia, i_datos = _rejilla_pegada(filas)
    if not cols_dia:
        raise HTTPException(400,
            "No encuentro la fila con los números de los días (1, 2, 3…). "
            "Copia también las cabeceras de tu hoja, no sólo las filas de gente.")
    fuera_de_mes = [n for n in cols_dia.values() if n > dias_mes]
    if fuera_de_mes:
        raise HTTPException(400,
            f"Lo pegado llega al día {max(fuera_de_mes)} y {mes} sólo tiene {dias_mes}.")

    # ── LA COMPROBACIÓN QUE EVITA EL DESASTRE ───────────────────────────────
    # Con los números de día ya no hace falta adivinar dónde empieza nada. Lo
    # que sí se comprueba, si la hoja trae la fila de días de la semana, es que
    # el mes elegido sea el del cuadrante: 'sáb' encima del día 1 sólo cuadra
    # con los meses que empiezan en sábado. Cuadrar 20 columnas por casualidad
    # es imposible, así que un fallo aquí es que el mes está mal.
    DOW = {"LUN": 0, "MAR": 1, "MIE": 2, "MIER": 2, "JUE": 3, "VIE": 4,
           "SAB": 5, "DOM": 6, "X": 2}
    aviso_alineacion = None
    fila_dow = None
    for fila in filas[:i_datos]:
        etiquetas = [_sin_tildes(str(c or "")).strip().rstrip(".").upper() for c in fila]
        if sum(1 for e in etiquetas if e in DOW) >= 5:
            fila_dow = etiquetas
            break
    if fila_dow:
        MESES = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
                 "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
        DIAS_SEM = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"]
        fallos = []
        for j, n in sorted(cols_dia.items()):
            etq = fila_dow[j] if j < len(fila_dow) else ""
            if etq in DOW and DOW[etq] != date_cls(anio, mesn, n).weekday():
                fallos.append((n, etq))
        if len(fallos) > 1:
            n, etq = fallos[0]
            raise HTTPException(400,
                f"En tu hoja el día {n} es {etq.lower()}, pero el {n} de "
                f"{MESES[mesn]} de {anio} cae en {DIAS_SEM[date_cls(anio, mesn, n).weekday()]}. "
                f"El mes elegido no es el de este cuadrante. No se ha guardado nada.")
    else:
        aviso_alineacion = ("No has pegado la fila de días de la semana (lun, mar…), así que "
                            "no he podido comprobar que el mes sea el correcto. Mira el "
                            "resumen antes de guardar.")

    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    # Se traen TAMBIEN los dados de baja. Hay 71 fichas con active=False de 202,
    # y varias son gente que sigue saliendo en el cuadrante: excluirlas hacia
    # desaparecer sus filas sin decir nada. Se encuentran, y se avisa.
    drivers = await db.drivers.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}},
        {"_id": 0, "id": 1, "name": 1, "active": 1}).to_list(2000)
    por_nombre = {_clave_nombre(d.get("name")): d for d in drivers}
    por_id = {d["id"]: d for d in drivers}
    alias = await _alias_cuadrante()

    items, sin_conductor, sin_codigo, de_baja = [], [], {}, set()
    for fila in filas[i_datos:]:
        if not fila or col_nombre >= len(fila):
            continue
        nombre = (fila[col_nombre] or "").strip()
        # Una fila cuyo "nombre" es un número es la de totales o un resto de la
        # hoja, no una persona.
        if not nombre or nombre.isdigit():
            continue
        drv, motivo = _empareja_conductor(nombre, drivers, alias)
        if not drv:
            sin_conductor.append({"nombre": nombre, "motivo": motivo})
            continue
        if drv.get("active") is False:
            de_baja.add(drv["name"])
        for j, n in sorted(cols_dia.items()):
            crudo = fila[j] if j < len(fila) else None
            if crudo in (None, ""):
                continue
            cod, hora = _despieza_codigo(crudo)
            if cod not in mapa:
                sin_codigo[cod] = sin_codigo.get(cod, 0) + 1
                continue
            tipo = mapa[cod]
            if not tipo:
                continue
            it = {"driver_id": drv["id"], "driver_name": drv["name"],
                  "center": center, "date": f"{anio:04d}-{mesn:02d}-{n:02d}",
                  "type": tipo, "cod": cod}
            if hora:
                it["hora"] = hora
            items.append(it)

    dias_con_datos = sorted({i["date"] for i in items})
    resumen = {
        "mes": f"{anio:04d}-{mesn:02d}", "center": center,
        "dias": len(dias_con_datos),
        "primer_dia": dias_con_datos[0] if dias_con_datos else None,
        "ultimo_dia": dias_con_datos[-1] if dias_con_datos else None,
        "conductores": len({i["driver_id"] for i in items}),
        "turnos": len(items),
        "trabaja": sum(1 for i in items if i["type"] == "trabaja"),
        "libre": sum(1 for i in items if i["type"] == "libre"),
        "extra": sum(1 for i in items if i["type"] == "extra"),
        "sin_conductor": sin_conductor[:60],
        "n_sin_conductor": len(sin_conductor),
        "de_baja": sorted(de_baja),
        "codigos_desconocidos": dict(sorted(sin_codigo.items(), key=lambda x: -x[1])),
        "guardado": False,
    }
    if aviso_alineacion:
        resumen["aviso_alineacion"] = aviso_alineacion
    if sin_codigo and not confirmar:
        resumen["aviso"] = ("Hay códigos que no sé qué significan. Tradúcelos antes de "
                            "guardar, o confirma para importar sólo el resto.")
        return resumen
    if not confirmar:
        return resumen
    if not items:
        raise HTTPException(400, "No hay ni un turno que guardar")

    items, respetados = await _respeta_aprobados(items)

    guardados = 0
    for i in range(0, len(items), 500):
        lote = items[i:i + 500]
        await _bulk_turnos([
            UpdateOne({"driver_id": it["driver_id"], "date": it["date"]},
                      {"$set": it}, upsert=True) for it in lote])
        guardados += len(lote)
    resumen["guardado"] = True
    resumen["saved"] = guardados
    resumen["respetados"] = respetados[:30]
    resumen["n_respetados"] = len(respetados)
    logger.info("Cuadrante pegado: %s %s - %s turnos", center, resumen["mes"], guardados)
    return resumen


# Los mismos cinco colores de la pantalla, pero para papel blanco. En la app el
# fondo es oscuro y valen tintes translucidos; en Excel hay que dar el color
# opaco y un texto que se lea encima. Se mantienen las cinco familias: si aqui
# hubiera dieciseis colores, la hoja descargada seria justo el arcoiris del que
# se venia huyendo.
COLOR_FAMILIA_XLSX = {
    "ruta":     ("D6EAD7", "1E5B2A"),
    "apoyo":    ("D5EFEC", "12554E"),
    "libre":    ("F1F1EF", "72726C"),
    "previsto": ("DBEAF7", "12456F"),
    "aprobado": ("F8DCE8", "7A2447"),
    "aviso":    ("FADCDC", "8C1D1D"),
}
FAMILIA_NOMBRE_XLSX = {
    "ruta": "Sale a ruta", "apoyo": "Trabaja sin ruta", "libre": "Dia libre",
    "previsto": "Ausencia prevista", "aprobado": "Dia concedido (no se toca)",
    "aviso": "Ausencia no prevista",
}
DIAS_SEM_CORTO = ["lun", "mar", "mie", "jue", "vie", "sab", "dom"]
MESES_ES = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
            "agosto", "septiembre", "octubre", "noviembre", "diciembre"]


@api_router.get("/shifts/export")
async def exportar_cuadrante(center: str, desde: str, hasta: str,
                             user: dict = Depends(require_admin)):
    """El cuadrante, en un .xlsx que se abre en Excel y en Sheets.

    Se genera aqui y no en el navegador a proposito: asi la hoja lleva colores,
    cabeceras congeladas y anchos de columna sin meter una libreria de Excel en
    el bundle del panel, y sale igual desde cualquier ordenador.

    Dos hojas:
      · "Cuadrante" — la rejilla tal cual se ve, para mirarla o imprimirla.
      · "Por conductor" — una fila por persona y dia. Es la que sirve para
        filtrar, ordenar o mandarle a alguien solo lo suyo; una rejilla no se
        puede filtrar.
    """
    import openpyxl, io as _io
    from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
    from openpyxl.comments import Comment

    dias = _date_range(desde, hasta)

    q = dict(_filtro_centro(user, center))
    q["date"] = {"$gte": desde, "$lte": hasta}
    turnos = await db.shifts.find(q, {"_id": 0}).to_list(20000)

    dem = {d["date"]: d for d in await db.route_demand.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}}, {"_id": 0}).to_list(400)}

    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    def info(cod):
        base = CODIGOS_CUADRANTE_INFO.get(cod)
        if base:
            return base[1], base[2]
        return cod, "libre"

    # Solo sale quien tenga algo puesto. Bajar una hoja con veinte filas vacias
    # de gente que ya no esta es exactamente el problema que se acaba de quitar
    # de la pantalla.
    por_id = {}
    for s in turnos:
        did = s.get("driver_id")
        if not did:
            continue
        f = por_id.setdefault(did, {"nombre": s.get("driver_name") or "", "dias": {}})
        cod = s.get("cod") or {"trabaja": "1", "libre": "N/T", "extra": "EXTRA"}.get(s.get("type"), "")
        f["dias"][s["date"]] = (cod, s.get("hora") or "")
        if s.get("driver_name"):
            f["nombre"] = s["driver_name"]
    filas = sorted(por_id.values(), key=lambda x: _clave_nombre(x["nombre"]))

    fino = Side(style="thin", color="D9D9D9")
    medio = Side(style="thin", color="9C9C9C")
    borde = Border(left=fino, right=fino, top=fino, bottom=fino)
    centro = Alignment(horizontal="center", vertical="center")

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Cuadrante"

    d0 = datetime.strptime(dias[0], "%Y-%m-%d")
    ws.cell(row=1, column=1,
            value=f"Cuadrante {center} - {MESES_ES[d0.month]} de {d0.year}").font = Font(bold=True, size=14)
    ws.cell(row=1, column=3, value=f"{dias[0]} a {dias[-1]}").font = Font(color="808080", size=10)

    ws.cell(row=2, column=1, value="CONDUCTOR").font = Font(bold=True, size=9, color="606060")
    ws.cell(row=2, column=2, value="Dias").font = Font(bold=True, size=9, color="606060")
    for j, f in enumerate(dias):
        d = datetime.strptime(f, "%Y-%m-%d")
        finde = d.weekday() >= 5
        c1 = ws.cell(row=2, column=3 + j, value=DIAS_SEM_CORTO[d.weekday()])
        c1.font = Font(size=8, color="A00000" if finde else "808080")
        c1.alignment = centro
        if d.weekday() == 6:
            c1.border = Border(left=medio)
            ws.cell(row=3, column=3 + j).border = Border(left=medio)
        c2 = ws.cell(row=3, column=3 + j, value=d.day)
        c2.font = Font(bold=True, size=10, color="A00000" if finde else "303030")
        c2.alignment = centro
        if finde:
            for r in (2, 3):
                ws.cell(row=r, column=3 + j).fill = PatternFill("solid", fgColor="F2F2F2")
    ws.cell(row=3, column=1, value="Nombre").font = Font(bold=True, size=9, color="606060")

    for i, fila in enumerate(filas):
        r = 4 + i
        cn = ws.cell(row=r, column=1, value=fila["nombre"])
        cn.font = Font(size=10)
        cn.border = borde
        trabajados = sum(1 for cod, _ in fila["dias"].values()
                         if mapa.get(cod) in ("trabaja", "extra"))
        ct = ws.cell(row=r, column=2, value=trabajados)
        ct.font = Font(bold=True, size=10, color="606060")
        ct.alignment = centro
        ct.border = borde
        for j, f in enumerate(dias):
            cod, hora = fila["dias"].get(f, ("", ""))
            cel = ws.cell(row=r, column=3 + j, value=cod)
            cel.alignment = centro
            # Linea mas marcada donde empieza la semana. La semana de Amazon va
            # de DOMINGO a sabado: cortando en lunes, la raya cae en medio de
            # cada una de sus semanas y las cuentas no cuadran con las suyas.
            cel.border = (Border(left=medio, right=fino, top=fino, bottom=fino)
                          if datetime.strptime(f, "%Y-%m-%d").weekday() == 6 else borde)
            if cod:
                etiqueta, fam = info(cod)
                bg, fg = COLOR_FAMILIA_XLSX.get(fam, COLOR_FAMILIA_XLSX["libre"])
                cel.fill = PatternFill("solid", fgColor=bg)
                cel.font = Font(bold=True, size=9, color=fg)
                # La hora no cabe en la celda, pero no se tira: va al
                # comentario, que se ve al pasar por encima y no ensucia
                # la rejilla.
                if hora:
                    cel.comment = Comment(f"{etiqueta} - entra a las {hora}", "FlotaDSP")

    # Las tres cifras del dia, juntas y en el mismo orden que en la hoja de la
    # que sale esto. Solas no dicen nada: 39 personas es mucho o poco segun lo
    # que pidan, y no llegar al maximo comprometido es lo que hace que la
    # proxima vez no te ofrezcan rutas.
    rcob = 4 + len(filas) + 1
    cobs = []
    for j, f in enumerate(dias):
        n = sum(1 for fila in filas
                if fila["dias"].get(f, ("", ""))[0] in CODIGOS_QUE_SACAN_RUTA)
        cobs.append(n)

    for k, (titulo, saca, bg) in enumerate([
        ("Salen a ruta", lambda j, f: cobs[j], "DCEAF7"),
        ("Rutas que piden", lambda j, f: dem.get(f, {}).get("objetivo"), None),
        ("Maximas comprometidas", lambda j, f: dem.get(f, {}).get("maximo"), "FBE3C8"),
    ]):
        r = rcob + k
        ct = ws.cell(row=r, column=1, value=titulo)
        ct.font = Font(bold=True, size=9, color="606060")
        for j, f in enumerate(dias):
            v = saca(j, f)
            c = ws.cell(row=r, column=3 + j, value=v)
            c.font = Font(bold=True, size=10)
            c.alignment = centro
            c.border = Border(top=medio if k == 0 else fino,
                              bottom=medio if k == 2 else fino, left=fino, right=fino)
            if bg:
                c.fill = PatternFill("solid", fgColor=bg)
            # Rojo si ese dia no llegas a lo que piden: es una ruta sin cubrir.
            if k == 0:
                piden = dem.get(f, {}).get("objetivo")
                if piden is not None and cobs[j] < piden:
                    c.font = Font(bold=True, size=10, color="C00000")

    # Leyenda, por familias. Debajo de la tabla para que salga al imprimir.
    rl = rcob + 4
    ws.cell(row=rl, column=1, value="LEYENDA").font = Font(bold=True, size=9, color="606060")
    for k, (fam, nombre) in enumerate(FAMILIA_NOMBRE_XLSX.items()):
        codigos = [c for c, v in CODIGOS_CUADRANTE_INFO.items() if v[2] == fam]
        bg, fg = COLOR_FAMILIA_XLSX[fam]
        c = ws.cell(row=rl + 1 + k, column=1, value=", ".join(codigos))
        c.fill = PatternFill("solid", fgColor=bg)
        c.font = Font(bold=True, size=9, color=fg)
        c.alignment = centro
        c.border = borde
        ws.cell(row=rl + 1 + k, column=2, value=nombre).font = Font(size=9, color="606060")

    ws.freeze_panes = "C4"
    ws.column_dimensions["A"].width = 32
    ws.column_dimensions["B"].width = 6
    for j in range(len(dias)):
        ws.column_dimensions[get_column_letter(3 + j)].width = 5.5
    ws.sheet_view.showGridLines = False

    # ── Hoja 2: una fila por persona y dia ────────────────────────────────
    ws2 = wb.create_sheet("Por conductor")
    for j, cab in enumerate(["Conductor", "Fecha", "Dia", "Codigo", "Significado", "Entra a las"]):
        c = ws2.cell(row=1, column=1 + j, value=cab)
        c.font = Font(bold=True, size=9, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="595959")
        c.alignment = centro
    r = 2
    for fila in filas:
        for f in dias:
            cod, hora = fila["dias"].get(f, ("", ""))
            if not cod:
                continue
            etiqueta, _fam = info(cod)
            d = datetime.strptime(f, "%Y-%m-%d")
            for j, v in enumerate([fila["nombre"], f, DIAS_SEM_CORTO[d.weekday()],
                                   cod, etiqueta, hora]):
                ws2.cell(row=r, column=1 + j, value=v).font = Font(size=10)
            r += 1
    ws2.freeze_panes = "A2"
    ws2.auto_filter.ref = f"A1:F{max(1, r - 1)}"
    for col, ancho in zip("ABCDEF", (32, 12, 6, 11, 20, 12)):
        ws2.column_dimensions[col].width = ancho

    buf = _io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    nombre = f"cuadrante-{re.sub(r'[^A-Za-z0-9]+', '', center) or 'centro'}-{dias[0]}-a-{dias[-1]}.xlsx"
    logger.info("Cuadrante exportado: %s %s a %s, %d conductores", center, dias[0], dias[-1], len(filas))
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{nombre}"'},
    )


_DIA_TID = re.compile(r"^A[A-Z0-9]{8,16}$")


@api_router.get("/shifts/alias-nombres")
async def listar_alias_cuadrante(_=Depends(require_admin)):
    """Los nombres del cuadrante que ya se han emparejado a mano con su ficha."""
    return {"mapa": await _alias_cuadrante()}


@api_router.put("/shifts/alias-nombres")
async def guardar_alias_cuadrante(data: dict = Body(...), _=Depends(require_admin)):
    """Guarda 'este nombre del cuadrante es este conductor'. body: {mapa: {...}}

    Se guarda una vez y sirve para siempre: es lo que hace que el mes que viene
    no haya que volver a emparejar a los mismos catorce.
    """
    mapa = data.get("mapa")
    if not isinstance(mapa, dict):
        raise HTTPException(400, "mapa debe ser un objeto {nombre: driver_id}")
    limpio = {}
    for k, v in mapa.items():
        nombre = str(k).strip()[:120]
        did = str(v or "").strip()
        if not nombre:
            continue
        if did:
            limpio[nombre] = did      # emparejado
        # Un valor vacío borra el alias, que es como se deshace un error.
    if len(limpio) > 2000:
        raise HTTPException(400, "Demasiados alias")
    # Comprobar que los conductores existen: un alias a un id fantasma haría que
    # esas filas se perdieran en silencio, que es justo lo que se quiere evitar.
    ids = list({v for v in limpio.values()})
    existen = set()
    if ids:
        existen = {d["id"] for d in await db.drivers.find(
            {"id": {"$in": ids}}, {"_id": 0, "id": 1}).to_list(2000)}
    malos = sorted({k for k, v in limpio.items() if v not in existen})
    if malos:
        raise HTTPException(400, f"Estos alias apuntan a un conductor que no existe: {malos[:5]}")
    await db.app_meta.update_one(
        {"_id": _ALIAS_DOC},
        {"$set": {"mapa": limpio, "actualizado_en": datetime.now(timezone.utc).isoformat()}},
        upsert=True)
    return {"success": True, "alias": len(limpio)}


# Códigos del cuadrante mensual de Amazon. Se editan desde el panel porque
# cada nave usa los suyos; esto es sólo el punto de partida conocido.
# Cada codigo del cuadrante: (tipo, etiqueta, color).
#
# El TIPO es lo unico que entiende el resto de la app (cobertura, peticiones de
# dias, portal del conductor) y son solo tres. La ETIQUETA y el COLOR existen
# porque el tipo, solo, no basta para nadie que mire la pantalla: 'V',
# 'COMP', 'N/D' y 'N/P' son los cuatro "libre", y significan cosas muy
# distintas. Hasta que se guardo el codigo, pegar el cuadrante de OGA5 daba una
# pared de dos letras que no se parecia a la hoja de la que salio.
#
# El color es un nombre, no una clase de CSS: el backend no sabe de Tailwind y
# la pantalla no deberia tener que saberse los codigos de memoria.
#
# SON CINCO COLORES PARA DIECISEIS CODIGOS, Y ES A PROPOSITO. Con un color por
# codigo la rejilla era un arcoiris en el que no se distinguia nada: la
# recomendacion que se repite en todas las guias de accesibilidad y de
# visualizacion (Okabe-Ito, IBM, AudioEye) es NO PASAR DE SEIS colores
# categoricos, porque a partir de ahi dejan de diferenciarse a tamano pequeno
# —y una celda de cuadrante son 22 px—. El color dice de que FAMILIA es el dia
# y el texto del codigo, que siempre se ve, dice cual es exactamente. Asi el
# color se lee de un vistazo desde lejos y el detalle esta ahi cuando hace
# falta. Las familias:
#   ruta     -> sale a repartir
#   apoyo    -> trabaja, pero no en ruta (backup, oficina, ride along, extra)
#   libre    -> dia libre normal
#   previsto -> ausencia planificada (vacaciones, compensa)
#   aprobado -> dia concedido por la oficina: el unico que no se puede tocar
#   aviso    -> ausencia NO prevista (no disponible, no presentado, suspendido)
# La cuarta columna es SI ESE DIA SACA RUTA, y no es lo mismo que "trabaja".
#
# BKP y Site trabajan —cobran, estan en la nave— pero no sacan furgoneta, y
# el ride along va de acompanante en la de otro. Meterlos en la cuenta hacia
# que la fila de cobertura dijera 39 cuando a la calle salian 36, justo el
# numero que se compara con lo que pide Amazon. Un numero que se usa para
# decidir y que esta inflado es peor que no tenerlo.
CODIGOS_CUADRANTE_INFO = {
    # ── TRABAJA ────────────────────────────────────────────────────────────
    #              tipo        etiqueta            color      ¿saca ruta?
    "1":         ("trabaja", "Trabaja", "ruta", True),
    "T":         ("trabaja", "Trabaja", "ruta", True),
    "X":         ("trabaja", "Trabaja", "ruta", True),
    "BKP":       ("trabaja", "Backup", "apoyo", False),
    "S":         ("trabaja", "Site (oficina)", "apoyo", False),
    "RIDE":      ("trabaja", "Ride along", "apoyo", False),
    "RA":        ("trabaja", "Ride along", "apoyo", False),
    # El extra SI cuenta: es un dia de mas que alguien hace, y lo hace en ruta.
    "EXTRA":     ("extra", "Extra", "apoyo", True),
    # ── LIBRE ──────────────────────────────────────────────────────────────
    "N/T":       ("libre", "No trabaja", "libre", False),
    "L":         ("libre", "Libre", "libre", False),
    "V":         ("libre", "Vacaciones", "previsto", False),
    "COMP":      ("libre", "Compensa", "previsto", False),
    # Familia propia, no "previsto" con las vacaciones. Un dia concedido no es
    # una ausencia mas: es la unica casilla del cuadrante que NO se puede tocar
    # sin hablar con la persona, y tiene que distinguirse desde el otro lado de
    # la mesa. Es el sexto color, y ahi se para: seis es el limite por encima
    # del cual dejan de diferenciarse a tamano de celda.
    "N/T APROB": ("libre", "Libre aprobado", "aprobado", False),
    # ── AUSENCIAS QUE NO ESTABAN PREVISTAS ────────────────────────────────
    "N/D":       ("libre", "No disponible", "aviso", False),
    "N/P":       ("libre", "No presentado", "aviso", False),
    "SUSP":      ("libre", "Suspendido", "aviso", False),
}

CODIGOS_CUADRANTE_DEF = {k: v[0] for k, v in CODIGOS_CUADRANTE_INFO.items()}

# Los codigos que cuentan como ruta. Un codigo que no este aqui NO suma en la
# cobertura, aunque su tipo sea "trabaja".
CODIGOS_QUE_SACAN_RUTA = {k for k, v in CODIGOS_CUADRANTE_INFO.items() if v[3]}

# Como se cuenta un turno guardado ANTES de que hubiera codigos: solo tiene
# tipo. Se cuenta como ruta si trabajaba, que es lo que se venia haciendo; asi
# los meses viejos no cambian de numero de golpe sin motivo.
_FILTRO_RUTA = {"$or": [
    {"cod": {"$in": sorted(CODIGOS_QUE_SACAN_RUTA)}},
    {"cod": {"$exists": False}, "type": {"$in": ["trabaja", "extra"]}},
    {"cod": None, "type": {"$in": ["trabaja", "extra"]}},
]}


async def _respeta_aprobados(items: list) -> tuple:
    """Quita de `items` los dias que romperian una peticion ya aprobada.

    Devuelve (items_que_si_van, [{driver_name, date, type}, ...]).

    Existe porque el candado de la rejilla no bastaba. Pegar el cuadrante del
    mes desde Sheets escribe DIRECTO en la coleccion, sin pasar por
    /shifts/bulk, asi que se saltaba la proteccion entera: la hoja de Sheets no
    sabe nada de los dias que se aprobaron en la app, y al pegarla el mes que
    viene los borraba a todos de una vez y en silencio. Es el mismo fallo, pero
    peor, porque en vez de una celda son sesenta a la vez.

    Aqui se respeta SIEMPRE, tenga o no permiso quien pega. Pegar el cuadrante
    no es decidir sobre el dia de nadie: es traer la hoja del mes. Si de verdad
    hay que quitarle el dia a alguien, se hace en su casilla, a proposito y
    dejando rastro.
    """
    if not items:
        return items, []
    fechas = sorted({it["date"] for it in items})
    conductores = sorted({it["driver_id"] for it in items})
    aprobados = {}
    cur = db.shift_requests.find(
        {"status": "aprobado", "driver_id": {"$in": conductores},
         "date": {"$gte": fechas[0], "$lte": fechas[-1]}},
        {"_id": 0, "driver_id": 1, "date": 1, "type": 1, "driver_name": 1})
    async for r in cur:
        aprobados[f"{r['driver_id']}|{r['date']}"] = r
    if not aprobados:
        return items, []

    limpios, respetados = [], []
    for it in items:
        prot = aprobados.get(f"{it['driver_id']}|{it['date']}")
        if prot is None:
            limpios.append(it)
            continue
        aprobado = prot.get("type")
        rompe = ((aprobado == "libre" and it.get("type") in ("trabaja", "extra"))
                 or (aprobado == "extra" and it.get("type") == "libre"))
        if rompe:
            respetados.append({"driver_name": prot.get("driver_name") or it.get("driver_name") or "",
                               "date": it["date"], "type": aprobado})
        else:
            limpios.append(it)
    return limpios, respetados


def _despieza_codigo(crudo) -> tuple:
    """'V (05:43)' -> ('V', '05:43'). Devuelve (codigo, hora o '').

    Antes el parentesis se tiraba a la basura. Es la hora de entrada, y en el
    cuadrante de OGA5 aparece en la mitad de las celdas de vacaciones y de
    trabajo. Al conductor le importa mas esa hora que el codigo, asi que se
    guarda aparte en vez de perderla.
    """
    txt = str(crudo or "").strip()
    m = re.search(r"\(([^)]*)\)", txt)
    hora = ""
    if m:
        dentro = m.group(1).strip()
        if re.fullmatch(r"\d{1,2}[:.]\d{2}", dentro):
            hora = dentro.replace(".", ":")
        txt = re.sub(r"\s*\(.*?\)", "", txt)
    return re.sub(r"\s+", " ", txt).strip().upper(), hora


def _sin_tildes(s: str) -> str:
    tabla = str.maketrans("ÁÀÄÂÉÈËÊÍÌÏÎÓÒÖÔÚÙÜÛÑÇ", "AAAAEEEEIIIIOOOOUUUUNC")
    return (s or "").upper().translate(tabla)


def _clave_nombre(s: str) -> str:
    """Nombre comparable: sin tildes, sin espacios dobles, en mayúsculas."""
    return re.sub(r"\s+", " ", _sin_tildes(str(s or ""))).strip()


# ─── EMPAREJAR EL NOMBRE DEL CUADRANTE CON SU FICHA ──────────────────────────
#
# Aquí es donde se pierde el cuadrante. Medido con el de agosto: el fichero
# traía 61 conductores y se guardaron 47. Los otros 14 se cayeron en silencio.
# Dos motivos, ninguno tiene que ver con el Excel:
#
#  1. EL ORDEN DEL NOMBRE. La comparación era por igualdad del nombre
#     normalizado, y `_clave_nombre` casi no normaliza: 'ROJAS PEREZ, SERGIO L.'
#     se queda tal cual. Un cuadrante escrito "APELLIDOS, NOMBRE" no casa NUNCA
#     con una ficha que pone "NOMBRE APELLIDOS".
#
#  2. LOS DADOS DE BAJA. El importador sólo miraba fichas con `active != False`,
#     y hay 71 de 202 con `active: False` — 16 sólo en OGA5, varios de ellos
#     gente que sigue en el cuadrante. Sus filas desaparecían sin decir nada.
#
# Lo que se hace ahora:
#   · se comparan las PALABRAS del nombre, no la cadena entera;
#   · si el nombre corto está entero dentro del largo, es la misma persona;
#   · si encajan DOS fichas, no se elige ninguna — se dice que es ambiguo. Meter
#     los turnos de un hermano en la ficha del otro es peor que no meterlos;
#   · a los dados de baja se les encuentra igual, pero se avisa de que lo están
#     en vez de tragárselos.

_RELLENO_NOMBRE = {"DE", "DEL", "DA", "DO", "LA", "LAS", "LOS", "Y", "E", "SAN"}


def _palabras_nombre(s: str) -> set:
    """Las palabras que identifican a una persona, sin ruido.

    Fuera acentos, comas, puntos, iniciales sueltas y palabras de relleno.
    'ROJAS PEREZ, SERGIO L.' y 'Sergio Luis Rojas Pérez' acaban compartiendo
    {ROJAS, PEREZ, SERGIO}.
    """
    t = _sin_tildes(str(s or "")).upper()
    t = re.sub(r"[^A-Z0-9 ]+", " ", t)
    return {p for p in t.split()
            if len(p) > 1 and p not in _RELLENO_NOMBRE}


def _empareja_conductor(nombre: str, fichas: list, alias: dict):
    """Devuelve (ficha, motivo). La ficha es None si no se puede afirmar.

    motivo: 'alias' | 'exacto' | 'palabras' | 'no_encontrado' | 'ambiguo'
    """
    # 1. Lo que dijo una persona manda sobre cualquier heurística.
    did = alias.get((nombre or "").strip())
    if did:
        for f in fichas:
            if f["id"] == did:
                return f, "alias"

    clave = _clave_nombre(nombre)
    exactas = [f for f in fichas if _clave_nombre(f.get("name")) == clave]
    if len(exactas) == 1:
        return exactas[0], "exacto"
    if len(exactas) > 1:
        return None, "ambiguo"

    # 2. Por palabras. El nombre corto tiene que estar ENTERO dentro del largo,
    #    y con al menos dos palabras: con una sola, 'GARCIA' emparejaría media
    #    plantilla.
    pal = _palabras_nombre(nombre)
    if len(pal) < 2:
        return None, "no_encontrado"
    candidatas = []
    for f in fichas:
        pf = _palabras_nombre(f.get("name"))
        if len(pf) < 2:
            continue
        corto, largo = (pal, pf) if len(pal) <= len(pf) else (pf, pal)
        if corto and corto <= largo and len(corto) >= 2:
            candidatas.append(f)
    if len(candidatas) == 1:
        return candidatas[0], "palabras"
    if len(candidatas) > 1:
        # Dos personas encajan: no se elige. Meter los turnos de uno en la ficha
        # del otro es peor que dejarlos fuera y decirlo.
        return None, "ambiguo"
    return None, "no_encontrado"


# ─── IMPORTAR LOS MOVILES PERSONALES DESDE LOS CONTACTOS DEL TELEFONO ───────
#
# La oficina tiene a los conductores en la agenda de SU movil, con el numero de
# verdad (no el de la ruta del dia: gotchas 57 y 66). Se exporta la agenda
# (vCard o CSV), se sube aqui y se empareja por nombre con las fichas.
#
# DOS REGLAS QUE NO SE NEGOCIAN:
#   · LA AGENDA NO SE GUARDA. Trae a toda la familia y los amigos de quien la
#     exporta: el fichero se lee, se empareja y se descarta. Al panel solo
#     vuelven los contactos que encajan con UNA ficha, y de los demas solo se
#     cuenta cuantos son.
#   · NO SE ADIVINA. Es la misma regla de `_empareja_conductor`: con dos fichas
#     posibles no se propone ninguna, y un numero que saldria en dos personas
#     (o que ya es de otra ficha) se enseña aparte y sin marcar. Un movil
#     puesto a quien no es no se nota nunca, porque la ficha parece completa.

_MOVILES_MAX_BYTES = 8 * 1024 * 1024
_MOVILES_MAX_APLICAR = 500


def _vcf_lineas(texto: str) -> list:
    """Las lineas de un .vcf con los pliegues deshechos.

    Dos formas de partir una linea larga: la del estandar (la siguiente empieza
    por un espacio o tabulador) y la de los Android viejos, que acaban la linea
    en `=` cuando el valor va en QUOTED-PRINTABLE.
    """
    lineas = []
    for l in texto.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if lineas and l[:1] in (" ", "\t"):
            lineas[-1] += l[1:]
        elif (lineas and lineas[-1].endswith("=")
              and "QUOTED-PRINTABLE" in lineas[-1].split(":", 1)[0].upper()):
            lineas[-1] = lineas[-1][:-1] + l
        else:
            lineas.append(l)
    return lineas


def _vcf_valor(valor: str, params: str) -> str:
    if "QUOTED-PRINTABLE" in params.upper():
        import quopri
        try:
            return quopri.decodestring(valor.encode("latin-1", "ignore")).decode(
                "utf-8", errors="replace")
        except Exception:                                        # noqa: BLE001
            return valor
    return (valor.replace("\\n", " ").replace("\\N", " ").replace("\\,", ",")
            .replace("\\;", ";").replace("\\\\", "\\"))


def _vcf_contactos(texto: str) -> list:
    """`[{"nombre": str, "telefonos": [str]}]` de un fichero vCard."""
    salida, cur = [], None
    for l in _vcf_lineas(texto):
        u = l.strip().upper()
        if u == "BEGIN:VCARD":
            cur = {"fn": "", "n": "", "telefonos": []}
            continue
        if u == "END:VCARD":
            if cur is not None:
                nombre = cur["fn"] or cur["n"]
                if nombre or cur["telefonos"]:
                    salida.append({"nombre": nombre, "telefonos": cur["telefonos"]})
            cur = None
            continue
        if cur is None or ":" not in l:
            continue
        cab, valor = l.split(":", 1)
        partes = cab.split(";")
        prop = partes[0].split(".")[-1].upper()          # 'item1.TEL' -> 'TEL'
        params = ";".join(partes[1:])
        if prop == "FN":
            cur["fn"] = re.sub(r"\s+", " ", _vcf_valor(valor, params)).strip()
        elif prop == "N":
            # apellidos;nombre;segundo;prefijo;sufijo
            cachos = (_vcf_valor(valor, params).split(";") if "QUOTED-PRINTABLE" in params.upper()
                      else [_vcf_valor(c, params) for c in valor.split(";")])
            cachos += [""] * 5
            cur["n"] = re.sub(r"\s+", " ", " ".join(
                c for c in (cachos[1], cachos[2], cachos[0]) if c.strip())).strip()
        elif prop == "TEL":
            v = re.sub(r"^tel:", "", valor.strip(), flags=re.I)
            if v:
                cur["telefonos"].append(v)
    return salida


_MOV_COL_NOMBRE_COMPLETO = {"name", "nombre", "nombre completo", "full name", "display name",
                            "nombre y apellidos", "contacto", "contact"}
_MOV_COL_NOMBRE_PARTE = {"first name", "given name", "middle name", "additional name",
                         "last name", "family name", "surname", "apellidos", "apellido"}


def _tabla_contactos(filas: list) -> list:
    """`[{"nombre", "telefonos"}]` de un CSV/Excel de contactos (Google, Outlook...)."""
    filas = [f for f in filas if any(str(c or "").strip() for c in f)]
    if len(filas) < 2:
        return []
    cab = [re.sub(r"\s+", " ", _clave_nombre(c).lower().replace("_", " ").replace("-", " ")).strip()
           for c in filas[0]]
    completo = [i for i, h in enumerate(cab) if h in _MOV_COL_NOMBRE_COMPLETO]
    partes = [i for i, h in enumerate(cab) if h in _MOV_COL_NOMBRE_PARTE]
    tel = [i for i, h in enumerate(cab)
           if re.search(r"phone|tel|movil|mobile|celular|whatsapp", h)
           and not re.search(r"label|type|tipo|fax|phonetic|fonetic", h)]
    if not (completo or partes) or not tel:
        return []
    salida = []
    for f in filas[1:]:
        def cel(i):
            return str(f[i]).strip() if i < len(f) and f[i] is not None else ""
        nombre = next((cel(i) for i in completo if cel(i)), "")
        if not nombre:
            nombre = " ".join(cel(i) for i in partes if cel(i))
        nums = []
        for i in tel:
            nums += [x for x in re.split(r"\s*(?::::|;|\n)\s*", cel(i)) if x.strip()]
        if nombre or nums:
            salida.append({"nombre": re.sub(r"\s+", " ", nombre).strip(), "telefonos": nums})
    return salida


def _movil_de_contacto(crudo: str) -> str:
    """El movil listo para WhatsApp (E.164 sin '+'), o '' si no lo es.

    Un fijo no sirve para WhatsApp y un 981... en la ficha de alguien es un
    numero que no recibira nada: en Espana solo entran los que empiezan por 6 o 7.
    """
    e164 = whatsapp.normaliza_telefono(crudo)
    if not e164:
        return ""
    if e164.startswith("34"):
        return e164 if len(e164) == 11 and e164[2] in "67" else ""
    return e164


def _moviles_propone(contactos: list, fichas: list) -> dict:
    """Empareja los contactos con las fichas. NO toca nada: solo propone.

    `fichas`: `[{"id", "name", "center", "movil_personal"}]` de las activas.
    """
    por_ficha: dict = {}
    sin_ficha = ambiguos = sin_movil = 0
    for c in contactos:
        movs = list(dict.fromkeys(m for m in (_movil_de_contacto(t) for t in c["telefonos"]) if m))
        if not movs or not (c.get("nombre") or "").strip():
            sin_movil += 1
            continue
        ficha, motivo = _empareja_conductor(c["nombre"], fichas, {})
        if ficha is None:
            if motivo == "ambiguo":
                ambiguos += 1
            else:
                sin_ficha += 1
            continue
        e = por_ficha.setdefault(ficha["id"], {"ficha": ficha, "contactos": [], "movs": []})
        e["contactos"].append(c["nombre"])
        e["movs"] += [m for m in movs if m not in e["movs"]]

    # Un numero propuesto a dos personas distintas, o que ya es de otra ficha.
    quien: dict = {}
    for did, e in por_ficha.items():
        quien.setdefault(e["movs"][0], []).append(did)
    de_otra: dict = {}
    for f in fichas:
        n = whatsapp.normaliza_telefono(f.get("movil_personal"))
        if n:
            de_otra.setdefault(n, []).append(f["id"])

    propuestas, ya_estaban = [], 0
    for did, e in por_ficha.items():
        f, mov = e["ficha"], e["movs"][0]
        actual = whatsapp.normaliza_telefono(f.get("movil_personal"))
        if actual and actual == mov:
            ya_estaban += 1
            continue
        compartido = (len(quien.get(mov, [])) > 1
                      or any(x != did for x in de_otra.get(mov, [])))
        propuestas.append({
            "driver_id": did, "nombre": f.get("name") or "", "centro": f.get("center") or "",
            "contacto": e["contactos"][0], "movil": "+" + mov,
            "otros": ["+" + m for m in e["movs"][1:]],
            "actual": ("+" + actual) if actual else "",
            "estado": "cambia" if actual else "nuevo",
            "compartido": compartido})
    propuestas.sort(key=lambda p: (p["compartido"], p["estado"] != "nuevo",
                                   _clave_nombre(p["nombre"]), p["driver_id"]))
    return {"propuestas": propuestas, "ya_estaban": ya_estaban, "sin_ficha": sin_ficha,
            "ambiguos": ambiguos, "sin_movil": sin_movil}


def _moviles_lee_fichero(contenido: bytes, nombre: str) -> list:
    nombre = (nombre or "").lower()
    if nombre.endswith(".vcf") or contenido[:64].lstrip(b"\xef\xbb\xbf \r\n").upper().startswith(b"BEGIN:VCARD"):
        for cod in ("utf-8-sig", "cp1252"):
            try:
                return _vcf_contactos(contenido.decode(cod))
            except UnicodeDecodeError:
                continue
        return _vcf_contactos(contenido.decode("utf-8", errors="ignore"))
    return _tabla_contactos(_read_table_any(contenido, nombre))


@api_router.post("/drivers/moviles/analizar")
async def drivers_moviles_analizar(file: UploadFile = File(...), _=Depends(require_admin)):
    """Que moviles se pondrian a que conductor, SIN guardar nada."""
    contenido = await file.read()
    if len(contenido) > _MOVILES_MAX_BYTES:
        raise HTTPException(400, "El fichero es demasiado grande (maximo 8 MB).")
    try:
        contactos = _moviles_lee_fichero(contenido, file.filename or "")
    except Exception as e:                                       # noqa: BLE001
        raise HTTPException(400, "No se pudo leer el fichero: %s" % str(e)[:120])
    if not contactos:
        raise HTTPException(
            400, "No he encontrado contactos con telefono. Sirve el .vcf que exporta el "
                 "movil o el CSV de Google Contactos (con columnas de nombre y telefono).")
    fichas = await db.drivers.find(
        {"active": {"$ne": False}, "status": {"$nin": ["deleted", "baja"]}},
        {"_id": 0, "id": 1, "name": 1, "center": 1, "movil_personal": 1}).to_list(3000)
    fichas = [f for f in fichas if f.get("id") and f.get("name")]
    r = _moviles_propone(contactos, fichas)
    en_propuesta = {p["driver_id"] for p in r["propuestas"]}
    r.update({
        "total_contactos": len(contactos),
        "con_movil": len(contactos) - r["sin_movil"],
        # Cuantos conductores siguen sin movil personal aunque se aplique todo.
        "faltan": sum(1 for f in fichas
                      if not whatsapp.normaliza_telefono(f.get("movil_personal"))
                      and f["id"] not in en_propuesta),
    })
    return r


@api_router.post("/drivers/moviles/aplicar")
async def drivers_moviles_aplicar(body: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda los moviles que la oficina ha confirmado. Recalcula todo en el servidor.

    Del cliente solo se acepta QUE ficha y QUE numero; que el numero sea un
    movil y que no sea ya de otra ficha se vuelve a comprobar aqui (gotcha 38).
    """
    items = body.get("items")
    if not isinstance(items, list) or not items:
        raise HTTPException(400, "No has marcado ninguno")
    if len(items) > _MOVILES_MAX_APLICAR:
        raise HTTPException(400, "Demasiados de golpe (maximo %d)." % _MOVILES_MAX_APLICAR)
    ahora = datetime.now(timezone.utc).isoformat()
    aplicados, rechazados, cambios, usados = 0, [], [], set()
    for it in items:
        if not isinstance(it, dict):
            continue
        did = _texto_cuerpo(it.get("driver_id"), 80)
        e164 = _movil_de_contacto(_texto_cuerpo(it.get("movil"), 30))
        if not did or not e164:
            rechazados.append({"driver_id": did, "motivo": "no es un movil"})
            continue
        ficha = await db.drivers.find_one(
            {"id": did}, {"_id": 0, "id": 1, "name": 1, "active": 1, "movil_personal": 1})
        if not ficha or ficha.get("active") is False:
            rechazados.append({"driver_id": did, "motivo": "la ficha no existe o esta de baja"})
            continue
        otra = await db.drivers.find_one(
            {"movil_personal": "+" + e164, "id": {"$ne": did}, "active": {"$ne": False}},
            {"_id": 0, "name": 1})
        if otra or e164 in usados:
            rechazados.append({"driver_id": did, "nombre": ficha.get("name"),
                               "motivo": "ese numero ya es de %s"
                                         % ((otra or {}).get("name") or "otra ficha del lote")})
            continue
        await db.drivers.update_one({"id": did}, {"$set": {"movil_personal": "+" + e164}})
        usados.add(e164)
        aplicados += 1
        cambios.append({"id": did, "antes": ficha.get("movil_personal") or "",
                        "despues": "+" + e164})
    if cambios:
        # Deshacer un lote = volver a poner `antes`. Se guardan los ultimos 20.
        await db.app_meta.update_one(
            {"_id": "respaldo_moviles_personales"},
            {"$push": {"lotes": {"$each": [{"en": ahora,
                                            "por": user.get("name") or user.get("sub"),
                                            "cambios": cambios}], "$slice": -20}}},
            upsert=True)
        await _audit(user, "moviles_importar", {"aplicados": aplicados})
    return {"ok": True, "aplicados": aplicados, "rechazados": rechazados}


@api_router.get("/shifts/codigos")
async def get_codigos_cuadrante(_=Depends(require_admin)):
    """Qué significa cada código del Excel mensual."""
    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})
    # `info` lleva la etiqueta y el color de cada codigo. Los que anadio el
    # usuario a mano no estan en la tabla de arriba, asi que se les da una
    # etiqueta con su propio nombre y el color gris: mejor eso que no salir.
    info = {}
    for cod, tipo in mapa.items():
        base = CODIGOS_CUADRANTE_INFO.get(cod)
        info[cod] = {"tipo": tipo,
                     "etiqueta": base[1] if base else cod,
                     "color": base[2] if base else "libre",
                     # Sin base, un codigo anadido a mano cuenta como ruta si
                     # es de trabajar: es lo que espera quien lo anadio.
                     "ruta": bool(base[3]) if base else tipo in ("trabaja", "extra")}
    return {"codigos": doc.get("mapa") or CODIGOS_CUADRANTE_DEF,
            "mapa": mapa, "info": info,
            "tipos": sorted(VALID_SHIFT_TYPE)}


@api_router.put("/shifts/codigos")
async def set_codigos_cuadrante(data: dict = Body(...), _=Depends(require_admin)):
    """Traduce los códigos del Excel a turnos. Vacío = reconocido y se ignora."""
    mapa = {}
    for k, v in _dict_cuerpo(data.get("codigos")).items():
        k = str(k).strip().upper()[:20]
        if not k:
            continue
        if v in (None, "", "ignorar"):
            mapa[k] = None
        elif v in VALID_SHIFT_TYPE:
            mapa[k] = v
        else:
            raise HTTPException(400, f"Tipo no válido para {k}")
    await db.app_meta.update_one({"_id": "codigos_cuadrante"},
                                 {"$set": {"mapa": mapa}}, upsert=True)
    return {"codigos": mapa}


@api_router.post("/shifts/import")
async def import_shifts(file: UploadFile = File(...), center: str = Form(...),
                        mes: str = Form(...), confirmar: str = Form(default=""),
                        user: dict = Depends(require_admin)):
    """Importa el cuadrante mensual de turnos (hoja MENSUAL).

    ── POR QUÉ NO SE FÍA DEL FICHERO ────────────────────────────────────────
    El Excel real trae dos cosas que, tomadas al pie de la letra, meten un
    cuadrante equivocado para toda la nave:

      1. La cabecera pone "Desde: 01-06-2026 hasta: 30-06-2026" en un fichero
         que es de AGOSTO — el texto se queda del mes anterior al reutilizar
         la plantilla. Por eso el mes lo pone QUIEN IMPORTA, no el fichero.

      2. La fila de números de día viene rota: repite el 22, se salta el 23 y
         pone 1, 2, 3, 4 donde van 27, 28, 29 y 30. Fiarse de esos números
         escribiría turnos en días que no son. Se usa la POSICIÓN de la
         columna, que sí es correlativa, y el bloque de días se delimita con
         la fila de días de la semana, la única fiable de la cabecera.

    Y antes de escribir nada se comprueba que el día 1 del mes elegido caiga
    en el día de la semana que dice el Excel. Si no cuadra, se para: con 61
    conductores, un mes de desfase son más de 1.800 turnos mal puestos.

    Sin `confirmar` no guarda nada: primero devuelve el resumen de lo que hará.
    """
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")
    m = re.fullmatch(r"(\d{4})-(\d{1,2})", (mes or "").strip())
    if not m:
        raise HTTPException(400, "Elige el mes del cuadrante (YYYY-MM)")
    anio, mesn = int(m.group(1)), int(m.group(2))
    if not 1 <= mesn <= 12:
        raise HTTPException(400, "Mes fuera de rango")

    content = await file.read()
    try:
        import openpyxl, io
        wb = openpyxl.load_workbook(io.BytesIO(content), data_only=True)
        ws = wb["MENSUAL"] if "MENSUAL" in wb.sheetnames else wb[wb.sheetnames[0]]
        celdas = [[ws.cell(r, c).value for c in range(1, ws.max_column + 1)]
                  for r in range(1, min(ws.max_row, 400) + 1)]
    except Exception as e:
        raise HTTPException(400, f"No se pudo leer el Excel: {e}")

    # ── Cabecera: la fila que tiene "Nombre" ─────────────────────────────────
    fila_cab = col_nombre = None
    for i, fila in enumerate(celdas):
        for j, v in enumerate(fila):
            if _sin_tildes(str(v or "")).strip() == "NOMBRE":
                fila_cab, col_nombre = i, j
                break
        if fila_cab is not None:
            break
    if not fila_cab:
        raise HTTPException(400, "No encontré la fila de cabecera con la columna Nombre")

    # ── Días: el bloque que tiene día de la semana en la fila de encima ──────
    DOW = {"LUN": 0, "MAR": 1, "MIE": 2, "MIER": 2, "JUE": 3, "VIE": 4, "SAB": 5, "DOM": 6}
    fila_dow = celdas[fila_cab - 1]
    cols_dia, dow_primero = [], None
    for j in range(col_nombre + 1, len(fila_dow)):
        etiqueta = _sin_tildes(str(fila_dow[j] or "")).strip().rstrip(".")
        if etiqueta not in DOW:
            if cols_dia:
                break
            continue
        if dow_primero is None:
            dow_primero = DOW[etiqueta]
        cols_dia.append(j)
    if len(cols_dia) < 28:
        raise HTTPException(400,
            "No encontré la fila de días de la semana encima de la cabecera. "
            "Comprueba que es la hoja MENSUAL del cuadrante de turnos.")

    dias_mes = calendar.monthrange(anio, mesn)[1]
    if len(cols_dia) > dias_mes:
        cols_dia = cols_dia[:dias_mes]

    # ── La comprobación que evita el desastre ────────────────────────────────
    DIAS_SEM = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"]
    MESES_ES = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
                "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
    dow_real = date_cls(anio, mesn, 1).weekday()
    if dow_primero != dow_real:
        raise HTTPException(400,
            f"Este cuadrante empieza en {DIAS_SEM[dow_primero]} y el 1 de {MESES_ES[mesn]} "
            f"de {anio} cae en {DIAS_SEM[dow_real]}. O el mes elegido no es el del fichero, "
            f"o el Excel no es el que crees. No se ha guardado nada.")

    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    # Se traen TAMBIEN los dados de baja. Hay 71 fichas con active=False de 202,
    # y varias son gente que sigue saliendo en el cuadrante: excluirlas hacia
    # desaparecer sus filas sin decir nada. Se encuentran, y se avisa.
    drivers = await db.drivers.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}},
        {"_id": 0, "id": 1, "name": 1, "active": 1}).to_list(2000)
    por_nombre = {_clave_nombre(d.get("name")): d for d in drivers}
    alias = await _alias_cuadrante()

    items, sin_conductor, sin_codigo, de_baja = [], [], {}, set()
    for fila in celdas[fila_cab + 1:]:
        if col_nombre >= len(fila):
            continue
        nombre = str(fila[col_nombre] or "").strip()
        if not nombre:
            continue
        drv, motivo = _empareja_conductor(nombre, drivers, alias)
        if not drv:
            sin_conductor.append({"nombre": nombre, "motivo": motivo})
            continue
        if drv.get("active") is False:
            de_baja.add(drv["name"])
        for n, j in enumerate(cols_dia, start=1):
            if j >= len(fila):
                continue
            crudo = fila[j]
            if crudo in (None, ""):
                continue
            cod, hora = _despieza_codigo(crudo)
            if cod not in mapa:
                sin_codigo[cod] = sin_codigo.get(cod, 0) + 1
                continue
            tipo = mapa[cod]
            if not tipo:
                continue
            it = {"driver_id": drv["id"], "driver_name": drv["name"],
                  "center": center, "date": f"{anio:04d}-{mesn:02d}-{n:02d}",
                  "type": tipo, "cod": cod}
            if hora:
                it["hora"] = hora
            items.append(it)

    resumen = {
        "mes": f"{anio:04d}-{mesn:02d}", "center": center,
        "dias": len(cols_dia), "conductores": len({i["driver_id"] for i in items}),
        "turnos": len(items),
        "trabaja": sum(1 for i in items if i["type"] == "trabaja"),
        "libre": sum(1 for i in items if i["type"] == "libre"),
        "extra": sum(1 for i in items if i["type"] == "extra"),
        "sin_conductor": sin_conductor[:40],
        "n_sin_conductor": len(sin_conductor),
        "de_baja": sorted(de_baja),
        "codigos_desconocidos": dict(sorted(sin_codigo.items(), key=lambda x: -x[1])),
        "guardado": False,
    }

    # Un código sin traducir es un día que se quedaría sin poner. Se avisa
    # ANTES: un cuadrante a medias es peor que uno sin importar, porque parece
    # completo y ya nadie vuelve a mirarlo.
    if sin_codigo and not confirmar:
        resumen["aviso"] = ("Hay códigos que no sé qué significan. Tradúcelos antes de guardar, "
                            "o confirma para importar sólo el resto.")
        return resumen
    if not confirmar:
        return resumen

    items, respetados = await _respeta_aprobados(items)

    guardados = 0
    for i in range(0, len(items), 500):
        lote = items[i:i + 500]
        if lote:
            await _bulk_turnos([
                UpdateOne({"driver_id": it["driver_id"], "date": it["date"]},
                          {"$set": it}, upsert=True) for it in lote])
            guardados += len(lote)
    resumen["guardado"] = True
    resumen["saved"] = guardados
    resumen["respetados"] = respetados[:30]
    resumen["n_respetados"] = len(respetados)
    logger.info("Cuadrante importado: %s %s - %s turnos", center, resumen["mes"], guardados)
    return resumen


def _date_range(desde: str, hasta: str) -> list:
    """Los dias, en ISO, entre dos fechas incluidas las dos.

    NO EXISTIA. La llamaban /shifts/generate y /shifts/generate-auto, asi que
    las dos reventaban con NameError en la primera linea util. Y una de ellas
    tiene un boton detras: "Generar cuadrante" en la pantalla de Turnos llevaba
    devolviendo 500 desde siempre. Lo destapo el unico test que fallaba del CI,
    que llevaba semanas en rojo sin que nadie pudiera leer el log.

    Aqui no aplica el lio de husos horarios del gotcha 11: se entra y se sale en
    texto ISO, sin pasar por fechas locales en ningun momento.
    """
    try:
        a = datetime.strptime(desde, "%Y-%m-%d")
        b = datetime.strptime(hasta, "%Y-%m-%d")
    except (TypeError, ValueError):
        raise HTTPException(status_code=400,
                            detail="Las fechas van en formato AAAA-MM-DD")
    if b < a:
        raise HTTPException(status_code=400,
                            detail="La fecha de fin es anterior a la de inicio")
    # Un tope, porque el que llama manda las fechas y un rango de anos montaria
    # un cuadrante enorme y tumbaria la maquina por memoria.
    if (b - a).days > 366:
        raise HTTPException(status_code=400,
                            detail="Como mucho un ano de una vez")
    return [(a + timedelta(days=i)).strftime("%Y-%m-%d")
            for i in range((b - a).days + 1)]


# EL GENERADOR CON IA SE HA BORRADO (22-08-2026).
#
# Eran 155 lineas que no funcionaron jamas: llamaban a
# `_generate_schedule_with_gemini`, una funcion que nunca se escribio, dentro
# de un try que convertia el NameError en un 502 diciendo "la IA no pudo
# generar el cuadrante; reintenta". Un mensaje falso — no era la IA, y
# reintentar no iba a servir de nada.
#
# Ninguna pantalla la llamaba. Y el generador AUTOMATICO de aqui abajo hace lo
# mismo mejor: es instantaneo, deterministra, gratis y no gasta cuota de IA,
# que ademas se agota a diario. Esta en el historial de git por si algun dia
# se quiere retomar.

# Presupuesto de días/semana por nivel (carga progresiva de novatos)
_NIVEL_BUDGET = {"L1": 3, "L2": 4, "L3": 5, "pleno": 5}
_NOVATOS = {"L1", "L2", "L3"}


@api_router.get("/route-demand")
async def get_route_demand(center: str, desde: str, hasta: str,
                           user: dict = Depends(require_admin)):
    """Cuánta gente hace falta cada día. Es de lo que cuelga el cuadrante entero.

    NO SE PUEDE QUITAR SIN ROMPER TURNOS. La pantalla pide cinco cosas a la vez y
    un 404 en esta tumba la carga completa: «No se pudo cargar la cobertura» y ni
    un conductor en pantalla. Pasó en la app de la que sale esta, en un centro con
    61 conductores, y no se vio porque la pantalla no estaba en el menú.
    """
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")
    docs = await db.route_demand.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}}, {"_id": 0}).to_list(400)
    return {"demand": {d["date"]: {"objetivo": d.get("objetivo"), "maximo": d.get("maximo")}
                       for d in docs}}


@api_router.post("/route-demand")
async def set_route_demand(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda cuánta gente hace falta cada día. `null` borra ese dato.

    Son DOS números independientes y no se pueden tratar como uno:

      · `maximo`   — el techo: lo que habría que poder cubrir en el peor caso.
                     Se rellena con antelación, cuando aún no se sabe el día.
      · `objetivo` — las personas que hacen falta ESE día. Llega más tarde.

    Cada uno se guarda o se quita por su cuenta, y el día solo se borra cuando no
    queda ninguno de los dos: rellenar los máximos del mes y verlos desaparecer
    al dejar vacío el objetivo era exactamente el orden en que se usa.

    Se borra en vez de guardar un cero porque no son lo mismo: cero es un día sin
    trabajo, y «no lo sé todavía» es un día sin rellenar. El generador exige que
    haya objetivo, así que confundirlos haría un cuadrante vacío creyendo que ese
    día no se trabaja.
    """
    center = _texto_cuerpo(data.get("center"))
    if not center:
        raise HTTPException(400, "Falta el centro")
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")

    def _numero(crudo, fecha, que):
        if crudo in (None, ""):
            return None
        try:
            n = int(str(crudo).strip())
        except ValueError:
            raise HTTPException(400, f"{que} del {fecha} tiene que ser un número")
        if not 0 <= n <= 999:
            raise HTTPException(400, f"{que} del {fecha} está fuera de rango")
        return n

    ops, borrar = [], []
    for it in _lista_cuerpo(data.get("items")):
        if not isinstance(it, dict):
            continue
        fecha = str(it.get("date") or "")[:10]
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", fecha):
            continue
        objetivo = _numero(it.get("objetivo"), fecha, "Las personas necesarias")
        maximo = _numero(it.get("maximo"), fecha, "El máximo")
        if objetivo is None and maximo is None:
            borrar.append(fecha)
            continue
        doc = {"center": center, "date": fecha,
               "updated_at": datetime.now(timezone.utc).isoformat(),
               "updated_by": user.get("name")}
        quitar = {}
        for clave, valor in (("objetivo", objetivo), ("maximo", maximo)):
            if valor is None:
                quitar[clave] = ""
            else:
                doc[clave] = valor
        cambio = {"$set": doc}
        if quitar:
            cambio["$unset"] = quitar
        ops.append(UpdateOne({"center": center, "date": fecha}, cambio, upsert=True))

    if ops:
        await db.route_demand.bulk_write(ops)
    if borrar:
        await db.route_demand.delete_many({"center": center, "date": {"$in": borrar}})
    return {"ok": True, "guardados": len(ops), "borrados": len(borrar)}


@api_router.post("/shifts/generate-auto")
async def generate_schedule_auto(data: dict = Body(...), _=Depends(require_admin)):
    """Genera el cuadrante con un ALGORITMO DETERMINISTA (sin IA): instantáneo,
    gratis y siempre consistente. Cubre la gente que hace falta cada día,
    respeta plantilla (L-V) / ETT, protege a los novatos y reparte los días con
    justicia. No guarda: devuelve una propuesta."""
    center = _texto_cuerpo(data.get("center"), 30)
    desde = data.get("desde")
    hasta = data.get("hasta")
    if not (center and desde and hasta):
        raise HTTPException(status_code=400, detail="center, desde y hasta requeridos")
    days = _date_range(desde, hasta)

    drivers = await db.drivers.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}, "active": {"$ne": False}},
        {"_id": 0, "id": 1, "name": 1, "driver_id": 1, "contrato": 1, "nivel": 1},
    ).to_list(1000)
    if not drivers:
        raise HTTPException(status_code=404, detail=f"No hay conductores en {center}")

    # demanda
    dem_docs = await db.route_demand.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}}, {"_id": 0}
    ).to_list(400)
    demand = {d["date"]: d for d in dem_docs}
    if not any(demand.get(dd, {}).get("objetivo") for dd in days):
        raise HTTPException(status_code=400,
            detail="Falta cuánta gente hace falta: pon las personas necesarias de cada día antes de generar.")

    # días ya trabajados últimas 2 semanas (para no recargar siempre a los mismos)
    d14 = (datetime.strptime(desde, "%Y-%m-%d") - timedelta(days=14)).strftime("%Y-%m-%d")
    worked = {}
    cur2 = db.shifts.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}, "date": {"$gte": d14, "$lt": desde},
         "type": {"$in": ["trabaja", "extra"]}}, {"_id": 0, "driver_id": 1})
    async for s in cur2:
        worked[s["driver_id"]] = worked.get(s["driver_id"], 0) + 1

    # agrupar en semanas (lunes inicia semana) para el cupo de ~5 días
    weeks, cur = [], []
    for dd in days:
        if datetime.strptime(dd, "%Y-%m-%d").weekday() == 0 and cur:
            weeks.append(cur); cur = []
        cur.append(dd)
    if cur:
        weeks.append(cur)

    assignments, faltas = [], []
    name_by_id = {d["id"]: d.get("name", "") for d in drivers}
    for wk in weeks:
        assigned = {d["id"]: 0 for d in drivers}   # días asignados esta semana
        for dd in wk:
            obj = demand.get(dd, {}).get("objetivo")
            if not obj:
                continue
            mx = demand.get(dd, {}).get("maximo") or obj
            need = min(int(obj), int(mx))
            is_weekend = datetime.strptime(dd, "%Y-%m-%d").weekday() >= 5

            elig = []
            for d in drivers:
                contrato = (d.get("contrato") or "ett").lower()
                if contrato == "empresa" and is_weekend:
                    continue   # empresa nunca trabaja en finde
                elig.append(d)

            def sortkey(d):
                nivel = d.get("nivel") or "pleno"
                budget = _NIVEL_BUDGET.get(nivel, 5)
                under = assigned[d["id"]] < budget
                is_nov = nivel in _NOVATOS
                grp = 0 if (is_nov and under) else (1 if under else 2)  # novatos protegidos primero
                # REPARTO JUSTO: primero los novatos que aún tienen cupo; luego
                # quien menos lleva esta semana y quien menos trabajó las dos
                # anteriores. El nombre solo desempata, para que el resultado
                # sea siempre el mismo con los mismos datos.
                return (grp, assigned[d["id"]], worked.get(d["id"], 0), d.get("name", ""))

            elig.sort(key=sortkey)
            picked = elig[:need]
            for d in picked:
                budget = _NIVEL_BUDGET.get(d.get("nivel") or "pleno", 5)
                typ = "extra" if assigned[d["id"]] >= budget else "trabaja"
                assignments.append({"driver_id": d["id"], "driver_name": name_by_id[d["id"]],
                                    "center": center, "date": dd, "type": typ})
                assigned[d["id"]] += 1
            if len(picked) < int(obj):
                faltas.append(f"{dd[8:]}/{dd[5:7]} faltan {int(obj) - len(picked)}")

    cov = {dd: 0 for dd in days}
    for a in assignments:
        if a["type"] in ("trabaja", "extra"):
            cov[a["date"]] = cov.get(a["date"], 0) + 1

    resumen = ("Cuadrante automático con reparto justo de días. "
               "Plantilla solo de lunes a viernes, novatos protegidos con carga progresiva.")
    if faltas:
        resumen += " ⚠️ Días sin cubrir el objetivo: " + ", ".join(faltas[:12])
    else:
        resumen += " Todos los días cubren el objetivo."

    return {"success": True, "assignments": assignments, "resumen": resumen,
            "coverage": cov, "faltas": len(faltas)}


def _csv_filas(content: bytes) -> list:
    """Filas de un CSV tal y como lo guarda cada cual.

    Solo se leian comas en UTF-8, y el Excel en español guarda el «CSV» con
    PUNTO Y COMA y en Windows-1252: un fichero normal de un cliente llegaba
    como una sola columna y la importacion decia «no encuentro la matricula».
    Lo pegado desde Excel va con TABULADORES. Se prueba la codificacion y se
    elige el separador que mas aparece en la primera linea con datos.
    """
    import csv, io
    txt = None
    for cod in ("utf-8-sig", "cp1252"):
        try:
            txt = content.decode(cod)
            break
        except UnicodeDecodeError:
            continue
    if txt is None:
        txt = content.decode("utf-8", errors="ignore")
    txt = txt.replace("\r\n", "\n").replace("\r", "\n")
    primera = next((l for l in txt.split("\n") if l.strip()), "")
    sep = max(("\t", ";", ",", "|"), key=lambda s: primera.count(s))
    if not primera.count(sep):
        sep = ","
    return [r for r in csv.reader(io.StringIO(txt), delimiter=sep)]


def _read_table_any(content: bytes, filename: str):
    """Devuelve filas (listas de str) de xlsx/xls/csv/html."""
    fn = (filename or "").lower()
    rows = []
    if fn.endswith(".xlsx") or fn.endswith(".xlsm"):
        import openpyxl, io
        wb = openpyxl.load_workbook(io.BytesIO(content), read_only=True, data_only=True)
        for ws in wb.worksheets:
            for r in ws.iter_rows(values_only=True):
                rows.append(["" if c is None else str(c) for c in r])
    elif fn.endswith(".xls"):
        import xlrd
        book = xlrd.open_workbook(file_contents=content)
        for sh in book.sheets():
            for ri in range(sh.nrows):
                rows.append([str(sh.cell_value(ri, ci)) for ci in range(sh.ncols)])
    elif fn.endswith((".csv", ".txt", ".tsv")):
        rows = _csv_filas(content)
    else:
        html = content.decode("utf-8", errors="ignore")
        for tbl in re.findall(r"<table.*?</table>", html, re.S | re.I):
            for tr in re.findall(r"<tr.*?</tr>", tbl, re.S | re.I):
                cells = [re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", c)).strip()
                         for c in re.findall(r"<t[hd].*?</t[hd]>", tr, re.S | re.I)]
                if any(cells):
                    rows.append(cells)
    return rows


# ═══════════════════════════════════════════════════════════════════════════
# COMO VA LA SEMANA, HOY
# ═══════════════════════════════════════════════════════════════════════════
# EL PROBLEMA. La scorecard de Amazon llega con semanas de retraso: la ultima
# oficial cargada es la 29 y estamos en la 35. Cuando por fin ves que el DCR se
# hundio, esa semana lleva un mes cerrada y no hay nada que hacer.
#
# ESTO NO PREDICE NADA, Y ESA ES LA GRACIA. No hay modelo, no hay tendencia
# extrapolada, no hay "vas camino de". Se cuenta lo que YA ha pasado esta
# semana con los paquetes de Cortex —256.663 guardados, con su estado y su
# dia— y se compara contra los umbrales oficiales que ya tiene la app.
# Un acumulado real no se equivoca; una prediccion con 5 semanas de historico
# si, y mucho.
#
# `daily_ratios` esta VACIA y por eso `/scorecard/daily-trend` no devolvia nada:
# depende de que alguien suba el Resumen diario a mano. Cortex ya trae lo mismo
# y se actualiza solo cada pocos minutos.
#
# EL DIA DE HOY NO CUENTA para el acumulado si todavia hay paquetes en vuelo.
# A media tarde hay miles cargados en furgonetas: contarlos como fallo hunde el
# numero y da un susto falso todas las tardes. Sale aparte, marcado.


async def _latido(clave: str, **datos) -> None:
    """Deja constancia de que un bucle ha pasado por aqui.

    Un cron que se muere es INDISTINGUIBLE de uno que no tiene nada que hacer:
    los dos no escriben nada. Por eso cada bucle marca CADA pasada, tenga o no
    algo que hacer — sin esto, la unica forma de saber que seguia vivo es mirar
    dias despues si falta trabajo, que es tarde.

    Generico y no uno por bucle: el segundo que hizo falta ya iba a ser una
    copia del primero, y una copia se queda atras en cuanto se toca el original.
    Se consulta en `GET /admin/latidos`.
    """
    try:
        await global_db.app_meta.update_one(
            {"_id": "latido_%s" % clave},
            {"$set": {"at": datetime.now(timezone.utc), "bucle": clave, **datos}},
            upsert=True)
    except Exception as e:                                       # noqa: BLE001
        # El latido no puede tumbar el bucle: es el vigilante, no el trabajo.
        logger.error("Latido de %s: %s", clave, e)


async def avisar_bucles_muertos() -> dict:
    """Avisa si algun bucle ha dejado de latir.

    Sin esto el latido no sirve de nada: es un dato que hay que ir a mirar, y a
    los que hay que ir a mirar no los mira nadie. El que se muere en silencio es
    justo el que importa —el de congelar el dia pierde datos que no se pueden
    recuperar— asi que el aviso tiene que venir solo.
    """
    ahora = datetime.now(timezone.utc)
    muertos = []
    async for d in global_db.app_meta.find({"_id": {"$regex": "^latido_"}}):
        at = d.get("at")
        if not at:
            continue
        try:
            mins = (ahora - (at if at.tzinfo else at.replace(
                tzinfo=timezone.utc))).total_seconds() / 60
        except Exception:                                        # noqa: BLE001
            continue
        # El doble de su propio ritmo: un retraso puntual no es una muerte, y
        # avisar por eso haria que se dejara de leer el aviso.
        if mins > (d.get("cada_min") or 30) * 2:
            muertos.append((d.get("bucle") or str(d.get("_id"))[7:], round(mins)))
    if not muertos:
        return {"muertos": []}
    if await _ya_enviado_hoy("bucles_muertos", ahora.strftime("%Y-%m-%d")):
        return {"muertos": muertos, "avisado": False}
    lineas = ["⏱️ <b>Un proceso automático ha dejado de correr</b>"]
    for nom, mins in muertos:
        lineas.append("• <b>%s</b>: sin señal desde hace %d min" % (nom, mins))
    lineas.append("Suele arreglarse volviendo a desplegar el backend.")
    await _telegram_aviso("\n".join(lineas))
    return {"muertos": muertos, "avisado": True}


@api_router.get("/admin/latidos")
async def admin_latidos(_=Depends(require_admin)):
    """Que bucles siguen vivos. Un cron muerto no avisa: hay que preguntarle."""
    ahora = datetime.now(timezone.utc)
    out = []
    async for d in global_db.app_meta.find({"_id": {"$regex": "^latido_"}}):
        at = d.get("at")
        mins = None
        if at:
            try:
                mins = round((ahora - (at if at.tzinfo else at.replace(
                    tzinfo=timezone.utc))).total_seconds() / 60)
            except Exception:                                    # noqa: BLE001
                pass
        out.append({"bucle": d.get("bucle") or str(d.get("_id"))[7:],
                    "hace_min": mins, "error": d.get("error"),
                    # Cada bucle late a su ritmo, asi que el umbral sale de lo
                    # que el propio bucle diga que tarda, con margen.
                    "vivo": mins is not None and mins <= (d.get("cada_min") or 30) * 2,
                    "detalle": {k: v for k, v in d.items()
                                if k not in ("_id", "at", "bucle", "error")}})
    out.sort(key=lambda x: x["bucle"])
    return {"latidos": out,
            "todos_vivos": all(x["vivo"] for x in out) if out else None}


