async def _campana_apuntar(modo: str, tipo: str, correo: str) -> None:
    """Deja constancia de que ESE correo ya salio. Insert-only y por (tipo,
    correo): es lo que permite reanudar manana sin repetirselo a nadie."""
    if modo != "real":
        return
    try:
        await db.candidatos_campana_envios.update_one(
            {"_id": f"{tipo}:{correo}"},
            {"$setOnInsert": {"en": datetime.now(timezone.utc).isoformat()}}, upsert=True)
    except Exception as e:                                       # noqa: BLE001
        logger.error("campana: no se pudo apuntar %s a %s: %s", tipo, correo, e)


_CAMPANA_CORREOS = ("cupon", "suscripcion")


def _campana_pendientes(destinatarios: list, ya_enviados: set) -> list:
    """De cada persona, QUE correos le faltan todavia.

    La campana son dos correos por cabeza y Resend corta por cuota diaria (100
    al dia en el plan gratuito): el 19-09-2026 se quedaron 127 personas sin
    nada. Repetir la campana tal cual se la mandaria otra vez a los 97 que ya
    la tenian, con un cupon nuevo cada uno — spam y dinero. Con lo ya enviado
    apuntado por (tipo, correo), reanudar manana manda SOLO lo que falta."""
    salida = []
    for d in destinatarios:
        faltan = [t for t in _CAMPANA_CORREOS if f"{t}:{d['email']}" not in ya_enviados]
        if faltan:
            salida.append({**d, "faltan": faltan})
    return salida


def _campana_destinatarios(fichas: list) -> list:
    """Una persona, un correo. La MISMA direccion aparece en varias
    candidaturas —253 fichas para 224 correos el 19-09-2026—, y una campana
    sobre las fichas se manda dos veces a quien se postulo dos veces: dos
    correos identicos y DOS cupones personales, o sea 60 EUR regalados a la
    misma persona en vez de 30. Se queda el primer nombre que no venga vacio,
    porque una de las dos fichas puede tenerlo sin rellenar."""
    vistos, salida = {}, []
    for f in fichas:
        correo = (f.get("email") or "").strip().lower()
        if not correo:
            continue
        nombre = (f.get("nombre") or "").strip()
        if correo in vistos:
            if not vistos[correo]["nombre"] and nombre:
                vistos[correo]["nombre"] = nombre
            continue
        vistos[correo] = {"email": correo, "nombre": nombre}
        salida.append(vistos[correo])
    return salida


@api_router.post("/admin/candidatos/campana-bienvenida")
async def candidatos_campana_bienvenida(body: dict = Body(...), user: dict = Depends(require_superadmin)):
    modo = _texto_cuerpo(body.get("modo"), 10) or "prueba"
    if modo not in ("prueba", "real"):
        raise HTTPException(400, "modo debe ser 'prueba' o 'real'")
    if modo == "real" and _texto_cuerpo(body.get("confirmar"), 20) != "ENVIAR":
        raise HTTPException(400, "Escribe confirmar: \"ENVIAR\" para mandarlo a todos de verdad")

    enlace_tienda = await _tienda_enlace_publico()
    if not enlace_tienda:
        raise HTTPException(
            400, "Abre antes la tienda pública (Negocio > Tienda) y crea su enlace con /tienda/enlace")
    if not _stripe_encendido():
        raise HTTPException(503, "El cobro con tarjeta no está activo todavía (falta la clave de Stripe)")

    url_suscripcion = f"{_PORTAL_BASE_FRONT}/empleo/prioridad"

    if modo == "prueba":
        email_prueba = _texto_cuerpo(body.get("email_prueba"), 120).lower()
        if not email_prueba or not _EMAIL_RE.match(email_prueba):
            raise HTTPException(400, "Pon un correo válido en email_prueba para la prueba")
        destinatarios = [{"email": email_prueba, "nombre": user.get("name") or "Dani"}]
    else:
        fichas = await db.candidatos.find(
            {"email": {"$exists": True, "$ne": ""}}, {"_id": 0, "email": 1, "nombre": 1}).to_list(2000)
        destinatarios = _campana_destinatarios(fichas)

    # Un cupón PERSONAL por destinatario, con su propio reloj de 4h desde que se
    # genera — no uno compartido que cualquiera pudiera reenviar a otra persona
    # antes de gastarlo. Admite tres usos (`_CAMPANA_CUPON_USOS`): uno por
    # prenda, para que quien se lleve el hoodie conserve el descuento en el
    # cortavientos y en la gorra.
    # LO YA ENVIADO NO SE REPITE. En modo prueba no cuenta: es para mirarlo.
    if modo == "real":
        ya = {e["_id"] for e in await db.candidatos_campana_envios.find(
            {}, {"_id": 1}).to_list(20000)}
        destinatarios = _campana_pendientes(destinatarios, ya)
    else:
        destinatarios = [{**d, "faltan": list(_CAMPANA_CORREOS)} for d in destinatarios]

    enviados, fallidos, sin_cupon, pendientes = 0, 0, 0, 0
    ultima_expira = None
    for n, d in enumerate(destinatarios):
        # Cortar EN CUANTO Resend dice que por hoy no hay mas: seguir solo
        # sirve para tirar un cupon de Stripe por cabeza y acumular rechazos.
        if _email_sin_cuota_hoy():
            pendientes = len(destinatarios) - n
            break
        quiere_cupon = "cupon" in d["faltan"]
        cupon = None
        if quiere_cupon:
            cupon = await _stripe_crear_cupon(
                _CAMPANA_CUPON_EUR, _CAMPANA_CUPON_HORAS, usos=_CAMPANA_CUPON_USOS)
            if not cupon:
                sin_cupon += 1
                fallidos += 1
                continue
            ultima_expira = cupon["expira_en"]
        nombre = d.get("nombre") or ""
        algo = False
        if cupon:
            # La caducidad viaja en la URL para que la tienda pueda pintar una
            # cuenta atras real — sin esto, cada persona veia el mismo texto
            # fijo sin saber si le quedan 10 minutos o 3 horas y media.
            url_tienda = f"{enlace_tienda}?cupon={cupon['id']}&exp={_url_quote(cupon['expira_en'])}"
            if await _enviar_email(
                    d["email"], "Un regalo por tu candidatura con FlotaDSP",
                    _candidatos_campana_html_cupon(nombre, url_tienda, cupon["expira_en"]),
                    responder_a=os.environ.get("EMAIL_FROM_RESPUESTA", "")):
                algo = True
                await _campana_apuntar(modo, "cupon", d["email"])
        if "suscripcion" in d["faltan"]:
            if await _enviar_email(
                    d["email"], "Entérate el primero de los próximos empleos",
                    _candidatos_campana_html_suscripcion(nombre, url_suscripcion),
                    responder_a=os.environ.get("EMAIL_FROM_RESPUESTA", "")):
                algo = True
                await _campana_apuntar(modo, "suscripcion", d["email"])
        if algo:
            enviados += 1
        else:
            fallidos += 1

    if modo == "real":
        await db.candidatos_campanas.insert_one({
            "id": str(uuid.uuid4()), "tipo": "bienvenida_cv",
            "enviados": enviados, "fallidos": fallidos, "sin_cupon": sin_cupon,
            "destinatarios": len(destinatarios), "expira_en": ultima_expira,
            "pendientes": pendientes,
            "enviado_en": datetime.now(timezone.utc).isoformat(),
            "enviado_por": user.get("name") or user.get("username") or "",
        })
    return {"ok": True, "modo": modo, "enviados": enviados, "fallidos": fallidos,
            "destinatarios": len(destinatarios), "expira_en": ultima_expira,
            # Lo que queda para la proxima vez. `sin_cuota` es la diferencia
            # entre «no habia a quien mandar» y «hoy ya no salen mas correos».
            "pendientes": pendientes, "sin_cuota": _email_sin_cuota_hoy()}


# -------------------------------------------------------------------------
# TIENDA — CUENTAS DE CLIENTE, APARTE DE LAS DEL TRABAJO
# -------------------------------------------------------------------------
"""Quien compra tiene su propia cuenta, y NO es la del trabajo.

DOS IDENTIDADES SEPARADAS A PROPOSITO:

· La cuenta de TRABAJO (`driver_accounts`) la crea la oficina, va con el correo
  de la empresa y sirve para auditar la furgoneta y pedir dias. Esa no se toca:
  el conductor sigue entrando con ella exactamente igual.
· La cuenta de TIENDA (`tienda_clientes`) la crea la persona, con SU correo de
  verdad y SU contraseña. Sirve para comprar y para recibir el aviso de un
  drop nuevo.

Por que separadas y no un campo mas en la ficha:
 1. El correo del trabajo se lo lee la oficina; el suyo, no. Un justificante de
    compra es cosa suya.
 2. El dia que alguien deja la empresa, su cuenta de trabajo se apaga — y su
    pedido pagado no puede desaparecer con ella.
 3. Y sobre todo: **puede comprar quien no trabaja aqui**. Un amigo, un
    conductor de otro DSP, cualquiera. Con una sola identidad eso seria
    imposible sin darle acceso al portal de la empresa.

El vinculo es opcional (`driver_id`): si la cuenta la crea un conductor desde
su portal, queda enganchada a su ficha y no tiene que volver a identificarse.

EL TOKEN DE TIENDA ES SUYO Y NO SE MEZCLA. Lleva `scope: "tienda"` y se lee con
una dependencia aparte, sin tocar `get_current_user`: un fallo aqui no puede
abrirle a nadie el panel ni el portal del conductor.
"""

_TCOL_CLIENTES = "tienda_clientes"
_TIENDA_CLAVE_MIN = 8
_TIENDA_TOKEN_DIAS = 60


def _tienda_correo(valor) -> str:
    """El correo, normalizado. Sin correo no hay cuenta: es donde va todo."""
    c = _texto_cuerpo(valor, 160).lower()
    if not re.match(r"^[^@\s]+@[^@\s]+\.[a-z]{2,}$", c):
        raise HTTPException(400, "Ese correo no parece válido")
    return c


def _tienda_clave_ok(valor) -> str:
    """La contraseña, con el minimo comprobado EN EL SERVIDOR.

    El navegador ya avisa mientras se escribe, pero eso es una comodidad, no
    una defensa: quien mande la peticion a mano se salta la pantalla entera.
    """
    c = str(valor or "")
    if len(c) < _TIENDA_CLAVE_MIN:
        raise HTTPException(400, "La contraseña necesita al menos %d caracteres"
                            % _TIENDA_CLAVE_MIN)
    if len(c) > 200:
        raise HTTPException(400, "Esa contraseña es demasiado larga")
    return c


def _tienda_token_cliente(cliente: dict, db_name: str) -> str:
    """Token de la tienda. `scope` lo separa de los del panel y del portal."""
    return jwt.encode({
        "sub": cliente["id"], "scope": "tienda", "db_name": db_name,
        "email": cliente.get("email"),
        "exp": datetime.now(timezone.utc) + timedelta(days=_TIENDA_TOKEN_DIAS),
    }, SECRET_KEY, algorithm=JWT_ALGORITHM)


async def _tienda_cliente_del_token(request: Request) -> dict | None:
    """El cliente de tienda del Bearer, o None. NUNCA acepta otro scope."""
    cab = request.headers.get("authorization") or ""
    if not cab.lower().startswith("bearer "):
        return None
    try:
        datos = decode_token(cab[7:]) or {}
    except Exception:                                            # noqa: BLE001
        return None
    if datos.get("scope") != "tienda":
        return None
    # La empresa la fija el token, como en todo endpoint sin sesion de panel
    # (gotcha 26): sin esto caeria en la BD por defecto.
    if datos.get("db_name"):
        set_current_org_db(datos["db_name"])
    return await db[_TCOL_CLIENTES].find_one(
        {"id": datos.get("sub"), "activo": {"$ne": False}}, {"_id": 0, "hashed_password": 0})


def _tienda_cliente_publico(c: dict) -> dict:
    return {"id": c.get("id"), "email": c.get("email"), "nombre": c.get("nombre") or "",
            "es_conductor": bool(c.get("driver_id")), "avisos": bool(c.get("avisos"))}


async def _tienda_crear_cliente(correo: str, clave: str, nombre: str,
                                driver_id: str = "", avisos: bool = True) -> dict:
    """Crea la cuenta. El correo unico lo garantiza el INDICE, no un `find`.

    Comprobarlo antes con una consulta no sirve con dos peticiones a la vez:
    las dos pasan la comprobacion y las dos insertan (gotcha 46).
    """
    doc = {
        "id": str(uuid.uuid4()), "email": correo,
        "hashed_password": hash_password(clave),
        "nombre": _texto_cuerpo(nombre, 80),
        "driver_id": driver_id or None,
        "avisos": bool(avisos), "activo": True,
        "creado_en": datetime.now(timezone.utc).isoformat(),
    }
    try:
        await db[_TCOL_CLIENTES].insert_one(dict(doc))
    except DuplicateKeyError:
        raise HTTPException(409, "Ya hay una cuenta con ese correo. Entra con ella.")
    return doc


@api_router.post("/tienda/cuenta/registro")
async def tienda_registro(body: dict = Body(...), request: Request = None):
    """Cuenta nueva de tienda. PUBLICA: puede comprar quien no trabaja aqui."""
    _rl_public_action("tregistro:%s" % _rl_key_ip(request), max_count=8, window_s=3600,
                      detail="Demasiadas cuentas seguidas. Inténtalo en un rato.")
    await _set_tenant_by_slug(_texto_cuerpo(body.get("slug"), 60))
    correo = _tienda_correo(body.get("email"))
    clave = _tienda_clave_ok(body.get("password"))
    nombre = _texto_cuerpo(body.get("nombre"), 80)
    if len(nombre) < 2:
        raise HTTPException(400, "Escribe tu nombre")
    c = await _tienda_crear_cliente(correo, clave, nombre,
                                    avisos=bool(body.get("avisos", True)))
    return {"token": _tienda_token_cliente(c, _current_db_name.get()),
            "cliente": _tienda_cliente_publico(c)}


@api_router.post("/tienda/cuenta/entrar")
async def tienda_entrar(body: dict = Body(...), request: Request = None):
    """Entrar en la tienda con la cuenta de tienda."""
    correo = _texto_cuerpo(body.get("email"), 160).lower()
    rl = "tentrar:%s" % (correo or _rl_key_ip(request))
    _rl_check(rl)
    await _set_tenant_by_slug(_texto_cuerpo(body.get("slug"), 60))
    c = await db[_TCOL_CLIENTES].find_one({"email": correo, "activo": {"$ne": False}})
    if not c or not verify_password(str(body.get("password") or ""), c["hashed_password"]):
        await _rl_fail(rl, "tienda '%s' (IP %s)" % (correo, _rl_key_ip(request)))
        # La misma espera que en los otros logins: sin ella, el tiempo de
        # respuesta dice si el correo existe.
        await asyncio.sleep(0.8)
        raise HTTPException(401, "Correo o contraseña incorrectos")
    _rl_ok(rl)
    return {"token": _tienda_token_cliente(c, _current_db_name.get()),
            "cliente": _tienda_cliente_publico(c)}


@api_router.post("/tienda/cuenta/vincular")
async def tienda_vincular_cuenta(body: dict = Body(...), user: dict = Depends(require_any_auth)):
    """El conductor se crea SU cuenta de tienda desde el portal, ya identificado.

    No vuelve a entrar en ningun sitio: ya ha demostrado quien es con la cuenta
    del trabajo. Aqui solo dice con que correo suyo quiere que le lleguen las
    cosas y que contraseña quiere para la tienda.
    """
    did = _tienda_driver(user)
    correo = _tienda_correo(body.get("email"))
    clave = _tienda_clave_ok(body.get("password"))
    ya = await db[_TCOL_CLIENTES].find_one({"driver_id": did}, {"_id": 0})
    if ya:
        raise HTTPException(409, "Ya tienes cuenta de tienda con %s" % ya.get("email"))
    ficha = await db.drivers.find_one({"id": did}, {"_id": 0, "name": 1})
    c = await _tienda_crear_cliente(correo, clave, (ficha or {}).get("name") or "",
                                    driver_id=did, avisos=bool(body.get("avisos", True)))
    return {"token": _tienda_token_cliente(c, _current_db_name.get()),
            "cliente": _tienda_cliente_publico(c)}


@api_router.get("/tienda/cuenta")
async def tienda_mi_cuenta(request: Request):
    """Quien soy en la tienda. Vale el token de tienda Y el del conductor."""
    c = await _tienda_cliente_del_token(request)
    if c:
        return {"cliente": _tienda_cliente_publico(c), "via": "tienda"}
    # Si viene del portal, se busca su cuenta por la ficha.
    try:
        user = await get_current_user(request, await _bearer(request))
    except Exception:                                            # noqa: BLE001
        return {"cliente": None}
    if user.get("role") != "driver":
        return {"cliente": None}
    c = await db[_TCOL_CLIENTES].find_one(
        {"driver_id": user.get("sub"), "activo": {"$ne": False}}, {"_id": 0})
    return {"cliente": _tienda_cliente_publico(c) if c else None,
            "via": "conductor" if c else None}


@api_router.post("/tienda/cuenta/avisos")
async def tienda_avisos(body: dict = Body(...), request: Request = None):
    """Activa o quita los avisos de drops nuevos. Lo decide la persona."""
    c = await _tienda_cliente_del_token(request)
    if not c:
        raise HTTPException(401, "Entra en tu cuenta de tienda")
    quiere = bool(body.get("avisos"))
    await db[_TCOL_CLIENTES].update_one({"id": c["id"]}, {"$set": {"avisos": quiere}})
    return {"ok": True, "avisos": quiere}


# -------------------------------------------------------------------------
# TIENDA — LA FOTO DE LA PRENDA
# -------------------------------------------------------------------------
"""La foto real de cada prenda. El dibujo no basta para que alguien pague.

El lienzo vectorial sirve para DECIDIR —donde va el logo, de que tamaño— pero
nadie saca la tarjeta mirando un dibujo de linea. Quien compra tiene que ver
la prenda que le va a llegar.

LA FOTO VA EN SU PROPIA COLECCION, no dentro del documento de la prenda. Con
doce prendas a medio mega, la lista del escaparate pesaria siete megas y se
bajaria entera en cada carga: la lista lleva solo `tiene_foto`, y la imagen se
pide por su URL, que el navegador cachea un año porque cambia de id al
cambiar de foto.
"""

_TCOL_FOTOS = "tienda_fotos"
_FOTO_MAX_BYTES = 900 * 1024
_FOTO_TIPOS = {
    "jpg": "image/jpeg", "jpeg": "image/jpeg",
    "png": "image/png", "webp": "image/webp",
}
# Los primeros bytes de cada formato. La extension la pone quien sube; esto es
# lo que dice de verdad que es: un .exe renombrado a .jpg no pasa de aqui.
_FOTO_FIRMAS = {
    "image/jpeg": [b"\xff\xd8\xff"],
    "image/png": [b"\x89PNG\r\n\x1a\n"],
    "image/webp": [b"RIFF"],
}


def _foto_valida(nombre: str, datos: bytes) -> str:
    ext = (nombre or "").rsplit(".", 1)[-1].lower() if "." in (nombre or "") else ""
    if ext not in _FOTO_TIPOS:
        raise HTTPException(400, "La foto tiene que ser .jpg, .png o .webp")
    if not datos:
        raise HTTPException(400, "El fichero está vacío")
    if len(datos) > _FOTO_MAX_BYTES:
        raise HTTPException(400, "La foto no puede pasar de %d KB (la tuya: %d KB). "
                                 "Redúcela y vuelve a subirla."
                            % (_FOTO_MAX_BYTES // 1024, len(datos) // 1024))
    mime = _FOTO_TIPOS[ext]
    if not any(datos.startswith(f) for f in _FOTO_FIRMAS[mime]):
        raise HTTPException(400, "Ese fichero no es una imagen %s de verdad" % ext)
    return mime


@api_router.post("/tienda/prendas/{prenda_id}/foto")
async def tienda_subir_foto(prenda_id: str, file: UploadFile = File(...),
                            user: dict = Depends(require_admin)):
    """Sube la foto de una prenda. Sustituye la que hubiera."""
    p = await db[_PRENDAS_COL].find_one({"id": prenda_id, "archivada": {"$ne": True}},
                                        {"_id": 0, "id": 1})
    if not p:
        raise HTTPException(404, "Esa prenda no existe")
    datos = await file.read()
    mime = _foto_valida(file.filename or "", datos)
    # `ver` cambia con cada foto y viaja en la URL: asi el navegador puede
    # cachearla un año y aun asi ver la nueva al instante.
    ver = uuid.uuid4().hex[:8]
    await db[_TCOL_FOTOS].update_one(
        {"prenda": prenda_id},
        {"$set": {"prenda": prenda_id, "mime": mime,
                  "datos": base64.b64encode(datos).decode("ascii"),
                  "bytes": len(datos), "ver": ver,
                  "at": datetime.now(timezone.utc).isoformat(),
                  "por": user.get("name") or user.get("username") or ""}},
        upsert=True)
    await db[_PRENDAS_COL].update_one({"id": prenda_id}, {"$set": {"foto_ver": ver}})
    return {"ok": True, "foto_ver": ver}


@api_router.delete("/tienda/prendas/{prenda_id}/foto")
async def tienda_borrar_foto(prenda_id: str, _=Depends(require_admin)):
    await db[_TCOL_FOTOS].delete_one({"prenda": prenda_id})
    await db[_PRENDAS_COL].update_one({"id": prenda_id}, {"$unset": {"foto_ver": ""}})
    return {"ok": True}


@api_router.get("/tienda/prendas/{prenda_id}/foto")
async def tienda_ver_foto(prenda_id: str, user: dict = Depends(require_any_auth)):
    """La foto. La ve quien tiene sesion —oficina o conductor—, no el mundo."""
    f = await db[_TCOL_FOTOS].find_one({"prenda": prenda_id}, {"_id": 0})
    if not f:
        raise HTTPException(404, "Esa prenda no tiene foto")
    from fastapi.responses import Response as _Resp
    return _Resp(
        content=base64.b64decode(f.get("datos") or ""),
        media_type=f.get("mime") or "image/jpeg",
        # Un año: la URL lleva la version dentro, asi que una foto nueva es
        # otra URL y no hay que invalidar nada.
        headers={"cache-control": "private, max-age=31536000, immutable"},
    )


