# Lo que NO es un gasto aunque salga en el extracto: es dinero que ENTRA. Si se
# cuela, el mes sale inflado por lo que cobras de Amazon, que es justo al revés.
_GASTO_INGRESOS = [
    "amazon logistics", "amazon eu", "amazon road", "amazon spain fulfillment",
    "transferencia recibida", "transf recibida", "abono", "ingreso ", "bizum recibido",
    "devolucion", "liquidacion a favor", "traspaso recibido",
]

# Umbrales, con su porqué escrito al lado:
_GASTO_FIJO_MESES = 2       # con un mes suelto no se puede decir que algo sea fijo
_GASTO_SALTO_MIN = 3        # para decir «te han cobrado de más» hacen falta 3 medidas
_GASTO_SALTO_PCT = 0.30     # y un salto del 30 % sobre lo habitual
_GASTO_MAX_PEGADO = 500     # líneas de un pegado: más que eso es un fichero


def _gasto_quien_es(texto: str, aprendidos: dict = None) -> dict:
    """Qué es ese cargo: {proveedor, categoria, que_es, fuente}.

    Primero lo APRENDIDO (lo que Dani haya enseñado alguna vez), que manda
    sobre el catálogo: es su empresa y su taller de siempre puede llamarse
    igual que una cadena. Después el catálogo. Y si nada encaja, se dice —
    `categoria: "otros"` y `que_es: ""`— en vez de adivinar: una factura
    colgada de la categoría que no es no se nota nunca, y de eso van los
    gotchas 6 y 60. La cifra sigue contando en el total; solo se queda sin
    etiqueta, que es lo honesto.

    Cuando encaja más de una clave gana la MÁS LARGA: «amazon business» es
    material y «amazon logistics» es un ingreso, y con la más corta ganaría
    siempre la primera del catálogo, que es orden de escritura y no evidencia.
    """
    n = _gasto_norm(texto)
    if not n:
        return {"proveedor": "", "categoria": "otros", "que_es": "", "fuente": ""}

    # 1) Lo aprendido, que manda.
    mejor_ap, largo_ap = None, 0
    for clave, doc in (aprendidos or {}).items():
        if clave and clave in n and len(clave) > largo_ap:
            mejor_ap, largo_ap = doc, len(clave)
    if mejor_ap:
        return {"proveedor": mejor_ap.get("proveedor") or "",
                "categoria": mejor_ap.get("categoria") if mejor_ap.get("categoria") in _GASTO_CAT_CLAVES else "otros",
                "que_es": mejor_ap.get("que_es") or "",
                "fuente": "aprendido"}

    # 2) El catálogo.
    mejor, largo = None, 0
    for claves, nombre, categoria, que_es in _GASTO_CATALOGO:
        for c in claves:
            if len(c) <= largo:
                continue
            # Una clave corta exige palabra entera: 'itv' dentro de 'activa' no
            # es una inspección técnica. Un checker que grita en falso deja de
            # leerse, y esta pantalla es exactamente igual.
            casa = re.search(r"\b%s\b" % re.escape(c), n) if len(c) <= 4 else (c in n)
            if casa:
                mejor, largo = (nombre, categoria, que_es), len(c)
    if mejor:
        return {"proveedor": mejor[0], "categoria": mejor[1], "que_es": mejor[2], "fuente": "catalogo"}
    return {"proveedor": "", "categoria": "otros", "que_es": "", "fuente": ""}


def _gasto_es_ingreso(texto: str) -> bool:
    """¿Es dinero que ENTRA? Lo que cobras de tus clientes no es un gasto."""
    n = _gasto_norm(texto)
    return any(p.strip() in n for p in _GASTO_INGRESOS)


def _gasto_importe(texto: str):
    """El importe de una linea, en euros y siempre positivo, o None.

    Aguanta las dos formas de escribir un numero —1.234,56 y 1,234.56— y el
    signo: en un extracto los gastos vienen en negativo, y aqui se guardan
    positivos porque la pantalla ya sabe que son gastos. Se queda con el
    ULTIMO numero con decimales, que es donde ponen el importe tanto el banco
    como cualquier factura; el primero suele ser un numero de factura.

    El numero se coge ENTERO y se interpreta despues. La primera version lo
    hacia al reves —una alternativa del propio patron por cada forma— y como
    las alternativas se prueban en orden, «57.30» casaba con la de miles y se
    quedaba en **57**. Un importe mal leido no falla: sale otro numero y
    parece medido, que es justo el fallo que esta pantalla no puede tener.
    """
    if not texto:
        return None
    # Un numero pegado: digitos con separadores dentro. El espacio solo cuenta
    # como separador de miles si detras van EXACTAMENTE tres cifras; si no,
    # «REPSOL 4 57,30» se leeria como un solo numero de 457,30.
    patron = re.compile(r"(?<![\w.,])([-+]?\d+(?:[.,]\d+|\s\d{3}(?!\d))*)")
    candidatos = []
    for m in patron.finditer(texto):
        limpio = m.group(1).replace(" ", "")
        decimales = False
        if "," in limpio and "." in limpio:
            # Manda el ULTIMO separador: el otro es el de los miles.
            dec = "," if limpio.rfind(",") > limpio.rfind(".") else "."
            mil = "." if dec == "," else ","
            limpio, decimales = limpio.replace(mil, "").replace(dec, "."), True
        else:
            sep = "," if "," in limpio else ("." if "." in limpio else "")
            if sep:
                trozos = limpio.split(sep)
                # Una sola vez y una o dos cifras detras: son decimales.
                # Tres cifras es el separador de miles («1.234» son mil
                # doscientos treinta y cuatro, no uno con doscientos).
                if len(trozos) == 2 and 1 <= len(trozos[1]) <= 2:
                    limpio, decimales = limpio.replace(sep, "."), True
                else:
                    limpio = limpio.replace(sep, "")
        try:
            v = float(limpio)
        except ValueError:
            continue
        if v == 0 or abs(v) > 1_000_000:
            continue
        candidatos.append((v, decimales))
    if not candidatos:
        return None
    con_dec = [c for c in candidatos if c[1]]
    return round(abs((con_dec or candidatos)[-1][0]), 2)


_GASTO_MESES_TXT = {
    "ene": 1, "feb": 2, "mar": 3, "abr": 4, "may": 5, "jun": 6,
    "jul": 7, "ago": 8, "sep": 9, "set": 9, "oct": 10, "nov": 11, "dic": 12,
}


def _gasto_fecha(texto: str, hoy: str = None):
    """La fecha de una línea como 'YYYY-MM-DD', o None.

    Acepta 20/09/2026, 20-09-26, 2026-09-20 y «20 sep». El año de dos cifras
    se completa con el siglo actual, y una fecha sin año se queda en el año de
    hoy salvo que eso la deje en el futuro —un extracto de enero con «28 dic»
    es del año pasado—. Eso es una regla, no una adivinanza: una fecha futura
    en un gasto ya pagado no existe.
    """
    if not texto:
        return None
    hoy = hoy or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    anio_hoy = int(hoy[:4])

    m = re.search(r"(?<!\d)(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?!\d)", texto)
    if m:
        a, mes, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    else:
        m = re.search(r"(?<!\d)(\d{1,2})[-/.](\d{1,2})(?:[-/.](\d{2,4}))?(?!\d)", texto)
        if m:
            d, mes = int(m.group(1)), int(m.group(2))
            a = int(m.group(3)) if m.group(3) else anio_hoy
            if a < 100:
                a += 2000
        else:
            m = re.search(r"(?<!\d)(\d{1,2})\s*(?:de\s+)?([a-záéíóú]{3,10})\.?\s*(?:de\s+)?(\d{4})?", texto, re.I)
            if not m:
                return None
            mes = _GASTO_MESES_TXT.get(_gasto_norm(m.group(2))[:3])
            if not mes:
                return None
            d = int(m.group(1))
            a = int(m.group(3)) if m.group(3) else anio_hoy
    if not (1 <= mes <= 12 and 1 <= d <= 31) or not (2015 <= a <= anio_hoy + 1):
        return None
    try:
        f = datetime(a, mes, d).strftime("%Y-%m-%d")
    except ValueError:
        return None
    # Sin año explícito y en el futuro: es del año pasado.
    if f > hoy and not re.search(r"\d{4}", texto):
        try:
            f = datetime(a - 1, mes, d).strftime("%Y-%m-%d")
        except ValueError:
            return None
    return f


# La fecha de una linea, para quitarla. Vive suelta porque la usan los dos:
# el que lee el concepto y el que lee el importe (que si no leeria el ano).
_GASTO_SIN_FECHA = re.compile(r"(?<!\d)\d{1,4}[-/.]\d{1,2}(?:[-/.]\d{2,4})?(?!\d)")


def _gasto_concepto(linea: str) -> str:
    """El texto de la línea sin la fecha ni el importe: lo que dice QUÉ es."""
    s = _GASTO_SIN_FECHA.sub(" ", linea or "")
    s = re.sub(r"[-+]?\d[\d.,\s]*\d?\s*(?:€|eur\b)?", " ", s, flags=re.I)
    s = re.sub(r"[;|\t]+", " ", s)
    return re.sub(r"\s+", " ", s).strip(" .-·")[:200]


def _gasto_huella(fecha: str, proveedor: str, importe) -> str:
    """Clave para reconocer lo ya apuntado: mismo día, mismo sitio, mismo importe.

    Solo AVISA, nunca bloquea: dos repostajes iguales el mismo día existen, y
    un índice único aquí perdería el segundo en silencio, que es peor que un
    duplicado a la vista (gotcha 6: no adivinar cuando no hay certeza).
    """
    return "%s|%s|%.2f" % (fecha or "", _gasto_norm(proveedor)[:40], float(importe or 0))


def _gasto_analizar(texto: str, aprendidos: dict = None, hoy: str = None) -> list:
    """Convierte lo pegado —extracto del banco, lista de facturas, Excel— en
    filas propuestas. NO guarda nada: esto solo propone, y confirma una persona.

    Cada fila lleva por qué se ha clasificado así, para poder discutirla:
    `fuente` dice si salió del catálogo, de lo aprendido o de nada.

    El signo se usa solo si el pegado lo tiene: en un extracto los gastos van
    en negativo y lo positivo es un ingreso, pero una lista de facturas no
    lleva signos y ahí todo es gasto. Se mira el pegado ENTERO antes de decidir
    —es la diferencia entre medir y suponer—.
    """
    lineas = [l for l in (texto or "").replace("\r", "").split("\n")][:_GASTO_MAX_PEGADO]
    crudas = []
    for l in lineas:
        if not l.strip() or len(l.strip()) < 4:
            continue
        imp_firmado = None
        m = re.search(r"([-+]?\d[\d.,\s]*)\s*(?:€|eur)?\s*$", l.strip(), re.I)
        if m and m.group(1).strip().startswith("-"):
            imp_firmado = -1
        crudas.append((l, imp_firmado))
    hay_signos = any(s == -1 for _, s in crudas)

    filas = []
    for l, signo in crudas:
        # La fecha fuera ANTES de buscar el importe: en «20/09/2026 APUNTE SIN
        # IMPORTE» el ultimo numero es 2026, y esa linea entraria como un gasto
        # de dos mil veintiseis euros sin que nada fallara.
        importe = _gasto_importe(_GASTO_SIN_FECHA.sub(" ", l))
        if importe is None:
            continue
        concepto = _gasto_concepto(l)
        if not concepto:
            continue
        quien = _gasto_quien_es(concepto, aprendidos)
        # Un ingreso: o lo dice el texto, o lo dice el signo cuando el pegado
        # trae signos de verdad.
        ingreso = _gasto_es_ingreso(concepto) or (hay_signos and signo is None)
        filas.append({
            "fecha": _gasto_fecha(l, hoy) or "",
            "concepto": concepto,
            "importe": importe,
            "proveedor": quien["proveedor"] or concepto[:40],
            "categoria": quien["categoria"],
            "que_es": quien["que_es"],
            "fuente": quien["fuente"],
            "reconocido": bool(quien["fuente"]),
            "ingreso": ingreso,
            "linea": l.strip()[:300],
        })
    return filas


def _gasto_mes(fecha: str) -> str:
    return (fecha or "")[:7]


def _gasto_fijos(gastos: list, mes_actual: str) -> list:
    """Lo que sale TODOS los meses, con la prueba de cuántos meses se ha visto.

    Un proveedor es «fijo» si aparece en `_GASTO_FIJO_MESES` meses distintos.
    Nunca se dice «todos los meses» con dos apuntes: se dice «visto en N de los
    últimos M», que es lo que se ha medido de verdad (gotcha 65: una prueba
    solo vale dentro de lo que ha mirado).

    El importe típico es la MEDIANA, no la media: una factura anual de golpe
    —el dominio, la ITV— dispara la media y dejaría de parecerse a lo que se
    paga cada mes.
    """
    por_prov = {}
    for g in gastos:
        clave = _gasto_norm(g.get("proveedor")) or "?"
        por_prov.setdefault(clave, []).append(g)

    fijos = []
    for clave, lista in por_prov.items():
        meses = sorted({_gasto_mes(g.get("fecha")) for g in lista if g.get("fecha")})
        if len(meses) < _GASTO_FIJO_MESES:
            continue
        importes = sorted(float(g.get("importe") or 0) for g in lista)
        n = len(importes)
        mediana = importes[n // 2] if n % 2 else round((importes[n // 2 - 1] + importes[n // 2]) / 2, 2)
        ultimo = max(meses)
        de_este_mes = [g for g in lista if _gasto_mes(g.get("fecha")) == mes_actual]
        importe_mes = round(sum(float(g.get("importe") or 0) for g in de_este_mes), 2) if de_este_mes else None
        # ¿Se ha disparado? Hace falta base suficiente: con dos medidas, la
        # segunda siempre «se desvía» de la primera (gotcha 31).
        salto = None
        if importe_mes is not None and n >= _GASTO_SALTO_MIN and mediana > 0:
            dif = (importe_mes - mediana) / mediana
            if abs(dif) >= _GASTO_SALTO_PCT:
                salto = round(dif * 100)
        fijos.append({
            "proveedor": lista[-1].get("proveedor") or clave,
            "categoria": lista[-1].get("categoria") or "otros",
            "que_es": next((g.get("que_es") for g in reversed(lista) if g.get("que_es")), ""),
            "meses": len(meses),
            "veces": n,
            "tipico": round(mediana, 2),
            "ultimo_mes": ultimo,
            "importe_mes": importe_mes,
            "falta_este_mes": importe_mes is None and ultimo < mes_actual,
            "salto_pct": salto,
        })
    # Desempate determinista (gotcha 62): a igual gasto manda el nombre.
    fijos.sort(key=lambda f: (-(f["tipico"] * f["meses"]), f["proveedor"]))
    return fijos


def _gasto_resumen(gastos: list, meses: int, hoy: str, n_furgos: int) -> dict:
    """Los números de la pantalla, todos de la MISMA lista.

    Que salgan del mismo sitio no es cosmético: un total calculado aparte del
    desglose acaba diciendo otra cosa y nadie sabe cuál de los dos creer
    (gotcha 40). Aquí el total es la suma de los cajones, y se comprueba.
    """
    mes_actual = hoy[:7]
    # Los últimos N meses en orden, incluido el actual aunque esté vacío: un
    # hueco en la serie es información («ese mes no pagaste luz»).
    serie = []
    a, m = int(hoy[:4]), int(hoy[5:7])
    for _ in range(meses):
        serie.append("%04d-%02d" % (a, m))
        m -= 1
        if m == 0:
            a, m = a - 1, 12
    serie.reverse()

    por_mes = {k: 0.0 for k in serie}
    por_cat = {}
    por_prov = {}
    # Por furgoneta: es la pregunta que se hace un dueno de flota —«cual me
    # esta costando dinero»— y el dato ya esta, porque las ordenes de taller
    # entran con su matricula. Solo cuenta lo que la LLEVA: un gasto de
    # software repartido entre furgonetas no significa nada (gotcha 31).
    por_furgo = {}
    por_mes_cat = {k: {} for k in serie}
    sin_clasificar = 0.0
    total = 0.0
    for g in gastos:
        imp = float(g.get("importe") or 0)
        mes = _gasto_mes(g.get("fecha"))
        cat = g.get("categoria") if g.get("categoria") in _GASTO_CAT_CLAVES else "otros"
        # Solo lo que cae DENTRO de los meses que se ensenan. Si el total
        # contara algo que el grafico no pinta, los dos numeros de la misma
        # pantalla dirian cosas distintas y no habria forma de saber cual creer.
        if mes not in por_mes:
            continue
        total += imp
        por_cat[cat] = round(por_cat.get(cat, 0) + imp, 2)
        por_mes[mes] = round(por_mes[mes] + imp, 2)
        por_mes_cat[mes][cat] = round(por_mes_cat[mes].get(cat, 0) + imp, 2)
        mat = _texto_cuerpo(g.get("matricula"), 15).upper()
        if mat:
            f = por_furgo.setdefault(mat, {"matricula": mat, "importe": 0.0, "veces": 0,
                                           "ultimo": "", "que": ""})
            f["importe"] = round(f["importe"] + imp, 2)
            f["veces"] += 1
            if (g.get("fecha") or "") >= f["ultimo"]:
                f["ultimo"] = g.get("fecha") or ""
                f["que"] = (g.get("concepto") or g.get("proveedor") or "")[:60]
        prov = g.get("proveedor") or "(sin nombre)"
        p = por_prov.setdefault(prov, {"proveedor": prov, "categoria": cat, "importe": 0.0,
                                       "veces": 0, "que_es": g.get("que_es") or "",
                                       "ultimo": ""})
        p["importe"] = round(p["importe"] + imp, 2)
        p["veces"] += 1
        p["ultimo"] = max(p["ultimo"], g.get("fecha") or "")
        if not g.get("que_es") and cat == "otros":
            sin_clasificar += imp

    este = round(por_mes.get(mes_actual, 0), 2)
    anterior = round(por_mes.get(serie[-2], 0), 2) if len(serie) > 1 else 0
    # La media se calcula sobre los meses CON algo, no sobre los N del rango:
    # tres meses de uso y doce de rango darían una media a la cuarta parte de
    # lo real, y con ese número se decide algo.
    con_datos = [v for k, v in por_mes.items() if v > 0 and k != mes_actual]
    media = round(sum(con_datos) / len(con_datos), 2) if con_datos else 0

    cats = []
    for c in GASTO_CATEGORIAS:
        imp = round(por_cat.get(c["clave"], 0), 2)
        if imp <= 0:
            continue
        cats.append({**c, "importe": imp,
                     "pct": round(imp * 100 / total, 1) if total > 0 else 0,
                     # Por furgoneta solo donde significa algo, y solo si hay
                     # furgonetas de verdad que contar.
                     "por_furgo_eur": round(imp / n_furgos, 2) if c["por_furgo"] and n_furgos else None})
    cats.sort(key=lambda c: (-c["importe"], c["nombre"]))

    provs = sorted(por_prov.values(), key=lambda p: (-p["importe"], p["proveedor"]))
    # Desempate por matricula: a igual gasto, siempre el mismo orden (gotcha 62).
    furgos = sorted(por_furgo.values(), key=lambda f: (-f["importe"], f["matricula"]))

    return {
        "meses": [{"mes": k, "importe": por_mes[k], "cats": por_mes_cat[k]} for k in serie],
        "mes_actual": mes_actual,
        "este_mes": este,
        "mes_anterior": anterior,
        "media_mensual": media,
        "meses_con_datos": len(con_datos) + (1 if este > 0 else 0),
        "total": round(total, 2),
        # La suma de los cajones TIENE que dar el total (gotcha 30). Si no da,
        # se dice en vez de enseñar dos números que no cuadran.
        "cuadra": abs(round(sum(c["importe"] for c in cats), 2) - round(total, 2)) < 0.02,
        "categorias": cats,
        "proveedores": provs,
        "vehiculos": furgos,
        "sin_clasificar": round(sin_clasificar, 2),
        "furgonetas": n_furgos,
        "fijos": _gasto_fijos(gastos, mes_actual),
    }


async def _gasto_aprendidos() -> dict:
    """Lo que Dani ha enseñado: {clave normalizada: {proveedor, categoria, que_es}}."""
    salida = {}
    try:
        async for d in db.gastos_proveedores.find({}, {"_id": 0}):
            clave = _gasto_norm(d.get("clave"))
            if clave:
                salida[clave] = d
    except Exception as e:                                        # noqa: BLE001
        logger.warning("gastos: no se pudieron leer los proveedores aprendidos: %s", e)
    return salida


async def _gasto_n_furgonetas() -> int:
    """Furgonetas que de verdad cuentan: ni borradas ni de baja (gotcha 13)."""
    try:
        return await db.vehicles.count_documents({"status": {"$nin": ["deleted", "baja"]}})
    except Exception:                                             # noqa: BLE001
        return 0


def _gasto_publico(g: dict) -> dict:
    """Lo que sale a la pantalla. Lista blanca: `_id` de Mongo no se serializa."""
    return {
        "id": g.get("id"), "fecha": g.get("fecha") or "", "proveedor": g.get("proveedor") or "",
        "concepto": g.get("concepto") or "", "importe": round(float(g.get("importe") or 0), 2),
        "categoria": g.get("categoria") or "otros", "que_es": g.get("que_es") or "",
        "nota": g.get("nota") or "", "matricula": g.get("matricula") or "",
        "origen": g.get("origen") or "manual", "ref": g.get("ref") or "",
        "creado_en": g.get("creado_en") or "",
        # Lo que llega por el buzon trae tres cosas mas que hay que ENSENAR, no
        # esconder: el PDF (que es lo que de verdad contesta «de que es esto»),
        # la moneda de origen con su cambio —57 dolares no son 57 euros— y si
        # no se ha sabido leer el total, que es una factura que hay que mirar.
        "adjunto": g.get("adjunto") or None,
        "moneda": g.get("moneda") or "EUR",
        "importe_original": g.get("importe_original"),
        "cambio": g.get("cambio"), "cambio_dia": g.get("cambio_dia") or "",
        "revisar": bool(g.get("revisar")),
        "de": g.get("de") or "",
    }


def _gasto_valida(data: dict, hoy: str) -> dict:
    """Los campos de un gasto, validados. Lanza 400 con un mensaje útil."""
    fecha = _texto_cuerpo(data.get("fecha"), 10)
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", fecha):
        fecha = _gasto_fecha(fecha, hoy) or ""
    if not fecha:
        raise HTTPException(400, "Pon la fecha de la factura (día/mes/año)")
    if fecha > hoy:
        raise HTTPException(400, "Esa fecha es del futuro: revísala")
    importe = _gasto_importe(_texto_cuerpo(data.get("importe"), 20))
    if importe is None or importe <= 0:
        raise HTTPException(400, "Pon el importe en euros (por ejemplo 57,30)")
    proveedor = _texto_cuerpo(data.get("proveedor"), 80)
    if not proveedor:
        raise HTTPException(400, "Pon de quién es la factura")
    categoria = _texto_cuerpo(data.get("categoria"), 20)
    if categoria not in _GASTO_CAT_CLAVES:
        categoria = "otros"
    return {
        "fecha": fecha, "importe": importe, "proveedor": proveedor, "categoria": categoria,
        "concepto": _texto_cuerpo(data.get("concepto"), 200),
        "nota": _texto_cuerpo(data.get("nota"), 400),
        "matricula": _texto_cuerpo(data.get("matricula"), 15).upper(),
    }


@api_router.get("/gastos")
async def gastos_listar(meses: int = 12, categoria: str = "", q: str = "",
                        _: dict = Depends(require_superadmin)):
    """Todo lo apuntado más los números de la pantalla.

    El filtro por categoría y por texto se aplica a la LISTA, no al resumen: si
    filtrando por «software» los totales de arriba bajaran también, cualquiera
    leería ese número como «el gasto del mes», que es justo lo que no es.
    """
    meses = max(1, min(int(meses or 12), 36))
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    desde = (datetime.now(timezone.utc) - timedelta(days=31 * meses + 5)).strftime("%Y-%m-%d")
    todos = await db.gastos.find({"fecha": {"$gte": desde}}, {"_id": 0}).sort("fecha", -1).to_list(5000)
    lista = [_gasto_publico(g) for g in todos]

    filtrada = lista
    cat = _gasto_norm(categoria)
    if cat and cat in _GASTO_CAT_CLAVES:
        filtrada = [g for g in filtrada if g["categoria"] == cat]
    busca = _gasto_norm(q)
    if busca:
        filtrada = [g for g in filtrada
                    if busca in _gasto_norm(g["proveedor"] + " " + g["concepto"] + " "
                                            + g["nota"] + " " + g["matricula"])]

    resumen = _gasto_resumen(lista, meses, hoy, await _gasto_n_furgonetas())
    # Los que no se han sabido clasificar, para poder enseñárselos a la app una
    # vez y no volver a preguntarlos nunca más.
    por_saber = {}
    for g in lista:
        if g["categoria"] == "otros" and not g["que_es"]:
            k = _gasto_norm(g["proveedor"])
            p = por_saber.setdefault(k, {"proveedor": g["proveedor"], "importe": 0.0, "veces": 0})
            p["importe"] = round(p["importe"] + g["importe"], 2)
            p["veces"] += 1
    return {"gastos": filtrada, "total_apuntados": len(lista), "resumen": resumen,
            "categorias": GASTO_CATEGORIAS,
            "por_saber": sorted(por_saber.values(), key=lambda p: (-p["importe"], p["proveedor"]))[:20],
            "hoy": hoy}


@api_router.post("/gastos")
async def gastos_crear(data: dict = Body(...), user: dict = Depends(require_superadmin)):
    """Apunta una factura."""
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    campos = _gasto_valida(data, hoy)
    quien = _gasto_quien_es(campos["proveedor"] + " " + campos["concepto"], await _gasto_aprendidos())
    if _texto_cuerpo(data.get("categoria"), 20) not in _GASTO_CAT_CLAVES:
        campos["categoria"] = quien["categoria"]

    ahora = datetime.now(timezone.utc)
    huella = _gasto_huella(campos["fecha"], campos["proveedor"], campos["importe"])
    # Dos clics seguidos son UNA factura, no dos (gotcha 46). No se pone índice
    # único: dos repostajes idénticos el mismo día existen de verdad, y perder
    # el segundo en silencio sería peor que el duplicado que se ve y se borra.
    repe = await db.gastos.find_one(
        {"huella": huella, "creado_en": {"$gte": (ahora - timedelta(seconds=90)).isoformat()}},
        {"_id": 0})
    if repe:
        return {"ok": True, "gasto": _gasto_publico(repe), "ya_estaba": True}

    doc = {**campos, "id": str(uuid.uuid4()), "huella": huella,
           "que_es": quien["que_es"], "origen": "manual", "ref": "",
           "creado_en": ahora.isoformat(), "creado_por": (user or {}).get("name") or ""}
    await db.gastos.insert_one(dict(doc))          # copia: insert_one muta (gotcha 42)
    return {"ok": True, "gasto": _gasto_publico(doc)}


@api_router.patch("/gastos/{gid}")
async def gastos_editar(gid: str, data: dict = Body(...), _: dict = Depends(require_superadmin)):
    """Corrige una factura ya apuntada."""
    actual = await db.gastos.find_one({"id": gid}, {"_id": 0})
    if not actual:
        raise HTTPException(404, "Ese gasto ya no está")
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    campos = _gasto_valida({**actual, **{k: v for k, v in data.items() if v is not None}}, hoy)
    campos["huella"] = _gasto_huella(campos["fecha"], campos["proveedor"], campos["importe"])
    if _texto_cuerpo(data.get("que_es"), 300):
        campos["que_es"] = _texto_cuerpo(data.get("que_es"), 300)
    await db.gastos.update_one({"id": gid}, {"$set": campos})
    return {"ok": True, "gasto": _gasto_publico({**actual, **campos})}


@api_router.delete("/gastos/{gid}")
async def gastos_borrar(gid: str, user: dict = Depends(require_superadmin)):
    """Borra UNA factura. Nunca un `delete_many` (gotcha 45)."""
    g = await db.gastos.find_one({"id": gid}, {"_id": 0})
    if not g:
        raise HTTPException(404, "Ese gasto ya no está")
    await db.gastos.delete_one({"id": gid})
    await _audit(user, "gasto_borrado", {"id": gid, "proveedor": g.get("proveedor"),
                                         "importe": g.get("importe"), "fecha": g.get("fecha")})
    return {"ok": True}


@api_router.post("/gastos/analizar")
async def gastos_analizar(data: dict = Body(...), _: dict = Depends(require_superadmin)):
    """Lee lo pegado y PROPONE. No guarda nada.

    Se separa de guardar a propósito: lo que sale de aquí hay que mirarlo —una
    línea mal partida es un importe mal leído— y un importador que guarda a
    ciegas es justo el que nadie vuelve a usar después del primer susto.
    """
    texto = _texto_cuerpo(data.get("texto"), 200_000)
    if len(texto) < 4:
        raise HTTPException(400, "Pega aquí las líneas del banco o la lista de facturas")
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    filas = _gasto_analizar(texto, await _gasto_aprendidos(), hoy)
    if not filas:
        return {"filas": [], "aviso": "No he encontrado ninguna línea con fecha e importe. "
                                      "Pega una línea por factura, con el importe al final."}
    # ¿Ya está apuntado? Solo se avisa; decide una persona.
    huellas = set()
    async for g in db.gastos.find({}, {"_id": 0, "huella": 1}):
        if g.get("huella"):
            huellas.add(g["huella"])
    for f in filas:
        f["repetido"] = _gasto_huella(f["fecha"], f["proveedor"], f["importe"]) in huellas
        # Lo que entra marcado por defecto: gasto, con fecha, sin repetir.
        f["marcada"] = bool(f["fecha"]) and not f["ingreso"] and not f["repetido"]
    return {
        "filas": filas,
        "resumen": {
            "lineas": len(filas),
            "gastos": sum(1 for f in filas if not f["ingreso"]),
            "ingresos": sum(1 for f in filas if f["ingreso"]),
            "repetidos": sum(1 for f in filas if f["repetido"]),
            "sin_reconocer": sum(1 for f in filas if not f["reconocido"] and not f["ingreso"]),
            "suma": round(sum(f["importe"] for f in filas if f["marcada"]), 2),
        },
        "categorias": GASTO_CATEGORIAS,
    }


@api_router.post("/gastos/importar")
async def gastos_importar(data: dict = Body(...), user: dict = Depends(require_superadmin)):
    """Guarda las filas que se hayan marcado en la vista previa."""
    filas = data.get("filas")
    if not isinstance(filas, list) or not filas:
        raise HTTPException(400, "No has marcado ninguna línea")
    if len(filas) > _GASTO_MAX_PEGADO:
        raise HTTPException(400, "Demasiadas líneas de golpe: hazlo por partes")
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    ahora = datetime.now(timezone.utc).isoformat()
    nuevos, malas = [], []
    for i, f in enumerate(filas):
        f = _dict_cuerpo(f)
        try:
            campos = _gasto_valida(f, hoy)
        except HTTPException as e:
            malas.append({"linea": i + 1, "por_que": str(e.detail)})
            continue
        nuevos.append({**campos, "id": str(uuid.uuid4()),
                       "huella": _gasto_huella(campos["fecha"], campos["proveedor"], campos["importe"]),
                       "que_es": _texto_cuerpo(f.get("que_es"), 300),
                       "origen": "pegado", "ref": "",
                       "creado_en": ahora, "creado_por": (user or {}).get("name") or ""})
    if nuevos:
        # `ordered=False`: una fila rara no puede tirar las otras 39.
        await db.gastos.insert_many([dict(d) for d in nuevos], ordered=False)
    return {"ok": True, "guardados": len(nuevos), "malas": malas,
            "suma": round(sum(d["importe"] for d in nuevos), 2)}


@api_router.post("/gastos/proveedor")
async def gastos_ensenar(data: dict = Body(...), user: dict = Depends(require_superadmin)):
    """Enseñarle qué es un proveedor que no reconoce. Se aprende para siempre.

    Y se aplica HACIA ATRÁS a lo ya apuntado: si no, la pantalla sigue diciendo
    «no sé qué es esto» de algo que acabas de explicarle, que es la forma más
    rápida de que alguien deje de corregirla.
    """
    clave = _gasto_norm(data.get("clave") or data.get("proveedor"))
    if len(clave) < 3:
        raise HTTPException(400, "Escribe al menos tres letras del nombre que pone en la factura")
    categoria = _texto_cuerpo(data.get("categoria"), 20)
    if categoria not in _GASTO_CAT_CLAVES:
        raise HTTPException(400, "Elige a qué categoría pertenece")
    doc = {"clave": clave,
           "proveedor": _texto_cuerpo(data.get("proveedor"), 80) or clave,
           "categoria": categoria,
           "que_es": _texto_cuerpo(data.get("que_es"), 300),
           "creado_en": datetime.now(timezone.utc).isoformat(),
           "creado_por": (user or {}).get("name") or ""}
    await db.gastos_proveedores.update_one({"clave": clave}, {"$set": doc}, upsert=True)

    tocados = 0
    async for g in db.gastos.find({}, {"_id": 0, "id": 1, "proveedor": 1, "concepto": 1, "categoria": 1}):
        if clave in _gasto_norm((g.get("proveedor") or "") + " " + (g.get("concepto") or "")):
            await db.gastos.update_one({"id": g["id"]}, {"$set": {
                "categoria": doc["categoria"], "que_es": doc["que_es"],
                "proveedor": doc["proveedor"]}})
            tocados += 1
    return {"ok": True, "aprendido": doc["proveedor"], "arreglados": tocados}


@api_router.post("/gastos/taller")
async def gastos_desde_taller(_: dict = Depends(require_superadmin)):
    """Trae los importes que ya están en las órdenes de taller.

    Es dinero real que la app ya conoce y que nadie va a volver a teclear. Se
    trae solo el importe FINAL —lo que se pagó—, nunca el presupuesto: un
    presupuesto no es un gasto, y contarlo inflaría el mes con algo que puede
    no llegar a hacerse.

    Es idempotente por construcción: el `id` del gasto es `ot:<orden>`, así que
    darle mil veces al botón no puede duplicar nada (la lección del gotcha 32).
    """
    ahora = datetime.now(timezone.utc).isoformat()
    nuevos = actualizados = 0
    async for o in db.ordenes_trabajo.find(
            {"importe_final": {"$ne": None}},
            {"_id": 0, "id": 1, "numero": 1, "matricula": 1, "taller_nombre": 1,
             "importe_final": 1, "fecha_entrega_real": 1, "fecha_entrada": 1, "problema": 1}):
        imp = _ot_importe(o.get("importe_final"))
        if imp is None or imp <= 0:
            continue
        fecha = (o.get("fecha_entrega_real") or o.get("fecha_entrada") or ahora)[:10]
        gid = "ot:%s" % o.get("id")
        campos = {
            "fecha": fecha, "importe": imp,
            "proveedor": o.get("taller_nombre") or "Taller",
            "concepto": "%s · %s" % (o.get("numero") or "OT", (o.get("problema") or "")[:80]),
            "categoria": "taller",
            "que_es": "Reparación de una furgoneta. Sale de la orden de taller, no hay que apuntarla a mano.",
            "matricula": o.get("matricula") or "", "nota": "",
            "origen": "taller", "ref": o.get("id") or "",
            "huella": _gasto_huella(fecha, o.get("taller_nombre") or "Taller", imp),
        }
        # El `id` NO va en el $setOnInsert: ya lo pone el filtro, y repetirlo
        # es un conflicto de rutas que Mongo rechaza.
        r = await db.gastos.update_one({"id": gid},
                                       {"$set": campos, "$setOnInsert": {"creado_en": ahora}},
                                       upsert=True)
        if r.upserted_id is not None:
            nuevos += 1
        elif r.modified_count:
            actualizados += 1
    return {"ok": True, "nuevos": nuevos, "actualizados": actualizados}


# ═══════════════════════════════════════════════════════════════════════════
# EL BUZÓN DE FACTURAS — que aparezcan solas, sin apuntar nada
# ═══════════════════════════════════════════════════════════════════════════
#
# Dicho por Dani el 20-09-2026: «quiero que me desgloses lo que pago de Fly.io,
# de Stripe, de Mongo, de todo, y que aparezca ya ahí; no subirlo yo, si no de
# qué me vale».
#
# Lo primero que miré fue la API de cada proveedor, y la respuesta honesta es
# que casi ninguno sirve (comprobado el 20-09-2026, no supuesto):
#
#   · Fly.io        — su GraphQL NO tiene `invoices`: se introspeccionó el
#                     esquema entero y en `Organization` solo hay
#                     `billingStatus` y `creditBalance`. No hay importe.
#   · Cloudflare    — la v4 no publica el histórico de facturación.
#   · MongoDB Atlas — SÍ lo tiene (`/orgs/{id}/invoices`), pero hace falta una
#                     clave de API que se crea a mano. Está preparado para
#                     cuando la pegues.
#   · Stripe        — sí: la comisión de cada cobro sale de `balance_transactions`.
#   · Meta/WhatsApp — sí: `conversation_analytics` da el coste por conversación.
#   · Brevo         — sí: dice en qué plan estás.
#
# O sea que las tres facturas que de verdad cuestan dinero no se pueden pedir
# por API. Pero TODAS llegan por correo, y `flotadsp.com` ya recibe correo por
# Cloudflare Email Routing. Así que el camino bueno es un buzón:
#
#   factura -> facturas@flotadsp.com -> Worker de Cloudflare -> este endpoint
#
# Pones esa dirección como correo de facturación en Fly, Atlas, Cloudflare y
# quien sea, y no vuelves a tocar nada: la factura entra sola, con su PDF.
#
# CUIDADO CON LA EMPRESA (gotcha 26): esto es un endpoint SIN sesión, y
# `_current_db_name` tiene valor por defecto, así que caería en la BD
# principal pase lo que pase. La dirección del buzón vive en `global_db` CON
# su `db_name` dentro y se fija a mano antes de tocar `db`.
# ═══════════════════════════════════════════════════════════════════════════

# De qué proveedor es un correo, por el dominio de quien lo manda. El dominio
# es más fiable que el texto: «Fly.io» puede salir en el cuerpo de cualquier
# correo, pero solo Fly manda desde fly.io.
_GASTO_DOMINIOS = {
    "fly.io": "Fly.io", "cloudflare.com": "Cloudflare", "mongodb.com": "MongoDB Atlas",
    "brevo.com": "Brevo", "sendinblue.com": "Brevo", "resend.com": "Resend",
    "stripe.com": "Stripe", "lemonsqueezy.com": "Lemon Squeezy",
    "anthropic.com": "Anthropic", "openai.com": "OpenAI",
    "google.com": "Google Cloud / Gemini", "googlemail.com": "Google Cloud / Gemini",
    "github.com": "GitHub", "apple.com": "Apple Developer",
    "facebook.com": "Meta (WhatsApp Business)", "facebookmail.com": "Meta (WhatsApp Business)",
    "namecheap.com": "Dominios", "godaddy.com": "Dominios", "ionos.es": "Dominios",
    "northgate.es": "Northgate", "ayvens.com": "Ayvens (antes ALD / LeasePlan)",
    "arval.es": "Arval (BNP Paribas)", "repsol.com": "Repsol / Solred",
    "solred.es": "Repsol / Solred", "cepsa.com": "Cepsa", "mapfre.com": "Seguro",
    "movistar.es": "Teléfono e internet", "vodafone.es": "Teléfono e internet",
    "iberdrola.es": "Luz y gas", "endesa.com": "Luz y gas", "naturgy.es": "Luz y gas",
    "seg-social.es": "Seguridad Social", "agenciatributaria.es": "Agencia Tributaria",
    "audasa.es": "Peajes", "midas.es": "Midas", "norauto.es": "Norauto",
    "amazon.es": "Amazon (compras)", "amazon.com": "Amazon (compras)",
}

# Lo que un correo de factura llama al total, en los dos idiomas. Se busca por
# ORDEN: «total a pagar» es más específico que «total», y el primero que casa
# gana — al revés, «total» pillaría el subtotal (gotcha 83 con otra cara).
_GASTO_ETIQUETAS_TOTAL = [
    "total a pagar", "importe total", "total factura", "total a cargo",
    "amount due", "total due", "amount paid", "total charged", "grand total",
    "you paid", "total amount", "importe", "total", "cargo",
]
# Las monedas que se reconocen. Sin esto, 57 dólares entrarían como 57 euros.
_GASTO_MONEDAS = {"€": "EUR", "eur": "EUR", "euro": "EUR", "euros": "EUR",
                  "$": "USD", "usd": "USD", "us$": "USD", "dolar": "USD",
                  "£": "GBP", "gbp": "GBP"}
_GASTO_BUZON_COL = "gastos_buzones"          # en global_db: lleva el db_name dentro
_GASTO_ADJUNTO_MAX = 8 * 1024 * 1024         # el PDF de una factura no pesa más


def _gasto_dominio_de(correo: str) -> str:
    """El dominio de quien manda, sin subdominios: `billing@mail.fly.io` -> `fly.io`."""
    m = re.search(r"@([A-Za-z0-9.\-]+)", _texto_cuerpo(correo, 200))
    if not m:
        return ""
    partes = m.group(1).lower().strip(".").split(".")
    # Los dos últimos trozos, salvo los dominios de dos niveles tipo `co.uk`.
    if len(partes) >= 3 and partes[-2] in ("co", "com", "org", "net") and len(partes[-1]) == 2:
        return ".".join(partes[-3:])
    return ".".join(partes[-2:]) if len(partes) >= 2 else partes[-1]


def _gasto_total_correo(texto: str) -> tuple:
    """El total de una factura y su moneda: (importe, moneda) o (None, "").

    Se busca por la ETIQUETA, no por «el número más grande»: en una factura de
    Fly el número más grande puede ser el identificador de la cuenta, y en una
    de renting, los kilómetros. Y se mira la moneda pegada al importe, porque
    Fly y Stripe facturan en dólares: contar 57 dólares como 57 euros sería un
    número falso con toda la pinta de medido.
    """
    if not texto:
        return None, ""
    plano = re.sub(r"[ \t]+", " ", _gasto_norm_suave(texto))
    for etiqueta in _GASTO_ETIQUETAS_TOTAL:
        for m in re.finditer(re.escape(etiqueta) + r"[^\n\d-]{0,40}?([$€£]?\s*[-+]?[\d][\d.,\s]*\d?\s*(?:€|eur|usd|us\$|\$|gbp|£)?)",
                             plano, re.I):
            trozo = m.group(1)
            importe = _gasto_importe(trozo)
            if importe is None or importe <= 0:
                continue
            return importe, _gasto_moneda_de(trozo) or _gasto_moneda_de(plano[max(0, m.start() - 30):m.end() + 30])
    return None, ""


def _gasto_norm_suave(texto: str) -> str:
    """Minúsculas y sin tildes, PERO conservando números, signos y saltos.

    `_gasto_norm` se carga los puntos y las comas, que es justo lo que hace
    falta para leer un importe. Son dos trabajos distintos y por eso son dos
    funciones: reutilizar el otro aquí habría devuelto «1 234 56».
    """
    s = unicodedata.normalize("NFD", _texto_cuerpo(texto, 200_000).lower())
    return "".join(c for c in s if unicodedata.category(c) != "Mn")


def _gasto_moneda_de(trozo: str) -> str:
    """La moneda que va pegada a un importe, o "" si no se ve ninguna."""
    t = (trozo or "").lower()
    if "€" in t or re.search(r"\beur\b|\beuros?\b", t):
        return "EUR"
    if "£" in t or re.search(r"\bgbp\b", t):
        return "GBP"
    if "$" in t or re.search(r"\busd\b|\bdolar", t):
        return "USD"
    return ""


async def _gasto_cambio_bce(moneda: str) -> tuple:
    """Cuántos euros vale 1 <moneda>, según el BCE. (cambio, fecha) o (None, "").

    El tipo de cambio NO se inventa ni se deja a ojo: sale del feed diario del
    Banco Central Europeo, que es público, gratuito y sin clave. Y se guarda
    de qué DÍA es, porque el de hoy aplicado a una factura de la semana pasada
    no es exacto y la pantalla lo tiene que poder decir.
    """
    if moneda == "EUR":
        return 1.0, ""
    try:
        import httpx as _hx
        async with _hx.AsyncClient(timeout=15) as _c:
            xml = (await _c.get("https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml")).text
    except Exception as e:                                        # noqa: BLE001
        logger.warning("gastos: no se pudo leer el cambio del BCE: %s", e)
        return None, ""
    dia = (re.search(r"time='([\d-]+)'", xml) or re.search(r'time="([\d-]+)"', xml))
    m = re.search(r"currency=['\"]%s['\"]\s+rate=['\"]([\d.]+)['\"]" % re.escape(moneda), xml)
    if not m:
        m = re.search(r"rate=['\"]([\d.]+)['\"]\s+currency=['\"]%s['\"]" % re.escape(moneda), xml)
    if not m:
        return None, ""
    try:
        por_euro = float(m.group(1))
    except ValueError:
        return None, ""
    if por_euro <= 0:
        return None, ""
    return round(1 / por_euro, 6), (dia.group(1) if dia else "")


async def _gasto_buzon(direccion: str) -> Optional[dict]:
    """El buzón y LA EMPRESA a la que pertenece. Nunca el valor por defecto."""
    d = _texto_cuerpo(direccion, 200).lower()
    if not d:
        return None
    return await global_db[_GASTO_BUZON_COL].find_one({"direccion": d}, {"_id": 0})


_GASTO_CORREO_MAX = 20 * 1024 * 1024         # un correo con su PDF, de sobra


def _gasto_correo_partes(crudo: bytes) -> dict:
    """Abre el correo tal cual llegó: de quién, asunto, texto y el primer PDF.

    Se parsea AQUÍ y no en el Worker de Cloudflare a propósito: Python trae el
    parser de MIME en la biblioteca estándar y el Worker tendría que cargar una
    librería de npm para lo mismo. Cuantas menos piezas, menos sitios donde se
    rompa algo que solo se ve cuando llega una factura de verdad.

    El cuerpo preferido es el texto plano; si la factura viene solo en HTML
    —que es lo normal— se le quitan las etiquetas, porque el total está en el
    texto y no en el marcado.
    """
    import email
    import html as _html
    from email import policy as _pol

    msg = email.message_from_bytes(crudo, policy=_pol.default)
    texto_plano, texto_html = "", ""
    adjunto = None
    for parte in msg.walk():
        if parte.get_content_maintype() == "multipart":
            continue
        nombre = parte.get_filename()
        tipo = (parte.get_content_type() or "").lower()
        if nombre:
            # El primero que valga: una factura trae UN PDF, y guardar los
            # logotipos del pie de firma no le sirve a nadie.
            if adjunto is None and not tipo.startswith("image/"):
                try:
                    datos = parte.get_payload(decode=True) or b""
                except Exception:                                 # noqa: BLE001
                    datos = b""
                if datos:
                    adjunto = {"nombre": nombre[:120], "tipo": tipo or "application/octet-stream",
                               "datos": datos}
            continue
        try:
            trozo = parte.get_content()
        except Exception:                                         # noqa: BLE001
            trozo = ""
        if tipo == "text/plain":
            texto_plano += "\n" + str(trozo)
        elif tipo == "text/html":
            texto_html += "\n" + str(trozo)

    cuerpo = texto_plano.strip()
    if not cuerpo and texto_html:
        sin_tags = re.sub(r"<(script|style)[^>]*>.*?</\1>", " ", texto_html, flags=re.S | re.I)
        sin_tags = re.sub(r"<br\s*/?>|</p>|</tr>|</div>", "\n", sin_tags, flags=re.I)
        sin_tags = re.sub(r"<[^>]+>", " ", sin_tags)
        cuerpo = _html.unescape(sin_tags)
    return {
        "de": str(msg.get("From") or "")[:300],
        "asunto": str(msg.get("Subject") or "")[:300],
        "fecha": str(msg.get("Date") or "")[:80],
        "message_id": str(msg.get("Message-ID") or "")[:300],
        "texto": re.sub(r"[ \t]*\n[ \t]*", "\n", cuerpo)[:200_000],
        "adjunto": adjunto,
    }


@api_router.post("/gastos/correo")
async def gastos_correo(request: Request):
    """Una factura que ha llegado al buzón. La manda el Worker de Cloudflare.

    Endpoint PÚBLICO (detrás de un correo no hay sesión), así que las reglas
    del gotcha 26: la empresa se fija A MANO desde lo que dice `global_db`, y
    el secreto se compara en tiempo constante. Lo que devuelve es mínimo: esta
    respuesta la lee el Worker, no una persona.
    """
    import hmac as _hm

    secreto = request.headers.get("X-Buzon-Secreto") or ""
    para = _texto_cuerpo(request.headers.get("X-Buzon-Para"), 200).lower()
    buzon = await _gasto_buzon(para)
    if not buzon or not secreto or not _hm.compare_digest(secreto, buzon.get("secreto") or "\x00"):
        # El mismo 404 con buzón inexistente y con secreto malo: distinguirlos
        # diría desde fuera qué direcciones existen.
        raise HTTPException(404, "Buzón no encontrado")
    set_current_org_db(buzon.get("db_name"))

    crudo = await request.body()
    if not crudo:
        raise HTTPException(400, "Correo vacío")
    if len(crudo) > _GASTO_CORREO_MAX:
        raise HTTPException(413, "Correo demasiado grande")
    try:
        partes = _gasto_correo_partes(crudo)
    except Exception as e:                                        # noqa: BLE001
        logger.warning("Buzón de facturas: no se pudo abrir el correo: %s", e)
        raise HTTPException(400, "No se pudo leer el correo")

    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    de, asunto, cuerpo = partes["de"], partes["asunto"], partes["texto"]

    # Idempotente por el Message-ID: un reintento del Worker —o el mismo correo
    # reenviado dos veces— no puede apuntar la factura dos veces.
    semilla = partes["message_id"] or (de + asunto + cuerpo[:400])
    gid = "mail:" + hashlib.sha256(semilla.encode("utf-8", "ignore")).hexdigest()[:32]
    if await db.gastos.find_one({"id": gid}, {"_id": 0, "id": 1}):
        return {"ok": True, "ya_estaba": True}

    dominio = _gasto_dominio_de(de)
    nombre = _GASTO_DOMINIOS.get(dominio, "")
    if nombre:
        # El dominio dice QUIÉN es; la categoría y la explicación salen del
        # catálogo por ese nombre, para no escribirlas en dos sitios.
        del_catalogo = _gasto_quien_es(nombre)
        quien = {"proveedor": nombre, "categoria": del_catalogo["categoria"],
                 "que_es": del_catalogo["que_es"]}
    else:
        quien = _gasto_quien_es(asunto + " " + de + " " + cuerpo[:400], await _gasto_aprendidos())

    importe, moneda = _gasto_total_correo(asunto + "\n" + cuerpo)
    moneda = moneda or "EUR"
    original, cambio, cambio_dia = None, None, ""
    if importe is not None and moneda != "EUR":
        original = importe
        cambio, cambio_dia = await _gasto_cambio_bce(moneda)
        importe = round(importe * cambio, 2) if cambio else None

    fecha = (_gasto_fecha(asunto, hoy) or _gasto_correo_fecha(partes["fecha"]) or hoy)

    adjunto = None
    crudo_adj = partes["adjunto"]
    s3 = get_r2()
    if crudo_adj and s3 and len(crudo_adj["datos"]) <= _GASTO_ADJUNTO_MAX:
        ext = (crudo_adj["nombre"].rsplit(".", 1)[-1] or "pdf").lower()[:5]
        clave = "facturas/%s/%s.%s" % (buzon.get("db_name") or "x", gid[5:], ext)
        try:
            await asyncio.get_running_loop().run_in_executor(
                _executor, lambda: s3.put_object(
                    Bucket=R2_BUCKET, Key=clave, Body=crudo_adj["datos"],
                    ContentType=crudo_adj["tipo"], ContentDisposition="inline"))
            adjunto = {"nombre": crudo_adj["nombre"],
                       "url": "%s/%s" % (R2_PUBLIC_URL, clave) if R2_PUBLIC_URL else clave,
                       "tam": len(crudo_adj["datos"])}
        except Exception as e:                                    # noqa: BLE001
            logger.warning("gastos: no se pudo guardar el adjunto de %s: %s", de, e)

    doc = {
        "id": gid, "fecha": fecha,
        "importe": importe if importe is not None else 0.0,
        "proveedor": quien["proveedor"] or (dominio or "Desconocido"),
        "concepto": asunto[:200],
        "categoria": quien["categoria"] if quien["categoria"] in _GASTO_CAT_CLAVES else "otros",
        "que_es": quien["que_es"], "nota": "", "matricula": "",
        "origen": "correo", "ref": partes["message_id"], "de": de,
        "adjunto": adjunto,
        # Si no se ha sabido leer el total, se DICE: una factura apuntada a 0 €
        # que nadie mira es peor que una que pide que la mires.
        "revisar": importe is None or importe <= 0,
        "moneda": moneda, "importe_original": original,
        "cambio": cambio, "cambio_dia": cambio_dia,
        "huella": _gasto_huella(fecha, quien["proveedor"] or dominio, importe or 0),
        "creado_en": datetime.now(timezone.utc).isoformat(), "creado_por": "buzon",
    }
    await db.gastos.insert_one(dict(doc))
    await global_db[_GASTO_BUZON_COL].update_one(
        {"direccion": para},
        {"$set": {"ultimo_en": doc["creado_en"]}, "$inc": {"recibidos": 1}})
    logger.info("Buzon de facturas: %s -> %s %.2f %s (revisar=%s)",
                de, doc["proveedor"], doc["importe"], moneda, doc["revisar"])
    return {"ok": True, "proveedor": doc["proveedor"], "revisar": doc["revisar"]}


def _gasto_correo_fecha(cabecera: str):
    """La fecha de la cabecera `Date`, en local. Devuelve None si no se puede.

    Se convierte a la hora de aquí antes de quedarse con el día: la cabecera
    viene en UTC y un correo de las 00:30 se apuntaría el día anterior — es el
    gotcha 11 entrando por la puerta del correo.
    """
    if not cabecera:
        return None
    try:
        from email.utils import parsedate_to_datetime
        from zoneinfo import ZoneInfo
        d = parsedate_to_datetime(cabecera)
    except Exception:                                             # noqa: BLE001
        return None
    if d is None:
        return None
    try:
        if d.tzinfo is not None:
            d = d.astimezone(ZoneInfo("Europe/Madrid"))
        return d.strftime("%Y-%m-%d")
    except Exception:                                             # noqa: BLE001
        return d.strftime("%Y-%m-%d")


@api_router.get("/gastos/buzon")
async def gastos_buzon_estado(_: dict = Depends(require_superadmin)):
    """La dirección del buzón y cuántas facturas han entrado por ahí."""
    db_name = _current_db_name.get()
    b = await global_db[_GASTO_BUZON_COL].find_one(
        {"db_name": db_name}, {"_id": 0, "secreto": 0})
    pendientes = await db.gastos.count_documents({"origen": "correo", "revisar": True})
    return {"buzon": b, "por_revisar": pendientes,
            "proveedores": sorted(set(_GASTO_DOMINIOS.values()))}


app.include_router(auth_router)
app.include_router(api_router)


